CREATE TABLE IF NOT EXISTS public.sales (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_name text NOT NULL,
    product_name text NOT NULL,
    amount numeric(12,2) NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    category text DEFAULT 'subscription'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    salesperson_id uuid,
    source text DEFAULT 'other'::text,
    pipeline_id uuid,
    forecast_category forecast_category,
    account_id uuid,
    broadcast_sent_at timestamp with time zone,
    script_variant text,
    client_id uuid,
    product_id uuid,
    sku text,
    stock_reduced boolean DEFAULT false,
    enrichment_data jsonb DEFAULT '{}'::jsonb,
    enrichment_status text DEFAULT 'pending'::text,
    lost_to_competitor_id uuid,
    competitor_price_at_deal numeric(12,2),
    territory_id uuid,
    ai_prediction_score double precision DEFAULT 0,
    ai_prediction_reasoning text,
    whatsapp_last_interaction timestamp with time zone,
    whatsapp_status text DEFAULT 'not_connected'::text,
    sdr_id uuid,
    closer_id uuid,
    is_first_sale boolean DEFAULT false,
    unit_cost numeric(12,2),
    total_cost numeric(14,2),
    cost_source text,
    cost_synced_at timestamp with time zone,
    margin_amount numeric(14,2) GENERATED ALWAYS AS (
CASE
    WHEN ((total_cost IS NULL) OR (amount IS NULL)) THEN NULL::numeric
    ELSE round((amount - total_cost), 2)
END) STORED,
    markup_pct numeric(8,2) GENERATED ALWAYS AS (
CASE
    WHEN ((total_cost IS NULL) OR (total_cost = (0)::numeric) OR (amount IS NULL)) THEN NULL::numeric
    ELSE round((((amount - total_cost) / total_cost) * (100)::numeric), 2)
END) STORED,
    stage text,
    segment text,
    notes text,
    loss_reason text,
    competitor_name text,
    closed_at timestamp with time zone,
    external_deal_id text,
    deleted_at timestamp with time zone,
    deleted_by uuid,
    delete_reason text,
    version integer DEFAULT 1 NOT NULL,
    deal_status deal_status GENERATED ALWAYS AS (
CASE
    WHEN (status = ANY (ARRAY['completed'::text, 'won'::text, 'closed'::text])) THEN 'completed'::deal_status
    WHEN (status = ANY (ARRAY['lost'::text, 'cancelled'::text])) THEN 'lost'::deal_status
    WHEN (status = 'qualified'::text) THEN 'qualified'::deal_status
    WHEN (status = 'proposal'::text) THEN 'proposal'::deal_status
    WHEN (status = 'negotiation'::text) THEN 'negotiation'::deal_status
    WHEN (status = ANY (ARRAY['pending'::text, 'lead'::text, 'prospecting'::text, 'open'::text, 'in_progress'::text])) THEN 'pending'::deal_status
    ELSE NULL::deal_status
END) STORED
);

