-- private.add_salesperson_xp(p_salesperson_id uuid, p_xp_amount integer, p_source text)

CREATE OR REPLACE FUNCTION private.add_salesperson_xp(p_salesperson_id uuid, p_xp_amount integer, p_source text DEFAULT 'system'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_sp_id uuid;
  v_level_base numeric;
BEGIN
  v_caller_sp_id := get_current_salesperson_id();

  -- Only the salesperson themselves or admin/manager can add XP
  IF v_caller_sp_id != p_salesperson_id AND NOT is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Validate positive increment
  IF p_xp_amount <= 0 OR p_xp_amount > 10000 THEN
    RAISE EXCEPTION 'Invalid XP amount (must be 1-10000)';
  END IF;

  v_level_base := public.get_app_config_number('xp.level_base', 1000);

  UPDATE public.salesperson_xp SET
    total_xp = total_xp + p_xp_amount,
    current_level = GREATEST(current_level, 1 + floor((total_xp + p_xp_amount) / v_level_base)::int),
    updated_at = now()
  WHERE salesperson_id = p_salesperson_id;

  RETURN FOUND;
END;
$function$
;

-- private.assign_cadence_variant(_ab_test_id uuid)

CREATE OR REPLACE FUNCTION private.assign_cadence_variant(_ab_test_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _split INT;
  _count_a INT;
  _count_b INT;
  _total INT;
  _ratio_a NUMERIC;
BEGIN
  SELECT traffic_split INTO _split FROM public.cadence_ab_tests WHERE id = _ab_test_id;
  IF _split IS NULL THEN RETURN 'a'; END IF;

  SELECT
    COUNT(*) FILTER (WHERE variant = 'a'),
    COUNT(*) FILTER (WHERE variant = 'b')
  INTO _count_a, _count_b
  FROM public.cadence_ab_assignments
  WHERE ab_test_id = _ab_test_id;

  _total := _count_a + _count_b;
  IF _total = 0 THEN RETURN 'a'; END IF;

  _ratio_a := (_count_a::NUMERIC / _total::NUMERIC) * 100;

  IF _ratio_a < _split THEN
    RETURN 'a';
  ELSE
    RETURN 'b';
  END IF;
END;
$function$
;

-- private.auto_create_commission()

CREATE OR REPLACE FUNCTION private.auto_create_commission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule_percentage NUMERIC(5,2);
  v_rule_id UUID;
  v_commission_amount NUMERIC(12,2);
BEGIN
  -- Only trigger on completed sales with a salesperson
  IF NEW.deal_status != 'completed' OR NEW.salesperson_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Skip if commission already exists for this sale
  IF EXISTS (SELECT 1 FROM public.commissions WHERE sale_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  -- Find best matching rule (priority: salesperson + category > salesperson > category > global)
  SELECT id, percentage INTO v_rule_id, v_rule_percentage
  FROM public.commission_rules
  WHERE is_active = true
    AND (min_amount IS NULL OR NEW.amount >= min_amount)
    AND (max_amount IS NULL OR NEW.amount <= max_amount)
    AND (
      (salesperson_id = NEW.salesperson_id AND category = NEW.category)
      OR (salesperson_id = NEW.salesperson_id AND category IS NULL)
      OR (salesperson_id IS NULL AND category = NEW.category)
      OR (salesperson_id IS NULL AND category IS NULL)
    )
  ORDER BY
    CASE
      WHEN salesperson_id = NEW.salesperson_id AND category = NEW.category THEN 1
      WHEN salesperson_id = NEW.salesperson_id THEN 2
      WHEN category = NEW.category THEN 3
      ELSE 4
    END ASC,
    priority DESC,
    created_at DESC
  LIMIT 1;

  -- Default to 5% if no rule found
  IF v_rule_id IS NULL THEN
    v_rule_percentage := 5.00;
  END IF;

  v_commission_amount := ROUND(NEW.amount * v_rule_percentage / 100, 2);

  INSERT INTO public.commissions (
    sale_id, salesperson_id, rule_id, base_amount, percentage, commission_amount, status
  ) VALUES (
    NEW.id, NEW.salesperson_id, v_rule_id, NEW.amount, v_rule_percentage, v_commission_amount, 'pending'
  );

  RETURN NEW;
END;
$function$
;

-- private.auto_enroll_in_cadence()

CREATE OR REPLACE FUNCTION private.auto_enroll_in_cadence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  matching_rule RECORD;
BEGIN
  SELECT r.id, r.cadence_id INTO matching_rule
  FROM public.cadence_enrollment_rules r
  WHERE r.is_active = true
    AND (r.trigger_stage IS NULL OR r.trigger_stage = NEW.status)
    AND (r.trigger_category IS NULL OR r.trigger_category = NEW.category)
    AND (r.trigger_source IS NULL OR r.trigger_source = NEW.source)
    AND (r.min_amount IS NULL OR NEW.amount >= r.min_amount)
    AND (r.max_amount IS NULL OR NEW.amount <= r.max_amount)
    AND NOT EXISTS (
      SELECT 1 FROM public.prospect_cadences pc
      WHERE pc.sale_id = NEW.id AND pc.cadence_id = r.cadence_id
        AND pc.status IN ('active','paused')
    )
  ORDER BY r.priority ASC LIMIT 1;

  IF matching_rule.id IS NOT NULL THEN
    INSERT INTO public.prospect_cadences (sale_id, cadence_id, salesperson_id, status, next_action_date)
    VALUES (NEW.id, matching_rule.cadence_id, NEW.salesperson_id, 'active', CURRENT_DATE);
  END IF;
  RETURN NEW;
END;
$function$
;

-- private.auto_enroll_quote_cadence()

CREATE OR REPLACE FUNCTION private.auto_enroll_quote_cadence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cadence_id uuid;
  v_existing uuid;
BEGIN
  IF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'sent')
     OR (TG_OP = 'INSERT' AND NEW.status = 'sent') THEN

    SELECT id INTO v_existing FROM public.prospect_cadences
    WHERE quote_id = NEW.id AND status IN ('active','paused') LIMIT 1;

    IF v_existing IS NOT NULL THEN RETURN NEW; END IF;

    SELECT id INTO v_cadence_id FROM public.cadences
    WHERE cadence_type = 'quote_followup' AND is_active = true
    ORDER BY created_at ASC LIMIT 1;

    IF v_cadence_id IS NOT NULL THEN
      PERFORM public.enroll_quote_in_cadence(NEW.id, v_cadence_id);
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

-- private.auto_link_sale_to_account()

CREATE OR REPLACE FUNCTION private.auto_link_sale_to_account()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id uuid;
BEGIN
  IF NEW.client_name IS NULL OR length(trim(NEW.client_name)) = 0 THEN
    RETURN NEW;
  END IF;
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_account_id
  FROM public.accounts
  WHERE lower(name) = lower(trim(NEW.client_name))
  LIMIT 1;

  IF v_account_id IS NULL THEN
    BEGIN
      INSERT INTO public.accounts (name, owner_id, tier)
      VALUES (trim(NEW.client_name), NEW.salesperson_id, 'mid_market')
      RETURNING id INTO v_account_id;
    EXCEPTION WHEN unique_violation THEN
      SELECT id INTO v_account_id
      FROM public.accounts
      WHERE lower(name) = lower(trim(NEW.client_name))
      LIMIT 1;
    END;
  END IF;

  NEW.account_id := v_account_id;
  RETURN NEW;
END;
$function$
;

-- private.auto_pause_cadence_on_response()

CREATE OR REPLACE FUNCTION private.auto_pause_cadence_on_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.direction = 'inbound' AND NEW.deal_id IS NOT NULL THEN
    UPDATE public.prospect_cadences
    SET status = 'paused',
        paused_reason = 'response_detected:' || COALESCE(NEW.channel, 'unknown'),
        paused_at = now(),
        updated_at = now()
    WHERE sale_id = NEW.deal_id
      AND status = 'active';

    -- Marca tarefas pendentes como skipped automaticamente
    UPDATE public.cadence_tasks
    SET status = 'skipped',
        notes = COALESCE(notes, '') || ' [auto-skipped: prospect respondeu via ' || COALESCE(NEW.channel, 'canal') || ']'
    WHERE status = 'pending'
      AND prospect_cadence_id IN (
        SELECT id FROM public.prospect_cadences
        WHERE sale_id = NEW.deal_id AND status = 'paused' AND paused_reason LIKE 'response_detected%'
      )
      AND scheduled_date >= CURRENT_DATE;
  END IF;
  RETURN NEW;
END;
$function$
;

-- private.auto_pause_enrollment(_enrollment_id uuid, _reason text)

CREATE OR REPLACE FUNCTION private.auto_pause_enrollment(_enrollment_id uuid, _reason text DEFAULT 'reply_detected'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _enr record;
BEGIN
  SELECT id, contact_id, contact_type, status
    INTO _enr
  FROM public.sequence_enrollments
  WHERE id = _enrollment_id;

  IF _enr.id IS NULL THEN
    RETURN;
  END IF;

  IF _enr.status = 'paused' THEN
    RETURN;
  END IF;

  UPDATE public.sequence_enrollments
     SET status = 'paused',
         auto_paused_at = now(),
         auto_pause_reason = COALESCE(_reason, 'reply_detected'),
         next_action_at = NULL
   WHERE id = _enrollment_id;

  -- Record engagement signal + recompute (best-effort)
  BEGIN
    PERFORM public.record_engagement_signal(_enr.contact_id, _enr.contact_type, 'reply', now());
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  BEGIN
    PERFORM public.recompute_engagement_score(_enr.contact_id, _enr.contact_type);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
END;
$function$
;

-- private.auto_promote_sequence_winners(_sequence_id uuid)

CREATE OR REPLACE FUNCTION private.auto_promote_sequence_winners(_sequence_id uuid)
 RETURNS TABLE(step_id uuid, promoted_label text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s_step record;
  winner record;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'manager')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  FOR s_step IN
    SELECT DISTINCT st.id
    FROM public.sequence_steps st
    JOIN public.sequence_step_variants v ON v.step_id = st.id
    WHERE st.sequence_id = _sequence_id
    GROUP BY st.id
    HAVING count(v.id) >= 2
  LOOP
    SELECT label, sent, replied,
           CASE WHEN sent > 0 THEN replied::numeric / sent ELSE 0 END AS rate
    INTO winner
    FROM public.sequence_variant_performance
    WHERE step_id = s_step.id AND sent >= 30
    ORDER BY (CASE WHEN sent > 0 THEN replied::numeric / sent ELSE 0 END) DESC
    LIMIT 1;

    IF winner.label IS NOT NULL THEN
      PERFORM public.declare_step_winner(s_step.id, winner.label::text);
      step_id := s_step.id;
      promoted_label := winner.label;
      RETURN NEXT;
    END IF;
  END LOOP;
  RETURN;
END;
$function$
;

-- private.auto_set_forecast_category()

CREATE OR REPLACE FUNCTION private.auto_set_forecast_category()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('completed', 'won', 'closed') THEN
    NEW.forecast_category := 'closed';
  ELSIF NEW.status IN ('lost', 'cancelled') THEN
    NEW.forecast_category := 'omitted';
  ELSIF NEW.status = 'negotiation' THEN
    NEW.forecast_category := COALESCE(NEW.forecast_category, 'commit');
  ELSIF NEW.status = 'proposal' THEN
    NEW.forecast_category := COALESCE(NEW.forecast_category, 'best_case');
  ELSE
    NEW.forecast_category := COALESCE(NEW.forecast_category, 'pipeline');
  END IF;
  RETURN NEW;
END;
$function$
;

-- private.auto_victory_post()

CREATE OR REPLACE FUNCTION private.auto_victory_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF TG_TABLE_NAME = 'sales' THEN
        IF NEW.deal_status = 'completed' AND (OLD.deal_status IS DISTINCT FROM NEW.deal_status) AND NEW.amount >= 5000 THEN
            INSERT INTO public.victory_feed (salesperson_id, title, description, value, event_type)
            VALUES (NEW.salesperson_id, 'Fechamento Épico! 🚀',
              'Selou um deal de ' || COALESCE(NEW.product_name, 'Produto') || ' para ' || COALESCE(NEW.client_name, 'Cliente'),
              NEW.amount, 'sale');
            INSERT INTO public.available_spins (salesperson_id, spins_count, updated_at)
            VALUES (NEW.salesperson_id, 1, now())
            ON CONFLICT (salesperson_id) DO UPDATE SET spins_count = available_spins.spins_count + 1, updated_at = now();
        END IF;
    ELSIF TG_TABLE_NAME = 'sales_battles' THEN
        IF NEW.status = 'completed' AND (OLD.status IS DISTINCT FROM NEW.status) AND NEW.winner_id IS NOT NULL THEN
            INSERT INTO public.victory_feed (salesperson_id, title, description, event_type)
            VALUES (NEW.winner_id, 'Campeão da Arena! 🏆', 'Venceu a batalha: ' || NEW.title, 'achievement');
            INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
            VALUES (NEW.winner_id, COALESCE(NEW.xp_reward, 100), 'battle', NEW.id, 'Vitória na Batalha: ' || NEW.title);
            INSERT INTO public.available_spins (salesperson_id, spins_count, updated_at)
            VALUES (NEW.winner_id, 2, now())
            ON CONFLICT (salesperson_id) DO UPDATE SET spins_count = available_spins.spins_count + 2, updated_at = now();
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
;

