-- private.guard_activity_soft_delete()

CREATE OR REPLACE FUNCTION private.guard_activity_soft_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Sem mudança no estado de exclusão: a autoria registrada não pode ser reescrita.
  IF NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at THEN
    NEW.deleted_by := OLD.deleted_by;
    RETURN NEW;
  END IF;

  -- Exclusão: o autor é quem está autenticado, nunca o valor enviado pelo client.
  IF OLD.deleted_at IS NULL THEN
    NEW.deleted_by := COALESCE(auth.uid(), NEW.deleted_by);
    RETURN NEW;
  END IF;

  -- Restaurar (deleted_at → NULL) ou mudar a data da exclusão: só admin/gestor ou backend.
  IF current_user IN ('authenticated', 'anon')
     AND NOT public.is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'Somente admin ou gestor pode restaurar uma atividade excluída'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.deleted_at IS NULL THEN
    NEW.deleted_by := NULL;
  END IF;
  RETURN NEW;
END;
$function$
;

-- private.handle_audit_logging()

CREATE OR REPLACE FUNCTION private.handle_audit_logging()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    actor_id UUID;
    actor_email TEXT;
    old_data JSONB;
    new_data JSONB;
    changed_fields JSONB;
BEGIN
    -- Try to get the current user
    actor_id := auth.uid();
    
    -- Prepare data for audit
    IF (TG_OP = 'UPDATE') THEN
        old_data := to_jsonb(OLD);
        new_data := to_jsonb(NEW);
        
        -- Compute changes (simplified)
        SELECT jsonb_object_agg(key, value) INTO changed_fields
        FROM jsonb_each(new_data)
        WHERE value IS DISTINCT FROM old_data -> key;
        
        INSERT INTO public.audit_logs (
            action,
            entity_type,
            entity_id,
            actor_id,
            changes
        ) VALUES (
            'update',
            TG_TABLE_NAME,
            OLD.id::text,
            actor_id,
            changed_fields
        );
    END IF;
    
    RETURN NEW;
END;
$function$
;

