-- private.handle_performance_update()

CREATE OR REPLACE FUNCTION private.handle_performance_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_bet RECORD;
    v_xp_change INTEGER;
BEGIN
    -- Only process active bets for the salesperson involved
    FOR v_bet IN 
        SELECT * FROM public.performance_bets 
        WHERE status = 'active' 
        AND salesperson_id = NEW.salesperson_id
    LOOP
        -- Calculate current progress for this specific bet
        IF v_bet.bet_type = 'deals' THEN
            SELECT COUNT(*) INTO v_bet.current_value 
            FROM public.sales 
            WHERE salesperson_id = v_bet.salesperson_id 
              AND created_at >= v_bet.created_at 
              AND created_at <= v_bet.ends_at
              AND (status = 'won' OR status = 'completed');
              
        ELSIF v_bet.bet_type = 'revenue' THEN
            SELECT COALESCE(SUM(amount), 0) INTO v_bet.current_value 
            FROM public.sales 
            WHERE salesperson_id = v_bet.salesperson_id 
              AND created_at >= v_bet.created_at 
              AND created_at <= v_bet.ends_at
              AND (status = 'won' OR status = 'completed');
              
        ELSIF v_bet.bet_type = 'calls' THEN
            SELECT COUNT(*) INTO v_bet.current_value 
            FROM public.activities 
            WHERE salesperson_id = v_bet.salesperson_id 
              AND created_at >= v_bet.created_at 
              AND created_at <= v_bet.ends_at
              AND activity_type = 'call'
              AND deleted_at IS NULL;
              
        ELSIF v_bet.bet_type = 'meetings' THEN
            SELECT COUNT(*) INTO v_bet.current_value 
            FROM public.activities 
            WHERE salesperson_id = v_bet.salesperson_id 
              AND created_at >= v_bet.created_at 
              AND created_at <= v_bet.ends_at
              AND activity_type = 'meeting'
              AND deleted_at IS NULL;
              
        ELSIF v_bet.bet_type = 'activities' THEN
            SELECT COUNT(*) INTO v_bet.current_value 
            FROM public.activities 
            WHERE salesperson_id = v_bet.salesperson_id 
              AND created_at >= v_bet.created_at 
              AND created_at <= v_bet.ends_at
              AND deleted_at IS NULL;
        END IF;

        -- Update the current value and check status
        IF v_bet.current_value >= v_bet.target_value THEN
            -- Bet Won
            v_xp_change := (v_bet.xp_wagered * v_bet.xp_multiplier)::INTEGER;
            
            UPDATE public.performance_bets 
            SET current_value = v_bet.current_value,
                status = 'won', 
                resolved_at = now(),
                updated_at = now()
            WHERE id = v_bet.id;
            
            -- Award XP (xp_history → trigger sync_total_xp atualiza salesperson_xp)
            INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
            VALUES (v_bet.salesperson_id, v_xp_change, 'bet_won', v_bet.id::text, 'Vitória em Aposta: ' || COALESCE(v_bet.description, ''));
        ELSE
            UPDATE public.performance_bets 
            SET current_value = v_bet.current_value,
                updated_at = now()
            WHERE id = v_bet.id;
        END IF;
    END LOOP;
    
    RETURN NEW;
END;
$function$
;

-- private.handle_sale_commissions()

CREATE OR REPLACE FUNCTION private.handle_sale_commissions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_is_activation BOOLEAN;
    v_sdr_commission NUMERIC := 0;
    v_closer_commission NUMERIC := 0;
    v_rule_percentage NUMERIC;
    v_rule_id UUID;
    v_sdr_rule_percentage NUMERIC;
    v_sdr_rule_id UUID;
    v_target_closer_id UUID;
BEGIN
    IF (
        (TG_OP = 'UPDATE' AND (NEW.status IN ('completed', 'won') OR NEW.deal_status = 'completed') AND (OLD.status NOT IN ('completed', 'won') AND OLD.deal_status != 'completed'))
        OR
        (TG_OP = 'INSERT' AND (NEW.status IN ('completed', 'won') OR NEW.deal_status = 'completed'))
    ) THEN
        v_target_closer_id := COALESCE(NEW.closer_id, NEW.salesperson_id);

        IF v_target_closer_id IS NULL THEN
            RETURN NEW;
        END IF;

        IF NEW.is_first_sale IS NOT NULL THEN
            v_is_activation := NEW.is_first_sale;
        ELSE
            IF NEW.client_id IS NOT NULL THEN
                v_is_activation := private.check_is_first_activation(NEW.client_id, NEW.id);
            ELSE
                v_is_activation := TRUE;
            END IF;
        END IF;

        -- Regra do closer: específica do vendedor > categoria > faixa > global.
        -- Faixa: amount dentro de [min_amount, max_amount] quando definidos.
        SELECT id, percentage INTO v_rule_id, v_rule_percentage
        FROM public.commission_rules
        WHERE is_active = true
          AND (salesperson_id = v_target_closer_id OR salesperson_id IS NULL)
          AND (category IS NULL OR category = NEW.category)
          AND NEW.amount >= COALESCE(min_amount, 0)
          AND (max_amount IS NULL OR NEW.amount <= max_amount)
        ORDER BY
          (salesperson_id = v_target_closer_id) DESC,
          (category IS NOT NULL) DESC,
          priority DESC
        LIMIT 1;

        IF v_rule_percentage IS NULL THEN v_rule_percentage := 5.0; END IF;

        v_closer_commission := (NEW.amount * v_rule_percentage / 100);

        INSERT INTO public.commissions (
            sale_id, salesperson_id, rule_id, base_amount, percentage, commission_amount, status, is_first_sale
        ) VALUES (
            NEW.id, v_target_closer_id, v_rule_id, NEW.amount, v_rule_percentage, v_closer_commission, 'pending', v_is_activation
        );

        -- Comissão do SDR na ativação: regra resolvida para o SDR, não a do closer.
        IF v_is_activation AND NEW.sdr_id IS NOT NULL AND NEW.sdr_id != v_target_closer_id THEN
            SELECT id, percentage INTO v_sdr_rule_id, v_sdr_rule_percentage
            FROM public.commission_rules
            WHERE is_active = true
              AND (salesperson_id = NEW.sdr_id OR salesperson_id IS NULL)
              AND (category IS NULL OR category = NEW.category)
              AND NEW.amount >= COALESCE(min_amount, 0)
              AND (max_amount IS NULL OR NEW.amount <= max_amount)
            ORDER BY
              (salesperson_id = NEW.sdr_id) DESC,
              (category IS NOT NULL) DESC,
              priority DESC
            LIMIT 1;

            IF v_sdr_rule_percentage IS NULL THEN v_sdr_rule_percentage := 5.0; END IF;

            v_sdr_commission := (NEW.amount * v_sdr_rule_percentage / 100);

            INSERT INTO public.commissions (
                sale_id, salesperson_id, rule_id, base_amount, percentage, commission_amount, status, is_first_sale
            ) VALUES (
                NEW.id, NEW.sdr_id, v_sdr_rule_id, NEW.amount, v_sdr_rule_percentage, v_sdr_commission, 'pending', TRUE
            );
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
;

-- private.handle_template_versioning()

CREATE OR REPLACE FUNCTION private.handle_template_versioning()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    next_version INTEGER;
BEGIN
    IF (OLD.whatsapp_template IS DISTINCT FROM NEW.whatsapp_template) THEN
        SELECT COALESCE(MAX(version_number), 0) + 1 INTO next_version
        FROM public.whatsapp_template_versions
        WHERE template_id = NEW.id;

        INSERT INTO public.whatsapp_template_versions (template_id, body, version_number, created_by)
        VALUES (NEW.id, NEW.whatsapp_template, next_version, auth.uid());
    END IF;
    RETURN NEW;
END;
$function$
;

-- private.handle_territory_conquest()

CREATE OR REPLACE FUNCTION private.handle_territory_conquest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_territory_id UUID;
    v_top_salesperson_id UUID;
    v_current_owner_id UUID;
BEGIN
    -- We assume the sale has a territory_id field (if not, we'd look it up via customer or region)
    -- For now, let's check if the sale has a territory context
    IF NEW.territory_id IS NULL THEN
        RETURN NEW;
    END IF;

    v_territory_id := NEW.territory_id;

    -- Update territory stats
    UPDATE public.territories 
    SET total_revenue = total_revenue + NEW.amount,
        total_deals = total_deals + 1,
        updated_at = now()
    WHERE id = v_territory_id
    RETURNING current_owner_id INTO v_current_owner_id;

    -- Find the salesperson with the highest total revenue in this territory
    SELECT salesperson_id INTO v_top_salesperson_id
    FROM (
        SELECT salesperson_id, SUM(amount) as revenue
        FROM public.sales
        WHERE territory_id = v_territory_id
          AND (status = 'won' OR status = 'completed')
        GROUP BY salesperson_id
        ORDER BY revenue DESC
        LIMIT 1
    ) sub;

    -- If a new owner is found
    IF v_top_salesperson_id IS NOT NULL AND (v_current_owner_id IS NULL OR v_top_salesperson_id != v_current_owner_id) THEN
        UPDATE public.territories 
        SET current_owner_id = v_top_salesperson_id,
            conquered_at = now()
        WHERE id = v_territory_id;

        -- Log history
        INSERT INTO public.territory_history (territory_id, salesperson_id, event_type, description)
        VALUES (v_territory_id, v_top_salesperson_id, 'conquest', 'Território conquistado por volume de vendas (Líder de Receita)');
    END IF;

    RETURN NEW;
END;
$function$
;

