-- private.match_weekly_players()

CREATE OR REPLACE FUNCTION private.match_weekly_players()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    active_salespeople UUID[];
    player_a UUID;
    player_b UUID;
    i INT;
    num_players INT;
    week_start DATE := public.start_of_week(CURRENT_DATE, 1);
BEGIN
    -- Pegar IDs de vendedores ativos
    SELECT ARRAY_AGG(id) INTO active_salespeople
    FROM public.salespeople
    WHERE is_active = true;

    num_players := ARRAY_LENGTH(active_salespeople, 1);
    
    -- Se número for ímpar, removemos um aleatoriamente para parear
    IF num_players % 2 != 0 THEN
        active_salespeople := active_salespeople[1:num_players-1];
        num_players := num_players - 1;
    END IF;

    FOR i IN 1..num_players LOOP
        -- Pegar dois jogadores e criar o matchup
        IF i % 2 != 0 AND i < num_players THEN
            player_a := active_salespeople[i];
            player_b := active_salespeople[i+1];
            
            INSERT INTO public.weekly_matchups (salesperson_a_id, salesperson_b_id, week_start, xp_reward, status)
            VALUES (player_a, player_b, week_start, 250, 'active')
            ON CONFLICT DO NOTHING;
        END IF;
    END LOOP;
END;
$function$
;

-- private.notify_critical_moment_created()

CREATE OR REPLACE FUNCTION private.notify_critical_moment_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  manager_record RECORD;
BEGIN
  IF NEW.severity NOT IN ('high','critical') THEN
    RETURN NEW;
  END IF;

  -- Notifica o próprio vendedor (owner)
  INSERT INTO public.critical_moment_notifications (moment_id, recipient_user_id)
  VALUES (NEW.id, NEW.owner_id);

  -- Notifica todos os managers e admins ativos
  FOR manager_record IN
    SELECT DISTINCT ur.user_id
    FROM public.user_roles ur
    WHERE ur.role IN ('manager'::app_role, 'admin'::app_role)
      AND ur.user_id <> NEW.owner_id
  LOOP
    INSERT INTO public.critical_moment_notifications (moment_id, recipient_user_id)
    VALUES (NEW.id, manager_record.user_id);
  END LOOP;

  RETURN NEW;
END;
$function$
;

-- private.notify_critical_winloss_pattern()

CREATE OR REPLACE FUNCTION private.notify_critical_winloss_pattern()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  fn_url text;
begin
  if NEW.confidence is not null and NEW.confidence > 0.85 then
    begin
      fn_url := current_setting('app.functions_url', true);
      if fn_url is not null and length(fn_url) > 0 then
        perform net.http_post(
          url := fn_url || '/notify-critical-pattern',
          headers := jsonb_build_object('content-type','application/json'),
          body := jsonb_build_object(
            'pattern_id', NEW.id,
            'name', NEW.name,
            'confidence', NEW.confidence
          )
        );
      end if;
    exception when others then
      -- Não bloqueia insert em caso de falha de rede / extensão indisponível
      null;
    end;
  end if;
  return NEW;
end;
$function$
;

