-- private.refresh_monthly_sales_summary(p_month text)

CREATE OR REPLACE FUNCTION private.refresh_monthly_sales_summary(p_month text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Bug pré-existente: o INSERT...SELECT abaixo retorna zero linhas quando
    -- o mês ficou sem vendas (DELETE da última venda ou UPDATE cross-month),
    -- então o resumo velho nunca era limpo — linha fantasma permanente.
    IF NOT EXISTS (
        SELECT 1 FROM public.sales
        WHERE to_char(created_at, 'YYYY-MM') = p_month
    ) THEN
        DELETE FROM public.monthly_sales_summary WHERE month = p_month;
        RETURN;
    END IF;

    INSERT INTO public.monthly_sales_summary (month, revenue, deals, won_deals, lost_deals, updated_at)
    SELECT
        to_char(created_at, 'YYYY-MM') as month,
        SUM(CASE WHEN deal_status::text IN ('won', 'completed', 'closed') OR status IN ('won', 'completed', 'closed') THEN amount ELSE 0 END)::NUMERIC as revenue,
        COUNT(*)::INT as deals,
        COUNT(CASE WHEN deal_status::text IN ('won', 'completed', 'closed') OR status IN ('won', 'completed', 'closed') THEN 1 END)::INT as won_deals,
        COUNT(CASE WHEN deal_status::text IN ('lost', 'cancelled') OR status IN ('lost', 'cancelled') THEN 1 END)::INT as lost_deals,
        now()
    FROM public.sales
    WHERE to_char(created_at, 'YYYY-MM') = p_month
    GROUP BY 1
    ON CONFLICT (month) DO UPDATE
    SET revenue = EXCLUDED.revenue,
        deals = EXCLUDED.deals,
        won_deals = EXCLUDED.won_deals,
        lost_deals = EXCLUDED.lost_deals,
        updated_at = EXCLUDED.updated_at;
END;
$function$
;

-- private.settle_performance_bets()

CREATE OR REPLACE FUNCTION private.settle_performance_bets()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_bet RECORD;
    v_xp_change INTEGER;
BEGIN
    FOR v_bet IN 
        SELECT * FROM public.performance_bets 
        WHERE status = 'active' AND (current_value >= target_value OR ends_at < NOW())
    LOOP
        IF v_bet.current_value >= v_bet.target_value THEN
            -- Bet Won
            v_xp_change := ROUND(v_bet.xp_wagered * (v_bet.xp_multiplier - 1));
            
            UPDATE public.performance_bets 
            SET status = 'won', resolved_at = NOW() 
            WHERE id = v_bet.id;

            -- Award XP (using existing XP system if available, else direct insert)
            INSERT INTO public.xp_transactions (salesperson_id, amount, source, source_id, description)
            VALUES (v_bet.salesperson_id, v_xp_change, 'bet', v_bet.id, 'Vitória em Aposta de Performance: ' || v_bet.bet_type);
            
        ELSIF v_bet.ends_at < NOW() THEN
            -- Bet Lost
            v_xp_change := -v_bet.xp_wagered;

            UPDATE public.performance_bets 
            SET status = 'lost', resolved_at = NOW() 
            WHERE id = v_bet.id;

            -- Deduct XP
            INSERT INTO public.xp_transactions (salesperson_id, amount, source, source_id, description)
            VALUES (v_bet.salesperson_id, v_xp_change, 'bet', v_bet.id, 'Falha em Aposta de Performance: ' || v_bet.bet_type);
        END IF;
    END LOOP;
END;
$function$
;

-- private.snapshot_race_daily(_season_id uuid)

CREATE OR REPLACE FUNCTION private.snapshot_race_daily(_season_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inserted_count INTEGER := 0;
  today_br DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  INSERT INTO public.race_daily_snapshots (
    season_id, salesperson_id, snapshot_date, rank, progress, total_sales, deals_count, score
  )
  SELECT
    v.season_id,
    v.salesperson_id,
    today_br,
    ROW_NUMBER() OVER (ORDER BY v.progress DESC)::INTEGER AS rank,
    v.progress,
    COALESCE(v.total_sales, 0),
    COALESCE(v.deals_count, 0),
    v.score
  FROM public.race_leaderboard_view v
  WHERE v.season_id = _season_id
  ON CONFLICT (season_id, salesperson_id, snapshot_date) DO UPDATE
    SET rank = EXCLUDED.rank,
        progress = EXCLUDED.progress,
        total_sales = EXCLUDED.total_sales,
        deals_count = EXCLUDED.deals_count,
        score = EXCLUDED.score;

  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  RETURN inserted_count;
END;
$function$
;

