-- private.trigger_recalculate_deal_health()

CREATE OR REPLACE FUNCTION private.trigger_recalculate_deal_health()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale_id UUID;
BEGIN
  -- Get sale_id from the recording
  SELECT sale_id INTO v_sale_id 
  FROM public.call_recordings 
  WHERE id = NEW.recording_id;

  IF v_sale_id IS NOT NULL THEN
    UPDATE public.deal_health_scores
    SET calculated_at = now() - interval '1 day' -- Mark as stale
    WHERE sale_id = v_sale_id;
  END IF;
  
  RETURN NEW;
END;
$function$
;

-- private.trigger_refresh_monthly_summary()

CREATE OR REPLACE FUNCTION private.trigger_refresh_monthly_summary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'DELETE') THEN
        PERFORM private.refresh_monthly_sales_summary(to_char(OLD.created_at, 'YYYY-MM'));
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE'
           AND to_char(OLD.created_at, 'YYYY-MM') IS DISTINCT FROM to_char(NEW.created_at, 'YYYY-MM')) THEN
        PERFORM private.refresh_monthly_sales_summary(to_char(OLD.created_at, 'YYYY-MM'));
        PERFORM private.refresh_monthly_sales_summary(to_char(NEW.created_at, 'YYYY-MM'));
        RETURN NEW;
    ELSE
        PERFORM private.refresh_monthly_sales_summary(to_char(NEW.created_at, 'YYYY-MM'));
        RETURN NEW;
    END IF;
END;
$function$
;

