-- public.add_league_weekly_xp(p_salesperson_id uuid, p_xp integer)

CREATE OR REPLACE FUNCTION public.add_league_weekly_xp(p_salesperson_id uuid, p_xp integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_sp_id uuid;
BEGIN
  v_caller_sp_id := get_current_salesperson_id();
  IF v_caller_sp_id != p_salesperson_id AND NOT is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_xp <= 0 OR p_xp > 10000 THEN
    RAISE EXCEPTION 'Invalid XP amount';
  END IF;

  UPDATE public.league_members SET
    weekly_xp = weekly_xp + p_xp,
    updated_at = now()
  WHERE salesperson_id = p_salesperson_id;

  RETURN FOUND;
END;
$function$
;

-- public.add_salesperson_xp(p_salesperson_id uuid, p_xp_amount integer, p_source text)

CREATE OR REPLACE FUNCTION public.add_salesperson_xp(p_salesperson_id uuid, p_xp_amount integer, p_source text DEFAULT 'system'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
      DECLARE
        v_caller_sp_id uuid;
        v_level_base numeric;
      BEGIN
        v_caller_sp_id := get_current_salesperson_id();

        IF v_caller_sp_id != p_salesperson_id AND NOT is_admin_or_manager(auth.uid()) THEN
          RAISE EXCEPTION 'Not authorized';
        END IF;

        IF p_xp_amount <= 0 OR p_xp_amount > 10000 THEN
          RAISE EXCEPTION 'Invalid XP amount (must be 1-10000)';
        END IF;

        v_level_base := public.get_app_config_number('xp.level_base', 1000);

        UPDATE public.salesperson_xp SET
          total_xp = total_xp + p_xp_amount,
          current_level = GREATEST(current_level, 1 + floor((total_xp + p_xp_amount) / v_level_base)::int),
          updated_at = now()
        WHERE salesperson_id = p_salesperson_id;

        RETURN FOUND;
      END;
      $function$
;

-- public.admin_capture_rollback_snapshot()

CREATE OR REPLACE FUNCTION public.admin_capture_rollback_snapshot()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _id UUID;
  _commit BIGINT;
  _rollback BIGINT;
  _deadlocks BIGINT;
  _temp_files BIGINT;
  _temp_bytes BIGINT;
BEGIN
  SELECT xact_commit, xact_rollback, deadlocks, temp_files, temp_bytes
    INTO _commit, _rollback, _deadlocks, _temp_files, _temp_bytes
  FROM pg_stat_database
  WHERE datname = current_database();

  INSERT INTO public.db_rollback_snapshots (
    xact_commit, xact_rollback, deadlocks, temp_files, temp_bytes
  ) VALUES (_commit, _rollback, _deadlocks, _temp_files, _temp_bytes)
  RETURNING id INTO _id;

  RETURN _id;
END;
$function$
;

-- public.admin_edge_cron_status()

CREATE OR REPLACE FUNCTION public.admin_edge_cron_status()
 RETURNS TABLE(jobid bigint, jobname text, schedule text, active boolean, function_name text, last_status text, last_run_at timestamp with time zone, last_return_code integer, run_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
BEGIN
  IF NOT (
    public.is_admin_or_manager(auth.uid())
    OR (auth.jwt() ->> 'role') = 'service_role'
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  SELECT
    j.jobid,
    j.jobname,
    j.schedule,
    j.active,
    -- extrai o nome da function de 'SELECT public.trigger_internal_edge_job(''x'');'
    substring(j.command from 'trigger_internal_edge_job\(''([^'']+)''\)') AS function_name,
    lr.status AS last_status,
    lr.start_time AS last_run_at,
    (regexp_match(lr.return_message, 'status:\s*(\d{3})'))[1]::integer AS last_return_code,
    COALESCE(rc.n, 0) AS run_count
  FROM cron.job AS j
  LEFT JOIN LATERAL (
    SELECT status, start_time, return_message
    FROM cron.job_run_details AS d
    WHERE d.jobid = j.jobid
    ORDER BY d.start_time DESC
    LIMIT 1
  ) AS lr ON true
  LEFT JOIN LATERAL (
    SELECT count(*) AS n
    FROM cron.job_run_details AS d
    WHERE d.jobid = j.jobid
  ) AS rc ON true
  WHERE j.command ILIKE '%trigger_internal_edge_job%'
  ORDER BY j.jobname;
END;
$function$
;

-- public.admin_get_cron_job_stats(_limit integer)

CREATE OR REPLACE FUNCTION public.admin_get_cron_job_stats(_limit integer DEFAULT 50)
 RETURNS TABLE(jobid bigint, jobname text, status text, return_message text, start_time timestamp with time zone, end_time timestamp with time zone, duration_ms integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    d.jobid,
    j.jobname,
    d.status,
    d.return_message,
    d.start_time,
    d.end_time,
    (EXTRACT(EPOCH FROM (d.end_time - d.start_time)) * 1000)::int AS duration_ms
  FROM cron.job_run_details d
  JOIN cron.job j ON j.jobid = d.jobid
  ORDER BY d.start_time DESC
  LIMIT LEAST(GREATEST(_limit, 1), 500);
END;
$function$
;

-- public.admin_get_rollback_rate_series(_hours integer)

CREATE OR REPLACE FUNCTION public.admin_get_rollback_rate_series(_hours integer DEFAULT 24)
 RETURNS TABLE(captured_at timestamp with time zone, xact_commit bigint, xact_rollback bigint, deadlocks bigint, rollbacks_per_min numeric, commits_per_min numeric, rollback_ratio_pct numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH snap AS (
    SELECT
      s.captured_at,
      s.xact_commit,
      s.xact_rollback,
      s.deadlocks,
      LAG(s.xact_commit)   OVER (ORDER BY s.captured_at) AS prev_commit,
      LAG(s.xact_rollback) OVER (ORDER BY s.captured_at) AS prev_rollback,
      LAG(s.captured_at)   OVER (ORDER BY s.captured_at) AS prev_at
    FROM public.db_rollback_snapshots s
    WHERE s.captured_at > now() - make_interval(hours => GREATEST(_hours, 1))
      AND public.has_role(auth.uid(), 'admin')
  )
  SELECT
    captured_at,
    xact_commit,
    xact_rollback,
    deadlocks,
    CASE
      WHEN prev_at IS NULL OR EXTRACT(EPOCH FROM (captured_at - prev_at)) <= 0 THEN 0::NUMERIC
      WHEN xact_rollback < prev_rollback THEN 0::NUMERIC  -- reset de contador (reboot)
      ELSE round(((xact_rollback - prev_rollback)::NUMERIC * 60.0)
                 / EXTRACT(EPOCH FROM (captured_at - prev_at))::NUMERIC, 2)
    END AS rollbacks_per_min,
    CASE
      WHEN prev_at IS NULL OR EXTRACT(EPOCH FROM (captured_at - prev_at)) <= 0 THEN 0::NUMERIC
      WHEN xact_commit < prev_commit THEN 0::NUMERIC
      ELSE round(((xact_commit - prev_commit)::NUMERIC * 60.0)
                 / EXTRACT(EPOCH FROM (captured_at - prev_at))::NUMERIC, 2)
    END AS commits_per_min,
    CASE
      WHEN prev_at IS NULL OR (xact_commit - COALESCE(prev_commit,0)) + (xact_rollback - COALESCE(prev_rollback,0)) <= 0 THEN 0::NUMERIC
      WHEN xact_rollback < prev_rollback OR xact_commit < prev_commit THEN 0::NUMERIC
      ELSE round(((xact_rollback - prev_rollback)::NUMERIC * 100.0)
                 / NULLIF((xact_commit - prev_commit) + (xact_rollback - prev_rollback), 0), 2)
    END AS rollback_ratio_pct
  FROM snap
  ORDER BY captured_at ASC;
$function$
;

-- public.admin_reset_query_stats()

CREATE OR REPLACE FUNCTION public.admin_reset_query_stats()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'access denied' USING ERRCODE = '42501';
  END IF;
  PERFORM extensions.pg_stat_statements_reset();
  INSERT INTO public.maintenance_log(job_name, status, completed_at, metadata)
  VALUES ('pg_stat_statements_reset', 'completed', now(),
          jsonb_build_object('reset_by', auth.uid()));
END;
$function$
;

-- public.admin_top_queries(_limit integer)

CREATE OR REPLACE FUNCTION public.admin_top_queries(_limit integer DEFAULT 20)
 RETURNS TABLE(query text, calls bigint, total_exec_ms double precision, mean_exec_ms double precision, max_exec_ms double precision, rows_returned bigint, hit_ratio numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'access denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    left(pss.query, 500) AS query,
    pss.calls,
    round(pss.total_exec_time::numeric, 2)::double precision AS total_exec_ms,
    round(pss.mean_exec_time::numeric, 3)::double precision AS mean_exec_ms,
    round(pss.max_exec_time::numeric, 3)::double precision AS max_exec_ms,
    pss.rows AS rows_returned,
    CASE WHEN (pss.shared_blks_hit + pss.shared_blks_read) > 0
         THEN round(100.0 * pss.shared_blks_hit / (pss.shared_blks_hit + pss.shared_blks_read), 2)
         ELSE NULL END AS hit_ratio
  FROM extensions.pg_stat_statements pss
  JOIN pg_database d ON d.oid = pss.dbid AND d.datname = current_database()
  WHERE pss.query !~* '^(SET |BEGIN|COMMIT|ROLLBACK|SHOW |DEALLOCATE|DISCARD|VACUUM|ANALYZE|LISTEN|NOTIFY)'
    AND pss.query NOT ILIKE '%pg_stat_statements%'
    AND pss.query NOT ILIKE '%pg_catalog.%'
    AND pss.query NOT ILIKE '%information_schema.%'
    AND pss.query NOT ILIKE '%extensions.%'
  ORDER BY pss.total_exec_time DESC
  LIMIT LEAST(GREATEST(_limit, 1), 100);
END;
$function$
;

-- public.aggregate_sales_stats(user_id uuid, start_date date, end_date date)

CREATE OR REPLACE FUNCTION public.aggregate_sales_stats(user_id uuid, start_date date, end_date date)
 RETURNS TABLE(total_deals integer, total_value numeric, won_deals integer, won_value numeric, win_rate numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::INTEGER,
    COALESCE(SUM(value), 0),
    COUNT(*) FILTER (WHERE status = 'won')::INTEGER,
    COALESCE(SUM(value) FILTER (WHERE status = 'won'), 0),
    (COUNT(*) FILTER (WHERE status = 'won')::NUMERIC / NULLIF(COUNT(*), 0)) * 100
  FROM deals
  WHERE assigned_to = user_id
    AND created_at::DATE BETWEEN start_date AND end_date;
END;
$function$
;

-- public.anonymize_data_subject(p_subject_email text, p_subject_id uuid, p_phone text, p_ip text, p_request_id uuid)

CREATE OR REPLACE FUNCTION public.anonymize_data_subject(p_subject_email text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid, p_phone text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token text;
  v_name text;
  v_client_ids uuid[];
  v_salesperson_ids uuid[];
  v_counts jsonb := '{}'::jsonb;
  v_n bigint;
BEGIN
  IF auth.role() <> 'service_role'
     AND NOT public.is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden: somente admin/manager ou service_role podem anonimizar titulares';
  END IF;

  IF p_subject_email IS NULL AND p_subject_id IS NULL AND p_phone IS NULL AND p_ip IS NULL THEN
    RAISE EXCEPTION 'pelo menos um identificador do titular é obrigatório (email, subject_id, phone ou ip)';
  END IF;

  v_token := left(md5(
    coalesce(lower(p_subject_email), '') || '|' ||
    coalesce(p_subject_id::text, '') || '|' ||
    coalesce(p_phone, '')
  ), 16);
  v_name := 'Titular anonimizado ' || v_token;

  -- Captura o nome atual do titular (quando houver) para limpar colunas
  -- que só guardam o nome — usado SOMENTE dentro das vendas do próprio
  -- titular (v_client_ids), nunca como match global (homônimos).
  BEGIN
    SELECT name INTO v_name
    FROM public.clients
    WHERE (p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email))
       OR (p_subject_id IS NOT NULL AND id = p_subject_id)
       OR (p_phone IS NOT NULL AND phone IS NOT NULL
           AND public.canonical_phone_key(phone) = public.canonical_phone_key(p_phone))
    LIMIT 1;
    v_name := COALESCE(v_name, 'Titular anonimizado ' || v_token);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_name := 'Titular anonimizado ' || v_token;
  END;

  -- Ids dos clientes do titular: escopo id-based para as colunas que só
  -- guardam nome (activities.contact_name, buying_committee.contact_name).
  BEGIN
    SELECT array_agg(id) INTO v_client_ids
    FROM public.clients
    WHERE (p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email))
       OR (p_subject_id IS NOT NULL AND id = p_subject_id)
       OR (p_phone IS NOT NULL AND phone IS NOT NULL
           AND public.canonical_phone_key(phone) = public.canonical_phone_key(p_phone));
    v_client_ids := COALESCE(v_client_ids, '{}'::uuid[]);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_client_ids := '{}'::uuid[];
  END;

  -- Ids do titular como vendedor (quando é usuário interno): usado para
  -- quotes.seller_name — só por e-mail, o mesmo critério do UPDATE de
  -- salespeople abaixo.
  BEGIN
    SELECT array_agg(id) INTO v_salesperson_ids
    FROM public.salespeople
    WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    v_salesperson_ids := COALESCE(v_salesperson_ids, '{}'::uuid[]);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_salesperson_ids := '{}'::uuid[];
  END;

  -- ---- pessoas/contatos ----

  BEGIN
    UPDATE public.clients
       SET name = 'Titular anonimizado ' || v_token,
           email = 'anon-' || v_token || '@anon.invalid',
           phone = NULL,
           updated_at = now()
     WHERE (p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email))
        OR (p_subject_id IS NOT NULL AND id = p_subject_id)
        OR (p_phone IS NOT NULL AND phone IS NOT NULL
            AND public.canonical_phone_key(phone) = public.canonical_phone_key(p_phone));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('clients', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('clients', 0);
  END;

  BEGIN
    UPDATE public.account_contacts
       SET name = 'Titular anonimizado ' || v_token,
           email = 'anon-' || v_token || '@anon.invalid',
           phone = NULL,
           linkedin_url = NULL,
           notes = NULL
     WHERE (p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email))
        OR (p_phone IS NOT NULL AND phone IS NOT NULL
            AND public.canonical_phone_key(phone) = public.canonical_phone_key(p_phone));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('account_contacts', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('account_contacts', 0);
  END;

  BEGIN
    UPDATE public.person_intelligence
       SET full_name = 'Titular anonimizado ' || v_token,
           email = 'anon-' || v_token || '@anon.invalid',
           current_title = NULL,
           previous_titles = '[]'::jsonb,
           linkedin_url = NULL,
           updated_at = now()
     WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('person_intelligence', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('person_intelligence', 0);
  END;

  BEGIN
    UPDATE public.deal_stakeholders
       SET name = 'Titular anonimizado ' || v_token,
           email = 'anon-' || v_token || '@anon.invalid',
           phone = NULL,
           linkedin_url = NULL,
           notes = NULL
     WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('deal_stakeholders', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('deal_stakeholders', 0);
  END;

  BEGIN
    UPDATE public.buying_committee_members
       SET contact_name = 'Titular anonimizado ' || v_token,
           contact_email = 'anon-' || v_token || '@anon.invalid',
           notes = NULL
     WHERE p_subject_email IS NOT NULL AND lower(contact_email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('buying_committee_members', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('buying_committee_members', 0);
  END;

  -- buying_committee só tem contact_name: antes casava por nome global e
  -- destruía dados de homônimos. Agora limita às vendas do titular
  -- (client_id resolvido por e-mail/subject_id).
  BEGIN
    UPDATE public.buying_committee
       SET contact_name = 'Titular anonimizado ' || v_token,
           notes = NULL
     WHERE contact_name = v_name
       AND sale_id IN (
         SELECT s.id FROM public.sales s WHERE s.client_id = ANY(v_client_ids)
       );
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('buying_committee', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('buying_committee', 0);
  END;

  BEGIN
    UPDATE public.document_signers
       SET name = 'Titular anonimizado ' || v_token,
           email = 'anon-' || v_token || '@anon.invalid'
     WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('document_signers', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('document_signers', 0);
  END;

  BEGIN
    UPDATE public.csat_ces_surveys
       SET contact_email = 'anon-' || v_token || '@anon.invalid'
     WHERE p_subject_email IS NOT NULL AND lower(contact_email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('csat_ces_surveys', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('csat_ces_surveys', 0);
  END;

  -- Logs e filas de e-mail: recipient_email era PII preservada.
  BEGIN
    UPDATE public.email_logs
       SET recipient_email = 'anon-' || v_token || '@anon.invalid'
     WHERE p_subject_email IS NOT NULL AND lower(recipient_email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('email_logs', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('email_logs', 0);
  END;

  BEGIN
    UPDATE public.email_tracking_events
       SET recipient_email = 'anon-' || v_token || '@anon.invalid'
     WHERE p_subject_email IS NOT NULL AND lower(recipient_email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('email_tracking_events', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('email_tracking_events', 0);
  END;

  -- Rascunhos de envio em massa: além do e-mail, casa por client_id do
  -- titular (cobra o titular identificado só por telefone).
  BEGIN
    UPDATE public.email_bulk_drafts
       SET recipient_email = 'anon-' || v_token || '@anon.invalid',
           recipient_name = 'Titular anonimizado ' || v_token,
           updated_at = now()
     WHERE (p_subject_email IS NOT NULL AND lower(recipient_email) = lower(p_subject_email))
        OR client_id = ANY (v_client_ids);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('email_bulk_drafts', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('email_bulk_drafts', 0);
  END;

  -- Vendas do titular: client_name é PII do cliente da venda. Escopo por
  -- client_id — vendas sem client_id ficam de fora (match por nome seria
  -- homônimo-inseguro); documentado no cabeçalho.
  BEGIN
    UPDATE public.sales
       SET client_name = 'Titular anonimizado ' || v_token
     WHERE client_id = ANY (v_client_ids);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sales', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('sales', 0);
  END;

  -- Cotações do titular como cliente: client_name/e-mail/telefone. Match
  -- por client_id ou pelo e-mail gravado na cotação.
  BEGIN
    UPDATE public.quotes
       SET client_name = 'Titular anonimizado ' || v_token,
           client_email = 'anon-' || v_token || '@anon.invalid',
           client_phone = NULL
     WHERE client_id = ANY (v_client_ids)
        OR (p_subject_email IS NOT NULL AND lower(client_email) = lower(p_subject_email));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('quotes', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('quotes', 0);
  END;

  -- Cotações emitidas pelo titular como vendedor: seller_name é PII dele.
  BEGIN
    UPDATE public.quotes
       SET seller_name = 'Titular anonimizado ' || v_token
     WHERE created_by = ANY (v_salesperson_ids);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('quotes_seller', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('quotes_seller', 0);
  END;

  -- Transcrições/análises de conversa dos clientes do titular: transcript é
  -- NOT NULL, então recebe marcador; campos livres/arrays que podem conter
  -- nomes também são limpos. Órfãs (client_id NULL) casam via
  -- sale_id → sales.client_id.
  BEGIN
    UPDATE public.conversation_analyses
       SET transcript = 'Transcrição anonimizada',
           decision_makers = '{}'::text[],
           summary = NULL,
           objections = '[]'::jsonb,
           next_steps = '[]'::jsonb,
           buying_signals = '{}'::text[],
           risk_signals = '{}'::text[]
     WHERE client_id = ANY (v_client_ids)
        OR sale_id IN (
             SELECT s.id FROM public.sales s WHERE s.client_id = ANY(v_client_ids)
           );
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('conversation_analyses', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('conversation_analyses', 0);
  END;

  -- Pesquisas NPS das vendas do titular: client_name é NOT NULL (recebe
  -- marcador) e comment é texto livre que pode conter PII. Pesquisas sem
  -- sale_id não têm vínculo seguro — ficam de fora.
  BEGIN
    UPDATE public.nps_surveys
       SET client_name = 'Titular anonimizado ' || v_token,
           comment = NULL
     WHERE sale_id IN (
             SELECT s.id FROM public.sales s WHERE s.client_id = ANY(v_client_ids)
           );
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('nps_surveys', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('nps_surveys', 0);
  END;

  -- Estado de alertas de churn: só tem client_name (sem client_id). Match
  -- por nome limitado aos vendedores que têm venda com o titular — mesmo
  -- critério anti-homônimo de buying_committee/activities.
  BEGIN
    UPDATE public.client_churn_alerts_state
       SET client_name = 'Titular anonimizado ' || v_token
     WHERE client_name = v_name
       AND salesperson_id IN (
             SELECT DISTINCT s.salesperson_id
               FROM public.sales s
              WHERE s.client_id = ANY(v_client_ids)
                AND s.salesperson_id IS NOT NULL
           );
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('client_churn_alerts_state', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('client_churn_alerts_state', 0);
  END;

  -- Envios agendados: payload é JSONB livre (destino + corpo da mensagem
  -- com dados do titular). Tomba o payload e cancela envios ainda pendentes
  -- — continuar enviando a um titular eliminado viola a própria exclusão.
  BEGIN
    UPDATE public.scheduled_sends
       SET payload = '{"anonymized": true}'::jsonb,
           status = CASE WHEN status IN ('pending', 'processing')
                         THEN 'cancelled' ELSE status END
     WHERE sale_id IN (
             SELECT s.id FROM public.sales s WHERE s.client_id = ANY(v_client_ids)
           );
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('scheduled_sends', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('scheduled_sends', 0);
  END;

  -- Interações do titular: content/metadata são texto livre com PII.
  BEGIN
    UPDATE public.client_interactions
       SET content = NULL,
           metadata = NULL
     WHERE client_id = ANY (v_client_ids);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('client_interactions', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('client_interactions', 0);
  END;

  -- channel_interactions: casa por e-mail ou telefone canônico do titular
  -- em contact_info — o OR por contact_name global removia dados de
  -- homônimos que nunca foram o titular.
  BEGIN
    UPDATE public.channel_interactions
       SET contact_name = 'Titular anonimizado ' || v_token,
           contact_info = 'anon-' || v_token || '@anon.invalid'
     WHERE (p_subject_email IS NOT NULL AND lower(contact_info) = lower(p_subject_email))
        OR (p_phone IS NOT NULL
            AND (contact_info = p_phone
                 OR public.canonical_phone_key(contact_info) = public.canonical_phone_key(p_phone)));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('channel_interactions', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('channel_interactions', 0);
  END;

  -- activities só tem contact_name: mesmo critério do buying_committee —
  -- nome dentro das vendas do titular, nunca match global por nome.
  BEGIN
    UPDATE public.activities
       SET contact_name = 'Titular anonimizado ' || v_token
     WHERE contact_name = v_name
       AND sale_id IN (
         SELECT s.id FROM public.sales s WHERE s.client_id = ANY(v_client_ids)
       );
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('activities', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('activities', 0);
  END;

  BEGIN
    UPDATE public.suppliers
       SET contact_name = 'Titular anonimizado ' || v_token,
           email = 'anon-' || v_token || '@anon.invalid',
           phone = NULL,
           cnpj = NULL,
           address = NULL,
           updated_at = now()
     WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('suppliers', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('suppliers', 0);
  END;

  BEGIN
    UPDATE public.salespeople
       SET name = 'Titular anonimizado ' || v_token,
           email = 'anon-' || v_token || '@anon.invalid',
           avatar_url = NULL,
           updated_at = now()
     WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('salespeople', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('salespeople', 0);
  END;

  -- Tombstone de supressão: email_opt_outs NÃO é anonimizado. A lista de
  -- opt-out é a base legal para nunca mais contatar o titular — apagar o
  -- e-mail aqui faria um titular reimportado voltar a receber mensagens.
  BEGIN
    SELECT count(*) INTO v_n
    FROM public.email_opt_outs
    WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    v_counts := v_counts || jsonb_build_object('email_opt_outs_preserved', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('email_opt_outs_preserved', 0);
  END;

  BEGIN
    UPDATE public.notification_preferences
       SET email = 'anon-' || v_token || '@anon.invalid'
     WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('notification_preferences', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('notification_preferences', 0);
  END;

  -- ---- telefone (SMS/MFA/chamadas/mensagens) ----
  -- Match por canonical_phone_key (normaliza DDI 55/formatos); nas tabelas
  -- com user_id também casa pelo subject_id do titular.

  BEGIN
    UPDATE public.sms_verification_codes
       SET phone_number = 'anon-' || v_token
     WHERE (p_subject_id IS NOT NULL AND user_id = p_subject_id)
        OR (p_phone IS NOT NULL
            AND public.canonical_phone_key(phone_number) = public.canonical_phone_key(p_phone));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('sms_verification_codes', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('sms_verification_codes', 0);
  END;

  BEGIN
    UPDATE public.user_mfa_settings
       SET phone_number = NULL
     WHERE (p_subject_id IS NOT NULL AND user_id = p_subject_id)
        OR (p_phone IS NOT NULL
            AND public.canonical_phone_key(phone_number) = public.canonical_phone_key(p_phone));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('user_mfa_settings', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('user_mfa_settings', 0);
  END;

  BEGIN
    UPDATE public.twilio_call_sessions
       SET from_number = CASE
             WHEN p_phone IS NOT NULL
                  AND public.canonical_phone_key(from_number) = public.canonical_phone_key(p_phone)
             THEN 'anon-' || v_token ELSE from_number END,
           to_number   = CASE
             WHEN p_phone IS NOT NULL
                  AND public.canonical_phone_key(to_number) = public.canonical_phone_key(p_phone)
             THEN 'anon-' || v_token ELSE to_number END
     WHERE p_phone IS NOT NULL
       AND (public.canonical_phone_key(from_number) = public.canonical_phone_key(p_phone)
            OR public.canonical_phone_key(to_number) = public.canonical_phone_key(p_phone));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('twilio_call_sessions', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('twilio_call_sessions', 0);
  END;

  BEGIN
    UPDATE public.outbound_messages
       SET to_number = 'anon-' || v_token
     WHERE p_phone IS NOT NULL
       AND public.canonical_phone_key(to_number) = public.canonical_phone_key(p_phone);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('outbound_messages', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('outbound_messages', 0);
  END;

  BEGIN
    UPDATE public.integration_logs
       SET recipient = 'anon-' || v_token || '@anon.invalid'
     WHERE p_subject_email IS NOT NULL AND lower(recipient) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('integration_logs', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('integration_logs', 0);
  END;

  -- ---- website_visitor_logs (IP + empresa desanonimizada) ----

  BEGIN
    UPDATE public.website_visitor_logs
       SET ip_address = NULL,
           company_name = NULL,
           domain = NULL,
           referrer = NULL,
           legal_basis = 'anonymized',
           retention_expires_at = now()
     WHERE (p_ip IS NOT NULL AND ip_address::text = p_ip)
        OR consent_record_id IN (
             SELECT c.id FROM public.consent_records c
             WHERE c.subject_id = p_subject_id
                OR (p_subject_email IS NOT NULL AND lower(c.subject_email) = lower(p_subject_email))
           );
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('website_visitor_logs', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('website_visitor_logs', 0);
  END;

  -- ---- logs de segurança/sessão com IP e user-agent do titular ----

  BEGIN
    UPDATE public.audit_log
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('audit_log', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('audit_log', 0);
  END;

  BEGIN
    UPDATE public.audit_logs
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL
       AND (changed_by = p_subject_id OR actor_id = p_subject_id);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('audit_logs', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('audit_logs', 0);
  END;

  BEGIN
    UPDATE public.login_attempts
       SET email = 'anon-' || v_token || '@anon.invalid',
           ip_address = NULL,
           user_agent = NULL
     WHERE p_subject_email IS NOT NULL AND lower(email) = lower(p_subject_email);
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('login_attempts', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('login_attempts', 0);
  END;

  BEGIN
    UPDATE public.session_activity
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('session_activity', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('session_activity', 0);
  END;

  BEGIN
    UPDATE public.active_sessions
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('active_sessions', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('active_sessions', 0);
  END;

  BEGIN
    UPDATE public.known_devices
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('known_devices', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('known_devices', 0);
  END;

  BEGIN
    UPDATE public.security_events
       SET ip_address = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('security_events', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('security_events', 0);
  END;

  BEGIN
    UPDATE public.login_alerts
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('login_alerts', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('login_alerts', 0);
  END;

  BEGIN
    UPDATE public.mfa_verification_attempts
       SET ip_address = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('mfa_verification_attempts', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('mfa_verification_attempts', 0);
  END;

  BEGIN
    UPDATE public.password_reset_requests
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('password_reset_requests', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('password_reset_requests', 0);
  END;

  BEGIN
    UPDATE public.reauthentication_requests
       SET ip_address = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('reauthentication_requests', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('reauthentication_requests', 0);
  END;

  BEGIN
    UPDATE public.user_2fa_log
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('user_2fa_log', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('user_2fa_log', 0);
  END;

  BEGIN
    UPDATE public.access_denied_logs
       SET ip_address = NULL, user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('access_denied_logs', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('access_denied_logs', 0);
  END;

  BEGIN
    UPDATE public.error_logs
       SET user_agent = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('error_logs', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('error_logs', 0);
  END;

  BEGIN
    UPDATE public.web_vitals_samples
       SET user_agent = NULL, session_id = NULL
     WHERE p_subject_id IS NOT NULL AND user_id = p_subject_id;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('web_vitals_samples', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('web_vitals_samples', 0);
  END;

  -- Revoga consentimentos ativos do titular (registro da eliminação)
  BEGIN
    UPDATE public.consent_records
       SET revoked_at = now(), updated_at = now()
     WHERE revoked_at IS NULL
       AND (subject_id = p_subject_id
            OR (p_subject_email IS NOT NULL AND lower(subject_email) = lower(p_subject_email)));
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_counts := v_counts || jsonb_build_object('consent_records_revoked', v_n);
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    v_counts := v_counts || jsonb_build_object('consent_records_revoked', 0);
  END;

  -- mv_client_ltv carrega clients.name — sem refresh o nome antigo fica
  -- servido até a agenda de refresh_materialized_views() rodar. REFRESH
  -- sem CONCURRENTLY é permitido em função; falhas não abortam a
  -- anonimização (a agenda cobre o reprocessamento).
  BEGIN
    REFRESH MATERIALIZED VIEW public.mv_client_ltv;
    v_counts := v_counts || jsonb_build_object('mv_client_ltv_refreshed', true);
  EXCEPTION WHEN OTHERS THEN
    v_counts := v_counts || jsonb_build_object('mv_client_ltv_refreshed', false);
  END;

  -- Se a chamada veio de uma solicitação de titular, marca-a como concluída.
  IF p_request_id IS NOT NULL THEN
    UPDATE public.data_subject_requests
       SET status = 'completed',
           processed_by = auth.uid(),
           processed_at = now(),
           result = v_counts,
           updated_at = now()
     WHERE id = p_request_id;
  END IF;

  RETURN v_counts;
END;
$function$
;

-- public.append_agent_step(_run_id uuid, _tool_name text, _tool_input jsonb, _tool_output jsonb, _status text, _executed_by text)

CREATE OR REPLACE FUNCTION public.append_agent_step(_run_id uuid, _tool_name text, _tool_input jsonb, _tool_output jsonb, _status text DEFAULT 'success'::text, _executed_by text DEFAULT 'ai'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idx integer;
  v_sp uuid;
  v_owner uuid;
BEGIN
  -- Owner check (mesmo padrão de approve_agent_run): service_role bypassa;
  -- autenticado precisa ser dono do run ou admin/manager.
  SELECT salesperson_id INTO v_owner FROM public.ai_agent_runs WHERE id = _run_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Run not found';
  END IF;
  IF auth.role() <> 'service_role' THEN
    v_sp := public.get_current_salesperson_id();
    IF (v_sp IS NULL OR v_owner <> v_sp)
       AND NOT public.has_role(auth.uid(), 'admin')
       AND NOT public.has_role(auth.uid(), 'manager') THEN
      RAISE EXCEPTION 'Not authorized';
    END IF;
  END IF;

  SELECT COALESCE(MAX(step_index), -1) + 1 INTO v_idx
  FROM public.ai_agent_actions WHERE run_id = _run_id;

  INSERT INTO public.ai_agent_actions(run_id, step_index, tool_name, tool_input, tool_output, status, executed_by)
  VALUES (_run_id, v_idx, _tool_name, _tool_input, _tool_output, _status, _executed_by);

  UPDATE public.ai_agent_runs
  SET steps = steps || jsonb_build_object('index', v_idx, 'tool', _tool_name, 'status', _status),
      status = CASE WHEN status = 'pending' THEN 'running' ELSE status END,
      updated_at = now()
  WHERE id = _run_id;
END;
$function$
;

-- public.approve_agent_run(_run_id uuid)

CREATE OR REPLACE FUNCTION public.approve_agent_run(_run_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sp uuid;
  v_owner uuid;
BEGIN
  v_sp := public.get_current_salesperson_id();
  SELECT salesperson_id INTO v_owner FROM public.ai_agent_runs WHERE id = _run_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Run not found';
  END IF;
  -- v_sp NULL (autenticado sem salespeople) não autoriza — antes `v_owner <> v_sp`
  -- avaliava NULL e aprovar run alheio passava sem exceção.
  IF (v_sp IS NULL OR v_owner <> v_sp)
     AND NOT public.has_role(auth.uid(), 'admin')
     AND NOT public.has_role(auth.uid(), 'manager') THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;
  UPDATE public.ai_agent_runs
  SET status = 'running',
      approved_by = auth.uid(),
      updated_at = now()
  WHERE id = _run_id AND status = 'awaiting_approval';
END;
$function$
;

-- public.archive_old_activities(p_days_old integer)

CREATE OR REPLACE FUNCTION public.archive_old_activities(p_days_old integer DEFAULT 365)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_archived_count INTEGER;
BEGIN
  WITH archived AS (
    DELETE FROM activities
    WHERE created_at < NOW() - (p_days_old || ' days')::INTERVAL
    RETURNING *
  )
  INSERT INTO activities_archive
  SELECT * FROM archived;
  
  GET DIAGNOSTICS v_archived_count = ROW_COUNT;
  
  RETURN v_archived_count;
END;
$function$
;

-- public.archive_old_data(days_old integer)

CREATE OR REPLACE FUNCTION public.archive_old_data(days_old integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  archived_count INT;
BEGIN
  WITH archived AS (
    UPDATE deals
    SET deleted_at = NOW()
    WHERE status = 'lost'
      AND updated_at < NOW() - (days_old || ' days')::INTERVAL
      AND deleted_at IS NULL
    RETURNING id
  )
  SELECT COUNT(*) INTO archived_count FROM archived;
  
  RETURN archived_count;
END;
$function$
;

-- public.assign_task_to_squad(_catalog_id uuid, _squad_id uuid, _due_date date, _recurrence text)

CREATE OR REPLACE FUNCTION public.assign_task_to_squad(_catalog_id uuid, _squad_id uuid, _due_date date DEFAULT NULL::date, _recurrence text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _count INTEGER := 0;
  _parent_id UUID := gen_random_uuid();
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Only admins can assign tasks to squads';
  END IF;

  INSERT INTO public.task_assignments (catalog_id, assigned_to, assigned_by, due_date, squad_id, recurrence_rule, parent_recurrence_id)
  SELECT _catalog_id, sm.user_id, auth.uid(), _due_date, _squad_id, _recurrence,
         CASE WHEN _recurrence IS NOT NULL THEN _parent_id ELSE NULL END
  FROM public.squad_members sm
  WHERE sm.squad_id = _squad_id;

  GET DIAGNOSTICS _count = ROW_COUNT;
  RETURN _count;
END;
$function$
;

-- public.audit_activity_changes()

CREATE OR REPLACE FUNCTION public.audit_activity_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.activity_audit_logs (activity_id, changed_by, old_data, new_data, action)
        VALUES (OLD.id, auth.uid(), to_jsonb(OLD), to_jsonb(NEW), 'UPDATE');
    ELSIF (TG_OP = 'DELETE') THEN
        INSERT INTO public.activity_audit_logs (activity_id, changed_by, old_data, action)
        VALUES (OLD.id, auth.uid(), to_jsonb(OLD), 'DELETE');
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.audit_log_row_change()

CREATE OR REPLACE FUNCTION public.audit_log_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor UUID;
  v_email TEXT;
  v_req TEXT;
  v_old JSONB;
  v_new JSONB;
  v_id TEXT;
BEGIN
  v_actor := auth.uid();

  IF v_actor IS NOT NULL THEN
    SELECT email INTO v_email FROM auth.users WHERE id = v_actor;
  END IF;

  -- X-Request-Id propagado pelo PostgREST/edge functions (quando presente)
  BEGIN
    v_req := current_setting('request.headers', true)::jsonb ->> 'x-request-id';
  EXCEPTION WHEN OTHERS THEN
    v_req := NULL;
  END;

  v_old := CASE WHEN TG_OP IN ('UPDATE', 'DELETE')
                THEN public.audit_scrub(to_jsonb(OLD)) END;
  v_new := CASE WHEN TG_OP IN ('INSERT', 'UPDATE')
                THEN public.audit_scrub(to_jsonb(NEW)) END;

  IF TG_OP = 'DELETE' THEN
    v_id := to_jsonb(OLD) ->> 'id';
  ELSE
    v_id := to_jsonb(NEW) ->> 'id';
  END IF;

  INSERT INTO public.audit_logs (
    actor_id, actor_email, action,
    entity_type, entity_id,
    table_name, record_id,
    old_data, new_data, changes,
    request_id, metadata
  ) VALUES (
    v_actor, v_email, TG_OP,
    TG_TABLE_NAME, v_id,
    TG_TABLE_NAME, v_id,
    v_old, v_new,
    jsonb_build_object('old', v_old, 'new', v_new),
    v_req, '{}'::jsonb
  );

  RETURN COALESCE(NEW, OLD);
END;
$function$
;

-- public.audit_scrub(p_data jsonb)

CREATE OR REPLACE FUNCTION public.audit_scrub(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  sensitive_exact TEXT[] := ARRAY[
    'password', 'password_hash', 'hashed_password', 'passphrase',
    'token', 'access_token', 'refresh_token', 'id_token',
    'api_key', 'apikey', 'secret', 'client_secret',
    'mfa_secret', 'totp_secret', 'otp', 'otp_code',
    'authorization', 'cookie', 'session_id', 'session',
    'private_key', 'service_role_key', 'anon_key', 'jwt',
    'credit_card', 'card_number', 'cvv', 'cpf'
  ];
  k TEXT;
  v JSONB;
  result JSONB := '{}'::jsonb;
BEGIN
  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' THEN
    RETURN p_data;
  END IF;

  FOR k, v IN SELECT key, value FROM jsonb_each(p_data) LOOP
    IF lower(k) = ANY (sensitive_exact)
       OR lower(k) LIKE '%\_token' ESCAPE '\'
       OR lower(k) LIKE '%\_secret' ESCAPE '\'
       OR lower(k) LIKE '%password%' THEN
      result := result || jsonb_build_object(k, '[REDACTED]');
    ELSIF jsonb_typeof(v) = 'object' THEN
      result := result || jsonb_build_object(k, public.audit_scrub(v));
    ELSE
      result := result || jsonb_build_object(k, v);
    END IF;
  END LOOP;

  RETURN result;
END;
$function$
;

-- public.audit_trigger()

CREATE OR REPLACE FUNCTION public.audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO audit_log (
    user_id,
    action,
    table_name,
    record_id,
    old_values,
    new_values
  ) VALUES (
    auth.uid(),
    TG_OP,
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
  );
  RETURN COALESCE(NEW, OLD);
END;
$function$
;

-- public.audit_trigger_func()

CREATE OR REPLACE FUNCTION public.audit_trigger_func()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  old_data JSONB;
  new_data JSONB;
  excluded_cols TEXT[] := ARRAY[]::TEXT[];
BEGIN
  IF TG_ARGV[0] IS NOT NULL THEN
    excluded_cols := TG_ARGV[0]::TEXT[];
  END IF;

  IF (TG_OP = 'UPDATE') THEN
    old_data := to_jsonb(OLD);
    new_data := to_jsonb(NEW);

    INSERT INTO audit_log (user_id, action, table_name, record_id, old_data, new_data)
    VALUES (auth.uid(), 'UPDATE', TG_TABLE_NAME, NEW.id::TEXT::uuid, old_data, new_data);

    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    old_data := to_jsonb(OLD);

    INSERT INTO audit_log (user_id, action, table_name, record_id, old_data)
    VALUES (auth.uid(), 'DELETE', TG_TABLE_NAME, OLD.id::TEXT::uuid, old_data);

    RETURN OLD;
  ELSIF (TG_OP = 'INSERT') THEN
    new_data := to_jsonb(NEW);

    INSERT INTO audit_log (user_id, action, table_name, record_id, new_data)
    VALUES (auth.uid(), 'INSERT', TG_TABLE_NAME, NEW.id::TEXT::uuid, new_data);

    RETURN NEW;
  END IF;

  RETURN NULL;
END;
$function$
;

-- public.audit_user_roles_change()

CREATE OR REPLACE FUNCTION public.audit_user_roles_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_email text := COALESCE(auth.jwt() ->> 'email', '');
  v_target uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.user_id ELSE NEW.user_id END;
  v_entity_id text := CASE WHEN TG_OP = 'DELETE' THEN OLD.id::text ELSE NEW.id::text END;
  v_new_role text := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE NEW.role::text END;
  v_old_role text := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.role::text END;
BEGIN
  IF to_regclass('public.audit_logs') IS NOT NULL THEN
    INSERT INTO public.audit_logs (
      actor_id, actor_email, action, entity_type, entity_id, changes, metadata
    ) VALUES (
      v_actor,
      NULLIF(v_actor_email, ''),
      'user_roles.' || lower(TG_OP),
      'user_roles',
      v_entity_id,
      jsonb_build_object(
        'old', CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
        'new', CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END
      ),
      jsonb_build_object(
        'source', 'audit_user_roles_change',
        'target_user_id', v_target
      )
    );
  END IF;

  IF to_regclass('public.security_events') IS NOT NULL
     AND (v_new_role = 'admin' OR v_old_role = 'admin') THEN
    INSERT INTO public.security_events (
      event_type, user_id, severity, description, metadata
    ) VALUES (
      CASE
        WHEN TG_OP = 'INSERT'
          OR (TG_OP = 'UPDATE' AND v_new_role = 'admin' AND v_old_role IS DISTINCT FROM 'admin')
          THEN 'admin_role_granted'
        WHEN TG_OP = 'DELETE'
          OR (TG_OP = 'UPDATE' AND v_old_role = 'admin' AND v_new_role IS DISTINCT FROM 'admin')
          THEN 'admin_role_revoked'
        ELSE 'admin_role_changed'
      END,
      v_target,
      'high',
      format('user_roles %s por %s', lower(TG_OP), COALESCE(v_actor::text, 'service_role/anon')),
      jsonb_build_object(
        'actor_id', v_actor,
        'actor_email', NULLIF(v_actor_email, ''),
        'row_id', v_entity_id,
        'old_role', v_old_role,
        'new_role', v_new_role
      )
    );
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.auto_add_client_to_portfolio()

CREATE OR REPLACE FUNCTION public.auto_add_client_to_portfolio()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sp UUID;
BEGIN
  -- Tenta descobrir o salesperson do usuário atual
  BEGIN
    v_sp := get_current_salesperson_id();
  EXCEPTION WHEN OTHERS THEN
    v_sp := NULL;
  END;

  -- Se não há salesperson (webhook/integração), não cria portfólio agora
  IF v_sp IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.client_portfolio (client_id, salesperson_id, status)
  VALUES (NEW.id, v_sp, 'active')
  ON CONFLICT (client_id, salesperson_id) DO NOTHING;

  RETURN NEW;
END;
$function$
;

-- public.auto_assign_lead(_sale_id uuid)

CREATE OR REPLACE FUNCTION public.auto_assign_lead(_sale_id uuid)
 RETURNS TABLE(assigned_to uuid, strategy text, rule_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule public.lead_routing_rules%ROWTYPE;
  v_sale public.sales%ROWTYPE;
  v_existing public.lead_assignments%ROWTYPE;
  v_chosen uuid;
BEGIN
  IF auth.role() <> 'service_role'
    AND (auth.uid() IS NULL OR NOT public.is_admin_or_manager(auth.uid())) THEN
    RAISE EXCEPTION 'Apenas administradores e gestores podem atribuir leads'
      USING ERRCODE = '42501';
  END IF;

  IF _sale_id IS NULL THEN
    RAISE EXCEPTION 'sale_id é obrigatório' USING ERRCODE = '22023';
  END IF;

  -- Evita que duas atribuições simultâneas escolham o mesmo vendedor a partir
  -- da mesma carga. O lock da venda garante idempotência da chamada repetida.
  PERFORM pg_advisory_xact_lock(hashtextextended('auto_assign_lead', 0));

  SELECT *
  INTO v_sale
  FROM public.sales
  WHERE id = _sale_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada' USING ERRCODE = 'P0002';
  END IF;

  IF v_sale.salesperson_id IS NOT NULL THEN
    SELECT *
    INTO v_existing
    FROM public.lead_assignments
    WHERE sale_id = _sale_id
    ORDER BY assigned_at DESC, id DESC
    LIMIT 1;

    RETURN QUERY
      SELECT v_sale.salesperson_id,
             COALESCE(v_existing.strategy_used, 'already_assigned'),
             v_existing.rule_id;
    RETURN;
  END IF;

  SELECT *
  INTO v_rule
  FROM public.lead_routing_rules
  WHERE is_active IS TRUE
    AND (filter_min_value IS NULL OR v_sale.amount >= filter_min_value)
    AND (filter_source IS NULL OR filter_source = v_sale.source)
  ORDER BY priority ASC, created_at ASC, id ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nenhuma regra ativa é compatível com a venda'
      USING ERRCODE = 'P0001';
  END IF;

  IF v_rule.strategy = 'round_robin' THEN
    SELECT s.id
    INTO v_chosen
    FROM public.salespeople AS s
    LEFT JOIN public.lead_assignments AS la ON la.salesperson_id = s.id
    WHERE s.is_active IS TRUE
    GROUP BY s.id
    ORDER BY MAX(la.assigned_at) NULLS FIRST, s.id
    LIMIT 1;
  ELSIF v_rule.strategy = 'least_loaded' THEN
    SELECT s.id
    INTO v_chosen
    FROM public.salespeople AS s
    LEFT JOIN public.sales AS sa
      ON sa.salesperson_id = s.id
      AND sa.status NOT IN ('completed', 'won', 'closed', 'lost', 'cancelled')
    WHERE s.is_active IS TRUE
    GROUP BY s.id
    ORDER BY COUNT(sa.id) ASC, s.id
    LIMIT 1;
  ELSIF v_rule.strategy = 'top_performer' THEN
    SELECT s.id
    INTO v_chosen
    FROM public.salespeople AS s
    LEFT JOIN public.sales AS sa
      ON sa.salesperson_id = s.id
      AND sa.status IN ('completed', 'won', 'closed')
    WHERE s.is_active IS TRUE
    GROUP BY s.id
    ORDER BY COALESCE(SUM(sa.amount), 0) DESC, s.id
    LIMIT 1;
  ELSE
    RAISE EXCEPTION 'Estratégia de regra não suportada: %', v_rule.strategy
      USING ERRCODE = '22023';
  END IF;

  IF v_chosen IS NULL THEN
    RAISE EXCEPTION 'Nenhum vendedor ativo está disponível para atribuição'
      USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.sales
  SET salesperson_id = v_chosen
  WHERE id = _sale_id
    AND salesperson_id IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'A venda já foi atribuída por outra operação'
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.lead_assignments (
    sale_id,
    salesperson_id,
    rule_id,
    strategy_used
  ) VALUES (
    _sale_id,
    v_chosen,
    v_rule.id,
    v_rule.strategy
  );

  RETURN QUERY SELECT v_chosen, v_rule.strategy, v_rule.id;
END;
$function$
;

-- public.auto_create_sale_followup()

