-- public.auto_victory_post()

CREATE OR REPLACE FUNCTION public.auto_victory_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF TG_TABLE_NAME = 'sales' THEN
        IF NEW.deal_status = 'completed' AND NEW.amount >= 5000 THEN
            INSERT INTO public.victory_feed (salesperson_id, title, description, value, event_type)
            VALUES (
                NEW.salesperson_id,
                'Fechamento Épico! 🚀',
                'Selou um deal de ' || NEW.product_name || ' para ' || NEW.client_name,
                NEW.amount,
                'sale'
            );
            -- NOTE: salespeople.available_spins does not exist in this schema;
            -- prize-wheel-spin reward is disabled here until that reward
            -- mechanism is (re)wired to an actual column/table.
        END IF;
    ELSIF TG_TABLE_NAME = 'sales_battles' THEN
        IF NEW.status = 'completed' AND NEW.winner_id IS NOT NULL THEN
            INSERT INTO public.victory_feed (salesperson_id, title, description, event_type)
            VALUES (
                NEW.winner_id,
                'Campeão da Arena! 🏆',
                'Venceu a batalha: ' || NEW.title,
                'achievement'
            );
            -- NOTE: salespeople.xp / available_spins do not exist in this schema;
            -- XP + spin reward is disabled here until that reward mechanism is
            -- (re)wired to an actual column/table (e.g. xp_transactions, as
            -- private.handle_performance_update already does for bets).
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
;

-- public.award_bonus_if_eligible(_bonus_id uuid, _computed_amount numeric, _bonus_kind text)

CREATE OR REPLACE FUNCTION public.award_bonus_if_eligible(_bonus_id uuid, _computed_amount numeric, _bonus_kind text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sp_id uuid;
  _bonus record;
  _period date := date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo')::date;
  _existing uuid;
  _new_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  -- Deriva salesperson_id do usuário autenticado (impossível forjar)
  SELECT id INTO _sp_id FROM public.salespeople WHERE auth_user_id = auth.uid() LIMIT 1;
  IF _sp_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Valida bônus ativo e elegibilidade de escopo (individual/global)
  SELECT * INTO _bonus FROM public.commission_bonuses WHERE id = _bonus_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Se o bônus tem alvo individual, precisa ser o próprio vendedor
  IF _bonus.salesperson_id IS NOT NULL AND _bonus.salesperson_id <> _sp_id THEN
    RETURN NULL;
  END IF;

  -- Idempotência: já registrado no mês?
  SELECT id INTO _existing
  FROM public.commission_bonus_awards
  WHERE bonus_id = _bonus_id
    AND salesperson_id = _sp_id
    AND period_month = _period
  LIMIT 1;

  IF _existing IS NOT NULL THEN
    RETURN _existing;
  END IF;

  -- Valor/tipo vêm da regra no banco — o cliente não pode forjar o prêmio.
  INSERT INTO public.commission_bonus_awards (
    bonus_id, salesperson_id, period_month, computed_amount, bonus_kind, status
  ) VALUES (
    _bonus_id, _sp_id, _period, _bonus.bonus_amount, _bonus.bonus_kind, 'pending'
  )
  ON CONFLICT (bonus_id, salesperson_id, period_month) DO NOTHING
  RETURNING id INTO _new_id;

  RETURN _new_id;
END;
$function$
;

-- public.award_sale_xp(p_sale_id uuid)

CREATE OR REPLACE FUNCTION public.award_sale_xp(p_sale_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sale record;
  v_per_1000 numeric;
  v_xp integer;
  v_old_xp integer;
  v_new_xp integer;
  v_thresholds jsonb;
  v_prev_level integer;
  v_new_level integer;
  v_full_result boolean;
BEGIN
  -- service_role não carrega uid de usuário: o GRANT já é a fronteira —
  -- a concessão é feita em nome do dono da venda, nunca do caller.
  IF auth.role() IS DISTINCT FROM 'service_role' AND auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória' USING ERRCODE = '28000';
  END IF;

  SELECT id, salesperson_id, amount, status, client_name
    INTO v_sale
    FROM public.sales
   WHERE id = p_sale_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada' USING ERRCODE = 'P0002';
  END IF;

  -- Posse: todo cliente recebe o broadcast e pode disparar o crédito
  -- (idempotente por sale_id), mas só o dono da venda, admin/manager ou
  -- service_role recebem os totais — os demais recebem {'awarded': true}.
  v_full_result := auth.role() = 'service_role'
    OR public.is_admin_or_manager(auth.uid())
    OR v_sale.salesperson_id = public.get_current_salesperson_id();

  -- Status ganho canônico: WON/COUNTED = ('completed','won','closed').
  IF v_sale.status IS NULL
     OR NOT (v_sale.status = ANY (ARRAY['completed','won','closed'])) THEN
    RETURN jsonb_build_object('awarded', false, 'reason', 'sale_not_won');
  END IF;

  IF v_sale.salesperson_id IS NULL THEN
    RETURN jsonb_build_object('awarded', false, 'reason', 'no_salesperson');
  END IF;

  v_per_1000 := COALESCE(
    (SELECT (value ->> 'SALE_PER_1000')::numeric
       FROM public.app_config WHERE key = 'xp.rewards'),
    10
  );
  v_xp := (floor(v_sale.amount / 1000) * v_per_1000)::int;
  IF v_xp <= 0 THEN
    RETURN jsonb_build_object('awarded', false, 'reason', 'no_xp', 'xp_awarded', 0);
  END IF;

  -- Idempotência: N clientes recebem o broadcast e chamam juntos — o lock
  -- por sale_id serializa e o check em xp_history credita uma única vez.
  PERFORM pg_advisory_xact_lock(hashtext('award_sale_xp:' || p_sale_id::text));

  IF EXISTS (
    SELECT 1 FROM public.xp_history
     WHERE source_type = 'sale' AND source_id = p_sale_id::text
  ) THEN
    RETURN jsonb_build_object('awarded', false, 'reason', 'already_awarded', 'xp_awarded', 0);
  END IF;

  SELECT total_xp INTO v_old_xp
    FROM public.salesperson_xp
   WHERE salesperson_id = v_sale.salesperson_id;
  v_old_xp := COALESCE(v_old_xp, 0);
  v_new_xp := v_old_xp + v_xp;

  INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
  VALUES (
    v_sale.salesperson_id, v_xp, 'sale', p_sale_id::text,
    'Venda de R$ ' || to_char(v_sale.amount, 'FM999G999G990D00')
      || CASE WHEN v_sale.client_name IS NOT NULL
              THEN ' — ' || v_sale.client_name ELSE '' END
  );

  -- Nível pelos thresholds vivos do app_config (mesma regra do frontend:
  -- nível = quantidade de thresholds <= total_xp).
  SELECT value INTO v_thresholds
    FROM public.app_config WHERE key = 'xp.level_thresholds';
  v_thresholds := COALESCE(v_thresholds,
    '[0,100,250,500,850,1300,1900,2700,3700,5000,6500,8500,11000,14000,18000,23000,30000,40000,55000,75000]'::jsonb);

  SELECT count(*) INTO v_new_level
    FROM jsonb_array_elements_text(v_thresholds) AS t(v)
   WHERE v::numeric <= v_new_xp;
  v_new_level := GREATEST(v_new_level, 1);
  SELECT count(*) INTO v_prev_level
    FROM jsonb_array_elements_text(v_thresholds) AS t(v)
   WHERE v::numeric <= v_old_xp;
  v_prev_level := GREATEST(v_prev_level, 1);

  UPDATE public.salesperson_xp
     SET current_level = GREATEST(current_level, v_new_level),
         updated_at = now()
   WHERE salesperson_id = v_sale.salesperson_id;

  IF NOT v_full_result THEN
    RETURN jsonb_build_object('awarded', true);
  END IF;

  RETURN jsonb_build_object(
    'awarded', true,
    'xp_awarded', v_xp,
    'leveled_up', v_new_level > v_prev_level,
    'new_level', v_new_level,
    'previous_level', v_prev_level,
    'total_xp', v_new_xp
  );
END;
$function$
;

-- public.award_salesperson_xp(p_salesperson_id uuid, p_xp_amount integer, p_description text, p_source_type text, p_source_id uuid)

CREATE OR REPLACE FUNCTION public.award_salesperson_xp(p_salesperson_id uuid, p_xp_amount integer, p_description text, p_source_type text, p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_old_xp INTEGER;
    v_new_xp INTEGER;
    v_old_level INTEGER;
    v_new_level INTEGER;
    v_xp_step INTEGER := 1000;
    v_result JSONB;
BEGIN
    -- Amount arbitrário não pode vir do cliente: só service_role (edge
    -- functions/cron). auth.role() é NULL em SQL direto (migrations/admin),
    -- que segue autorizado.
    IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
        RAISE EXCEPTION 'forbidden: award_salesperson_xp é interno (service_role)';
    END IF;

    INSERT INTO public.salesperson_xp (salesperson_id, total_xp, current_level, updated_at)
    VALUES (p_salesperson_id, p_xp_amount, 1, now())
    ON CONFLICT (salesperson_id) DO UPDATE
    SET total_xp = salesperson_xp.total_xp + EXCLUDED.total_xp,
        updated_at = now()
    RETURNING total_xp, current_level INTO v_new_xp, v_old_level;

    v_new_level := floor(v_new_xp / v_xp_step) + 1;

    IF v_new_level > v_old_level THEN
        UPDATE public.salesperson_xp
        SET current_level = v_new_level
        WHERE salesperson_id = p_salesperson_id;
    END IF;

    INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
    VALUES (p_salesperson_id, p_xp_amount, p_source_type, p_source_id::text, p_description);

    SELECT jsonb_build_object(
        'leveled_up', v_new_level > v_old_level,
        'new_level', v_new_level,
        'total_xp', v_new_xp
    ) INTO v_result;

    RETURN v_result;
END;
$function$
;

-- public.backfill_orders_conversion_seq()

CREATE OR REPLACE FUNCTION public.backfill_orders_conversion_seq()
 RETURNS TABLE(previous_value bigint, new_value bigint, legacy_max bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev    bigint;
  v_legacy  bigint;
  v_target  bigint;
BEGIN
  -- Serializa qualquer backfill/conversão concorrente
  PERFORM pg_advisory_xact_lock(hashtext('orders_conversion_seq_backfill'));

  SELECT last_value INTO v_prev FROM public.orders_conversion_seq;

  -- Extrai maior NNNNNNNN de qualquer order_number ORC-YYYYMMDD-NNNNNNNN
  SELECT COALESCE(MAX((regexp_match(order_number, '^ORC-\d{8}-(\d+)$'))[1]::bigint), 0)
    INTO v_legacy
    FROM public.orders
   WHERE order_number ~ '^ORC-\d{8}-\d+$';

  v_target := GREATEST(v_prev, v_legacy);

  -- setval com is_called=true => próximo nextval() = v_target + 1
  PERFORM setval('public.orders_conversion_seq', v_target, true);

  RETURN QUERY SELECT v_prev, v_target, v_legacy;
END;
$function$
;

-- public.broadcast_sale_completed()

CREATE OR REPLACE FUNCTION public.broadcast_sale_completed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
DECLARE
  v_payload jsonb;
  v_base_url text;
  v_anon_key text;
  v_cron_secret text;
BEGIN
  IF NEW.deal_status IS DISTINCT FROM 'completed' THEN
    RETURN NEW;
  END IF;

  -- Dispara apenas na transição para venda ganha OU quando uma venda já
  -- WON ganha dono depois (OLD.salesperson_id NULL → NEW preenchido).
  -- Se o enqueue falhar, a venda fica com broadcast_sent_at nulo e
  -- o erro em edge_call_failures — sem re-tentar a cada update posterior.
  IF TG_OP = 'UPDATE'
     AND OLD.deal_status = 'completed'
     AND OLD.salesperson_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Evita rebroadcast da mesma venda já entregue.
  IF NEW.broadcast_sent_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.salesperson_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- A edge function lê os dados da venda no banco; o corpo carrega só o id.
  v_payload := jsonb_build_object('sale_id', NEW.id);

  SELECT
    max(s.value) FILTER (WHERE s.key = 'functions_base_url'),
    max(s.value) FILTER (WHERE s.key = 'anon_key'),
    max(s.value) FILTER (WHERE s.key = 'coaching_cron_secret')
  INTO v_base_url, v_anon_key, v_cron_secret
  FROM public._internal_secrets AS s;

  IF v_base_url IS NULL OR v_anon_key IS NULL OR v_cron_secret IS NULL THEN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('broadcast_sale_completed', 'broadcast-sale-notification',
            jsonb_build_object('sale_id', NEW.id), 'internal_edge_secrets_missing');
    RETURN NEW;
  END IF;
  IF v_base_url !~ '^https://[^[:space:]]+$' THEN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('broadcast_sale_completed', 'broadcast-sale-notification',
            jsonb_build_object('sale_id', NEW.id), 'internal_edge_base_url_must_be_https');
    RETURN NEW;
  END IF;

  PERFORM net.http_post(
    url := rtrim(v_base_url, '/') || '/broadcast-sale-notification',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_anon_key,
      'Authorization', 'Bearer ' || v_anon_key,
      'X-Cron-Secret', v_cron_secret
    ),
    body := v_payload
  );

  -- Marca como enviada somente quando o enqueue foi aceito pelo pg_net.
  UPDATE public.sales
  SET broadcast_sent_at = now(), updated_at = now()
  WHERE id = NEW.id;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Nunca quebrar a inserção da venda, mas deixar a falha visível.
  BEGIN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('broadcast_sale_completed', 'broadcast-sale-notification',
            jsonb_build_object('sale_id', NEW.id), SQLERRM);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RAISE WARNING 'broadcast_sale_completed failed: %', SQLERRM;
  RETURN NEW;
END;
$function$
;

-- public.bulk_approve_assignments(_ids uuid[], _xp_overrides jsonb)

CREATE OR REPLACE FUNCTION public.bulk_approve_assignments(_ids uuid[], _xp_overrides jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _id UUID;
  _xp INTEGER;
  _processed INTEGER := 0;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Only admins can bulk approve';
  END IF;

  FOREACH _id IN ARRAY _ids LOOP
    SELECT COALESCE(
      NULLIF(_xp_overrides->>(_id::text), '')::INTEGER,
      (SELECT tc.xp_reward FROM public.task_assignments ta JOIN public.task_catalog tc ON tc.id = ta.catalog_id WHERE ta.id = _id)
    ) INTO _xp;

    PERFORM public.grant_task_xp(_id, _xp, 'Aprovação em lote');
    _processed := _processed + 1;
  END LOOP;

  RETURN _processed;
END;
$function$
;

-- public.bulk_recompute_engagement(_owner_id uuid)

CREATE OR REPLACE FUNCTION public.bulk_recompute_engagement(_owner_id uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count INTEGER := 0;
  r RECORD;
BEGIN
  FOR r IN
    SELECT DISTINCT cstp.contact_id, cstp.contact_type
    FROM public.contact_send_time_profile cstp
    WHERE cstp.updated_at >= now() - interval '30 days'
      AND (
        _owner_id IS NULL
        OR (
          cstp.contact_type = 'lead' AND EXISTS (
            SELECT 1 FROM public.sales s WHERE s.id = cstp.contact_id AND s.salesperson_id = _owner_id
          )
        )
        OR (
          cstp.contact_type = 'client' AND EXISTS (
            SELECT 1 FROM public.client_portfolio cp WHERE cp.client_id = cstp.contact_id AND cp.salesperson_id = _owner_id
          )
        )
      )
  LOOP
    PERFORM public.recompute_engagement_score(r.contact_id, r.contact_type);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$
;

-- public.bulk_update_deal_stages(p_deal_ids uuid[], p_new_stage text)

CREATE OR REPLACE FUNCTION public.bulk_update_deal_stages(p_deal_ids uuid[], p_new_stage text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_updated_count INTEGER;
BEGIN
  UPDATE deals
  SET stage = p_new_stage, updated_at = NOW()
  WHERE id = ANY(p_deal_ids);
  
  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  
  RETURN v_updated_count;
END;
$function$
;

-- public.bump_row_version()

CREATE OR REPLACE FUNCTION public.bump_row_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.version := COALESCE(OLD.version, 0) + 1;
  RETURN NEW;
END;
$function$
;

-- public.calculate_account_score(p_account_id uuid)

CREATE OR REPLACE FUNCTION public.calculate_account_score(p_account_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_score INTEGER := 0;
  v_contacts INTEGER;
  v_decision_makers INTEGER;
  v_champions INTEGER;
  v_recent_activities INTEGER;
  v_tier TEXT;
BEGIN
  SELECT tier INTO v_tier FROM accounts WHERE id = p_account_id;

  -- Tier base
  v_score := v_score + CASE v_tier
    WHEN 'strategic' THEN 30
    WHEN 'enterprise' THEN 22
    WHEN 'mid_market' THEN 15
    ELSE 8
  END;

  -- Contacts coverage
  SELECT COUNT(*) INTO v_contacts FROM account_contacts WHERE account_id = p_account_id;
  v_score := v_score + LEAST(v_contacts * 3, 20);

  -- Buying committee strength
  SELECT
    COUNT(*) FILTER (WHERE buying_role = 'decision_maker'),
    COUNT(*) FILTER (WHERE buying_role = 'champion')
  INTO v_decision_makers, v_champions
  FROM account_contacts WHERE account_id = p_account_id;

  v_score := v_score + LEAST(v_decision_makers * 8, 16);
  v_score := v_score + LEAST(v_champions * 5, 10);

  -- Engagement (last 30 days)
  SELECT COUNT(*) INTO v_recent_activities
  FROM account_activities
  WHERE account_id = p_account_id
    AND occurred_at >= now() - INTERVAL '30 days';

  v_score := v_score + LEAST(v_recent_activities * 2, 24);

  v_score := LEAST(v_score, 100);

  UPDATE accounts SET
    account_score = v_score,
    health_status = CASE
      WHEN v_score >= 75 THEN 'healthy'
      WHEN v_score >= 45 THEN 'at_risk'
      WHEN v_score > 0 THEN 'critical'
      ELSE 'unknown'
    END,
    updated_at = now()
  WHERE id = p_account_id;

  RETURN v_score;
END;
$function$
;

-- public.calculate_asset_efficiency(_asset_id uuid)

CREATE OR REPLACE FUNCTION public.calculate_asset_efficiency(_asset_id uuid)
 RETURNS TABLE(total_views bigint, deals_influenced bigint, win_rate_influenced numeric, total_revenue_influenced numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(DISTINCT l.id)::BIGINT as total_views,
        COUNT(DISTINCT s.id)::BIGINT as deals_influenced,
        CASE 
            WHEN COUNT(DISTINCT l.deal_id) > 0 
            THEN (COUNT(DISTINCT CASE WHEN s.status = 'completed' THEN s.id END)::DECIMAL / COUNT(DISTINCT l.deal_id) * 100)
            ELSE 0 
        END as win_rate_influenced,
        COALESCE(SUM(CASE WHEN s.status = 'completed' THEN s.amount END), 0) as total_revenue_influenced
    FROM public.asset_usage_logs l
    LEFT JOIN public.sales s ON l.deal_id = s.id
    WHERE l.asset_id = _asset_id;
END;
$function$
;

-- public.calculate_daily_challenge_streak(p_salesperson_id uuid)

CREATE OR REPLACE FUNCTION public.calculate_daily_challenge_streak(p_salesperson_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_streak integer := 0;
  v_current_date date := CURRENT_DATE;
  v_check_date date;
  v_day_completed boolean;
BEGIN
  -- Start from today or yesterday (if today's challenges haven't been completed yet)
  v_check_date := v_current_date;
  
  LOOP
    -- Check if all challenges for this date were completed
    SELECT 
      CASE 
        WHEN COUNT(*) = 0 THEN false
        WHEN COUNT(*) = COUNT(CASE WHEN dcp.completed_at IS NOT NULL THEN 1 END) THEN true
        ELSE false
      END INTO v_day_completed
    FROM daily_challenges dc
    LEFT JOIN daily_challenge_progress dcp ON dc.id = dcp.challenge_id 
      AND dcp.salesperson_id = p_salesperson_id
    WHERE dc.challenge_date = v_check_date;
    
    -- If no challenges exist for this day, check previous day (but only on first iteration)
    IF v_check_date = v_current_date AND NOT v_day_completed THEN
      v_check_date := v_check_date - 1;
      CONTINUE;
    END IF;
    
    -- If day wasn't completed, break the streak
    IF NOT v_day_completed THEN
      EXIT;
    END IF;
    
    -- Increment streak and move to previous day
    v_streak := v_streak + 1;
    v_check_date := v_check_date - 1;
    
    -- Safety limit to prevent infinite loop
    IF v_streak > 365 THEN
      EXIT;
    END IF;
  END LOOP;
  
  RETURN v_streak;
END;
$function$
;

-- public.calculate_deal_health(_sale_id uuid)

CREATE OR REPLACE FUNCTION public.calculate_deal_health(_sale_id uuid)
 RETURNS TABLE(health_score integer, health_label text, positive_factors jsonb, negative_factors jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sale RECORD;
  _last_activity TIMESTAMPTZ;
  _activity_count INTEGER;
  _days_in_stage INTEGER;
  _interaction_count INTEGER;
  _score INTEGER := 50;
  _pos JSONB := '[]'::jsonb;
  _neg JSONB := '[]'::jsonb;
  _label TEXT;
BEGIN
  SELECT * INTO _sale FROM public.sales WHERE id = _sale_id;
  IF _sale.id IS NULL THEN RETURN; END IF;

  SELECT MAX(created_at), COUNT(*) INTO _last_activity, _activity_count
  FROM public.activities WHERE sale_id = _sale_id AND deleted_at IS NULL;

  SELECT COUNT(*) INTO _interaction_count
  FROM public.channel_interactions WHERE deal_id = _sale_id AND created_at > now() - interval '14 days';

  _days_in_stage := EXTRACT(DAY FROM (now() - _sale.updated_at))::INT;

  -- Recência de atividades
  IF _last_activity IS NOT NULL AND _last_activity > now() - interval '3 days' THEN
    _score := _score + 15;
    _pos := _pos || jsonb_build_object('factor','recent_activity','impact',15,'label','Atividade recente nos últimos 3 dias');
  ELSIF _last_activity IS NULL OR _last_activity < now() - interval '14 days' THEN
    _score := _score - 20;
    _neg := _neg || jsonb_build_object('factor','no_recent_activity','impact',-20,'label','Sem atividades há mais de 14 dias');
  END IF;

  -- Volume de atividades
  IF _activity_count >= 5 THEN
    _score := _score + 10;
    _pos := _pos || jsonb_build_object('factor','high_activity','impact',10,'label',_activity_count || ' atividades registradas');
  END IF;

  -- Engajamento via canais
  IF _interaction_count >= 3 THEN
    _score := _score + 15;
    _pos := _pos || jsonb_build_object('factor','engaged','impact',15,'label',_interaction_count || ' interações nos últimos 14 dias');
  ELSIF _interaction_count = 0 THEN
    _score := _score - 15;
    _neg := _neg || jsonb_build_object('factor','no_engagement','impact',-15,'label','Nenhuma interação multicanal recente');
  END IF;

  -- Tempo no estágio
  IF _days_in_stage > 30 THEN
    _score := _score - 25;
    _neg := _neg || jsonb_build_object('factor','stagnation','impact',-25,'label',_days_in_stage || ' dias parado no mesmo estágio');
  ELSIF _days_in_stage <= 7 THEN
    _score := _score + 10;
    _pos := _pos || jsonb_build_object('factor','fast_progress','impact',10,'label','Avanço rápido no funil');
  END IF;

  -- Estágio avançado
  IF _sale.stage IN ('proposal','negotiation') THEN
    _score := _score + 5;
    _pos := _pos || jsonb_build_object('factor','advanced_stage','impact',5,'label','Deal em estágio avançado');
  END IF;

  -- Clamp 0-100
  _score := GREATEST(0, LEAST(100, _score));

  _label := CASE
    WHEN _score >= 80 THEN 'excellent'
    WHEN _score >= 60 THEN 'healthy'
    WHEN _score >= 40 THEN 'at_risk'
    ELSE 'critical'
  END;

  RETURN QUERY SELECT _score, _label, _pos, _neg;
END;
$function$
;

-- public.calculate_deal_health_score(p_deal_id uuid)

CREATE OR REPLACE FUNCTION public.calculate_deal_health_score(p_deal_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_score DECIMAL := 0;
  v_age_days INTEGER;
  v_activity_count INTEGER;
  v_last_activity_days INTEGER;
BEGIN
  -- Get deal age
  SELECT EXTRACT(EPOCH FROM (NOW() - created_at)) / 86400 INTO v_age_days
  FROM deals WHERE id = p_deal_id;
  
  -- Get activity count
  SELECT COUNT(*) INTO v_activity_count
  FROM activities WHERE deal_id = p_deal_id;
  
  -- Get days since last activity
  SELECT COALESCE(EXTRACT(EPOCH FROM (NOW() - MAX(created_at))) / 86400, 999) 
  INTO v_last_activity_days
  FROM activities WHERE deal_id = p_deal_id;
  
  -- Calculate score (0-100)
  v_score := 100;
  
  -- Penalty for age
  IF v_age_days > 90 THEN v_score := v_score - 20; END IF;
  IF v_age_days > 180 THEN v_score := v_score - 20; END IF;
  
  -- Penalty for inactivity
  IF v_last_activity_days > 14 THEN v_score := v_score - 20; END IF;
  IF v_last_activity_days > 30 THEN v_score := v_score - 20; END IF;
  
  -- Bonus for high activity
  IF v_activity_count > 10 THEN v_score := v_score + 10; END IF;
  IF v_activity_count > 20 THEN v_score := v_score + 10; END IF;
  
  RETURN GREATEST(0, LEAST(100, v_score));
END;
$function$
;

-- public.calculate_deal_probability(deal_id uuid)

CREATE OR REPLACE FUNCTION public.calculate_deal_probability(deal_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  stage_weight NUMERIC;
  age_days INTEGER;
  activity_count INTEGER;
  probability NUMERIC;
BEGIN
  SELECT 
    CASE stage
      WHEN 'prospecting' THEN 0.1
      WHEN 'qualification' THEN 0.25
      WHEN 'proposal' THEN 0.50
      WHEN 'negotiation' THEN 0.75
      WHEN 'closing' THEN 0.90
      ELSE 0.05
    END,
    EXTRACT(DAY FROM now() - created_at),
    (SELECT COUNT(*) FROM activities WHERE activities.deal_id = deals.id)
  INTO stage_weight, age_days, activity_count
  FROM deals
  WHERE id = deal_id;
  
  probability := stage_weight * (1 - (age_days::NUMERIC / 365)) * (1 + (activity_count::NUMERIC / 100));
  
  RETURN GREATEST(0, LEAST(1, probability));
END;
$function$
;

-- public.calculate_lead_distribution()

CREATE OR REPLACE FUNCTION public.calculate_lead_distribution()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_object_agg(range, count) INTO result
  FROM (
    SELECT 
      CASE 
        WHEN score < 20 THEN '0-20'
        WHEN score < 40 THEN '21-40'
        WHEN score < 60 THEN '41-60'
        WHEN score < 80 THEN '61-80'
        ELSE '81-100'
      END as range,
      count(*) as count
    FROM public.lead_scores
    GROUP BY range
  ) sub;
  RETURN COALESCE(result, '{}'::jsonb);
END;
$function$
;

-- public.calculate_source_roi(_source text, _days integer)

CREATE OR REPLACE FUNCTION public.calculate_source_roi(_source text, _days integer DEFAULT 30)
 RETURNS TABLE(total_leads bigint, total_revenue numeric, roi_index numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        COUNT(s.id)::BIGINT as total_leads,
        COALESCE(SUM(s.amount), 0) as total_revenue,
        CASE 
            WHEN (SELECT monthly_budget FROM public.lead_source_configs WHERE source_name = _source) > 0 
            THEN (COALESCE(SUM(s.amount), 0) / (SELECT monthly_budget FROM public.lead_source_configs WHERE source_name = _source))
            ELSE 0 
        END as roi_index
    FROM public.sales s
    WHERE s.source = _source
    AND s.created_at >= (now() - (_days || ' days')::interval);
END;
$function$
;

-- public.calculate_team_performance(p_team_id uuid, p_start_date timestamp without time zone, p_end_date timestamp without time zone)

CREATE OR REPLACE FUNCTION public.calculate_team_performance(p_team_id uuid, p_start_date timestamp without time zone, p_end_date timestamp without time zone)
 RETURNS TABLE(user_id uuid, user_email text, deals_count integer, revenue numeric, win_rate numeric, avg_deal_size numeric)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    u.id,
    u.email,
    COUNT(DISTINCT d.id)::INTEGER,
    COALESCE(SUM(d.value) FILTER (WHERE d.status = 'won'), 0)::DECIMAL,
    CASE 
      WHEN COUNT(d.id) > 0 
      THEN (COUNT(d.id) FILTER (WHERE d.status = 'won')::DECIMAL / COUNT(d.id) * 100)
      ELSE 0 
    END::DECIMAL,
    COALESCE(AVG(d.value) FILTER (WHERE d.status = 'won'), 0)::DECIMAL
  FROM users u
  LEFT JOIN team_members tm ON tm.user_id = u.id
  LEFT JOIN deals d ON d.owner_id = u.id 
    AND d.created_at BETWEEN p_start_date AND p_end_date
  WHERE tm.team_id = p_team_id
  GROUP BY u.id, u.email
  ORDER BY revenue DESC;
END;
$function$
;

-- public.canonical_phone_key(p_phone text)

CREATE OR REPLACE FUNCTION public.canonical_phone_key(p_phone text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE STRICT
 SET search_path TO 'public'
AS $function$
  SELECT right(
    CASE
      -- com DDI 55 e número nacional completo (10-11 dígitos após o DDI):
      -- remove o DDI para convergir com o mesmo número gravado sem DDI
      WHEN left(d.digits, 2) = '55' AND length(d.digits) - 2 BETWEEN 10 AND 11
        THEN substr(d.digits, 3)
      ELSE d.digits
    END, 11)
  FROM (SELECT regexp_replace(p_phone, '\D', '', 'g') AS digits) d;
$function$
;

-- public.check_2fa_failed_attempts(p_user_id uuid)

CREATE OR REPLACE FUNCTION public.check_2fa_failed_attempts(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_failed_count integer;
BEGIN
  IF auth.role() <> 'service_role'
     AND (
       auth.uid() IS NULL
       OR (
         p_user_id IS DISTINCT FROM auth.uid()
         AND NOT public.is_admin_or_manager(auth.uid())
       )
     ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::integer
    INTO v_failed_count
    FROM public.user_2fa_log AS l
   WHERE l.user_id = p_user_id
     AND l.success IS FALSE
     AND l.created_at > now() - interval '15 minutes';

  RETURN v_failed_count;
END;
$function$
;

-- public.check_battle_achievements()

CREATE OR REPLACE FUNCTION public.check_battle_achievements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.winner_id IS NOT NULL AND OLD.winner_id IS NULL THEN
        PERFORM private.award_achievement_if_not_exists(NEW.winner_id, 'first_battle_win');
    END IF;
    
    IF NEW.winner_id IS NOT NULL AND OLD.winner_id IS NULL THEN
      IF (SELECT count(*) FROM public.weekly_matchups WHERE winner_id = NEW.winner_id) >= 10 THEN
          PERFORM private.award_achievement_if_not_exists(NEW.winner_id, 'battle_veteran');
      END IF;
    END IF;

    RETURN NEW;
END;
$function$
;

-- public.check_failed_attempts(p_email text, p_minutes integer)

CREATE OR REPLACE FUNCTION public.check_failed_attempts(p_email text, p_minutes integer DEFAULT 15)
 RETURNS integer
 LANGUAGE sql
AS $function$
