-- public.check_performance_bets_completion(p_salesperson_id uuid)

CREATE OR REPLACE FUNCTION public.check_performance_bets_completion(p_salesperson_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    bet_record RECORD;
    xp_to_award INTEGER;
BEGIN
    FOR bet_record IN 
        SELECT * FROM public.performance_bets 
        WHERE salesperson_id = p_salesperson_id 
        AND status = 'active'
    LOOP
        -- Check if WON
        IF bet_record.current_value >= bet_record.target_value THEN
            UPDATE public.performance_bets 
            SET status = 'won', resolved_at = now()
            WHERE id = bet_record.id;
            
            -- Award XP (Wager * Multiplier)
            xp_to_award := (bet_record.xp_wagered * bet_record.xp_multiplier)::INTEGER;
            
            -- We call the existing add_xp logic if it was a function, 
            -- but since it's likely handled by app or another trigger, 
            -- we insert directly into xp_history to trigger its own flow
            INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
            VALUES (
                p_salesperson_id, 
                xp_to_award, 
                'performance_bet', 
                bet_record.id, 
                'Ganhou aposta de performance: ' || bet_record.description
            );
            
        -- Check if LOST (expired)
        ELSIF bet_record.ends_at < now() THEN
            UPDATE public.performance_bets 
            SET status = 'lost', resolved_at = now()
            WHERE id = bet_record.id;
            
            -- No XP awarded, wager was already "spent" or just lost
            -- Optionally log a negative XP or just end the streak
        END IF;
    END LOOP;
END;
$function$
;

-- public.check_price_threats()

CREATE OR REPLACE FUNCTION public.check_price_threats()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_min_margin DECIMAL;
BEGIN
    SELECT min_margin_pct INTO v_min_margin 
    FROM public.price_protection_rules 
    WHERE product_id = NEW.product_id;

    -- Se o preço do concorrente for muito baixo
    IF NEW.price > 0 THEN
        INSERT INTO public.price_alerts (
            product_id,
            alert_type,
            message,
            is_read
        ) VALUES (
            NEW.product_id,
            'competitor_threat',
            'Preço do concorrente detectado em ' || NEW.price || '. Risco de margem.',
            false
        );
    END IF;

    RETURN NEW;
END;
$function$
;

-- public.check_rate_limit(p_identifier text, p_action text)

CREATE OR REPLACE FUNCTION public.check_rate_limit(p_identifier text, p_action text)
 RETURNS TABLE(allowed boolean, remaining integer, reset_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings RECORD;
  v_count INTEGER;
  v_window_start TIMESTAMPTZ;
BEGIN
  -- Buscar configurações
  SELECT * INTO v_settings FROM rate_limit_settings WHERE action = p_action AND is_active = true;
  
  IF NOT FOUND THEN
    RETURN QUERY SELECT true, 999, NOW() + INTERVAL '1 hour';
    RETURN;
  END IF;
  
  v_window_start := NOW() - (v_settings.window_seconds || ' seconds')::INTERVAL;
  
  -- Contar requests na janela
  SELECT COUNT(*) INTO v_count
  FROM rate_limit_logs
  WHERE identifier = p_identifier
  AND action = p_action
  AND created_at > v_window_start;
  
  IF v_count >= v_settings.max_requests THEN
    RETURN QUERY SELECT false, 0, NOW() + (v_settings.block_duration_seconds || ' seconds')::INTERVAL;
  ELSE
    RETURN QUERY SELECT true, (v_settings.max_requests - v_count - 1), v_window_start + (v_settings.window_seconds || ' seconds')::INTERVAL;
  END IF;
END;
$function$
;

-- public.check_sla_violations()

CREATE OR REPLACE FUNCTION public.check_sla_violations()
 RETURNS TABLE(processed integer, new_warnings integer, new_violations integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row RECORD;
  _hours NUMERIC;
  _new_status TEXT;
  _processed INT := 0;
  _warnings INT := 0;
  _violations INT := 0;
BEGIN
  FOR _row IN
    SELECT s.id AS sale_id, s.stage, s.updated_at, p.id AS policy_id, p.max_hours, p.warning_hours
    FROM public.sales s
    JOIN public.sla_policies p ON p.stage = s.stage AND p.is_active = true
    WHERE s.status NOT IN ('completed', 'won', 'closed', 'lost', 'cancelled')
  LOOP
    _processed := _processed + 1;
    _hours := EXTRACT(EPOCH FROM (now() - _row.updated_at)) / 3600.0;

    IF _hours >= _row.max_hours THEN
      _new_status := 'violated';
    ELSIF _hours >= _row.warning_hours THEN
      _new_status := 'warning';
    ELSE
      CONTINUE;
    END IF;

    INSERT INTO public.sla_violations (sale_id, policy_id, stage, hours_in_stage, status)
    VALUES (_row.sale_id, _row.policy_id, _row.stage, _hours, _new_status)
    ON CONFLICT DO NOTHING;

    IF _new_status = 'warning' THEN _warnings := _warnings + 1;
    ELSE _violations := _violations + 1; END IF;
  END LOOP;

  RETURN QUERY SELECT _processed, _warnings, _violations;
END;
$function$
;

-- public.check_webhook_rate_limit(_subscription_id uuid)

CREATE OR REPLACE FUNCTION public.check_webhook_rate_limit(_subscription_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_limit  integer;
  v_window integer;
  v_usado  integer;
BEGIN
  SELECT s.rate_limit_per_minute, s.rate_limit_window_seconds
    INTO v_limit, v_window
  FROM public.winloss_webhook_subscriptions s
  WHERE s.id = _subscription_id
  FOR UPDATE;

  IF NOT FOUND THEN RETURN false; END IF;

  DELETE FROM public.webhook_dispatch_rate r
  WHERE r.subscription_id = _subscription_id
    AND r.dispatched_at < now() - make_interval(secs => v_window * 10);

  SELECT count(*) INTO v_usado
  FROM public.webhook_dispatch_rate r
  WHERE r.subscription_id = _subscription_id
    AND r.dispatched_at > now() - make_interval(secs => v_window);

  IF v_usado >= v_limit THEN
    RETURN false;
  END IF;

  INSERT INTO public.webhook_dispatch_rate (subscription_id) VALUES (_subscription_id);
  RETURN true;
END;
$function$
;

-- public.claim_daily_challenge_reward(p_challenge_id uuid)

CREATE OR REPLACE FUNCTION public.claim_daily_challenge_reward(p_challenge_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sp uuid;
  v_challenge record;
  v_n bigint;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória para resgatar recompensa'
      USING ERRCODE = '28000';
  END IF;

  v_sp := public.get_current_salesperson_id();
  IF v_sp IS NULL THEN
    RAISE EXCEPTION 'Perfil comercial não encontrado para o usuário autenticado'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT id, title, xp_reward, target_value
    INTO v_challenge
    FROM public.daily_challenges
   WHERE id = p_challenge_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Desafio não encontrado' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.daily_challenge_progress
     SET xp_claimed = true,
         completed_at = COALESCE(completed_at, now()),
         current_value = GREATEST(current_value, v_challenge.target_value),
         updated_at = now()
   WHERE challenge_id = p_challenge_id
     AND salesperson_id = v_sp
     AND xp_claimed = false
     AND (completed_at IS NOT NULL OR current_value >= v_challenge.target_value);
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n = 0 THEN
    RAISE EXCEPTION 'Desafio não concluído ou recompensa já resgatada'
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
  VALUES (
    v_sp, v_challenge.xp_reward, 'daily_challenge', p_challenge_id::text,
    'Desafio completado: ' || v_challenge.title
  );

  RETURN jsonb_build_object('xp_reward', v_challenge.xp_reward);
END;
$function$
;

-- public.claim_pending_cadence_tasks(p_today date, p_limit integer)

CREATE OR REPLACE FUNCTION public.claim_pending_cadence_tasks(p_today date, p_limit integer DEFAULT 20)
 RETURNS TABLE(task_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    SELECT ct.id
    FROM public.cadence_tasks ct
    JOIN public.prospect_cadences pc ON pc.id = ct.prospect_cadence_id
    WHERE ct.status     = 'pending'
      AND ct.task_type  = 'automatic'
      AND ct.scheduled_date <= p_today
      AND pc.status     = 'active'   -- never fire for paused/cancelled cadences
    ORDER BY ct.scheduled_date ASC
    LIMIT p_limit
    FOR UPDATE OF ct SKIP LOCKED    -- atomic; concurrent runners skip locked rows
  )
  UPDATE public.cadence_tasks
  SET    status = 'processing',
         updated_at = now()
  FROM   claimed
  WHERE  cadence_tasks.id = claimed.id
  RETURNING cadence_tasks.id AS task_id;
END;
$function$
;

-- public.claim_streak_achievements()

CREATE OR REPLACE FUNCTION public.claim_streak_achievements()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sp uuid;
  v_streak integer;
  v_milestone record;
  v_n bigint;
  v_claimed jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória para resgatar conquistas'
      USING ERRCODE = '28000';
  END IF;

  v_sp := public.get_current_salesperson_id();
  IF v_sp IS NULL THEN
    RAISE EXCEPTION 'Perfil comercial não encontrado para o usuário autenticado'
      USING ERRCODE = 'P0001';
  END IF;

  v_streak := public.calculate_daily_challenge_streak(v_sp);

  FOR v_milestone IN
    SELECT * FROM (VALUES
      ('streak_3',  3,  50,   'Iniciante Dedicado'),
      ('streak_7',  7,  150,  'Semana Perfeita'),
      ('streak_14', 14, 400,  'Duas Semanas de Fogo'),
      ('streak_30', 30, 1000, 'Mestre da Consistência')
    ) AS m(streak_type, days, xp, title)
    WHERE m.days <= v_streak
  LOOP
    -- UNIQUE(salesperson_id, streak_type) torna o claim exatamente-uma-vez;
    -- quem perde o conflito não credita XP de novo.
    INSERT INTO public.daily_streak_achievements (
      salesperson_id, streak_type, streak_count, xp_awarded
    ) VALUES (
      v_sp, v_milestone.streak_type, v_streak, v_milestone.xp
    )
    ON CONFLICT (salesperson_id, streak_type) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;

    IF v_n > 0 THEN
      INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
      VALUES (
        v_sp, v_milestone.xp, 'streak_achievement', v_milestone.streak_type,
        'Conquista: ' || v_milestone.title || ' (' || v_milestone.days || ' dias)'
      );
      v_claimed := v_claimed || jsonb_build_object(
        'streak_type', v_milestone.streak_type,
        'xp_awarded', v_milestone.xp,
        'title', v_milestone.title
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object('streak', v_streak, 'claimed', v_claimed);
END;
$function$
;

