-- public.cleanup_deleted_records()

CREATE OR REPLACE FUNCTION public.cleanup_deleted_records()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  DELETE FROM deals WHERE deleted_at < NOW() - INTERVAL '90 days';
  DELETE FROM clients WHERE deleted_at < NOW() - INTERVAL '90 days';
  DELETE FROM activities WHERE deleted_at < NOW() - INTERVAL '90 days';
  DELETE FROM tasks WHERE deleted_at < NOW() - INTERVAL '90 days';
END;
$function$
;

-- public.cleanup_expired_narrative_cache()

CREATE OR REPLACE FUNCTION public.cleanup_expired_narrative_cache()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted INTEGER;
BEGIN
  DELETE FROM public.ai_narrative_cache
  WHERE expires_at < now();
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$function$
;

-- public.cleanup_old_audit_logs()

CREATE OR REPLACE FUNCTION public.cleanup_old_audit_logs()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM audit_log
  WHERE created_at < now() - INTERVAL '90 days';
  
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  
  RETURN deleted_count;
END;
$function$
;

-- public.cleanup_old_records()

CREATE OR REPLACE FUNCTION public.cleanup_old_records()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  deleted_count INTEGER := 0;
  temp_count INTEGER;
BEGIN
  DELETE FROM audit_log WHERE created_at < now() - INTERVAL '90 days';
  GET DIAGNOSTICS temp_count = ROW_COUNT;
  deleted_count := deleted_count + temp_count;
  
  DELETE FROM user_2fa_log WHERE created_at < now() - INTERVAL '90 days';
  GET DIAGNOSTICS temp_count = ROW_COUNT;
  deleted_count := deleted_count + temp_count;
  
  DELETE FROM security_events WHERE created_at < now() - INTERVAL '180 days';
  GET DIAGNOSTICS temp_count = ROW_COUNT;
  deleted_count := deleted_count + temp_count;
  
  RETURN deleted_count;
END;
$function$
;

-- public.coaching_progress_by_salesperson(_salesperson_id uuid, _days integer)

CREATE OR REPLACE FUNCTION public.coaching_progress_by_salesperson(_salesperson_id uuid, _days integer DEFAULT 30)
 RETURNS TABLE(category text, severity text, status text, count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT category, severity, status, COUNT(*)::bigint
  FROM public.coaching_actions
  WHERE salesperson_id = _salesperson_id
    AND created_at >= now() - (_days || ' days')::interval
  GROUP BY category, severity, status
$function$
;

-- public.complete_agent_run(_run_id uuid, _result jsonb, _status text, _error text)

CREATE OR REPLACE FUNCTION public.complete_agent_run(_run_id uuid, _result jsonb, _status text DEFAULT 'completed'::text, _error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sp uuid;
  v_owner uuid;
BEGIN
  -- Owner check (mesmo padrão de approve_agent_run): service_role bypassa;
  -- autenticado precisa ser dono do run ou admin/manager.
  SELECT salesperson_id INTO v_owner FROM public.ai_agent_runs WHERE id = _run_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Run not found';
  END IF;
  IF auth.role() <> 'service_role' THEN
    v_sp := public.get_current_salesperson_id();
    IF (v_sp IS NULL OR v_owner <> v_sp)
       AND NOT public.has_role(auth.uid(), 'admin')
       AND NOT public.has_role(auth.uid(), 'manager') THEN
      RAISE EXCEPTION 'Not authorized';
    END IF;
  END IF;

  UPDATE public.ai_agent_runs
  SET result = _result,
      status = _status,
      error_message = _error,
      completed_at = now(),
      updated_at = now()
  WHERE id = _run_id;
END;
$function$
;

-- public.complete_call_recording_ingest_job(_job_id uuid, _success boolean, _error text)

CREATE OR REPLACE FUNCTION public.complete_call_recording_ingest_job(_job_id uuid, _success boolean, _error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  j public.call_recording_ingest_jobs;
  backoff_secs INTEGER;
BEGIN
  SELECT * INTO j FROM public.call_recording_ingest_jobs WHERE id = _job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'job % not found', _job_id; END IF;

  IF _success THEN
    UPDATE public.call_recording_ingest_jobs
       SET status = 'succeeded', completed_at = now(),
           locked_at = NULL, locked_by = NULL, last_error = NULL, updated_at = now()
     WHERE id = _job_id;
  ELSIF j.attempts >= j.max_attempts THEN
    UPDATE public.call_recording_ingest_jobs
       SET status = 'dead_letter', last_error = COALESCE(_error,'unknown'),
           last_error_at = now(), locked_at = NULL, locked_by = NULL, updated_at = now()
     WHERE id = _job_id;
  ELSE
    backoff_secs := LEAST(3600, POWER(2, j.attempts)::int * 30) + FLOOR(random() * 30)::int;
    UPDATE public.call_recording_ingest_jobs
       SET status = 'pending',
           next_attempt_at = now() + make_interval(secs => backoff_secs),
           last_error = COALESCE(_error,'unknown'), last_error_at = now(),
           locked_at = NULL, locked_by = NULL, updated_at = now()
     WHERE id = _job_id;
  END IF;
END;
$function$
;

-- public.compute_challenge_progress_value(p_salesperson_id uuid, p_challenge_type text, p_start date, p_end date)

CREATE OR REPLACE FUNCTION public.compute_challenge_progress_value(p_salesperson_id uuid, p_challenge_type text, p_start date, p_end date)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_types activity_type[];
  v_val integer;
BEGIN
  IF p_challenge_type = 'sales' THEN
    -- WON canônico: ('completed','won','closed')
    SELECT count(*) INTO v_val
      FROM public.sales s
     WHERE s.salesperson_id = p_salesperson_id
       AND s.status = ANY (ARRAY['completed','won','closed'])
       AND s.created_at::date BETWEEN p_start AND p_end;
  ELSIF p_challenge_type = 'proposals' THEN
    SELECT count(*) INTO v_val
      FROM public.quotes q
     WHERE q.created_by = p_salesperson_id
       AND q.created_at::date BETWEEN p_start AND p_end;
  ELSIF p_challenge_type = 'follow_up' THEN
    SELECT count(*) INTO v_val
      FROM public.follow_up_audit_logs f
     WHERE f.user_id = (
             SELECT sp.auth_user_id FROM public.salespeople sp
              WHERE sp.id = p_salesperson_id
           )
       AND f.created_at::date BETWEEN p_start AND p_end;
  ELSE
    v_types := CASE p_challenge_type
      WHEN 'calls' THEN ARRAY['call'::activity_type]
      WHEN 'emails' THEN ARRAY['email'::activity_type]
      WHEN 'meetings' THEN ARRAY['meeting'::activity_type]
      WHEN 'demos' THEN ARRAY['meeting'::activity_type]
      WHEN 'linkedin' THEN ARRAY['linkedin'::activity_type]
      WHEN 'whatsapp' THEN ARRAY['whatsapp'::activity_type]
      ELSE NULL -- 'any'/'activity'/desconhecidos: qualquer tipo
    END;
    SELECT count(*) INTO v_val
      FROM public.activities a
     WHERE a.salesperson_id = p_salesperson_id
       AND a.created_at::date BETWEEN p_start AND p_end
       AND (v_types IS NULL OR a.activity_type = ANY (v_types));
  END IF;
  RETURN COALESCE(v_val, 0);
END;
$function$
;

-- public.compute_forecast_rollup(_horizon_days integer)

CREATE OR REPLACE FUNCTION public.compute_forecast_rollup(_horizon_days integer DEFAULT 90)
 RETURNS TABLE(category forecast_category, deal_count integer, total_amount numeric, weighted_amount numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH weights AS (
    SELECT * FROM (VALUES
      ('commit'::forecast_category, 0.90),
      ('best_case'::forecast_category, 0.60),
      ('pipeline'::forecast_category, 0.25),
      ('omitted'::forecast_category, 0.0),
      ('closed'::forecast_category, 1.0)
    ) AS t(c, w)
  )
  SELECT
    s.forecast_category,
    COUNT(*)::integer,
    COALESCE(SUM(s.amount), 0)::numeric,
    COALESCE(SUM(s.amount * w.w), 0)::numeric
  FROM public.sales s
  LEFT JOIN weights w ON w.c = s.forecast_category
  WHERE s.created_at >= now() - (_horizon_days || ' days')::interval
    AND s.forecast_category IS NOT NULL
    AND (is_admin_or_manager(auth.uid()) OR s.salesperson_id = get_current_salesperson_id())
  GROUP BY s.forecast_category
  ORDER BY s.forecast_category;
END;
$function$
;

-- public.compute_optimal_send_time(_contact_id uuid, _contact_type text, _earliest timestamp with time zone)

CREATE OR REPLACE FUNCTION public.compute_optimal_send_time(_contact_id uuid, _contact_type text, _earliest timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  best_hour smallint;
  best_dow smallint;
  candidate timestamptz;
  i int := 0;
BEGIN
  SELECT hour_of_day, day_of_week INTO best_hour, best_dow
  FROM public.contact_send_time_profile
  WHERE contact_id = _contact_id
    AND contact_type = _contact_type
    AND score > 0
  ORDER BY score DESC, updated_at DESC
  LIMIT 1;

  -- Fallback: next weekday at 10:00 UTC
  IF best_hour IS NULL THEN
    candidate := date_trunc('day', _earliest) + interval '10 hours';
    WHILE candidate < _earliest OR EXTRACT(DOW FROM candidate) IN (0, 6) LOOP
      candidate := candidate + interval '1 day';
    END LOOP;
    RETURN candidate;
  END IF;

  -- Find next occurrence of (best_dow, best_hour) >= _earliest
  candidate := date_trunc('day', _earliest) + (best_hour || ' hours')::interval;
  WHILE (EXTRACT(DOW FROM candidate)::int <> best_dow OR candidate < _earliest) AND i < 14 LOOP
    candidate := candidate + interval '1 day';
    i := i + 1;
  END LOOP;

  RETURN candidate;
END;
$function$
;

-- public.compute_pipeline_inspection()

CREATE OR REPLACE FUNCTION public.compute_pipeline_inspection()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _r RECORD;
  _flags jsonb;
  _last_act timestamptz;
  _days_act integer;
  _days_stage integer;
  _count integer := 0;
BEGIN
  IF NOT is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  FOR _r IN
    SELECT id, status, updated_at, salesperson_id
    FROM public.sales
    WHERE status NOT IN ('completed','won','closed','lost','cancelled')
  LOOP
    _flags := '[]'::jsonb;
    _days_stage := EXTRACT(epoch FROM (now() - _r.updated_at))::integer / 86400;

    SELECT MAX(created_at) INTO _last_act FROM public.activities WHERE sale_id = _r.id AND deleted_at IS NULL;
    _days_act := CASE WHEN _last_act IS NULL THEN NULL ELSE EXTRACT(epoch FROM (now() - _last_act))::integer / 86400 END;

    IF _days_stage > 14 THEN _flags := _flags || jsonb_build_array(jsonb_build_object('flag','stale_stage','severity','high','days',_days_stage)); END IF;
    IF _days_act IS NULL OR _days_act > 7 THEN _flags := _flags || jsonb_build_array(jsonb_build_object('flag','no_recent_activity','severity','medium','days',_days_act)); END IF;
    IF NOT EXISTS (SELECT 1 FROM public.buying_committee_members WHERE sale_id = _r.id AND committee_role IN ('decision_maker','champion')) THEN
      _flags := _flags || jsonb_build_array(jsonb_build_object('flag','no_decision_maker','severity','high'));
    END IF;
    IF (SELECT COUNT(*) FROM public.buying_committee_members WHERE sale_id = _r.id) <= 1 THEN
      _flags := _flags || jsonb_build_array(jsonb_build_object('flag','single_threaded','severity','medium'));
    END IF;

    INSERT INTO public.pipeline_inspection_snapshots
      (sale_id, stage, days_in_stage, last_activity_at, days_since_activity, risk_flags)
    VALUES (_r.id, _r.status, _days_stage, _last_act, _days_act, _flags);
    _count := _count + 1;
  END LOOP;

  RETURN _count;
END;
$function$
;

-- public.compute_salesperson_retention_cohort(_months_back integer)

CREATE OR REPLACE FUNCTION public.compute_salesperson_retention_cohort(_months_back integer DEFAULT 12)
 RETURNS TABLE(cohort_month date, cohort_size integer, month_offset integer, retained integer, retention_pct numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH first_won AS (
    SELECT
      s.salesperson_id,
      date_trunc('month', MIN(s.created_at) AT TIME ZONE 'America/Sao_Paulo')::date AS cohort_month
    FROM public.sales s
    WHERE s.status IN ('completed', 'won', 'closed') AND s.salesperson_id IS NOT NULL
    GROUP BY s.salesperson_id
  ),
  cohort_sizes AS (
    SELECT cohort_month, COUNT(*)::int AS cohort_size
    FROM first_won
    GROUP BY cohort_month
  ),
  activity AS (
    SELECT DISTINCT
      fw.cohort_month,
      fw.salesperson_id,
      (EXTRACT(YEAR FROM AGE(date_trunc('month', s.created_at AT TIME ZONE 'America/Sao_Paulo'), fw.cohort_month))::int * 12 +
       EXTRACT(MONTH FROM AGE(date_trunc('month', s.created_at AT TIME ZONE 'America/Sao_Paulo'), fw.cohort_month))::int) AS month_offset
    FROM first_won fw
    JOIN public.sales s
      ON s.salesperson_id = fw.salesperson_id
     AND s.status IN ('completed', 'won', 'closed')
     AND s.created_at >= fw.cohort_month
  ),
  retained_counts AS (
    SELECT cohort_month, month_offset, COUNT(*)::int AS retained
    FROM activity
    WHERE month_offset BETWEEN 0 AND 11
    GROUP BY cohort_month, month_offset
  )
  SELECT
    cs.cohort_month,
    cs.cohort_size,
    rc.month_offset,
    rc.retained,
    ROUND((rc.retained::numeric / NULLIF(cs.cohort_size, 0)) * 100, 1) AS retention_pct
  FROM cohort_sizes cs
  JOIN retained_counts rc USING (cohort_month)
  WHERE cs.cohort_month >= (date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') - (_months_back || ' months')::interval)::date
  ORDER BY cs.cohort_month DESC, rc.month_offset ASC;
$function$
;

-- public.compute_scheduled_report_next_run()

CREATE OR REPLACE FUNCTION public.compute_scheduled_report_next_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  candidate TIMESTAMP; -- instante local America/Sao_Paulo; convertido no final
BEGIN
  IF NEW.frequency = 'daily' THEN
    candidate := date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + (NEW.hour_of_day || ' hours')::interval;
    IF candidate <= now() AT TIME ZONE 'America/Sao_Paulo' THEN
      candidate := candidate + interval '1 day';
    END IF;
  ELSIF NEW.frequency = 'weekly' THEN
    candidate := date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') + (NEW.hour_of_day || ' hours')::interval;
    -- avança até bater no day_of_week (default 1 = segunda)
    WHILE EXTRACT(DOW FROM candidate)::INT <> COALESCE(NEW.day_of_week, 1) OR candidate <= now() AT TIME ZONE 'America/Sao_Paulo' LOOP
      candidate := candidate + interval '1 day';
    END LOOP;
  ELSE -- monthly
    candidate := date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo')
                 + ((COALESCE(NEW.day_of_month, 1) - 1) || ' days')::interval
                 + (NEW.hour_of_day || ' hours')::interval;
    IF candidate <= now() AT TIME ZONE 'America/Sao_Paulo' THEN
      candidate := candidate + interval '1 month';
    END IF;
  END IF;
  NEW.next_run_at := candidate AT TIME ZONE 'America/Sao_Paulo';
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$
;

-- public.convert_quote_to_order()

CREATE OR REPLACE FUNCTION public.convert_quote_to_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing_order uuid;
  v_order_id       uuid;
  v_order_number   text;
BEGIN
  -- Only act when status transitions to 'approved'.
  IF NEW.status <> 'approved' THEN
    RETURN NEW;
  END IF;

  -- Idempotency: skip if status was already approved (avoids re-fire on
  -- unrelated column updates).
  IF TG_OP = 'UPDATE' AND OLD.status = 'approved' THEN
    RETURN NEW;
  END IF;

  -- Idempotency: skip if an order already exists for this quote.
  SELECT id INTO v_existing_order
  FROM public.orders
  WHERE quote_id = NEW.id
  LIMIT 1;

  IF v_existing_order IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Guard: if quote_items haven't been synced yet (e.g. webhook hasn't
  -- completed its second step), skip creation entirely. The explicit RPC
  -- fn_convert_quote_to_sale will handle it correctly after sync.
  IF NOT EXISTS (
    SELECT 1 FROM public.quote_items WHERE quote_id = NEW.id LIMIT 1
  ) THEN
    RETURN NEW;
  END IF;

  -- Derive order number from quote_number (same strategy as original trigger).
  v_order_number := COALESCE(
    'PED-' || NULLIF(NEW.quote_number, ''),
    'PED-' || substr(NEW.id::text, 1, 8) || '-' || to_char(now(), 'YYMMDDHH24MISS')
  );

  -- Ensure uniqueness.
  WHILE EXISTS (SELECT 1 FROM public.orders WHERE order_number = v_order_number) LOOP
    v_order_number := v_order_number || '-' || substr(md5(random()::text), 1, 4);
  END LOOP;

  -- Insert order using the column set that actually exists on public.orders.
  INSERT INTO public.orders (
    order_number,
    status,
    subtotal,
    shipping,
    total,
    quote_id,
    client_id,
    salesperson_id,
    notes,
    metadata
  )
  VALUES (
    v_order_number,
    'pending',
    COALESCE(NEW.subtotal, NEW.total_value, 0),
    0,
    COALESCE(NEW.total_value, 0),
    NEW.id,
    NEW.client_id,
    NEW.created_by,
    NEW.notes,
    jsonb_build_object(
      'source',             COALESCE(NEW.source, 'manual'),
      'external_quote_id',  NEW.external_quote_id,
      'quote_number',       NEW.quote_number,
      'external_seller_id', NEW.external_seller_id,
      'client_name',        NEW.client_name,
      'client_email',       NEW.client_email,
      'client_phone',       NEW.client_phone
    )
  )
  RETURNING id INTO v_order_id;

  -- Copy items from the normalized quote_items table (not the JSONB blob).
  -- Uses only columns that exist on public.order_items.
  INSERT INTO public.order_items (order_id, product_name, quantity, unit_price)
  SELECT
    v_order_id,
    qi.product_name,
    qi.quantity,
    qi.unit_price
  FROM public.quote_items qi
  WHERE qi.quote_id = NEW.id;

  RETURN NEW;
END;
$function$
;

-- public.count_failed_login_attempts(check_email text, check_ip text, window_minutes integer)

CREATE OR REPLACE FUNCTION public.count_failed_login_attempts(check_email text, check_ip text, window_minutes integer DEFAULT 15)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COUNT(*)::INTEGER
  FROM login_attempts
  WHERE (email = check_email OR ip_address = check_ip)
  AND success = false
  AND created_at > NOW() - (window_minutes || ' minutes')::INTERVAL
$function$
;

-- public.count_reset_requests_24h(check_email text)

CREATE OR REPLACE FUNCTION public.count_reset_requests_24h(check_email text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COUNT(*)::INTEGER FROM password_reset_requests
  WHERE user_email = check_email
  AND requested_at > NOW() - INTERVAL '24 hours'
$function$
;

-- public.create_activities_from_action_items(_recording_id uuid)

CREATE OR REPLACE FUNCTION public.create_activities_from_action_items(_recording_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rec RECORD;
  v_caller_sp uuid;
  v_item jsonb;
  v_inserted int := 0;
  v_tag text;
  v_title text;
BEGIN
  SELECT id, salesperson_id, sale_id, action_items, title
    INTO v_rec
  FROM public.call_recordings
  WHERE id = _recording_id;

  IF v_rec.id IS NULL THEN
    RAISE EXCEPTION 'Recording not found';
  END IF;

  v_caller_sp := public.get_current_salesperson_id();
  IF v_rec.salesperson_id <> v_caller_sp AND NOT public.is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  v_tag := '[ai-summary:' || _recording_id::text || ']';

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(v_rec.action_items, '[]'::jsonb))
  LOOP
    v_title := COALESCE(v_item->>'title', 'Follow-up da reunião');

    -- Idempotency: skip if note already contains tag for this item title
    IF EXISTS (
      SELECT 1 FROM public.activities
      WHERE salesperson_id = v_rec.salesperson_id
        AND notes LIKE '%' || v_tag || '%'
        AND notes LIKE '%' || v_title || '%'
        AND deleted_at IS NULL
    ) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.activities (
      activity_type, outcome, sale_id, salesperson_id, notes, contact_name
    ) VALUES (
      'follow_up'::activity_type,
      'pending'::activity_outcome,
      v_rec.sale_id,
      v_rec.salesperson_id,
      v_tag || ' ' || v_title ||
        COALESCE(' | Prazo: ' || (v_item->>'due_hint'), '') ||
        COALESCE(' | Prioridade: ' || (v_item->>'priority'), '') ||
        COALESCE(' | Responsável: ' || (v_item->>'owner_hint'), ''),
      NULL
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN v_inserted;
END;
$function$
;

-- public.create_agent_run(_agent_type text, _goal text, _target_entity_type text, _target_entity_id uuid, _requires_approval boolean)

CREATE OR REPLACE FUNCTION public.create_agent_run(_agent_type text, _goal text DEFAULT NULL::text, _target_entity_type text DEFAULT NULL::text, _target_entity_id uuid DEFAULT NULL::uuid, _requires_approval boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sp uuid;
  v_id uuid;
  v_row jsonb;
  v_ok boolean;
BEGIN
  v_sp := public.get_current_salesperson_id();
  IF v_sp IS NULL AND NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'No salesperson context';
  END IF;

  IF _target_entity_type IS NOT NULL AND _target_entity_id IS NOT NULL
     AND NOT public.is_admin_or_manager(auth.uid()) THEN
    IF _target_entity_type = 'deal' THEN
      SELECT to_jsonb(s) INTO v_row FROM public.sales s WHERE s.id = _target_entity_id;
    ELSIF _target_entity_type = 'client' THEN
      SELECT to_jsonb(c) INTO v_row FROM public.clients c WHERE c.id = _target_entity_id;
    ELSIF _target_entity_type = 'activity' THEN
      SELECT to_jsonb(a) INTO v_row FROM public.activities a WHERE a.id = _target_entity_id;
    ELSIF _target_entity_type = 'lead' AND to_regclass('public.leads') IS NOT NULL THEN
      EXECUTE 'SELECT to_jsonb(l) FROM public.leads l WHERE l.id = $1'
        INTO v_row USING _target_entity_id;
    END IF;

    IF v_row IS NULL THEN
      RAISE EXCEPTION 'Target entity not found';
    END IF;

    v_ok :=
      v_row->>'user_id' = auth.uid()::text
      OR ((v_row->>'salesperson_id') IS NOT NULL AND (v_row->>'salesperson_id')::uuid = v_sp)
      OR ((v_row->>'sdr_id') IS NOT NULL AND (v_row->>'sdr_id')::uuid = v_sp)
      OR ((v_row->>'closer_id') IS NOT NULL AND (v_row->>'closer_id')::uuid = v_sp);

    IF NOT COALESCE(v_ok, false)
       AND _target_entity_type = 'client'
       AND v_sp IS NOT NULL THEN
      SELECT EXISTS (
        SELECT 1 FROM public.client_portfolio p
        WHERE p.client_id = _target_entity_id
          AND p.salesperson_id = v_sp
      ) INTO v_ok;
    END IF;

    IF NOT COALESCE(v_ok, false) THEN
      RAISE EXCEPTION 'Target entity not owned by caller';
    END IF;
  END IF;

  INSERT INTO public.ai_agent_runs(salesperson_id, agent_type, goal, target_entity_type, target_entity_id, requires_approval, status)
  VALUES (COALESCE(v_sp, '00000000-0000-0000-0000-000000000000'::uuid), _agent_type, _goal, _target_entity_type, _target_entity_id, _requires_approval, 'pending')
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;

-- public.create_version()

CREATE OR REPLACE FUNCTION public.create_version()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  INSERT INTO entity_versions (entity_type, entity_id, version_number, data, changed_by, change_summary)
  SELECT TG_TABLE_NAME, NEW.id, COALESCE(MAX(version_number), 0) + 1, row_to_json(OLD), auth.uid(), 'Auto-save'
  FROM entity_versions WHERE entity_type = TG_TABLE_NAME AND entity_id = NEW.id;
  RETURN NEW;
END;
$function$
;

-- public.data_subject_requests_guard_payload()

CREATE OR REPLACE FUNCTION public.data_subject_requests_guard_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_phone text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated'
     OR public.is_admin_or_manager(auth.uid()) THEN
    RETURN NEW;
  END IF;

  SELECT c.phone INTO v_phone
    FROM public.clients c
   WHERE lower(c.email) = lower(NEW.subject_email)
     AND c.phone IS NOT NULL
   LIMIT 1;

  IF v_phone IS NULL THEN
    NEW.payload := COALESCE(NEW.payload, '{}'::jsonb) - 'phone';
  ELSE
    NEW.payload := jsonb_set(
      COALESCE(NEW.payload, '{}'::jsonb), '{phone}', to_jsonb(v_phone), true);
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.declare_step_winner(_step_id uuid, _variant_label text)

CREATE OR REPLACE FUNCTION public.declare_step_winner(_step_id uuid, _variant_label text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _v record;
BEGIN
  IF NOT public.user_owns_sequence_step(_step_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT * INTO _v FROM public.sequence_step_variants WHERE step_id = _step_id AND label = _variant_label;
  IF NOT FOUND THEN RAISE EXCEPTION 'Variant not found'; END IF;
  UPDATE public.sequence_steps SET subject = _v.subject, body = _v.body WHERE id = _step_id;
  DELETE FROM public.sequence_step_variants WHERE step_id = _step_id;
  RETURN true;
END;
$function$
;

-- public.dequeue_call_recording_ingest_jobs(_batch_size integer, _worker_id text)

CREATE OR REPLACE FUNCTION public.dequeue_call_recording_ingest_jobs(_batch_size integer DEFAULT 10, _worker_id text DEFAULT 'edge-worker'::text)
 RETURNS SETOF call_recording_ingest_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  UPDATE public.call_recording_ingest_jobs j
     SET status     = 'processing',
         attempts   = j.attempts + 1,
         locked_at  = now(),
         locked_by  = _worker_id,
         updated_at = now()
   WHERE j.id IN (
     SELECT id
       FROM public.call_recording_ingest_jobs
      WHERE status IN ('pending','processing')
        AND next_attempt_at <= now()
        AND (locked_at IS NULL OR locked_at < now() - INTERVAL '5 minutes')
      ORDER BY next_attempt_at ASC
      FOR UPDATE SKIP LOCKED
      LIMIT _batch_size
   )
  RETURNING *;
END;
$function$
;

-- public.detect_renewal_risks()

CREATE OR REPLACE FUNCTION public.detect_renewal_risks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _updated int := 0;
BEGIN
  UPDATE public.renewals
  SET status = 'at_risk', updated_at = now()
  WHERE status = 'upcoming'
    AND renewal_date <= CURRENT_DATE + INTERVAL '60 days'
    AND account_id IN (
      SELECT a.id FROM public.accounts a
      WHERE a.health_status IN ('critical','at_risk')
    );
  GET DIAGNOSTICS _updated = ROW_COUNT;

  UPDATE public.renewals
  SET status = 'churned', updated_at = now()
  WHERE status IN ('upcoming','at_risk')
    AND renewal_date < CURRENT_DATE - INTERVAL '7 days'
    AND auto_renew = false;

  RETURN _updated;
END;
$function$
;

-- public.detect_slow_queries(_mean_ms double precision, _min_calls bigint)

CREATE OR REPLACE FUNCTION public.detect_slow_queries(_mean_ms double precision DEFAULT 500, _min_calls bigint DEFAULT 100)
 RETURNS TABLE(inserted integer, updated integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ins integer := 0;
  upd integer := 0;
  r record;
  h text;
BEGIN
  IF _mean_ms <= 0 OR _min_calls <= 0 THEN
    RAISE EXCEPTION 'thresholds_must_be_positive' USING ERRCODE = '22023';
  END IF;

  FOR r IN
    SELECT
      left(pss.query, 500) AS query_text,
      pss.calls,
      pss.total_exec_time,
      pss.mean_exec_time,
      pss.max_exec_time
    FROM extensions.pg_stat_statements AS pss
    JOIN pg_catalog.pg_database AS d
      ON d.oid = pss.dbid
     AND d.datname = current_database()
    WHERE pss.mean_exec_time >= _mean_ms
      AND pss.calls >= _min_calls
      AND pss.query !~* '^(SET |BEGIN|COMMIT|ROLLBACK|SHOW |DEALLOCATE|DISCARD|VACUUM|ANALYZE|LISTEN|NOTIFY)'
      AND pss.query NOT ILIKE '%pg_stat_statements%'
      AND pss.query NOT ILIKE '%pg_catalog.%'
    ORDER BY pss.mean_exec_time DESC
    LIMIT 50
  LOOP
    h := encode(extensions.digest(r.query_text, 'sha1'), 'hex');

    INSERT INTO public.slow_query_alerts(
      query_hash, query_preview, mean_exec_ms, max_exec_ms,
      calls, total_exec_ms, threshold_mean_ms, threshold_min_calls
    )
    VALUES (
      h, r.query_text, r.mean_exec_time, r.max_exec_time,
      r.calls, r.total_exec_time, _mean_ms, _min_calls
    )
    ON CONFLICT (query_hash) WHERE acknowledged_at IS NULL
    DO UPDATE SET
      last_detected_at = now(),
      detection_count = public.slow_query_alerts.detection_count + 1,
      mean_exec_ms = EXCLUDED.mean_exec_ms,
      max_exec_ms = EXCLUDED.max_exec_ms,
      calls = EXCLUDED.calls,
      total_exec_ms = EXCLUDED.total_exec_ms;

    IF FOUND THEN
      IF (
        SELECT detection_count = 1
        FROM public.slow_query_alerts
        WHERE query_hash = h AND acknowledged_at IS NULL
      ) THEN
        ins := ins + 1;
      ELSE
        upd := upd + 1;
      END IF;
    END IF;
  END LOOP;

  INSERT INTO public.maintenance_log(
    job_name, status, completed_at, rows_affected, metadata
  ) VALUES (
    'detect_slow_queries',
    'completed',
    now(),
    ins + upd,
    jsonb_build_object(
      'inserted', ins,
      'updated', upd,
      'threshold_mean_ms', _mean_ms,
      'threshold_min_calls', _min_calls
    )
  );

  inserted := ins;
  updated := upd;
  RETURN NEXT;
END;
$function$
;

-- public.detect_stalled_cron_jobs()

CREATE OR REPLACE FUNCTION public.detect_stalled_cron_jobs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron'
AS $function$
DECLARE
  v_alerts_created integer := 0;
  v_inserted integer;
  v_job record;
  v_last_run timestamptz;
  v_expected_interval interval;
  v_threshold interval;
  v_gap interval;
BEGIN
  FOR v_job IN
    SELECT jobid, jobname, schedule
    FROM cron.job
    WHERE active = true
      AND jobname NOT IN ('cron-failure-alerter-10min', 'detect-stalled-cron-15min')
  LOOP
    v_expected_interval := public.fn_cron_expected_interval(v_job.schedule);
    v_threshold := public.fn_cron_stalled_threshold(v_job.schedule);

    SELECT max(start_time)
      INTO v_last_run
      FROM cron.job_run_details
     WHERE jobid = v_job.jobid;
    IF v_last_run IS NULL THEN
      v_last_run := now() - interval '30 days';
    END IF;
    v_gap := now() - v_last_run;

    IF v_gap > v_threshold
       AND NOT EXISTS (
         SELECT 1
         FROM public.cron_failure_alerts
         WHERE jobid = v_job.jobid
           AND status = 'stalled'
           AND alerted_at > now() - interval '6 hours'
       ) THEN
      INSERT INTO public.cron_failure_alerts (
        jobid, jobname, start_time, status, return_message,
        alerted_at, notified_admin_count
      ) VALUES (
        v_job.jobid,
        v_job.jobname,
        v_last_run,
        'stalled',
        format(
          'Job %s não executa há %s (esperado a cada %s, threshold %s).',
          v_job.jobname,
          v_gap::text,
          v_expected_interval::text,
          v_threshold::text
        ),
        now(),
        0
      )
      ON CONFLICT (jobid, start_time) DO NOTHING;
      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      v_alerts_created := v_alerts_created + v_inserted;
    END IF;
  END LOOP;

  RETURN v_alerts_created;
END;
$function$
;

