-- public.enforce_status_transition()

CREATE OR REPLACE FUNCTION public.enforce_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Escopo: writes feitos por usuários do app via PostgREST. service_role,
  -- postgres e demais conexões internas são writers de sistema (sync, crons,
  -- migrations) e não são bloqueados — usam as RPCs quando aplicável.
  IF current_user NOT IN ('authenticated', 'anon') THEN
    RETURN NEW;
  END IF;

  IF OLD.status IS NULL OR NEW.status IS NULL OR OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  IF NOT public.is_valid_status_transition(TG_TABLE_NAME, OLD.status, NEW.status) THEN
    RAISE EXCEPTION 'Transição de status inválida em %: % → %',
      TG_TABLE_NAME, OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.enforce_telemetry_retention()

CREATE OR REPLACE FUNCTION public.enforce_telemetry_retention()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_deleted bigint;
  v_tbl text;
  v_ttl_30 text[] := ARRAY[
    'page_analytics',
    'web_vitals_samples',
    'rate_limit_logs',
    'geo_access_logs',
    'access_denied_logs',
    'login_attempts',
    'email_tracking_events',
    'duplicate_block_logs',
    'integration_logs',
    'inbound_reply_events',
    'activity_audit_logs',
    'webhook_deliveries'
  ];
  v_ttl_90 text[] := ARRAY['error_logs','audit_logs'];
BEGIN
  FOREACH v_tbl IN ARRAY v_ttl_30 LOOP
    BEGIN
      EXECUTE format(
        'DELETE FROM public.%I WHERE created_at < now() - interval ''30 days''',
        v_tbl
      );
      GET DIAGNOSTICS v_deleted = ROW_COUNT;
      v_result := v_result || jsonb_build_object(v_tbl, v_deleted);
    EXCEPTION WHEN undefined_column OR undefined_table THEN
      -- tabela pode não ter created_at ou pode ter sido renomeada; ignora
      v_result := v_result || jsonb_build_object(v_tbl, 'skipped');
    END;
  END LOOP;

  FOREACH v_tbl IN ARRAY v_ttl_90 LOOP
    BEGIN
      EXECUTE format(
        'DELETE FROM public.%I WHERE created_at < now() - interval ''90 days''',
        v_tbl
      );
      GET DIAGNOSTICS v_deleted = ROW_COUNT;
      v_result := v_result || jsonb_build_object(v_tbl, v_deleted);
    EXCEPTION WHEN undefined_column OR undefined_table THEN
      v_result := v_result || jsonb_build_object(v_tbl, 'skipped');
    END;
  END LOOP;

  RETURN v_result;
END;
$function$
;

-- public.enqueue_v4_callback()

CREATE OR REPLACE FUNCTION public.enqueue_v4_callback()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.external_quote_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN ('approved', 'rejected', 'expired', 'sent') THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.v4_callback_dead_letters (
    external_quote_id, quote_id, event_type, payload, next_retry_at
  )
  VALUES (
    NEW.external_quote_id,
    NEW.id,
    'quote_status_changed',
    jsonb_build_object(
      'external_quote_id', NEW.external_quote_id,
      'quote_id', NEW.id,
      'new_status', NEW.status,
      'quote_number', NEW.quote_number,
      'total', NEW.total_value,
      'updated_at', NEW.updated_at
    ),
    now()
  );

  RETURN NEW;
END;
$function$
;

-- public.enroll_quote_in_cadence(_quote_id uuid, _cadence_id uuid)

CREATE OR REPLACE FUNCTION public.enroll_quote_in_cadence(_quote_id uuid, _cadence_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_enrollment_id uuid;
  v_salesperson_id uuid;
  v_first_day int;
  v_first_date date;
BEGIN
  SELECT sp.id INTO v_salesperson_id
  FROM public.quotes q
  LEFT JOIN public.salespeople sp ON sp.auth_user_id = q.created_by
  WHERE q.id = _quote_id;

  SELECT COALESCE(MIN(day_number), 1) INTO v_first_day
  FROM public.cadence_steps WHERE cadence_id = _cadence_id;

  v_first_date := CURRENT_DATE + (v_first_day - 1);

  INSERT INTO public.prospect_cadences (
    quote_id, cadence_id, salesperson_id, enrollment_source, next_action_date
  ) VALUES (
    _quote_id, _cadence_id, v_salesperson_id, 'manual', v_first_date
  )
  RETURNING id INTO v_enrollment_id;

  INSERT INTO public.cadence_tasks (prospect_cadence_id, cadence_step_id, scheduled_date)
  SELECT v_enrollment_id, cs.id, CURRENT_DATE + (cs.day_number - 1)
  FROM public.cadence_steps cs
  WHERE cs.cadence_id = _cadence_id
  ORDER BY cs.step_order;

  RETURN v_enrollment_id;
END;
$function$
;

-- public.ensure_single_default_filter()

CREATE OR REPLACE FUNCTION public.ensure_single_default_filter()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE public.saved_filters
    SET is_default = false
    WHERE user_id = NEW.user_id
      AND entity_type = NEW.entity_type
      AND id != NEW.id
      AND is_default = true;
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.finalize_race_season(_season_id uuid)

CREATE OR REPLACE FUNCTION public.finalize_race_season(_season_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _winner_id uuid;
  _top_rows jsonb;
  _season_name text;
BEGIN
  -- Apenas admins podem finalizar
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'Apenas administradores podem finalizar temporadas';
  END IF;

  SELECT name INTO _season_name FROM public.race_seasons WHERE id = _season_id;
  IF _season_name IS NULL THEN
    RAISE EXCEPTION 'Temporada não encontrada';
  END IF;

  -- Top 1 e top 5 do leaderboard
  SELECT salesperson_id INTO _winner_id
  FROM public.race_leaderboard_view
  WHERE season_id = _season_id
  ORDER BY progress DESC NULLS LAST, score DESC NULLS LAST, total_sales DESC NULLS LAST
  LIMIT 1;

  SELECT jsonb_agg(row_to_json(t)) INTO _top_rows
  FROM (
    SELECT salesperson_id, salesperson_name, progress, score, total_sales, deals_count
    FROM public.race_leaderboard_view
    WHERE season_id = _season_id
    ORDER BY progress DESC NULLS LAST, score DESC NULLS LAST
    LIMIT 5
  ) t;

  -- Atualiza temporada
  UPDATE public.race_seasons
  SET status = 'finished',
      winner_id = _winner_id,
      updated_at = now()
  WHERE id = _season_id;

  -- Insere evento de campeão do mês
  IF _winner_id IS NOT NULL THEN
    INSERT INTO public.race_events (season_id, salesperson_id, event_type, metadata)
    VALUES (
      _season_id,
      _winner_id,
      'monthly_champion',
      jsonb_build_object(
        'season_name', _season_name,
        'finalized_at', now(),
        'top5', COALESCE(_top_rows, '[]'::jsonb)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'season_id', _season_id,
    'winner_id', _winner_id,
    'top5', COALESCE(_top_rows, '[]'::jsonb)
  );
END;
$function$
;

-- public.find_matching_cadence_rule(_sale_id uuid)

CREATE OR REPLACE FUNCTION public.find_matching_cadence_rule(_sale_id uuid)
 RETURNS TABLE(rule_id uuid, cadence_id uuid, rule_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sale RECORD;
BEGIN
  SELECT s.id, s.stage, s.category, s.source, s.amount
  INTO _sale
  FROM public.sales s
  WHERE s.id = _sale_id;

  IF _sale.id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT r.id, r.cadence_id, r.name
  FROM public.cadence_enrollment_rules r
  WHERE r.is_active = true
    AND (r.trigger_stage IS NULL OR r.trigger_stage = _sale.stage)
    AND (r.trigger_category IS NULL OR r.trigger_category = _sale.category)
    AND (r.trigger_source IS NULL OR r.trigger_source = _sale.source)
    AND (r.min_amount IS NULL OR _sale.amount >= r.min_amount)
    AND (r.max_amount IS NULL OR _sale.amount <= r.max_amount)
    -- Não re-inscrever se já existe cadência ativa com a mesma cadence_id
    AND NOT EXISTS (
      SELECT 1 FROM public.prospect_cadences pc
      WHERE pc.sale_id = _sale_id
        AND pc.cadence_id = r.cadence_id
        AND pc.status IN ('active', 'paused')
    )
  ORDER BY r.priority ASC
  LIMIT 1;
END;
$function$
;

-- public.fn_admin_cleanup_stale_logs(_days integer)

CREATE OR REPLACE FUNCTION public.fn_admin_cleanup_stale_logs(_days integer DEFAULT 90)
 RETURNS TABLE(table_name text, deleted_rows bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'permission denied: admin role required' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.fn_cleanup_stale_logs(_days);
END;
$function$
;

-- public.fn_admin_conversion_trail(_quote_id uuid, _sale_id uuid)

CREATE OR REPLACE FUNCTION public.fn_admin_conversion_trail(_quote_id uuid DEFAULT NULL::uuid, _sale_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_quote UUID := _quote_id;
  v_sale  UUID := _sale_id;
  v_result JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION '[NOT_AUTHENTICATED] auth.uid() ausente';
  END IF;
  IF NOT public.has_role(v_uid, 'admin') THEN
    RAISE EXCEPTION '[FORBIDDEN] admin role requerido';
  END IF;
  IF v_quote IS NULL AND v_sale IS NULL THEN
    RAISE EXCEPTION '[INVALID_INPUT] informe quote_id ou sale_id';
  END IF;

  -- Resolve o par (quote_id, sale_id) a partir do que veio
  IF v_quote IS NULL THEN
    SELECT id INTO v_quote FROM public.quotes WHERE sale_id = v_sale LIMIT 1;
  END IF;
  IF v_sale IS NULL THEN
    SELECT sale_id INTO v_sale FROM public.quotes WHERE id = v_quote LIMIT 1;
  END IF;

  SELECT jsonb_build_object(
    'quote_id', v_quote,
    'sale_id',  v_sale,
    'quote',    (SELECT to_jsonb(q) FROM public.quotes q WHERE q.id = v_quote),
    'sale',     (SELECT to_jsonb(s) FROM public.sales s WHERE s.id = v_sale),
    'orders',   COALESCE((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.created_at)
                         FROM public.orders o WHERE o.quote_id = v_quote), '[]'::jsonb),
    'order_items', COALESCE((SELECT jsonb_agg(to_jsonb(oi))
                             FROM public.order_items oi
                             JOIN public.orders o ON o.id = oi.order_id
                             WHERE o.quote_id = v_quote), '[]'::jsonb),
    'quote_items', COALESCE((SELECT jsonb_agg(to_jsonb(qi))
                             FROM public.quote_items qi WHERE qi.quote_id = v_quote), '[]'::jsonb),
    'conversion_audit', COALESCE((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.created_at)
                                   FROM public.quote_conversion_audit a
                                   WHERE a.quote_id = v_quote OR a.sale_id = v_sale), '[]'::jsonb),
    'sale_notifications', COALESCE((SELECT jsonb_agg(to_jsonb(n) ORDER BY n.created_at)
                                     FROM public.sale_notifications_audit n
                                     WHERE n.sale_id = v_sale), '[]'::jsonb),
    'follow_up_notifications', COALESCE((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.created_at)
                                          FROM public.follow_up_notifications f
                                          WHERE f.sale_id = v_sale), '[]'::jsonb),
    'follow_up_audit_logs', COALESCE((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.created_at)
                                       FROM public.follow_up_audit_logs l
                                       WHERE l.sale_id = v_sale), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END $function$
;

-- public.fn_admin_cron_alert_breakdown()

CREATE OR REPLACE FUNCTION public.fn_admin_cron_alert_breakdown()
 RETURNS TABLE(jobname text, alerts integer, stalled integer, failed integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role'
     AND NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'access_denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    COALESCE(a.jobname, 'unknown') AS jobname,
    COUNT(*)::int AS alerts,
    COUNT(*) FILTER (WHERE a.status = 'stalled')::int AS stalled,
    COUNT(*) FILTER (WHERE a.status = 'failed')::int AS failed
  FROM public.cron_failure_alerts a
  WHERE a.created_at >= now() - interval '24 hours'
  GROUP BY COALESCE(a.jobname, 'unknown')
  ORDER BY alerts DESC
  LIMIT 20;
END;
$function$
;

-- public.fn_admin_cron_alert_metrics()

CREATE OR REPLACE FUNCTION public.fn_admin_cron_alert_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_24h_total       INTEGER;
  v_24h_stalled     INTEGER;
  v_24h_failed      INTEGER;
  v_24h_jobs        INTEGER;
  v_7d_total        INTEGER;
  v_7d_stalled      INTEGER;
  v_7d_jobs         INTEGER;
  v_raw_failures_24h INTEGER;
  v_dedupe_saved_24h INTEGER;
  v_last_alert      TIMESTAMPTZ;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE status='stalled'),
         COUNT(*) FILTER (WHERE status<>'stalled'), COUNT(DISTINCT jobid)
    INTO v_24h_total, v_24h_stalled, v_24h_failed, v_24h_jobs
  FROM public.cron_failure_alerts
  WHERE alerted_at > now() - interval '24 hours';

  SELECT COUNT(*), COUNT(*) FILTER (WHERE status='stalled'), COUNT(DISTINCT jobid)
    INTO v_7d_total, v_7d_stalled, v_7d_jobs
  FROM public.cron_failure_alerts
  WHERE alerted_at > now() - interval '7 days';

  SELECT MAX(alerted_at) INTO v_last_alert FROM public.cron_failure_alerts;

  -- Estimativa de dedupe: falhas brutas do cron nas últimas 24h vs registros alertados.
  BEGIN
    SELECT COUNT(*) INTO v_raw_failures_24h
    FROM cron.job_run_details
    WHERE status <> 'succeeded' AND start_time > now() - interval '24 hours';
  EXCEPTION WHEN OTHERS THEN
    v_raw_failures_24h := NULL;
  END;

  IF v_raw_failures_24h IS NOT NULL THEN
    v_dedupe_saved_24h := GREATEST(0, v_raw_failures_24h - v_24h_total);
  ELSE
    v_dedupe_saved_24h := NULL;
  END IF;

  RETURN jsonb_build_object(
    'last_alert_at',       v_last_alert,
    'window_24h', jsonb_build_object(
      'alerts_total',      v_24h_total,
      'alerts_stalled',    v_24h_stalled,
      'alerts_failed',     v_24h_failed,
      'jobs_affected',     v_24h_jobs,
      'raw_failures',      v_raw_failures_24h,
      'dedupe_saved',      v_dedupe_saved_24h
    ),
    'window_7d', jsonb_build_object(
      'alerts_total',      v_7d_total,
      'alerts_stalled',    v_7d_stalled,
      'jobs_affected',     v_7d_jobs
    ),
    'generated_at',        now()
  );
END;
$function$
;

-- public.fn_admin_get_new_cron_failures(_since_minutes integer)

CREATE OR REPLACE FUNCTION public.fn_admin_get_new_cron_failures(_since_minutes integer DEFAULT 30)
 RETURNS TABLE(jobid bigint, jobname text, status text, return_message text, start_time timestamp with time zone, end_time timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Permite chamadas via service_role (auth.uid IS NULL). Chamadas de usuário
  -- só passam se forem admin. EXECUTE está restrito a service_role via GRANT,
  -- então este check é defesa em profundidade.
  IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  RETURN QUERY
  SELECT jrd.jobid, j.jobname, jrd.status, jrd.return_message, jrd.start_time, jrd.end_time
  FROM cron.job_run_details jrd
  LEFT JOIN cron.job j ON j.jobid = jrd.jobid
  WHERE jrd.status <> 'succeeded'
    AND jrd.start_time > now() - make_interval(mins => _since_minutes)
    AND NOT EXISTS (
      SELECT 1 FROM public.cron_failure_alerts a
      WHERE a.jobid = jrd.jobid AND a.start_time = jrd.start_time
    )
  ORDER BY jrd.start_time DESC
  LIMIT 200;
END;
$function$
;

-- public.fn_admin_list_dead_letter_ingest_jobs(_limit integer)

CREATE OR REPLACE FUNCTION public.fn_admin_list_dead_letter_ingest_jobs(_limit integer DEFAULT 100)
 RETURNS TABLE(id uuid, idempotency_key text, salesperson_id uuid, attempts integer, last_error text, locked_by text, created_at timestamp with time zone, updated_at timestamp with time zone, next_attempt_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role'
     AND NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'access_denied' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT j.id, j.idempotency_key, j.salesperson_id, j.attempts,
         j.last_error, j.locked_by, j.created_at, j.updated_at, j.next_attempt_at
  FROM public.call_recording_ingest_jobs j
  WHERE j.status = 'dead_letter'
  ORDER BY j.updated_at DESC
  LIMIT GREATEST(1, LEAST(_limit, 500));
END;
$function$
;

-- public.fn_admin_mark_cron_failure_alerted(_jobid bigint, _jobname text, _start_time timestamp with time zone, _status text, _return_message text, _notified_admin_count integer)

CREATE OR REPLACE FUNCTION public.fn_admin_mark_cron_failure_alerted(_jobid bigint, _jobname text, _start_time timestamp with time zone, _status text, _return_message text, _notified_admin_count integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _id UUID;
BEGIN
  INSERT INTO public.cron_failure_alerts (
    jobid, jobname, start_time, status, return_message, notified_admin_count
  ) VALUES (
    _jobid, _jobname, _start_time, _status, _return_message, _notified_admin_count
  )
  ON CONFLICT (jobid, start_time) DO UPDATE
    SET notified_admin_count = EXCLUDED.notified_admin_count,
        alerted_at = now()
  RETURNING id INTO _id;

  RETURN _id;
END;
$function$
;

-- public.fn_admin_platform_slo()

CREATE OR REPLACE FUNCTION public.fn_admin_replay_dead_letter_ingest_job(_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _rows int := 0;
  _locked boolean;
  _role text := auth.role();
  _uid uuid := auth.uid();
BEGIN
  IF _role <> 'service_role' AND NOT public.has_role(_uid, 'admin') THEN
    RAISE EXCEPTION 'access_denied' USING ERRCODE = '42501';
  END IF;

  -- Advisory lock scoped to this job_id to prevent concurrent replays
  _locked := pg_try_advisory_xact_lock(hashtextextended('dlq_replay:' || _job_id::text, 0));
  IF NOT _locked THEN
    INSERT INTO public.dead_letter_replay_audit(job_id, performed_by, performed_role, outcome)
    VALUES (_job_id, _uid, COALESCE(_role,'unknown'), 'skipped_locked');
    RETURN false;
  END IF;

  WITH candidate AS (
    SELECT id FROM public.call_recording_ingest_jobs
     WHERE id = _job_id AND status = 'dead_letter'
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.call_recording_ingest_jobs j
     SET status = 'pending',
         attempts = 0,
         last_error = NULL,
         locked_at = NULL,
         locked_by = NULL,
         next_attempt_at = now(),
         updated_at = now()
    FROM candidate c
   WHERE j.id = c.id;

  GET DIAGNOSTICS _rows = ROW_COUNT;

  INSERT INTO public.dead_letter_replay_audit(job_id, performed_by, performed_role, outcome)
  VALUES (_job_id, _uid, COALESCE(_role,'unknown'),
          CASE WHEN _rows > 0 THEN 'replayed' ELSE 'not_found_or_not_dead_letter' END);

  RETURN _rows > 0;
END;
$function$
;

-- public.fn_admin_reset_circuit(_circuit_name text, _reason text)

CREATE OR REPLACE FUNCTION public.fn_admin_reset_circuit(_circuit_name text, _reason text DEFAULT 'manual_reset'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _id UUID;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'permission denied: admin role required' USING ERRCODE = '42501';
  END IF;
  IF _circuit_name IS NULL OR length(_circuit_name) = 0 THEN
    RAISE EXCEPTION 'circuit_name required' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.circuit_breaker_events (
    circuit_name, event_type, previous_state, new_state, failure_count, details
  ) VALUES (
    _circuit_name,
    'closed',
    'OPEN',
    'CLOSED',
    0,
    jsonb_build_object('reason', _reason, 'actor', auth.uid())
  )
  RETURNING id INTO _id;

  RETURN _id;
END;
$function$
;

-- public.fn_admin_security_definer_exposure()

CREATE OR REPLACE FUNCTION public.fn_apply_data_retention()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  v_n bigint;
  v_total bigint;
  v_counts jsonb := '{}'::jsonb;
  v_cutoff timestamptz;
  v_batch constant int := 10000;
BEGIN
  FOR r IN
    SELECT p.table_name, p.ts_column, p.retention_days
    FROM public.data_retention_policies p
    WHERE p.enabled
    ORDER BY p.table_name
  LOOP
    v_total := 0;
    v_cutoff := now() - make_interval(days => r.retention_days);

    -- Tabela ou coluna ausente: política pulada sem derrubar o job.
    IF to_regclass('public.' || r.table_name) IS NULL
       OR NOT EXISTS (
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public'
              AND table_name = r.table_name
              AND column_name = r.ts_column) THEN
      v_counts := v_counts || jsonb_build_object(r.table_name, 'skipped:missing');
      CONTINUE;
    END IF;

    -- Qualquer erro numa tabela (coluna id ausente, permissão, drift de schema)
    -- é registrado e não derruba o job das demais.
    BEGIN
      IF r.table_name = 'website_visitor_logs' THEN
        -- Regra LGPD: purga expirados E sem consentimento ativo vinculado.
        LOOP
          EXECUTE format(
            'DELETE FROM public.%I WHERE id IN (
               SELECT w.id FROM public.%I w
               WHERE NOT EXISTS (
                       SELECT 1 FROM public.consent_records c
                       WHERE c.id = w.consent_record_id AND c.revoked_at IS NULL)
                 AND (w.retention_expires_at < now()
                      OR w.consent_record_id IS NOT NULL)
               LIMIT %s)',
            r.table_name, r.table_name, v_batch);
          GET DIAGNOSTICS v_n = ROW_COUNT;
          v_total := v_total + v_n;
          EXIT WHEN v_n = 0;
        END LOOP;
      ELSE
        LOOP
          EXECUTE format(
            'DELETE FROM public.%I WHERE id IN (
               SELECT id FROM public.%I
               WHERE %I < $1
               LIMIT %s)',
            r.table_name, r.table_name, r.ts_column, v_batch)
          USING v_cutoff;
          GET DIAGNOSTICS v_n = ROW_COUNT;
          v_total := v_total + v_n;
          EXIT WHEN v_n = 0;
        END LOOP;
      END IF;

      v_counts := v_counts || jsonb_build_object(r.table_name, v_total);
    EXCEPTION WHEN OTHERS THEN
      v_counts := v_counts || jsonb_build_object(r.table_name, 'error:' || SQLERRM);
    END;
  END LOOP;

  RETURN v_counts;
END;
$function$
;

-- public.fn_auto_map_inbound_seller()

CREATE OR REPLACE FUNCTION public.fn_auto_map_inbound_seller()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_salesperson_id UUID;
BEGIN
  IF NEW.seller_email IS NULL THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.external_seller_map
    WHERE lower(trim(E'\t\n\r ' FROM external_email)) = lower(NEW.seller_email)
      AND external_source = NEW.source
  ) THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_salesperson_id
  FROM public.salespeople
  WHERE lower(trim(E'\t\n\r ' FROM email)) = lower(NEW.seller_email)
    AND is_active = true
  LIMIT 1;

  IF v_salesperson_id IS NOT NULL THEN
    INSERT INTO public.external_seller_map (
      external_id, external_source, salesperson_id, external_email
    )
    VALUES (
      lower(NEW.seller_email),
      NEW.source,
      v_salesperson_id,
      lower(NEW.seller_email)
    )
    ON CONFLICT (external_id, external_source) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.fn_backfill_orders_conversion_seq()

CREATE OR REPLACE FUNCTION public.fn_backfill_orders_conversion_seq()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION '[NOT_AUTHENTICATED] Sessão ausente' USING ERRCODE = '42501';
  END IF;
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION '[FORBIDDEN] Apenas administradores podem reexecutar o backfill' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_result FROM public.backfill_orders_conversion_seq();

  RETURN jsonb_build_object(
    'previous_value', v_result.previous_value,
    'new_value', v_result.new_value,
    'legacy_max', v_result.legacy_max
  );
END;
$function$
;

-- public.fn_calculate_icp_score()

CREATE OR REPLACE FUNCTION public.fn_calculate_icp_score()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_params RECORD;
    v_score INTEGER := 0;
    v_match BOOLEAN := FALSE;
BEGIN
    -- Get the most recent parameters (or default)
    SELECT * INTO v_params FROM public.icp_parameters ORDER BY created_at DESC LIMIT 1;
    
    IF v_params IS NULL THEN
        -- Default weights if no parameters exist
        v_params := (SELECT NULL::public.icp_parameters);
        v_params.target_industries := '{}';
        v_params.preferred_niches := '{}';
        v_params.min_capital := 0;
        v_params.min_employees := 0;
        v_params.weight_industry := 30;
        v_params.weight_capital := 20;
        v_params.weight_employees := 20;
        v_params.weight_niche := 30;
    END IF;

    -- 1. Industry Fit (Weight 30)
    IF NEW.ramo_atividade IS NOT NULL AND NEW.ramo_atividade = ANY(v_params.target_industries) THEN
        v_score := v_score + v_params.weight_industry;
    END IF;

    -- 2. Capital Fit (Weight 20)
    IF NEW.capital_social >= v_params.min_capital THEN
        v_score := v_score + v_params.weight_capital;
    END IF;

    -- 3. Employees Fit (Weight 20)
    IF NEW.num_colaboradores >= v_params.min_employees THEN
        v_score := v_score + v_params.weight_employees;
    END IF;

    -- 4. Niche Fit (Weight 30)
    IF NEW.grupo_nicho IS NOT NULL AND NEW.grupo_nicho = ANY(v_params.preferred_niches) THEN
        v_score := v_score + v_params.weight_niche;
    END IF;

    -- Set match if score >= 70 (or other threshold)
    IF v_score >= 70 THEN
        v_match := TRUE;
    END IF;

    NEW.icp_score := v_score;
    NEW.is_icp_match := v_match;
    NEW.updated_at := now();

    RETURN NEW;
END;
$function$
;

-- public.fn_check_slo_burn_rate()

CREATE OR REPLACE FUNCTION public.fn_check_slo_burn_rate()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _thr_1h  numeric := COALESCE(
    (SELECT (value #>> '{}')::numeric FROM public.app_config WHERE key = 'slo.burn_rate_1h'), 0.20);
  _thr_24h numeric := COALESCE(
    (SELECT (value #>> '{}')::numeric FROM public.app_config WHERE key = 'slo.burn_rate_24h'), 0.10);
  _min_n   bigint := COALESCE(
    (SELECT (value #>> '{}')::bigint FROM public.app_config WHERE key = 'slo.min_samples'), 20);
  _all_1h  record;
  _all_24h record;
  _alerts  jsonb := '[]'::jsonb;
BEGIN
  -- Guards: sem as tabelas-fonte ou sem app_config, não há como medir — retorna skipped.
  IF to_regclass('public.winloss_webhook_deliveries') IS NULL
     AND to_regclass('public.email_logs') IS NULL THEN
    RETURN jsonb_build_object('skipped', 'no_source_tables');
  END IF;

  SELECT * INTO _all_1h  FROM public.fn_slo_burn_rate(interval '1 hour')  WHERE source = 'all';
  SELECT * INTO _all_24h FROM public.fn_slo_burn_rate(interval '24 hours') WHERE source = 'all';

  IF _all_1h.total >= _min_n AND _all_1h.rate > _thr_1h THEN
    INSERT INTO public.security_events (event_type, severity, description, metadata)
    VALUES (
      'slo_burn_rate', 'critical',
      format('Burn-rate 1h acima do threshold: %s > %s (%s/%s entregas falharam)',
             _all_1h.rate, _thr_1h, _all_1h.failed, _all_1h.total),
      jsonb_build_object(
        'window', '1h', 'rate', _all_1h.rate, 'threshold', _thr_1h,
        'total', _all_1h.total, 'failed', _all_1h.failed,
        'runbook', 'docs/runbooks/alertas-operacionais.md')
    );
    _alerts := _alerts || jsonb_build_object('window', '1h', 'rate', _all_1h.rate, 'threshold', _thr_1h);
  END IF;

  IF _all_24h.total >= _min_n AND _all_24h.rate > _thr_24h THEN
    INSERT INTO public.security_events (event_type, severity, description, metadata)
    VALUES (
      'slo_burn_rate', 'critical',
      format('Burn-rate 24h acima do threshold: %s > %s (%s/%s entregas falharam)',
             _all_24h.rate, _thr_24h, _all_24h.failed, _all_24h.total),
      jsonb_build_object(
        'window', '24h', 'rate', _all_24h.rate, 'threshold', _thr_24h,
        'total', _all_24h.total, 'failed', _all_24h.failed,
        'runbook', 'docs/runbooks/alertas-operacionais.md')
    );
    _alerts := _alerts || jsonb_build_object('window', '24h', 'rate', _all_24h.rate, 'threshold', _thr_24h);
  END IF;

  RETURN jsonb_build_object(
    'burn_rate_1h',  COALESCE(_all_1h.rate, 0),  'total_1h',  COALESCE(_all_1h.total, 0),
    'burn_rate_24h', COALESCE(_all_24h.rate, 0), 'total_24h', COALESCE(_all_24h.total, 0),
    'threshold_1h', _thr_1h, 'threshold_24h', _thr_24h, 'min_samples', _min_n,
    'alerts', _alerts);
END;
$function$
;

-- public.fn_cleanup_stale_logs(_days integer)

CREATE OR REPLACE FUNCTION public.fn_cleanup_stale_logs(_days integer DEFAULT 90)
 RETURNS TABLE(table_name text, deleted_rows bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _cutoff TIMESTAMPTZ := now() - make_interval(days => _days);
  _tbl TEXT;
  _deleted BIGINT;
  _targets TEXT[] := ARRAY[
    'access_denied_logs',
    'geo_access_logs',
    'rate_limit_logs',
    'email_tracking_events',
    'login_attempts',
    'webhook_inbound_log',
    'error_logs',
    'duplicate_block_logs',
    'mfa_verification_attempts',
    'page_analytics'
  ];
BEGIN
  FOREACH _tbl IN ARRAY _targets LOOP
    BEGIN
      EXECUTE format(
        'WITH d AS (DELETE FROM public.%I WHERE created_at < $1 RETURNING 1) SELECT count(*) FROM d',
        _tbl
      ) INTO _deleted USING _cutoff;
      table_name := _tbl;
      deleted_rows := COALESCE(_deleted, 0);
      RETURN NEXT;
    EXCEPTION WHEN undefined_column OR undefined_table THEN
      CONTINUE;
    END;
  END LOOP;
END;
$function$
;

-- public.fn_cleanup_webhook_dedupe()

CREATE OR REPLACE FUNCTION public.fn_cleanup_webhook_dedupe()
 RETURNS TABLE(deleted_count bigint, oldest_kept timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted bigint;
  v_oldest timestamptz;
  v_started timestamptz := clock_timestamp();
BEGIN
  WITH deleted AS (
    DELETE FROM public.webhook_inbound_dedupe
    WHERE received_at < (now() - INTERVAL '90 days')
    RETURNING id
  )
  SELECT count(*) INTO v_deleted FROM deleted;

  SELECT min(received_at) INTO v_oldest FROM public.webhook_inbound_dedupe;

  -- Auditoria interna: sempre registra a execução (mesmo com 0 linhas)
  INSERT INTO public.maintenance_log (
    job_name, started_at, completed_at, rows_affected, status, metadata
  ) VALUES (
    'fn_cleanup_webhook_dedupe',
    v_started,
    clock_timestamp(),
    v_deleted,
    'completed',
    jsonb_build_object(
      'oldest_kept', v_oldest,
      'invoked_by', session_user,
      'current_user', current_user,
      'cutoff', (now() - INTERVAL '90 days')
    )
  );

  RETURN QUERY SELECT v_deleted, v_oldest;
END;
$function$
;

-- public.fn_convert_quote_to_sale(_quote_id uuid)

CREATE OR REPLACE FUNCTION public.fn_convert_quote_to_sale(_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quote        public.quotes%ROWTYPE;
  v_sale_id      uuid;
  v_order_id     uuid;
  v_caller       uuid := auth.uid();
  v_is_admin     boolean;
  v_caller_sp    uuid;
  v_item_count   int;
  v_items_total  numeric(15,2);
  v_product_desc text;
  v_order_number text;
  v_attempts     int := 0;
  v_reused_order boolean := false;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION '[NOT_AUTHENTICATED] Sessão inválida ou expirada' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = _quote_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '[QUOTE_NOT_FOUND] Orçamento não encontrado' USING ERRCODE = 'P0002';
  END IF;

  IF v_quote.sale_id IS NOT NULL THEN
    SELECT id, order_number
      INTO v_order_id, v_order_number
      FROM public.orders WHERE quote_id = _quote_id
      ORDER BY created_at ASC LIMIT 1;
    RETURN jsonb_build_object(
      'sale_id', v_quote.sale_id,
      'order_id', v_order_id,
      'order_number', v_order_number,
      'idempotent', true
    );
  END IF;

  SELECT public.has_role(v_caller, 'admin'::public.app_role) INTO v_is_admin;
  IF NOT v_is_admin THEN
    SELECT id INTO v_caller_sp FROM public.salespeople
     WHERE auth_user_id = v_caller AND is_active = true LIMIT 1;
    IF v_caller_sp IS NULL OR v_caller_sp IS DISTINCT FROM v_quote.created_by THEN
      RAISE EXCEPTION '[FORBIDDEN] Você não tem permissão para converter este orçamento' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF v_quote.status NOT IN ('accepted','approved','won') THEN
    RAISE EXCEPTION '[INVALID_STATUS] Orçamento precisa estar aprovado/aceito. Status atual: %', v_quote.status USING ERRCODE = '22023';
  END IF;

  IF v_quote.total_value IS NULL OR v_quote.total_value < 0 THEN
    RAISE EXCEPTION '[INVALID_TOTAL] Valor total do orçamento inválido' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*), COALESCE(SUM(total_price), 0)::numeric(15,2)
    INTO v_item_count, v_items_total FROM public.quote_items WHERE quote_id = _quote_id;

  IF v_item_count = 0 THEN
    RAISE EXCEPTION '[EMPTY_ITEMS] Orçamento sem itens não pode virar venda' USING ERRCODE = '22023';
  END IF;

  IF ABS(v_items_total - v_quote.total_value) > 0.02 THEN
    RAISE EXCEPTION '[TOTAL_MISMATCH] Total do orçamento (%) não bate com a soma dos itens (%)',
      v_quote.total_value, v_items_total USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(string_agg(product_name || ' x' || quantity, ', ' ORDER BY created_at), v_quote.title)
    INTO v_product_desc FROM public.quote_items WHERE quote_id = _quote_id;

  INSERT INTO public.sales (client_name, product_name, amount, salesperson_id, status, source, client_id)
  VALUES (v_quote.client_name, LEFT(COALESCE(v_product_desc, v_quote.title), 500),
          v_quote.total_value, v_quote.created_by, 'won', 'quote_conversion', v_quote.client_id)
  RETURNING id INTO v_sale_id;

  SELECT id, order_number INTO v_order_id, v_order_number
  FROM public.orders WHERE quote_id = _quote_id
  ORDER BY created_at ASC LIMIT 1
  FOR UPDATE;

  IF v_order_id IS NOT NULL THEN
    v_reused_order := true;
    UPDATE public.orders
       SET status   = 'confirmed',
           total    = v_quote.total_value,
           subtotal = COALESCE(v_quote.subtotal, v_quote.total_value),
           user_id  = COALESCE(user_id, v_caller),
           metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
             'sale_id', v_sale_id,
             'converted_by', v_caller,
             'converted_at', now(),
             'source', 'quote_conversion'
           ),
           updated_at = now()
     WHERE id = v_order_id;
  ELSE
    LOOP
      v_attempts := v_attempts + 1;
      v_order_number := 'ORC-' || to_char(now(), 'YYYYMMDD') || '-'
                        || lpad(nextval('public.orders_conversion_seq')::text, 8, '0');
      BEGIN
        INSERT INTO public.orders (order_number, status, subtotal, shipping, total,
          quote_id, client_id, salesperson_id, user_id, notes, metadata)
        VALUES (v_order_number, 'confirmed',
          COALESCE(v_quote.subtotal, v_quote.total_value), 0, v_quote.total_value,
          _quote_id, v_quote.client_id, v_quote.created_by, v_caller, v_quote.notes,
          jsonb_build_object('source','quote_conversion','sale_id',v_sale_id,
            'quote_number',v_quote.quote_number,'converted_by',v_caller,'converted_at',now()))
        RETURNING id INTO v_order_id;
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        IF v_attempts >= 5 THEN RAISE; END IF; CONTINUE;
      END;
    END LOOP;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.order_items WHERE order_id = v_order_id) THEN
    INSERT INTO public.order_items (order_id, product_name, quantity, unit_price)
    SELECT v_order_id, product_name, quantity, unit_price
      FROM public.quote_items WHERE quote_id = _quote_id;
  END IF;

  UPDATE public.quotes
     SET sale_id = v_sale_id, status = 'converted',
         approved_at = COALESCE(approved_at, now()), updated_at = now()
   WHERE id = _quote_id;

  -- Auditoria: usar colunas reais (entity_type/entity_id/actor_id)
  BEGIN
    INSERT INTO public.audit_logs (action, entity_type, entity_id, actor_id, metadata)
    VALUES ('convert_quote_to_sale','quote',_quote_id::text,v_caller,
      jsonb_build_object('quote_id',_quote_id,'sale_id',v_sale_id,'order_id',v_order_id,
        'order_number',v_order_number,'total_value',v_quote.total_value,
        'item_count',v_item_count,'reused_order',v_reused_order));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('sale_id', v_sale_id, 'order_id', v_order_id,
    'order_number', v_order_number, 'items_count', v_item_count,
    'reused_order', v_reused_order, 'idempotent', false);
END;
$function$
;

-- public.fn_cron_expected_interval(_schedule text)

CREATE OR REPLACE FUNCTION public.fn_cron_expected_interval(_schedule text)
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _schedule LIKE '*/5 * * * *'  THEN interval '5 minutes'
    WHEN _schedule LIKE '*/10 * * * *' THEN interval '10 minutes'
    WHEN _schedule LIKE '*/15 * * * *' THEN interval '15 minutes'
    WHEN _schedule LIKE '*/30 * * * *' THEN interval '30 minutes'
    WHEN _schedule ~ '^[0-9]+ \* \* \* \*$'         THEN interval '1 hour'
    WHEN _schedule ~ '^[0-9]+ [0-9]+ \* \* \*$'     THEN interval '1 day'
    WHEN _schedule ~ '^[0-9]+ [0-9]+ \* \* [0-9]$'  THEN interval '7 days'
    ELSE interval '1 day'
  END;
$function$
;

-- public.fn_cron_stalled_threshold(_schedule text)

CREATE OR REPLACE FUNCTION public.fn_cron_stalled_threshold(_schedule text)
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT GREATEST(
    interval '30 minutes',
    LEAST(interval '25 hours', public.fn_cron_expected_interval(_schedule) * 2)
  );
$function$
;

-- public.fn_gc_call_recording_ingest_jobs()

CREATE OR REPLACE FUNCTION public.fn_gc_call_recording_ingest_jobs()
 RETURNS TABLE(deleted_succeeded integer, deleted_dead_letter integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _s int := 0;
  _d int := 0;
BEGIN
  WITH del AS (
    DELETE FROM public.call_recording_ingest_jobs
    WHERE status = 'succeeded' AND updated_at < now() - interval '7 days'
    RETURNING 1
  ) SELECT count(*) INTO _s FROM del;

  WITH del AS (
    DELETE FROM public.call_recording_ingest_jobs
    WHERE status = 'dead_letter' AND updated_at < now() - interval '30 days'
    RETURNING 1
  ) SELECT count(*) INTO _d FROM del;

  RETURN QUERY SELECT _s, _d;
END;
$function$
;

