-- public.fn_quotes_inbound_ordering_guard()

CREATE OR REPLACE FUNCTION public.fn_quotes_inbound_ordering_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _incoming timestamptz;
BEGIN
  _incoming := (NEW.raw_payload->>'event_at')::timestamptz;

  IF TG_OP = 'UPDATE' THEN
    IF OLD.event_at IS NOT NULL AND _incoming IS NOT NULL AND _incoming < OLD.event_at THEN
      NEW.status      := OLD.status;
      NEW.last_event  := OLD.last_event;
      NEW.event_at    := OLD.event_at;
      NEW.raw_payload := OLD.raw_payload;
      RETURN NEW;
    END IF;
  END IF;

  NEW.event_at := COALESCE(_incoming, OLD.event_at);
  RETURN NEW;
END;
$function$
;

-- public.fn_record_conversion_attempt(_quote_id uuid, _sale_id uuid, _order_id uuid, _order_number text, _previous_status text, _new_status text, _reused_order boolean, _idempotent boolean, _success boolean, _error_code text, _error_message text, _latency_ms integer, _request_id text)

CREATE OR REPLACE FUNCTION public.fn_record_conversion_attempt(_quote_id uuid, _sale_id uuid, _order_id uuid, _order_number text, _previous_status text, _new_status text, _reused_order boolean, _idempotent boolean, _success boolean, _error_code text, _error_message text, _latency_ms integer, _request_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION '[NOT_AUTHENTICATED] auth.uid() ausente';
  END IF;

  INSERT INTO public.quote_conversion_audit (
    quote_id, sale_id, order_id, order_number,
    previous_status, new_status, reused_order, idempotent,
    success, error_code, error_message, latency_ms, request_id, actor_user_id
  ) VALUES (
    _quote_id, _sale_id, _order_id, _order_number,
    _previous_status, _new_status, COALESCE(_reused_order, false), COALESCE(_idempotent, false),
    _success, _error_code, _error_message, _latency_ms, _request_id, auth.uid()
  ) RETURNING id INTO v_id;

  RETURN v_id;
END $function$
;

-- public.fn_slo_burn_rate(_window interval)

CREATE OR REPLACE FUNCTION public.fn_slo_burn_rate(_window interval)
 RETURNS TABLE(source text, total bigint, failed bigint, rate numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Requer as duas tabelas-fonte (existem no schema canônico); o guard
  -- to_regclass em fn_check_slo_burn_rate evita chamá-la sem elas.
  WITH events AS (
    SELECT 'winloss_webhook' AS source, (NOT d.succeeded) AS failed
    FROM public.winloss_webhook_deliveries d
    WHERE d.created_at > now() - _window
    UNION ALL
    SELECT 'email', (e.status <> 'sent') AS failed
    FROM public.email_logs e
    WHERE e.created_at > now() - _window
  )
  SELECT source, count(*)::bigint AS total,
         count(*) FILTER (WHERE failed)::bigint AS failed,
         CASE WHEN count(*) = 0 THEN 0
              ELSE round(count(*) FILTER (WHERE failed)::numeric / count(*), 4)
         END AS rate
  FROM events
  GROUP BY source
  UNION ALL
  SELECT 'all', count(*)::bigint,
         count(*) FILTER (WHERE failed)::bigint,
         CASE WHEN count(*) = 0 THEN 0
              ELSE round(count(*) FILTER (WHERE failed)::numeric / count(*), 4)
         END
  FROM events;
$function$
;

-- public.fn_test_backdate_cron_alert(_jobid bigint, _hours numeric)

CREATE OR REPLACE FUNCTION public.fn_test_backdate_cron_alert(_jobid bigint, _hours numeric)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_updated INTEGER;
BEGIN
  IF _jobid >= 0 THEN RAISE EXCEPTION 'requires negative synthetic jobid'; END IF;
  UPDATE public.cron_failure_alerts
  SET alerted_at = now() - make_interval(mins => (_hours * 60)::int)
  WHERE jobid = _jobid;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END; $function$
;

-- public.fn_test_cleanup_cron_alerts(_jobid bigint)

CREATE OR REPLACE FUNCTION public.fn_test_cleanup_cron_alerts(_jobid bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_deleted INTEGER;
BEGIN
  IF _jobid >= 0 THEN RAISE EXCEPTION 'requires negative synthetic jobid'; END IF;
  DELETE FROM public.cron_failure_alerts WHERE jobid = _jobid;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END; $function$
;

-- public.fn_test_cleanup_dedupe_privileges()

CREATE OR REPLACE FUNCTION public.fn_test_cleanup_dedupe_privileges()
 RETURNS TABLE(role_name text, can_execute boolean, expected boolean, passed boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  SELECT r.role_name,
         has_function_privilege(r.role_name, 'public.fn_cleanup_webhook_dedupe()', 'EXECUTE') AS can_execute,
         r.expected,
         has_function_privilege(r.role_name, 'public.fn_cleanup_webhook_dedupe()', 'EXECUTE') = r.expected AS passed
  FROM (VALUES
    ('anon', false),
    ('authenticated', false),
    ('service_role', true),
    ('public', false)
  ) AS r(role_name, expected);
$function$
;

-- public.fn_test_mark_cron_failure(_jobid bigint, _jobname text, _start_time timestamp with time zone, _status text, _return_message text, _notified_admin_count integer)

CREATE OR REPLACE FUNCTION public.fn_test_mark_cron_failure(_jobid bigint, _jobname text, _start_time timestamp with time zone, _status text, _return_message text, _notified_admin_count integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _id UUID;
BEGIN
  IF _jobid >= 0 THEN
    RAISE EXCEPTION 'fn_test_mark_cron_failure requires negative synthetic jobid';
  END IF;
  INSERT INTO public.cron_failure_alerts (
    jobid, jobname, start_time, status, return_message, notified_admin_count
  ) VALUES (_jobid, _jobname, _start_time, _status, _return_message, _notified_admin_count)
  ON CONFLICT (jobid, start_time) DO UPDATE
    SET notified_admin_count = EXCLUDED.notified_admin_count,
        alerted_at = now()
  RETURNING id INTO _id;
  RETURN _id;
END; $function$
;

-- public.fn_test_simulate_stalled_check(_jobid bigint, _jobname text, _schedule text, _last_run timestamp with time zone)

CREATE OR REPLACE FUNCTION public.fn_test_simulate_stalled_check(_jobid bigint, _jobname text, _schedule text, _last_run timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_expected_interval INTERVAL;
  v_threshold INTERVAL;
  v_gap INTERVAL;
  v_alert_created BOOLEAN := false;
  v_skipped_reason TEXT := NULL;
BEGIN
  IF _jobid >= 0 THEN
    RAISE EXCEPTION 'fn_test_simulate_stalled_check requires negative synthetic jobid';
  END IF;
  v_expected_interval := public.fn_cron_expected_interval(_schedule);
  v_threshold         := public.fn_cron_stalled_threshold(_schedule);
  v_gap               := now() - _last_run;

  IF v_gap <= v_threshold THEN
    v_skipped_reason := 'gap_below_threshold';
  ELSIF EXISTS (
    SELECT 1 FROM public.cron_failure_alerts
    WHERE jobid = _jobid AND status = 'stalled' AND alerted_at > now() - interval '6 hours'
  ) THEN
    v_skipped_reason := 'deduped_within_6h';
  ELSE
    INSERT INTO public.cron_failure_alerts (
      jobid, jobname, start_time, status, return_message, alerted_at, notified_admin_count
    ) VALUES (
      _jobid, _jobname, _last_run, 'stalled',
      format('SIMULATED %s gap=%s threshold=%s', _jobname, v_gap::text, v_threshold::text),
      now(), 0
    );
    v_alert_created := true;
  END IF;

  RETURN jsonb_build_object(
    'alert_created', v_alert_created,
    'skipped_reason', v_skipped_reason,
    'expected_interval', v_expected_interval::text,
    'threshold', v_threshold::text,
    'gap', v_gap::text
  );
END;
$function$
;

-- public.fn_website_visitor_log_consent()

CREATE OR REPLACE FUNCTION public.fn_website_visitor_log_consent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.retention_expires_at IS NULL THEN
    NEW.retention_expires_at := COALESCE(NEW.identified_at, now()) + interval '90 days';
  END IF;

  IF NEW.consent_record_id IS NULL AND NEW.domain IS NOT NULL THEN
    SELECT c.id INTO NEW.consent_record_id
    FROM public.consent_records c
    WHERE c.purpose = 'visitor_tracking'
      AND c.revoked_at IS NULL
      AND c.subject_email IS NOT NULL
      AND lower(split_part(c.subject_email, '@', 2)) = lower(NEW.domain)
    ORDER BY c.granted_at DESC
    LIMIT 1;

    IF NEW.consent_record_id IS NOT NULL THEN
      NEW.legal_basis := 'consent';
      NEW.retention_expires_at := NULL; -- guarda regida pelo consentimento, não pela janela
    END IF;
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.generate_api_token()

CREATE OR REPLACE FUNCTION public.generate_api_token()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN '$' || encode(sha256((gen_random_uuid()::text || now()::text || random()::text)::bytea), 'hex');
END;
$function$
;

-- public.generate_cadence_tasks()

CREATE OR REPLACE FUNCTION public.generate_cadence_tasks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    step_record RECORD;
BEGIN
    -- For each step in the assigned cadence, create a task
    FOR step_record IN 
        SELECT id, day_number, title, description, template_content, task_type 
        FROM public.cadence_steps 
        WHERE cadence_id = NEW.cadence_id
    LOOP
        INSERT INTO public.cadence_tasks (
            prospect_cadence_id,
            cadence_step_id,
            scheduled_date,
            status,
            priority,
            task_type
        ) VALUES (
            NEW.id,
            step_record.id,
            CURRENT_DATE + (step_record.day_number || ' days')::interval,
            'pending',
            'medium',
            step_record.task_type
        );
    END LOOP;

    RETURN NEW;
END;
$function$
;

-- public.generate_device_fingerprint(p_user_agent text, p_ip_address text)

CREATE OR REPLACE FUNCTION public.generate_device_fingerprint(p_user_agent text, p_ip_address text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN encode(sha256((COALESCE(p_user_agent, '') || COALESCE(p_ip_address, ''))::bytea), 'hex');
END;
$function$
;

-- public.generate_mfa_backup_codes()

CREATE OR REPLACE FUNCTION public.generate_mfa_backup_codes()
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  codes TEXT[] := ARRAY[]::TEXT[];
  i INTEGER;
BEGIN
  FOR i IN 1..10 LOOP
    codes := array_append(codes, upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8)));
  END LOOP;
  RETURN codes;
END;
$function$
;

-- public.generate_sales_forecast(p_user_id uuid, p_periods integer)

CREATE OR REPLACE FUNCTION public.generate_sales_forecast(p_user_id uuid DEFAULT NULL::uuid, p_periods integer DEFAULT 3)
 RETURNS TABLE(period_start date, period_end date, forecasted_revenue numeric, confidence_level text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_avg_monthly DECIMAL;
  v_growth_rate DECIMAL;
BEGIN
  -- Calculate average and growth
  SELECT 
    AVG(monthly_revenue),
    CASE 
      WHEN COUNT(*) > 1 
      THEN (MAX(monthly_revenue) - MIN(monthly_revenue)) / NULLIF(MIN(monthly_revenue), 0)
      ELSE 0 
    END
  INTO v_avg_monthly, v_growth_rate
  FROM (
    SELECT 
      DATE_TRUNC('month', closed_at) as month,
      SUM(value) as monthly_revenue
    FROM deals
    WHERE status = 'won' 
      AND (p_user_id IS NULL OR owner_id = p_user_id)
      AND closed_at >= NOW() - INTERVAL '6 months'
    GROUP BY DATE_TRUNC('month', closed_at)
  ) recent_months;
  
  -- Generate forecast
  FOR i IN 1..p_periods LOOP
    RETURN QUERY
    SELECT 
      DATE_TRUNC('month', NOW() + (i || ' months')::INTERVAL)::DATE,
      (DATE_TRUNC('month', NOW() + (i || ' months')::INTERVAL) + INTERVAL '1 month - 1 day')::DATE,
      (v_avg_monthly * (1 + v_growth_rate * i / p_periods))::DECIMAL,
      CASE 
        WHEN i = 1 THEN 'High'
        WHEN i = 2 THEN 'Medium'
        ELSE 'Low'
      END;
  END LOOP;
END;
$function$
;

-- public.get_ab_test_results(_ab_test_id uuid)

CREATE OR REPLACE FUNCTION public.get_ab_test_results(_ab_test_id uuid)
 RETURNS TABLE(variant text, cadence_name text, enrolled integer, completed integer, replied integer, converted integer, reply_rate numeric, conversion_rate numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH test AS (
    SELECT id, variant_a_id, variant_b_id FROM public.cadence_ab_tests WHERE id = _ab_test_id
  ),
  base AS (
    SELECT 'a'::TEXT AS variant, (SELECT variant_a_id FROM test) AS cad_id
    UNION ALL
    SELECT 'b'::TEXT AS variant, (SELECT variant_b_id FROM test) AS cad_id
  ),
  stats AS (
    SELECT
      a.variant,
      COUNT(DISTINCT pc.id)::INT AS enrolled,
      COUNT(DISTINCT pc.id) FILTER (WHERE pc.status = 'completed')::INT AS completed,
      COUNT(DISTINCT ci.deal_id)::INT AS replied,
      COUNT(DISTINCT s.id) FILTER (WHERE s.status = 'completed')::INT AS converted
    FROM public.cadence_ab_assignments a
    JOIN public.prospect_cadences pc ON pc.id = a.prospect_cadence_id
    LEFT JOIN public.channel_interactions ci ON ci.deal_id = pc.sale_id AND ci.direction = 'inbound' AND ci.created_at >= pc.started_at
    LEFT JOIN public.sales s ON s.id = pc.sale_id
    WHERE a.ab_test_id = _ab_test_id
    GROUP BY a.variant
  )
  SELECT
    b.variant,
    c.name,
    COALESCE(s.enrolled, 0),
    COALESCE(s.completed, 0),
    COALESCE(s.replied, 0),
    COALESCE(s.converted, 0),
    CASE WHEN COALESCE(s.enrolled, 0) > 0
      THEN ROUND((COALESCE(s.replied, 0)::NUMERIC / s.enrolled::NUMERIC) * 100, 1)
      ELSE 0 END,
    CASE WHEN COALESCE(s.enrolled, 0) > 0
      THEN ROUND((COALESCE(s.converted, 0)::NUMERIC / s.enrolled::NUMERIC) * 100, 1)
      ELSE 0 END
  FROM base b
  LEFT JOIN public.cadences c ON c.id = b.cad_id
  LEFT JOIN stats s ON s.variant = b.variant
  ORDER BY b.variant;
END;
$function$
;

-- public.get_account_engagement_summary(_account_id uuid)

CREATE OR REPLACE FUNCTION public.get_account_engagement_summary(_account_id uuid)
 RETURNS TABLE(account_id uuid, account_name text, total_contacts integer, engaged_contacts integer, avg_score numeric, coverage numeric, dominant_tier text, interactions_30d integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH contacts AS (
    SELECT ac.sale_id, ees.score, ees.tier
    FROM public.account_contacts ac
    LEFT JOIN public.email_engagement_scores ees ON ees.sale_id = ac.sale_id
    WHERE ac.account_id = _account_id AND ac.sale_id IS NOT NULL
  ),
  tier_counts AS (
    SELECT tier, count(*)::int AS c
    FROM contacts WHERE tier IS NOT NULL
    GROUP BY tier ORDER BY c DESC LIMIT 1
  ),
  ix AS (
    SELECT count(*)::int AS n
    FROM public.channel_interactions ci
    JOIN public.account_contacts ac ON ac.sale_id = ci.sale_id
    WHERE ac.account_id = _account_id AND ci.created_at > now() - interval '30 days'
  )
  SELECT
    a.id,
    a.name,
    (SELECT count(*)::int FROM contacts),
    (SELECT count(*)::int FROM contacts WHERE tier IN ('warm','hot','champion')),
    COALESCE((SELECT avg(score) FROM contacts WHERE score IS NOT NULL), 0)::numeric,
    CASE WHEN (SELECT count(*) FROM contacts) > 0
      THEN (SELECT count(*)::numeric FROM contacts WHERE tier IN ('warm','hot','champion')) / (SELECT count(*)::numeric FROM contacts) * 100
      ELSE 0 END,
    (SELECT tier FROM tier_counts LIMIT 1),
    (SELECT n FROM ix)
  FROM public.accounts a WHERE a.id = _account_id;
END;
$function$
;

-- public.get_active_salespeople()

CREATE OR REPLACE FUNCTION public.get_active_salespeople()
 RETURNS TABLE(id uuid, name text, avatar_url text, role text, is_active boolean)
 LANGUAGE sql
