-- public.get_app_config_number(p_key text, p_default numeric)

CREATE OR REPLACE FUNCTION public.get_app_config_number(p_key text, p_default numeric)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT CASE jsonb_typeof(value)
       WHEN 'number' THEN (value)::numeric
       ELSE NULLIF(value #>> '{}', '')::numeric
     END
     FROM public.app_config WHERE key = p_key),
    p_default
  );
$function$
;

-- public.get_auto_paused_count(_days integer)

CREATE OR REPLACE FUNCTION public.get_auto_paused_count(_days integer DEFAULT 7)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COUNT(*)::INT
  FROM public.prospect_cadences
  WHERE paused_reason LIKE 'response_detected%'
    AND paused_at >= now() - (_days || ' days')::INTERVAL
$function$
