-- public.get_bulk_job_summary(_job_id uuid)

CREATE OR REPLACE FUNCTION public.get_bulk_job_summary(_job_id uuid)
 RETURNS TABLE(total integer, approved integer, sent integer, errored integer, pending integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    COUNT(*)::int AS total,
    COUNT(*) FILTER (WHERE approved)::int AS approved,
    COUNT(*) FILTER (WHERE sent_at IS NOT NULL)::int AS sent,
    COUNT(*) FILTER (WHERE error IS NOT NULL)::int AS errored,
    COUNT(*) FILTER (WHERE approved AND sent_at IS NULL AND error IS NULL)::int AS pending
  FROM public.email_bulk_drafts
  WHERE job_id = _job_id;
$function$
;

-- public.get_cadence_metrics(_cadence_id uuid, _days integer)

CREATE OR REPLACE FUNCTION public.get_cadence_metrics(_cadence_id uuid DEFAULT NULL::uuid, _days integer DEFAULT 30)
 RETURNS TABLE(cadence_id uuid, cadence_name text, total_enrolled integer, active_count integer, paused_count integer, completed_count integer, cancelled_count integer, auto_paused_count integer, total_tasks integer, tasks_completed integer, tasks_skipped integer, completion_rate numeric, reply_rate numeric, conversion_rate numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  WITH base AS (
    SELECT c.id, c.name
    FROM public.cadences c
    WHERE _cadence_id IS NULL OR c.id = _cadence_id
  ),
  enrollments AS (
    SELECT
      pc.cadence_id,
      COUNT(*)::INT AS total,
      COUNT(*) FILTER (WHERE pc.status = 'active')::INT AS active,
      COUNT(*) FILTER (WHERE pc.status = 'paused')::INT AS paused,
      COUNT(*) FILTER (WHERE pc.status = 'completed')::INT AS completed,
      COUNT(*) FILTER (WHERE pc.status = 'cancelled')::INT AS cancelled,
      COUNT(*) FILTER (WHERE pc.paused_reason LIKE 'response_detected%')::INT AS auto_paused
    FROM public.prospect_cadences pc
    WHERE pc.created_at >= now() - (_days || ' days')::INTERVAL
    GROUP BY pc.cadence_id
  ),
  tasks AS (
    SELECT
      pc.cadence_id,
      COUNT(ct.*)::INT AS total_t,
      COUNT(ct.*) FILTER (WHERE ct.status = 'completed')::INT AS completed_t,
      COUNT(ct.*) FILTER (WHERE ct.status = 'skipped')::INT AS skipped_t
    FROM public.cadence_tasks ct
    JOIN public.prospect_cadences pc ON pc.id = ct.prospect_cadence_id
    WHERE pc.created_at >= now() - (_days || ' days')::INTERVAL
    GROUP BY pc.cadence_id
  ),
  responses AS (
    SELECT
      pc.cadence_id,
      COUNT(DISTINCT pc.sale_id)::INT AS replied
    FROM public.prospect_cadences pc
    JOIN public.channel_interactions ci ON ci.deal_id = pc.sale_id
    WHERE ci.direction = 'inbound'
      AND ci.created_at >= pc.started_at
      AND pc.created_at >= now() - (_days || ' days')::INTERVAL
    GROUP BY pc.cadence_id
  ),
  conversions AS (
    SELECT
      pc.cadence_id,
      COUNT(DISTINCT pc.sale_id)::INT AS converted
    FROM public.prospect_cadences pc
    JOIN public.sales s ON s.id = pc.sale_id
    WHERE s.status = 'completed'
      AND pc.created_at >= now() - (_days || ' days')::INTERVAL
    GROUP BY pc.cadence_id
  )
  SELECT
    b.id,
    b.name,
    COALESCE(e.total, 0),
    COALESCE(e.active, 0),
    COALESCE(e.paused, 0),
    COALESCE(e.completed, 0),
    COALESCE(e.cancelled, 0),
    COALESCE(e.auto_paused, 0),
    COALESCE(t.total_t, 0),
    COALESCE(t.completed_t, 0),
    COALESCE(t.skipped_t, 0),
    CASE WHEN COALESCE(t.total_t, 0) > 0
      THEN ROUND((t.completed_t::NUMERIC / t.total_t::NUMERIC) * 100, 1)
      ELSE 0 END,
    CASE WHEN COALESCE(e.total, 0) > 0
      THEN ROUND((COALESCE(r.replied, 0)::NUMERIC / e.total::NUMERIC) * 100, 1)
      ELSE 0 END,
    CASE WHEN COALESCE(e.total, 0) > 0
      THEN ROUND((COALESCE(cv.converted, 0)::NUMERIC / e.total::NUMERIC) * 100, 1)
      ELSE 0 END
  FROM base b
  LEFT JOIN enrollments e ON e.cadence_id = b.id
  LEFT JOIN tasks t ON t.cadence_id = b.id
  LEFT JOIN responses r ON r.cadence_id = b.id
  LEFT JOIN conversions cv ON cv.cadence_id = b.id
  ORDER BY COALESCE(e.total, 0) DESC;
END;
$function$
;

-- public.get_campaign_delivery_stats(_days integer)

CREATE OR REPLACE FUNCTION public.get_campaign_delivery_stats(_days integer DEFAULT 30)
 RETURNS TABLE(job_id uuid, prompt text, status text, created_at timestamp with time zone, target_count integer, sent_count integer, failed_count integer, pending_count integer, first_sent_at timestamp with time zone, last_sent_at timestamp with time zone, p50_latency_seconds numeric, p95_latency_seconds numeric, max_latency_seconds numeric, throughput_per_minute numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH win AS (
    SELECT now() - (LEAST(GREATEST(COALESCE(_days, 30), 1), 365) || ' days')::interval AS since
  ),
  jobs AS (
    SELECT j.id, j.prompt, j.status, j.created_at, j.target_count
    FROM public.email_bulk_jobs j, win
    WHERE j.created_at >= win.since
      AND (j.owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin'::app_role))
  ),
  drafts AS (
    SELECT d.job_id,
           d.sent_at,
           d.error,
           CASE
             WHEN d.sent_at IS NOT NULL
               THEN GREATEST(EXTRACT(EPOCH FROM (d.sent_at - jobs.created_at)), 0)
             ELSE NULL
           END AS latency_seconds
    FROM public.email_bulk_drafts d
    JOIN jobs ON jobs.id = d.job_id
  )
  SELECT jobs.id,
         jobs.prompt,
         jobs.status,
         jobs.created_at,
         COALESCE(jobs.target_count, 0)::integer,
         COALESCE(count(d.*) FILTER (WHERE d.sent_at IS NOT NULL), 0)::integer AS sent_count,
         COALESCE(count(d.*) FILTER (WHERE d.error IS NOT NULL AND d.sent_at IS NULL), 0)::integer AS failed_count,
         COALESCE(count(d.*) FILTER (WHERE d.sent_at IS NULL AND d.error IS NULL), 0)::integer AS pending_count,
         min(d.sent_at) AS first_sent_at,
         max(d.sent_at) AS last_sent_at,
         COALESCE(round(percentile_cont(0.5) WITHIN GROUP (ORDER BY d.latency_seconds)::numeric, 2), 0) AS p50_latency_seconds,
         COALESCE(round(percentile_cont(0.95) WITHIN GROUP (ORDER BY d.latency_seconds)::numeric, 2), 0) AS p95_latency_seconds,
         COALESCE(round(max(d.latency_seconds)::numeric, 2), 0) AS max_latency_seconds,
         CASE
           WHEN count(d.*) FILTER (WHERE d.sent_at IS NOT NULL) > 0
            AND EXTRACT(EPOCH FROM (max(d.sent_at) - min(d.sent_at))) >= 1
             THEN round(
               (count(d.*) FILTER (WHERE d.sent_at IS NOT NULL))::numeric * 60
               / EXTRACT(EPOCH FROM (max(d.sent_at) - min(d.sent_at)))::numeric, 2)
           ELSE 0
         END AS throughput_per_minute
  FROM jobs
  LEFT JOIN drafts d ON d.job_id = jobs.id
  GROUP BY jobs.id, jobs.prompt, jobs.status, jobs.created_at, jobs.target_count
  ORDER BY jobs.created_at DESC;
$function$
;

-- public.get_campaign_optout_rates(_days integer)

CREATE OR REPLACE FUNCTION public.get_campaign_optout_rates(_days integer DEFAULT 90)
 RETURNS TABLE(job_id uuid, prompt text, created_at timestamp with time zone, sent_count integer, opted_out_count integer, opt_out_rate numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH win AS (
    SELECT now() - (LEAST(GREATEST(COALESCE(_days, 90), 1), 365) || ' days')::interval AS since
  ),
  jobs AS (
    SELECT j.id, j.prompt, j.created_at
    FROM public.email_bulk_jobs j, win
    WHERE j.created_at >= win.since
      AND (j.owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin'::app_role))
  ),
  sent AS (
    SELECT d.job_id,
           lower(btrim(d.recipient_email)) AS email,
           min(d.sent_at) AS sent_at
    FROM public.email_bulk_drafts d
    JOIN jobs ON jobs.id = d.job_id
    WHERE d.sent_at IS NOT NULL
      AND d.recipient_email IS NOT NULL
      AND btrim(d.recipient_email) <> ''
    GROUP BY d.job_id, lower(btrim(d.recipient_email))
  ),
  matched AS (
    SELECT s.job_id,
           s.email,
           EXISTS (
             SELECT 1
             FROM public.email_opt_outs o
             WHERE lower(btrim(o.email)) = s.email
               AND o.created_at >= s.sent_at
           ) AS opted_out
    FROM sent s
  )
  SELECT jobs.id,
         jobs.prompt,
         jobs.created_at,
         COALESCE(count(m.email), 0)::integer AS sent_count,
         COALESCE(count(m.email) FILTER (WHERE m.opted_out), 0)::integer AS opted_out_count,
         CASE
           WHEN count(m.email) > 0
             THEN round((count(m.email) FILTER (WHERE m.opted_out))::numeric * 100 / count(m.email), 2)
           ELSE 0
         END AS opt_out_rate
  FROM jobs
  LEFT JOIN matched m ON m.job_id = jobs.id
  GROUP BY jobs.id, jobs.prompt, jobs.created_at
  ORDER BY jobs.created_at DESC;
$function$
;

-- public.get_campaign_recovery_rates(_days integer)

CREATE OR REPLACE FUNCTION public.get_campaign_recovery_rates(_days integer DEFAULT 90)
 RETURNS TABLE(job_id uuid, prompt text, created_at timestamp with time zone, failed_total integer, recovered_count integer, still_failing integer, recovery_rate numeric, avg_recovery_minutes numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH win AS (
    SELECT now() - (LEAST(GREATEST(COALESCE(_days, 90), 1), 365) || ' days')::interval AS since
  ),
  jobs AS (
    SELECT j.id, j.prompt, j.created_at
    FROM public.email_bulk_jobs j, win
    WHERE j.created_at >= win.since
      AND (j.owner_id = auth.uid() OR public.has_role(auth.uid(), 'admin'::app_role))
  ),
  failed AS (
    SELECT d.job_id,
           d.recovered_at IS NOT NULL AS recovered,
           CASE WHEN d.recovered_at IS NOT NULL AND d.last_error_at IS NOT NULL
                THEN EXTRACT(EPOCH FROM (d.recovered_at - d.last_error_at)) / 60 END AS minutes
    FROM public.email_bulk_drafts d
    JOIN jobs ON jobs.id = d.job_id
    WHERE d.last_error_message IS NOT NULL
  )
  SELECT jobs.id,
         jobs.prompt,
         jobs.created_at,
         COALESCE(count(f.*), 0)::integer AS failed_total,
         COALESCE(count(f.*) FILTER (WHERE f.recovered), 0)::integer AS recovered_count,
         COALESCE(count(f.*) FILTER (WHERE NOT f.recovered), 0)::integer AS still_failing,
         CASE WHEN count(f.*) > 0
              THEN round((count(f.*) FILTER (WHERE f.recovered))::numeric * 100 / count(f.*), 2)
              ELSE 0 END AS recovery_rate,
         COALESCE(round(avg(f.minutes)::numeric, 1), 0) AS avg_recovery_minutes
  FROM jobs
  LEFT JOIN failed f ON f.job_id = jobs.id
  GROUP BY jobs.id, jobs.prompt, jobs.created_at
  HAVING count(f.*) > 0
  ORDER BY jobs.created_at DESC;
$function$
;

-- public.get_client_purchase_heatmap(_client_id uuid, _months integer)

CREATE OR REPLACE FUNCTION public.get_client_purchase_heatmap(_client_id uuid DEFAULT NULL::uuid, _months integer DEFAULT 24)
 RETURNS TABLE(client_id uuid, client_name text, month_start date, salesperson_id uuid, salesperson_name text, is_current_user boolean, deal_count bigint, revenue numeric, won_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _sp_id uuid := public.get_current_salesperson_id();
  _is_privileged boolean := public.has_role(_uid, 'admin') OR public.has_role(_uid, 'manager');
  _start date := (date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') - (_months || ' months')::interval)::date;
BEGIN
  RETURN QUERY
  SELECT
    c.id AS client_id,
    c.name AS client_name,
    date_trunc('month', s.created_at AT TIME ZONE 'America/Sao_Paulo')::date AS month_start,
    s.salesperson_id,
    sp.name AS salesperson_name,
    (_sp_id IS NOT NULL AND s.salesperson_id = _sp_id) AS is_current_user,
    COUNT(*)::bigint AS deal_count,
    COALESCE(SUM(s.amount), 0)::numeric AS revenue,
    COUNT(*) FILTER (WHERE s.status IN ('completed', 'won', 'closed'))::bigint AS won_count
  FROM public.sales s
  JOIN public.clients c ON c.name = s.client_name
  LEFT JOIN public.salespeople sp ON sp.id = s.salesperson_id
  WHERE s.created_at >= _start
    AND (_client_id IS NULL OR c.id = _client_id)
    AND (
      _is_privileged
      OR EXISTS (
        SELECT 1 FROM public.sales s2
        WHERE s2.client_name = c.name AND s2.salesperson_id = _sp_id
      )
    )
  GROUP BY c.id, c.name, date_trunc('month', s.created_at AT TIME ZONE 'America/Sao_Paulo'), s.salesperson_id, sp.name
  ORDER BY month_start DESC, revenue DESC;
END;
$function$
;

-- public.get_client_seasonality(_client_id uuid, _months integer)

CREATE OR REPLACE FUNCTION public.get_client_seasonality(_client_id uuid, _months integer DEFAULT 24)
 RETURNS TABLE(year double precision, month double precision, quotes_count bigint, total_revenue numeric, avg_ticket numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        EXTRACT(YEAR FROM q.created_at)::double precision as year,
        EXTRACT(MONTH FROM q.created_at)::double precision as month,
        COUNT(q.id)::BIGINT as quotes_count,
        SUM(q.total_value)::NUMERIC as total_revenue,
        AVG(q.total_value)::NUMERIC as avg_ticket
    FROM public.quotes q
    WHERE q.client_id = _client_id
    AND q.created_at >= NOW() - (_months || ' months')::INTERVAL
    GROUP BY 1, 2
    ORDER BY 1 DESC, 2 DESC;
END;
$function$
;

-- public.get_client_top_products(_client_id uuid, _limit integer)

CREATE OR REPLACE FUNCTION public.get_client_top_products(_client_id uuid, _limit integer DEFAULT 5)
 RETURNS TABLE(product_id uuid, product_name text, total_quantity bigint, total_revenue numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        qi.product_id,
        p.name as product_name,
        SUM(qi.quantity)::BIGINT as total_quantity,
        SUM(qi.unit_price * qi.quantity)::NUMERIC as total_revenue
    FROM public.quotes q
    JOIN public.quote_items qi ON q.id = qi.quote_id
    JOIN public.products p ON qi.product_id = p.id
    WHERE q.client_id = _client_id
    AND q.status = 'approved'
    GROUP BY qi.product_id, p.name
    ORDER BY total_revenue DESC
    LIMIT _limit;
END;
$function$
;

