-- public.get_dashboard_kpis(start_date date, end_date date)

CREATE OR REPLACE FUNCTION public.get_dashboard_kpis(start_date date, end_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    result jsonb;
BEGIN
    -- Require an authenticated caller; RLS handles row visibility.
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
    END IF;

    WITH period_sales AS (
        SELECT amount, is_first_sale
        FROM public.sales
        WHERE created_at >= start_date::timestamp AT TIME ZONE 'UTC'
          AND created_at < (end_date + interval '1 day')::timestamp AT TIME ZONE 'UTC'
          AND status = 'completed'
    ),
    period_metrics AS (
        SELECT new_clients, conversion_rate
        FROM public.daily_metrics
        WHERE date >= start_date
          AND date <= end_date
    )
    SELECT jsonb_build_object(
        'totalRevenue', COALESCE(SUM(amount), 0),
        'totalSales', COUNT(*),
        'firstSaleRevenue', COALESCE(SUM(CASE WHEN is_first_sale THEN amount ELSE 0 END), 0),
        'recurringRevenue', COALESCE(SUM(CASE WHEN NOT is_first_sale THEN amount ELSE 0 END), 0),
        'newClients', (SELECT COALESCE(SUM(new_clients), 0) FROM period_metrics),
        'conversionRate', (SELECT COALESCE(AVG(conversion_rate), 0) FROM period_metrics),
        'avgTicket', CASE WHEN COUNT(*) > 0 THEN COALESCE(SUM(amount), 0) / COUNT(*) ELSE 0 END
    ) INTO result
    FROM period_sales;

    RETURN result;
END;
$function$
;

-- public.get_deleted_records(p_table_name text, p_limit integer)

CREATE OR REPLACE FUNCTION public.get_deleted_records(p_table_name text, p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, deleted_at timestamp with time zone, deleted_by_email text, delete_reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sql text;
BEGIN
  IF auth.role() <> 'service_role'
     AND (auth.uid() IS NULL OR NOT public.is_admin_or_manager(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_table_name NOT IN ('clients', 'activities', 'products', 'suppliers', 'teams') THEN
    RAISE EXCEPTION 'unsupported_soft_delete_table' USING ERRCODE = '22023';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 200 THEN
    RAISE EXCEPTION 'limit_out_of_range' USING ERRCODE = '22023';
  END IF;

  v_sql := format(
    'SELECT t.id, t.deleted_at, u.email::text, t.delete_reason FROM public.%I AS t LEFT JOIN auth.users AS u ON u.id = t.deleted_by WHERE t.deleted_at IS NOT NULL ORDER BY t.deleted_at DESC LIMIT $1',
    p_table_name
  );
  RETURN QUERY EXECUTE v_sql USING p_limit;
END;
$function$
;

-- public.get_dialer_queue_stats(_queue_id uuid)

CREATE OR REPLACE FUNCTION public.get_dialer_queue_stats(_queue_id uuid)
 RETURNS TABLE(pending_count integer, calling_count integer, done_count integer, skipped_count integer, snoozed_count integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COUNT(*) FILTER (WHERE status='pending')::int,
    COUNT(*) FILTER (WHERE status='calling')::int,
    COUNT(*) FILTER (WHERE status='done')::int,
    COUNT(*) FILTER (WHERE status='skipped')::int,
    COUNT(*) FILTER (WHERE status='snoozed')::int
  FROM public.dialer_queue_items WHERE queue_id = _queue_id;
$function$
;

-- public.get_embedded_report_by_token(_token uuid)

CREATE OR REPLACE FUNCTION public.get_embedded_report_by_token(_token uuid)
 RETURNS TABLE(report_id uuid, report_name text, report_entity text, report_config jsonb, is_valid boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _t RECORD;
  _r RECORD;
BEGIN
  SELECT * INTO _t FROM public.embedded_report_tokens WHERE public_token = _token AND is_active = true;
  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::JSONB, false, 'Token inválido';
    RETURN;
  END IF;
  IF _t.expires_at IS NOT NULL AND _t.expires_at < now() THEN
    RETURN QUERY SELECT NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::JSONB, false, 'Token expirado';
    RETURN;
  END IF;
  SELECT * INTO _r FROM public.custom_reports WHERE id = _t.report_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::JSONB, false, 'Relatório removido';
    RETURN;
  END IF;
  -- Track view
  UPDATE public.embedded_report_tokens
    SET view_count = view_count + 1, last_viewed_at = now()
    WHERE id = _t.id;
  RETURN QUERY SELECT _r.id, _r.name, _r.entity, _r.config, true, NULL::TEXT;
END;
$function$
;

-- public.get_engagement_leaderboard(_limit integer)

CREATE OR REPLACE FUNCTION public.get_engagement_leaderboard(_limit integer DEFAULT 20)
 RETURNS TABLE(sale_id uuid, client_name text, score integer, tier text, open_rate numeric, click_rate numeric, reply_rate numeric, total_sent integer, recency_days integer, salesperson_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 
    e.sale_id,
    s.client_name,
    e.score,
    e.tier,
    e.open_rate,
    e.click_rate,
    e.reply_rate,
    e.total_sent,
    e.recency_days,
    s.salesperson_id
  FROM public.email_engagement_scores e
  JOIN public.sales s ON s.id = e.sale_id
  LEFT JOIN public.salespeople sp ON sp.id = s.salesperson_id
  WHERE 
    public.has_role(auth.uid(), 'admin')
    OR public.has_role(auth.uid(), 'manager')
    OR sp.auth_user_id = auth.uid()
  ORDER BY e.score DESC, e.last_calculated_at DESC
  LIMIT GREATEST(1, LEAST(_limit, 100));
$function$
;

-- public.get_global_send_time_stats()

CREATE OR REPLACE FUNCTION public.get_global_send_time_stats()
 RETURNS TABLE(best_hour integer, best_dow integer, sample_size bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH opens AS (
    SELECT EXTRACT(HOUR FROM tracked_at AT TIME ZONE 'America/Sao_Paulo')::int AS h,
           EXTRACT(DOW FROM tracked_at AT TIME ZONE 'America/Sao_Paulo')::int AS d
    FROM public.email_tracking_events
    WHERE event_type IN ('open','opened') AND tracked_at > now() - interval '90 days'
  ),
  hour_agg AS (SELECT h, COUNT(*) c FROM opens GROUP BY h ORDER BY COUNT(*) DESC LIMIT 1),
  dow_agg AS (SELECT d, COUNT(*) c FROM opens GROUP BY d ORDER BY COUNT(*) DESC LIMIT 1)
  SELECT COALESCE((SELECT h FROM hour_agg), 10)::int,
         COALESCE((SELECT d FROM dow_agg), 2)::int,
         (SELECT COUNT(*) FROM opens)::bigint;
$function$
;

-- public.get_historical_benchmark(p_salesperson_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone)

CREATE OR REPLACE FUNCTION public.get_historical_benchmark(p_salesperson_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    current_period_revenue NUMERIC;
    previous_period_revenue NUMERIC;
    current_period_deals INTEGER;
    previous_period_deals INTEGER;
    days_diff INTEGER;
    p_prev_start TIMESTAMP WITH TIME ZONE;
    p_prev_end TIMESTAMP WITH TIME ZONE;
BEGIN
    days_diff := (p_end_date::date - p_start_date::date);
    p_prev_start := p_start_date - (days_diff || ' days')::INTERVAL;
    p_prev_end := p_start_date - INTERVAL '1 second';

    -- Current Period
    SELECT COALESCE(SUM(amount), 0), COUNT(*)
    INTO current_period_revenue, current_period_deals
    FROM public.sales
    WHERE (p_salesperson_id IS NULL OR salesperson_id = p_salesperson_id)
    AND created_at BETWEEN p_start_date AND p_end_date
    AND status = 'won';

    -- Previous Period
    SELECT COALESCE(SUM(amount), 0), COUNT(*)
    INTO previous_period_revenue, previous_period_deals
    FROM public.sales
    WHERE (p_salesperson_id IS NULL OR salesperson_id = p_salesperson_id)
    AND created_at BETWEEN p_prev_start AND p_prev_end
    AND status = 'won';

    RETURN jsonb_build_object(
        'current', jsonb_build_object('revenue', current_period_revenue, 'deals', current_period_deals),
        'previous', jsonb_build_object('revenue', previous_period_revenue, 'deals', previous_period_deals),
        'growth', jsonb_build_object(
            'revenue_pct', CASE WHEN previous_period_revenue = 0 THEN 100 ELSE ((current_period_revenue - previous_period_revenue) / previous_period_revenue * 100) END,
            'deals_pct', CASE WHEN previous_period_deals = 0 THEN 100 ELSE ((current_period_deals - previous_period_deals)::NUMERIC / previous_period_deals * 100) END
        )
    );
END;
$function$
;

-- public.get_industry_benchmark_stats(_company_ids uuid[], _days integer)

CREATE OR REPLACE FUNCTION public.get_industry_benchmark_stats(_company_ids uuid[], _days integer DEFAULT 180)
 RETURNS TABLE(metric_name text, industry_avg numeric, unit text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    SELECT 'Volume'::TEXT, 75.0::NUMERIC, 'un'::TEXT
    UNION ALL
    SELECT 'Conversão'::TEXT, 10.5::NUMERIC, '%'::TEXT
    UNION ALL
    SELECT 'Frequência'::TEXT, 3.8::NUMERIC, 'ped/mês'::TEXT
    UNION ALL
    SELECT 'Satisfação'::TEXT, 85.0::NUMERIC, 'pts'::TEXT;
END;
$function$
;

-- public.get_industry_seasonality(_company_ids uuid[], _months integer)

CREATE OR REPLACE FUNCTION public.get_industry_seasonality(_company_ids uuid[], _months integer DEFAULT 24)
 RETURNS TABLE(year double precision, month double precision, avg_quotes_per_company numeric, avg_revenue_per_company numeric, companies_active bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    WITH monthly_stats AS (
        SELECT 
            EXTRACT(YEAR FROM q.created_at) as yr,
            EXTRACT(MONTH FROM q.created_at) as mon,
            q.client_id,
            COUNT(q.id) as q_count,
            SUM(q.total_value) as total_rev
        FROM public.quotes q
        WHERE q.client_id = ANY(_company_ids)
        AND q.created_at >= NOW() - (_months || ' months')::INTERVAL
        GROUP BY 1, 2, 3
    )
    SELECT 
        yr::double precision as year,
        mon::double precision as month,
        AVG(q_count)::NUMERIC as avg_quotes_per_company,
        AVG(total_rev)::NUMERIC as avg_revenue_per_company,
        COUNT(DISTINCT client_id)::BIGINT as companies_active
    FROM monthly_stats
    GROUP BY 1, 2
    ORDER BY 1 DESC, 2 DESC;
END;
$function$
;

-- public.get_industry_top_products(_company_ids uuid[], _days integer, _limit integer)

CREATE OR REPLACE FUNCTION public.get_industry_top_products(_company_ids uuid[], _days integer DEFAULT 90, _limit integer DEFAULT 5)
 RETURNS TABLE(product_id uuid, product_name text, total_sales bigint, growth_rate numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN QUERY
    WITH cur AS (
        SELECT qi.product_id, COUNT(qi.id)::BIGINT AS sales_now
        FROM public.quotes q
        JOIN public.quote_items qi ON q.id = qi.quote_id
        WHERE q.client_id = ANY(_company_ids)
        AND q.created_at >= NOW() - (_days || ' days')::INTERVAL
        AND q.status = 'approved'
        GROUP BY qi.product_id
    ),
    prev AS (
        SELECT qi.product_id, COUNT(qi.id)::BIGINT AS sales_prev
        FROM public.quotes q
        JOIN public.quote_items qi ON q.id = qi.quote_id
        WHERE q.client_id = ANY(_company_ids)
        AND q.created_at >= NOW() - (2 * _days || ' days')::INTERVAL
        AND q.created_at <  NOW() - (_days || ' days')::INTERVAL
        AND q.status = 'approved'
        GROUP BY qi.product_id
    )
    SELECT
        c.product_id,
        p.name as product_name,
        c.sales_now as total_sales,
        CASE
            WHEN COALESCE(pr.sales_prev, 0) > 0
            THEN ROUND(((c.sales_now - pr.sales_prev)::NUMERIC / pr.sales_prev) * 100, 1)
            ELSE 0::NUMERIC
        END as growth_rate
    FROM cur c
    JOIN public.products p ON c.product_id = p.id
    LEFT JOIN prev pr ON pr.product_id = c.product_id
    ORDER BY total_sales DESC
    LIMIT _limit;
END;
$function$
;

-- public.get_login_lockout_status(p_email text)

CREATE OR REPLACE FUNCTION public.get_login_lockout_status(p_email text)
 RETURNS TABLE(attempts integer, last_failed_at timestamp with time zone, lockout_until timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text := lower(trim(COALESCE(p_email, '')));
  v_headers jsonb := COALESCE(
    NULLIF(current_setting('request.headers', true), '')::jsonb,
    '{}'::jsonb
  );
  v_ip text;
  v_last_success timestamptz;
  v_attempts integer := 0;
  v_last_failed timestamptz;
  v_recent integer := 0;
  v_recent_failed timestamptz;
  v_lockout_seconds integer;
BEGIN
  IF length(v_email) < 3
     OR length(v_email) > 320
     OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN
    RAISE EXCEPTION 'email_invalid' USING ERRCODE = '22023';
  END IF;

  v_ip := left(trim(split_part(COALESCE(
    v_headers ->> 'cf-connecting-ip',
    v_headers ->> 'x-forwarded-for',
    v_headers ->> 'x-real-ip',
    ''
  ), ',', 1)), 64);
  IF v_ip = '' THEN
    v_ip := NULL;
  ELSE
    BEGIN
      v_ip := host(v_ip::inet);
    EXCEPTION WHEN invalid_text_representation THEN
      v_ip := NULL;
    END;
  END IF;

  SELECT max(la.created_at)
    INTO v_last_success
    FROM public.login_attempts AS la
   WHERE lower(la.email) = v_email
     AND la.success IS TRUE
     AND (v_ip IS NULL OR la.ip_address = v_ip)
     AND la.created_at >= now() - interval '24 hours';

  SELECT count(*)::integer, max(la.created_at)
    INTO v_attempts, v_last_failed
    FROM public.login_attempts AS la
   WHERE lower(la.email) = v_email
     AND la.success IS FALSE
     AND (v_ip IS NULL OR la.ip_address = v_ip)
     AND la.created_at >= now() - interval '24 hours'
     AND (v_last_success IS NULL OR la.created_at > v_last_success);

  -- Espelha o limitador de escrita. Assim, um ataque distribuído ao mesmo
  -- e-mail (ou muitas contas pela mesma origem) não transforma a exceção de
  -- rate limit em fail-open no cliente: a consulta subsequente retorna lockout.
  SELECT count(*)::integer, max(la.created_at)
    INTO v_recent, v_recent_failed
    FROM public.login_attempts AS la
   WHERE la.success IS FALSE
     AND la.created_at >= now() - interval '1 minute'
     AND (
       lower(la.email) = v_email
       OR (v_ip IS NOT NULL AND la.ip_address = v_ip)
     );

  IF v_recent >= 10 THEN
    v_attempts := GREATEST(v_attempts, v_recent);
    v_last_failed := GREATEST(v_last_failed, v_recent_failed);
  END IF;

  IF v_attempts >= 5 AND v_last_failed IS NOT NULL THEN
    v_lockout_seconds := LEAST(
      3600,
      30 * power(2::numeric, LEAST(10, floor(v_attempts / 5.0)::integer - 1))::integer
    );
  END IF;

  RETURN QUERY
  SELECT v_attempts,
         v_last_failed,
         CASE
           WHEN v_lockout_seconds IS NULL THEN NULL::timestamptz
           ELSE v_last_failed + make_interval(secs => v_lockout_seconds)
         END;
END;
$function$
;

