-- public.get_user_permissions()

CREATE OR REPLACE FUNCTION public.get_user_permissions()
 RETURNS TABLE(permission_name text, resource text, action text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT p.name, p.resource, p.action
  FROM permissions p
  INNER JOIN role_permissions rp ON p.id = rp.permission_id
  INNER JOIN user_roles ur ON rp.role = ur.role
  WHERE ur.user_id = auth.uid()
$function$
;

-- public.get_user_role(_user_id uuid)

CREATE OR REPLACE FUNCTION public.get_user_role(_user_id uuid)
 RETURNS app_role
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN auth.role() = 'anon' THEN NULL
    WHEN _user_id IS DISTINCT FROM auth.uid()
         AND auth.role() <> 'service_role'
         AND NOT EXISTS (
           SELECT 1 FROM public.user_roles
           WHERE user_id = auth.uid() AND role IN ('admin', 'manager')
         )
    THEN NULL
    ELSE (
      SELECT role FROM public.user_roles WHERE user_id = _user_id
      ORDER BY CASE role WHEN 'admin' THEN 1 WHEN 'manager' THEN 2 WHEN 'salesperson' THEN 3 END
      LIMIT 1
    )
  END
$function$
;

-- public.grant_task_xp(_assignment_id uuid, _xp_amount integer, _reason text)

CREATE OR REPLACE FUNCTION public.grant_task_xp(_assignment_id uuid, _xp_amount integer, _reason text DEFAULT 'Task approved'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id UUID;
  _adjustment_id UUID;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Only admins can grant XP';
  END IF;

  SELECT assigned_to INTO _user_id
  FROM public.task_assignments
  WHERE id = _assignment_id;

  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'Assignment not found';
  END IF;

  UPDATE public.task_assignments
  SET status = 'approved',
      reviewed_by = auth.uid(),
      reviewed_at = now(),
      xp_granted = _xp_amount
  WHERE id = _assignment_id;

  INSERT INTO public.xp_adjustments(user_id, amount, reason, source, related_assignment_id, adjusted_by)
  VALUES (_user_id, _xp_amount, _reason, 'task_approval', _assignment_id, auth.uid())
  RETURNING id INTO _adjustment_id;

  RETURN _adjustment_id;
END;
$function$
;

-- public.handle_client_activation()

CREATE OR REPLACE FUNCTION public.handle_client_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- If the sale is completed and it's the first sale
    IF (NEW.status = 'completed' AND NEW.is_first_sale = true) THEN
        UPDATE public.clients
        SET 
            is_activated = true,
            activated_at = COALESCE(activated_at, now()),
            updated_at = now()
        WHERE id = NEW.client_id;
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.handle_client_ltv_update()

CREATE OR REPLACE FUNCTION public.handle_client_ltv_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'INSERT' AND NEW.status = 'completed') OR 
       (TG_OP = 'UPDATE' AND NEW.status = 'completed' AND OLD.status <> 'completed') THEN
        UPDATE public.clients 
        SET total_value = COALESCE(total_value, 0) + NEW.amount,
            updated_at = now()
        WHERE id = NEW.client_id;
    ELSIF (TG_OP = 'UPDATE' AND OLD.status = 'completed' AND NEW.status <> 'completed') OR
          (TG_OP = 'DELETE' AND OLD.status = 'completed') THEN
        UPDATE public.clients 
        SET total_value = GREATEST(0, COALESCE(total_value, 0) - OLD.amount),
            updated_at = now()
        WHERE id = OLD.client_id;
    END IF;
    RETURN NULL;
END;
$function$
;

-- public.handle_stock_management()

CREATE OR REPLACE FUNCTION public.handle_stock_management()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Se a venda for concluída, reduz o estoque (se ainda não reduzido)
    IF (NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status <> 'completed')) THEN
        IF NEW.product_id IS NOT NULL THEN
            UPDATE public.products 
            SET stock_quantity = GREATEST(0, COALESCE(stock_quantity, 0) - 1),
                sales_count = COALESCE(sales_count, 0) + 1,
                updated_at = now()
            WHERE id = NEW.product_id;
        END IF;
    -- Se uma venda concluída for cancelada ou movida para outro status, devolve ao estoque
    ELSIF (OLD.status = 'completed' AND NEW.status <> 'completed') THEN
        IF OLD.product_id IS NOT NULL THEN
            UPDATE public.products 
            SET stock_quantity = COALESCE(stock_quantity, 0) + 1,
                sales_count = GREATEST(0, COALESCE(sales_count, 0) - 1),
                updated_at = now()
            WHERE id = OLD.product_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.handle_stock_on_sale()

CREATE OR REPLACE FUNCTION public.handle_stock_on_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed')) THEN
        IF NEW.product_id IS NOT NULL THEN
            UPDATE public.inventory_levels
            SET current_stock = GREATEST(0, current_stock - 1),
                updated_at = now()
            WHERE product_id = NEW.product_id;
            
            INSERT INTO public.stock_movements (product_id, movement_type, quantity, reason, reference_id)
            VALUES (NEW.product_id, 'exit', 1, 'Venda Concluída: ' || NEW.id, NEW.id);
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
;

