-- public.is_valid_status_transition(p_entity text, p_origem text, p_destino text)

CREATE OR REPLACE FUNCTION public.is_valid_status_transition(p_entity text, p_origem text, p_destino text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    -- Sem origem (INSERT/primeira escrita) ou sem mudança: sempre válido.
    WHEN p_origem IS NULL OR p_origem = p_destino THEN true
    -- Origem fora do vocabulário conhecido: legacy passa (não temos semântica).
    WHEN NOT EXISTS (
      SELECT 1 FROM public.status_transitions
      WHERE entity = p_entity AND status_origem = p_origem
    ) THEN true
    ELSE EXISTS (
      SELECT 1 FROM public.status_transitions
      WHERE entity = p_entity
        AND status_origem = p_origem
        AND status_destino = p_destino
    )
  END;
$function$
;

-- public.is_webhook_host_allowed(p_host text)

CREATE OR REPLACE FUNCTION public.is_webhook_host_allowed(p_host text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_host text;
  v_ip   inet;
BEGIN
  IF p_host IS NULL THEN RETURN false; END IF;

  -- normaliza: caixa baixa, sem espaco, sem ponto final, sem colchete de IPv6
  v_host := lower(btrim(p_host));
  v_host := regexp_replace(v_host, '\.$', '');
  v_host := regexp_replace(v_host, '^\[|\]$', '', 'g');

  IF v_host = '' OR v_host ~ '[\s/@:]' THEN
    -- host com separador de URL dentro nao foi parseado: recusa
    RETURN false;
  END IF;

  -- 1) BLOCKLIST por nome (codigo, nao dado)
  IF v_host IN ('localhost', 'metadata', 'metadata.google.internal',
                'instance-data', 'metadata.goog')
     OR v_host LIKE '%.localhost'
     OR v_host LIKE '%.internal'
     OR v_host LIKE '%.local'
  THEN
    RETURN false;
  END IF;

  -- 2) BLOCKLIST por faixa de rede, quando o host E um literal de IP
  BEGIN
    v_ip := v_host::inet;
  EXCEPTION WHEN others THEN
    v_ip := NULL;
  END;

  IF v_ip IS NOT NULL THEN
    -- IP literal como destino de webhook nunca e legitimo aqui
    RETURN false;
  END IF;

  -- 3) ALLOWLIST: host exato, ou sufixo de um pattern '*.dominio'
  RETURN EXISTS (
    SELECT 1
    FROM public.webhook_allowed_domains d
    WHERE d.pattern = v_host
       OR (d.pattern LIKE '*.%'
           AND v_host LIKE '%' || substring(d.pattern from 2)
           AND length(v_host) > length(d.pattern) - 2)
  );
END;
$function$
;

-- public.log_audit()

CREATE OR REPLACE FUNCTION public.log_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, user_id)
  VALUES (
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    TG_OP,
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) END,
    auth.uid()
  );
  RETURN NEW;
END;
$function$
;

-- public.log_audit_event()

CREATE OR REPLACE FUNCTION public.log_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO audit_log (
    user_id,
    action,
    resource_type,
    resource_id,
    old_data,
    new_data
  ) VALUES (
    auth.uid(),
    TG_OP,
    TG_TABLE_NAME,
    COALESCE(NEW.id::TEXT, OLD.id::TEXT),
    CASE WHEN TG_OP = 'DELETE' THEN row_to_json(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE NULL END
  );
  RETURN NEW;
END;
$function$
;

-- public.log_audit_event(_action text, _entity_type text, _entity_id text, _changes jsonb, _metadata jsonb)

CREATE OR REPLACE FUNCTION public.log_audit_event(_action text, _entity_type text, _entity_id text DEFAULT NULL::text, _changes jsonb DEFAULT '{}'::jsonb, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _id UUID;
  _email TEXT;
  _req TEXT;
BEGIN
  SELECT email INTO _email FROM auth.users WHERE id = auth.uid();

  BEGIN
    _req := current_setting('request.headers', true)::jsonb ->> 'x-request-id';
  EXCEPTION WHEN OTHERS THEN
    _req := NULL;
  END;

  INSERT INTO public.audit_logs (
    actor_id, actor_email, action,
    entity_type, entity_id,
    table_name, record_id,
    changes, request_id, metadata
  ) VALUES (
    auth.uid(), _email, _action,
    _entity_type, _entity_id,
    _entity_type, _entity_id,
    public.audit_scrub(_changes), _req, _metadata
  )
  RETURNING id INTO _id;

  RETURN _id;
END;
$function$
;

-- public.log_data_access()

CREATE OR REPLACE FUNCTION public.log_data_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO data_access_log (user_id, table_name, record_id, action)
  VALUES (
    auth.uid(),
    TG_TABLE_NAME,
    COALESCE(NEW.id, OLD.id),
    TG_OP
  );
  
  RETURN COALESCE(NEW, OLD);
END;
$function$
;

-- public.log_rate_limit(p_identifier text, p_identifier_type text, p_action text, p_blocked boolean)

CREATE OR REPLACE FUNCTION public.log_rate_limit(p_identifier text, p_identifier_type text, p_action text, p_blocked boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
