;

-- public.log_security_event(p_event_type text, p_severity text, p_description text, p_metadata jsonb)

CREATE OR REPLACE FUNCTION public.log_security_event(p_event_type text, p_severity text, p_description text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id uuid;
BEGIN
  IF auth.uid() IS NULL AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_severity NOT IN ('low', 'medium', 'high', 'critical') THEN
    RAISE EXCEPTION 'severity_invalid' USING ERRCODE = '22023';
  END IF;
  IF length(trim(COALESCE(p_event_type, ''))) NOT BETWEEN 1 AND 100
     OR length(trim(COALESCE(p_description, ''))) NOT BETWEEN 1 AND 4000 THEN
    RAISE EXCEPTION 'event_payload_invalid' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.security_events (
    user_id, event_type, severity, description, metadata
  ) VALUES (
    auth.uid(),
    left(trim(p_event_type), 100),
    p_severity,
    left(trim(p_description), 4000),
    p_metadata
  ) RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$function$
;

-- public.log_soft_delete()

CREATE OR REPLACE FUNCTION public.log_soft_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL THEN
    INSERT INTO audit_log (
      table_name,
      record_id,
      action,
      user_id,
      changes,
      reason
    ) VALUES (
      TG_TABLE_NAME,
      NEW.id,
      'SOFT_DELETE',
      NEW.deleted_by,
      jsonb_build_object(
        'deleted_at', NEW.deleted_at,
        'reason', NEW.delete_reason
      ),
      NEW.delete_reason
    );
  END IF;
  
  RETURN NEW;
END;
$function$
;

-- public.maintain_sales_streaks()

CREATE OR REPLACE FUNCTION public.maintain_sales_streaks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_last_date DATE;
    v_current_streak INTEGER;
BEGIN
    SELECT last_sale_date, current_streak INTO v_last_date, v_current_streak
    FROM public.sales_streaks
    WHERE salesperson_id = NEW.salesperson_id;

    IF NOT FOUND THEN
        INSERT INTO public.sales_streaks (salesperson_id, current_streak, longest_streak, last_sale_date)
        VALUES (NEW.salesperson_id, 1, 1, CURRENT_DATE);
    ELSE
        IF v_last_date = CURRENT_DATE - 1 THEN
            UPDATE public.sales_streaks
            SET current_streak = current_streak + 1,
                last_sale_date = CURRENT_DATE,
                longest_streak = GREATEST(longest_streak, current_streak + 1)
            WHERE salesperson_id = NEW.salesperson_id;
            -- NOTE: salespeople.available_spins does not exist in this schema;
            -- the 7-day-streak spin reward is disabled here until that reward
            -- mechanism is (re)wired to an actual column/table.
        ELSIF v_last_date = CURRENT_DATE THEN
            NULL; -- already logged today, nothing to change
        ELSE
            UPDATE public.sales_streaks
            SET current_streak = 1,
                last_sale_date = CURRENT_DATE
            WHERE salesperson_id = NEW.salesperson_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
;

-- public.manage_stock_on_sale()

CREATE OR REPLACE FUNCTION public.manage_stock_on_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed') AND NEW.product_id IS NOT NULL AND NEW.stock_reduced = FALSE THEN
        UPDATE public.products
        SET stock_quantity = GREATEST(0, COALESCE(stock_quantity, 0) - 1),
            sales_count = COALESCE(sales_count, 0) + 1,
            updated_at = now()
        WHERE id = NEW.product_id;
        
        NEW.stock_reduced := TRUE;
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.manual_xp_adjustment(_user_id uuid, _amount integer, _reason text)

CREATE OR REPLACE FUNCTION public.manual_xp_adjustment(_user_id uuid, _amount integer, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _adjustment_id UUID;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Only admins can adjust XP';
  END IF;

  IF _reason IS NULL OR length(trim(_reason)) < 3 THEN
    RAISE EXCEPTION 'Reason is required (min 3 chars)';
  END IF;

  INSERT INTO public.xp_adjustments(user_id, amount, reason, source, adjusted_by)
  VALUES (_user_id, _amount, _reason, 'manual', auth.uid())
  RETURNING id INTO _adjustment_id;

  RETURN _adjustment_id;
END;
$function$
;

