-- public.match_reply_to_enrollment(_contact_email text, _received_at timestamp with time zone)

CREATE OR REPLACE FUNCTION public.match_reply_to_enrollment(_contact_email text, _received_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _enrollment_id uuid;
BEGIN
  IF _contact_email IS NULL OR length(trim(_contact_email)) = 0 THEN
    RETURN NULL;
  END IF;

  -- Try via sales (leads/deals) email
  SELECT se.id INTO _enrollment_id
  FROM public.sequence_enrollments se
  JOIN public.sales s ON s.id = se.contact_id AND se.contact_type = 'lead'
  WHERE lower(s.email) = lower(_contact_email)
    AND se.status IN ('active','scheduled')
    AND se.auto_paused_at IS NULL
    AND se.started_at <= _received_at
  ORDER BY se.started_at DESC
  LIMIT 1;

  IF _enrollment_id IS NOT NULL THEN
    RETURN _enrollment_id;
  END IF;

  -- Try via clients email
  SELECT se.id INTO _enrollment_id
  FROM public.sequence_enrollments se
  JOIN public.clients c ON c.id = se.contact_id AND se.contact_type = 'client'
  WHERE lower(c.email) = lower(_contact_email)
    AND se.status IN ('active','scheduled')
    AND se.auto_paused_at IS NULL
    AND se.started_at <= _received_at
  ORDER BY se.started_at DESC
  LIMIT 1;

  RETURN _enrollment_id;
END;
$function$
;

-- public.match_semantic(_query_embedding vector, _match_count integer, _entity_types text[])

CREATE OR REPLACE FUNCTION public.match_semantic(_query_embedding vector, _match_count integer DEFAULT 20, _entity_types text[] DEFAULT NULL::text[])
 RETURNS TABLE(id uuid, entity_type text, entity_id uuid, content text, metadata jsonb, similarity real)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_admin BOOLEAN;
  v_sp UUID;
BEGIN
  v_is_admin := public.is_admin_or_manager(auth.uid());
  v_sp := public.get_current_salesperson_id();

  RETURN QUERY
  SELECT
    si.id,
    si.entity_type,
    si.entity_id,
    si.content,
    si.metadata,
    (1 - (si.embedding <=> _query_embedding))::real AS similarity
  FROM public.semantic_index si
  WHERE si.embedding IS NOT NULL
    AND (_entity_types IS NULL OR si.entity_type = ANY(_entity_types))
    AND (v_is_admin OR si.salesperson_id = v_sp)
  ORDER BY si.embedding <=> _query_embedding
  LIMIT GREATEST(1, LEAST(_match_count, 50));
END;
$function$
;

-- public.match_weekly_players()

CREATE OR REPLACE FUNCTION public.match_weekly_players()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_players uuid[];
  v_player_a uuid;
  v_player_b uuid;
  v_index integer;
  v_count integer;
  v_week_start date := public.start_of_week(current_date, 1);
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtextextended('match_weekly_players:' || v_week_start::text, 0)
  );

  SELECT array_agg(
           s.id ORDER BY md5(s.id::text || ':' || v_week_start::text), s.id
         )
    INTO v_players
    FROM public.salespeople AS s
   WHERE s.is_active IS TRUE;

  v_count := COALESCE(array_length(v_players, 1), 0);
  IF v_count < 2 THEN
    RETURN;
  END IF;
  IF v_count % 2 <> 0 THEN
    v_count := v_count - 1;
  END IF;

  FOR v_index IN 1..v_count BY 2 LOOP
    v_player_a := v_players[v_index];
    v_player_b := v_players[v_index + 1];

    IF NOT EXISTS (
      SELECT 1
      FROM public.weekly_matchups AS wm
      WHERE wm.week_start = v_week_start
        AND (
          wm.salesperson_a_id IN (v_player_a, v_player_b)
          OR wm.salesperson_b_id IN (v_player_a, v_player_b)
        )
    ) THEN
      INSERT INTO public.weekly_matchups (
        salesperson_a_id, salesperson_b_id, week_start, xp_reward, status
      ) VALUES (
        v_player_a, v_player_b, v_week_start, 250, 'active'
      );
    END IF;
  END LOOP;
END;
$function$
;

-- public.match_whatsapp_reply_to_enrollment(_from_digits text, _owner_ids uuid[], _received_at timestamp with time zone)

CREATE OR REPLACE FUNCTION public.match_whatsapp_reply_to_enrollment(_from_digits text, _owner_ids uuid[] DEFAULT NULL::uuid[], _received_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _enrollment_id uuid;
  _digits text;
BEGIN
  _digits := regexp_replace(COALESCE(_from_digits, ''), '[^0-9]', '', 'g');
  IF length(_digits) = 0 THEN
    RETURN NULL;
  END IF;

  SELECT se.id INTO _enrollment_id
  FROM public.sequence_enrollments se
  JOIN public.outbound_messages om ON om.enrollment_id = se.id
  WHERE om.channel = 'whatsapp'
    AND om.provider = 'evolution'
    AND regexp_replace(om.to_number, '[^0-9]', '', 'g') = _digits
    AND se.status IN ('active', 'scheduled')
    AND se.auto_paused_at IS NULL
    AND se.started_at <= _received_at
  ORDER BY
    -- Preferência pelo dono da credencial da instância que recebeu a
    -- resposta (mesmo critério do fallback no webhook); depois o outbound
    -- mais recente para o número.
    CASE WHEN _owner_ids IS NOT NULL AND om.owner_id = ANY(_owner_ids)
         THEN 0 ELSE 1 END,
    om.created_at DESC
  LIMIT 1;

  RETURN _enrollment_id;
END;
$function$
;

-- public.merge_clients(target_id uuid, duplicate_ids uuid[], preferred_fields jsonb)

CREATE OR REPLACE FUNCTION public.merge_clients(target_id uuid, duplicate_ids uuid[], preferred_fields jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    dup_id UUID;
    field_key TEXT;
    field_value TEXT;
    merged_tags TEXT[];
BEGIN
    -- 1. Atualizar campos preferenciais se fornecidos
    IF preferred_fields <> '{}'::JSONB THEN
        FOR field_key, field_value IN SELECT * FROM jsonb_each_text(preferred_fields)
        LOOP
            IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'clients' AND column_name = field_key) THEN
                EXECUTE format('UPDATE public.clients SET %I = %L WHERE id = %L', field_key, field_value, target_id);
            END IF;
        END LOOP;
    END IF;

    -- 2. Consolidar Tags (Merge de arrays removendo duplicatas)
    SELECT ARRAY_AGG(DISTINCT tag)
    INTO merged_tags
    FROM (
        SELECT UNNEST(tags) as tag FROM public.clients WHERE id = target_id OR id = ANY(duplicate_ids)
    ) t
    WHERE tag IS NOT NULL;

    UPDATE public.clients SET tags = merged_tags WHERE id = target_id;

    -- 3. Reatribuir registros relacionados de todas as tabelas conhecidas
    FOREACH dup_id IN ARRAY duplicate_ids
    LOOP
        -- Core CRM
        UPDATE public.sales SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.tasks SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.activities SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.notes SET client_id = target_id WHERE client_id = dup_id;
        
        -- Intelligence & Analytics
        UPDATE public.agenda_events SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.call_recordings SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.conversation_analyses SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.lead_detailed_logs SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.lead_routing_log SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.client_interactions SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.icp_data SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.client_portfolio SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.client_purchase_seasonality SET client_id = target_id WHERE client_id = dup_id;
        UPDATE public.lead_scenarios SET client_id = target_id WHERE client_id = dup_id;
        
        -- Logs de Auditoria
        UPDATE public.audit_logs SET record_id = target_id WHERE record_id = dup_id AND table_name = 'clients';

        -- Tabelas condicionais (Engajamento/Sequências)
        BEGIN
            EXECUTE 'UPDATE public.cadence_enrollments SET client_id = $1 WHERE client_id = $2' USING target_id, dup_id;
            EXECUTE 'UPDATE public.sequence_enrollments SET client_id = $1 WHERE client_id = $2' USING target_id, dup_id;
        EXCEPTION WHEN OTHERS THEN NULL; END;

        -- Deletar o registro duplicado
        DELETE FROM public.clients WHERE id = dup_id;
    END LOOP;

    -- 4. Recalcular total_value para o mestre (Soma de vendas ganhas)
    UPDATE public.clients 
    SET total_value = (
        SELECT COALESCE(SUM(amount), 0) 
        FROM public.sales 
        WHERE client_id = target_id 
        AND (status = 'won' OR status = 'completed' OR deal_status::text IN ('won', 'completed'))
    )
    WHERE id = target_id;

END;
$function$
;

-- public.next_dialer_item(_queue_id uuid)

CREATE OR REPLACE FUNCTION public.next_dialer_item(_queue_id uuid)
 RETURNS TABLE(item_id uuid, sale_id uuid, score numeric, queue_position integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item_id uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.dialer_queues q WHERE q.id = _queue_id
    AND (q.owner_id = auth.uid() OR has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager'))) THEN
    RAISE EXCEPTION 'Not authorized for queue %', _queue_id;
  END IF;

  SELECT i.id INTO v_item_id FROM public.dialer_queue_items i
  WHERE i.queue_id = _queue_id AND i.status = 'pending'
    AND (i.snooze_until IS NULL OR i.snooze_until <= now())
  ORDER BY i.queue_position ASC, i.score DESC
  LIMIT 1 FOR UPDATE SKIP LOCKED;

  IF v_item_id IS NULL THEN RETURN; END IF;

  UPDATE public.dialer_queue_items SET status = 'calling' WHERE id = v_item_id;

  RETURN QUERY SELECT i.id, i.sale_id, i.score, i.queue_position
    FROM public.dialer_queue_items i WHERE i.id = v_item_id;
END;
$function$
;

-- public.normalize_bulk_failure_reason(_error text)

CREATE OR REPLACE FUNCTION public.normalize_bulk_failure_reason(_error text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN _error IS NULL OR btrim(_error) = '' THEN 'sem_erro'
    WHEN _error ~* 'opted_out|unsubscrib|suppress' THEN 'supressao'
    WHEN _error ~* 'missing_recipient_email' THEN 'destinatario_ausente'
    WHEN _error ~* 'invalid[_ -]?(recipient|email|address)|mailbox (does not exist|unavailable)|5\.1\.[0-9]+' THEN 'endereco_invalido'
    WHEN _error ~* 'hard[_ -]?bounce' THEN 'hard_bounce'
    WHEN _error ~* 'email_infra_missing|sender_not_configured' THEN 'infra_remetente'
    WHEN _error ~* 'rate|throttl|429|too many' THEN 'limite_de_vazao'
    WHEN _error ~* 'timeout|timed out|network|fetch failed|502|503|504' THEN 'rede_indisponivel'
    ELSE 'outro'
  END;
$function$
;

-- public.notify_asset_ai_status()

CREATE OR REPLACE FUNCTION public.notify_asset_ai_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Se view_count atingir um limite (ex: 50) e for ativo, notifica como 'IA Ativa'
    IF NEW.view_count >= 50 AND OLD.view_count < 50 THEN
        INSERT INTO public.notifications (
            user_id,
            title,
            message,
            category,
            priority,
            action_url
        )
        SELECT 
            sp.id,
            '🚀 Novo Material IA Ativa: ' || NEW.title,
            'Este material atingiu o nível de Elite e agora possui suporte neural aprimorado.',
            'ai',
            'high',
            '/sales-enablement'
        FROM public.salespeople sp;
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.notify_asset_influence_boost()

CREATE OR REPLACE FUNCTION public.notify_asset_influence_boost()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_deals_count BIGINT;
    v_asset_title TEXT;
BEGIN
    -- Verifica quantos deals esse asset influenciou
    SELECT COUNT(DISTINCT deal_id) INTO v_deals_count 
    FROM asset_usage_logs 
    WHERE asset_id = NEW.asset_id;

    -- Notifica a cada 10 deals influenciados
    IF v_deals_count > 0 AND v_deals_count % 10 = 0 THEN
        SELECT title INTO v_asset_title FROM sales_enablement_assets WHERE id = NEW.asset_id;
        
        INSERT INTO public.notifications (
            user_id,
            title,
            message,
            category,
            priority,
            action_url
        )
        SELECT 
            sp.id,
            '🔥 Boost de Eficiência: ' || v_asset_title,
            'Este material acaba de influenciar seu ' || v_deals_count || 'º deal fechado! Considere usá-lo mais vezes.',
            'sales',
            'medium',
            '/sales-enablement'
        FROM salespeople sp;
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.notify_sale_completion()

CREATE OR REPLACE FUNCTION public.notify_sale_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_seller_name TEXT;
    v_sale_amount NUMERIC;
    v_seller_rank INT;
    v_recipient RECORD;
    v_recipient_rank INT;
    v_seller_id UUID;
    v_formatted_amount TEXT;
BEGIN
    -- Detect closure event (deal_status = 'completed' cobre o trio WON via
    -- coluna GENERATED — 'won'/'closed' também disparam o alerta).
    -- Dispara também quando uma venda já WON ganha dono depois
    -- (OLD.salesperson_id NULL → NEW preenchido) e ignora WON sem dono —
    -- competitive_chat_messages.salesperson_id é NOT NULL, inserir com
    -- NULL abortava a transação inteira.
    IF NEW.deal_status = 'completed'::deal_status
       AND NEW.salesperson_id IS NOT NULL
       AND (
         TG_OP = 'INSERT'
         OR OLD.deal_status IS DISTINCT FROM 'completed'::deal_status
         OR OLD.salesperson_id IS NULL
       ) THEN

        v_seller_id := NEW.salesperson_id;
        v_sale_amount := NEW.amount;
        v_formatted_amount := 'R$ ' || to_char(v_sale_amount, 'FM999G999G990D00');

        -- Get seller details
        SELECT name INTO v_seller_name FROM public.salespeople WHERE id = v_seller_id;

        -- Calculate seller rank at this exact moment
        SELECT pos INTO v_seller_rank
        FROM (
            SELECT salesperson_id, RANK() OVER (ORDER BY SUM(amount) DESC) as pos
            FROM public.sales
            WHERE deal_status = 'completed'::deal_status
              AND created_at >= date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo'
            GROUP BY salesperson_id
        ) snap WHERE salesperson_id = v_seller_id;

        IF v_seller_rank IS NULL THEN v_seller_rank := 1; END IF;

        -- Notify ALL other active salespeople
        FOR v_recipient IN
            SELECT sp.id, sp.auth_user_id, sp.name, COALESCE(r.pos, 0) as recipient_rank
            FROM public.salespeople sp
            LEFT JOIN (
                SELECT salesperson_id, RANK() OVER (ORDER BY SUM(amount) DESC) as pos
                FROM public.sales
                WHERE deal_status = 'completed'::deal_status
                  AND created_at >= date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo'
                GROUP BY salesperson_id
            ) r ON r.salesperson_id = sp.id
            WHERE sp.is_active = true
              AND sp.id != v_seller_id
              AND sp.auth_user_id IS NOT NULL
        LOOP
            v_recipient_rank := v_recipient.recipient_rank;

            -- 1. Insert individual notification
            INSERT INTO public.notifications (
                user_id,
                type,
                category,
                priority,
                title,
                message,
                icon,
                metadata
            ) VALUES (
                v_recipient.auth_user_id,
                'sale_alert',
                'gamification',
                'high',
                '🚀 ' || v_seller_name || ' vendeu!',
                'Fechou ' || v_formatted_amount || '! Rank dele: #' || v_seller_rank ||
                '. Seu rank: ' || CASE WHEN v_recipient_rank = 0 THEN 'S/R' ELSE '#' || v_recipient_rank END ||
                '. Vamos buscar!',
                'Zap',
                jsonb_build_object(
                    'sale_id', NEW.id,
                    'seller_id', v_seller_id,
                    'seller_name', v_seller_name,
                    'amount', v_sale_amount,
                    'seller_rank', v_seller_rank,
                    'recipient_rank', v_recipient_rank,
                    'is_competition_alert', true
                )
            );

            -- 2. Log audit history
            INSERT INTO public.sale_notifications_audit (
                sale_id,
                seller_id,
                seller_name,
                sale_amount,
                seller_rank_at_time,
                recipient_id,
                recipient_rank_at_time,
                notification_type
            ) VALUES (
                NEW.id,
                v_seller_id,
                v_seller_name,
                v_sale_amount,
                v_seller_rank,
                v_recipient.id,
                v_recipient_rank,
                'in-app'
            );
        END LOOP;

        -- Competitive Chat Post
        INSERT INTO public.competitive_chat_messages (
            salesperson_id,
            message,
            message_type
        ) VALUES (
            v_seller_id,
            'Acabei de fechar ' || v_formatted_amount || '! A meta tá logo ali! 🔥',
            'chat'
        );

    END IF;
    RETURN NEW;
END;
$function$
;

-- public.notify_salesperson_on_bonus_paid()

CREATE OR REPLACE FUNCTION public.notify_salesperson_on_bonus_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _auth_user uuid;
  _bonus_name text;
  _amount_txt text;
BEGIN
  IF NEW.status <> 'paid' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'paid' THEN
    RETURN NEW;
  END IF;

  SELECT auth_user_id INTO _auth_user
  FROM public.salespeople
  WHERE id = NEW.salesperson_id
  LIMIT 1;

  IF _auth_user IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT name INTO _bonus_name
  FROM public.commission_bonuses
  WHERE id = NEW.bonus_id
  LIMIT 1;

  _amount_txt := to_char(COALESCE(NEW.computed_amount, 0), 'FM"R$" 999G999G990D00');

  INSERT INTO public.notifications (
    user_id, type, category, priority, icon, title, message,
    action_label, action_url, metadata
  ) VALUES (
    _auth_user,
    'commission_paid',
    'commission',
    'high',
    'trophy',
    '🎉 Premiação paga!',
    'Sua premiação "' || COALESCE(_bonus_name, 'Bônus') || '" no valor de ' || _amount_txt || ' foi liberada.',
    'Ver detalhes',
    '/meu-assistente',
    jsonb_build_object(
      'award_id', NEW.id,
      'bonus_id', NEW.bonus_id,
      'amount', NEW.computed_amount,
      'period_month', NEW.period_month,
      'bonus_kind', NEW.bonus_kind
    )
  );

  RETURN NEW;
END;
$function$
;

-- public.pick_step_variant(_step_id uuid)

CREATE OR REPLACE FUNCTION public.pick_step_variant(_step_id uuid)
 RETURNS TABLE(variant_id uuid, label text, subject text, body text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _total int; _r numeric; _cum int := 0; _row record;
BEGIN
  SELECT COALESCE(SUM(traffic_weight),0) INTO _total FROM public.sequence_step_variants WHERE step_id = _step_id;
  IF _total = 0 THEN RETURN; END IF;
  _r := random() * _total;
  FOR _row IN
    SELECT v.id, v.label, v.subject, v.body, v.traffic_weight
    FROM public.sequence_step_variants v WHERE v.step_id = _step_id ORDER BY v.label
  LOOP
    _cum := _cum + _row.traffic_weight;
    IF _r <= _cum THEN
      RETURN QUERY SELECT _row.id, _row.label, _row.subject, _row.body;
      RETURN;
    END IF;
  END LOOP;
END;
$function$
;

-- public.process_audit_log()

CREATE OR REPLACE FUNCTION public.process_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'DELETE') THEN
        INSERT INTO public.audit_logs(table_name, record_id, action, old_data, changed_by)
        VALUES (TG_TABLE_NAME, OLD.id, TG_OP, to_jsonb(OLD), auth.uid());
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.audit_logs(table_name, record_id, action, old_data, new_data, changed_by)
        VALUES (TG_TABLE_NAME, NEW.id, TG_OP, to_jsonb(OLD), to_jsonb(NEW), auth.uid());
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO public.audit_logs(table_name, record_id, action, new_data, changed_by)
        VALUES (TG_TABLE_NAME, NEW.id, TG_OP, to_jsonb(NEW), auth.uid());
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$
;

-- public.process_lead_intent_event(p_prospect_cadence_id uuid, p_event_type text, p_details jsonb)

CREATE OR REPLACE FUNCTION public.process_lead_intent_event(p_prospect_cadence_id uuid, p_event_type text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_prospect RECORD;
    v_rule RECORD;
    v_event_count INTEGER;
    v_transitioned BOOLEAN := FALSE;
    v_result JSONB;
BEGIN
    -- Get prospect info
    SELECT pc.*, c.name as cadence_name, pc.salesperson_id
    INTO v_prospect
    FROM prospect_cadences pc
    JOIN cadences c ON c.id = pc.cadence_id
    WHERE pc.id = p_prospect_cadence_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'Prospect not found');
    END IF;

    -- Log the event
    INSERT INTO intent_audit_logs (lead_id, event_type, details)
    VALUES (p_prospect_cadence_id, p_event_type, p_details);

    -- Check for matching rules for the current stage
    FOR v_rule IN 
        SELECT * FROM cadence_funnel_rules 
        WHERE is_active = true 
          AND from_stage = v_prospect.funnel_stage 
          AND condition_type = p_event_type
    LOOP
        -- Count occurrences within time window
        SELECT count(*)
        INTO v_event_count
        FROM intent_audit_logs
        WHERE lead_id = p_prospect_cadence_id
          AND event_type = p_event_type
          AND created_at >= now() - (v_rule.time_window_hours || ' hours')::interval;

        -- Check if condition is met
        IF v_event_count >= v_rule.condition_value THEN
            -- Update prospect stage
            UPDATE prospect_cadences
            SET funnel_stage = v_rule.to_stage,
                updated_at = now()
            WHERE id = p_prospect_cadence_id;

            v_transitioned := TRUE;

            -- If transitioned to "high_interest", create a "Ligar Agora" task
            IF v_rule.to_stage = 'high_interest' THEN
                -- Create task
                INSERT INTO cadence_tasks (
                    prospect_cadence_id,
                    scheduled_date,
                    status,
                    notes
                ) VALUES (
                    p_prospect_cadence_id,
                    CURRENT_DATE,
                    'pending',
                    'Gatilho de Intenção: ' || p_event_type || ' (' || v_event_count || ' vezes)'
                );

                -- Notify salesperson
                IF v_prospect.salesperson_id IS NOT NULL THEN
                    INSERT INTO notifications (
                        user_id,
                        type,
                        category,
                        priority,
                        title,
                        message,
                        icon,
                        metadata
                    ) VALUES (
                        v_prospect.salesperson_id,
                        'alert',
                        'sales',
                        'high',
                        '🔥 Lead com Alto Interesse!',
                        'O lead ' || substring(p_prospect_cadence_id::text, 1, 8) || ' realizou ' || v_event_count || ' ' || p_event_type || '(s). Ligue agora!',
                        'Flame',
                        jsonb_build_object('prospect_id', p_prospect_cadence_id, 'event_type', p_event_type)
                    );
                END IF;
            END IF;

            -- Exit loop after first successful transition
            EXIT;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'transitioned', v_transitioned,
        'new_stage', CASE WHEN v_transitioned THEN v_rule.to_stage ELSE v_prospect.funnel_stage END,
        'event_count', v_event_count
    );
END;
$function$
;

-- public.process_performance_bet_event()

CREATE OR REPLACE FUNCTION public.process_performance_bet_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    bet_record RECORD;
    val_to_add NUMERIC := 0;
BEGIN
    -- This trigger should run after activities or sales inserts
    
    -- If it's a sale, we might be tracking 'deals' or 'revenue'
    IF TG_TABLE_NAME = 'sales' THEN
        -- Loop through active bets for this salesperson
        FOR bet_record IN 
            SELECT * FROM public.performance_bets 
            WHERE salesperson_id = NEW.salesperson_id 
            AND status = 'active'
            AND ends_at > now()
        LOOP
            IF bet_record.bet_type = 'deals' THEN
                UPDATE public.performance_bets 
                SET current_value = current_value + 1
                WHERE id = bet_record.id;
            ELSIF bet_record.bet_type = 'revenue' THEN
                UPDATE public.performance_bets 
                SET current_value = current_value + COALESCE(NEW.value, 0)
                WHERE id = bet_record.id;
            END IF;
        END LOOP;
        
    -- If it's an activity, we might be tracking 'calls', 'meetings' or 'activities'
    ELSIF TG_TABLE_NAME = 'activities' THEN
        FOR bet_record IN 
            SELECT * FROM public.performance_bets 
            WHERE salesperson_id = NEW.salesperson_id 
            AND status = 'active'
            AND ends_at > now()
        LOOP
            IF bet_record.bet_type = 'activities' THEN
                UPDATE public.performance_bets SET current_value = current_value + 1 WHERE id = bet_record.id;
            ELSIF bet_record.bet_type = 'calls' AND NEW.activity_type = 'call' THEN
                UPDATE public.performance_bets SET current_value = current_value + 1 WHERE id = bet_record.id;
            ELSIF bet_record.bet_type = 'meetings' AND NEW.activity_type = 'meeting' THEN
                UPDATE public.performance_bets SET current_value = current_value + 1 WHERE id = bet_record.id;
            END IF;
        END LOOP;
    END IF;

    -- Trigger a check for completion after update
    PERFORM public.check_performance_bets_completion(NEW.salesperson_id);

    RETURN NEW;
END;
$function$
;

-- public.process_race_event_on_sale()

CREATE OR REPLACE FUNCTION public.process_race_event_on_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
DECLARE
  v_payload jsonb;
  v_base_url text;
  v_anon_key text;
  v_cron_secret text;
BEGIN
  IF NEW.salesperson_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_payload := jsonb_build_object('sale_id', NEW.id);

  SELECT
    max(s.value) FILTER (WHERE s.key = 'functions_base_url'),
    max(s.value) FILTER (WHERE s.key = 'anon_key'),
    max(s.value) FILTER (WHERE s.key = 'coaching_cron_secret')
  INTO v_base_url, v_anon_key, v_cron_secret
  FROM public._internal_secrets AS s;

  IF v_base_url IS NULL OR v_anon_key IS NULL OR v_cron_secret IS NULL THEN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('process_race_event_on_sale', 'process-race-event',
            jsonb_build_object('sale_id', NEW.id), 'internal_edge_secrets_missing');
    RETURN NEW;
  END IF;
  IF v_base_url !~ '^https://[^[:space:]]+$' THEN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('process_race_event_on_sale', 'process-race-event',
            jsonb_build_object('sale_id', NEW.id), 'internal_edge_base_url_must_be_https');
    RETURN NEW;
  END IF;

  PERFORM net.http_post(
    url := rtrim(v_base_url, '/') || '/process-race-event',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_anon_key,
      'Authorization', 'Bearer ' || v_anon_key,
      'X-Cron-Secret', v_cron_secret
    ),
    body := v_payload
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Nunca quebrar a escrita da venda, mas deixar a falha visível.
  BEGIN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('process_race_event_on_sale', 'process-race-event',
            jsonb_build_object('sale_id', NEW.id), SQLERRM);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RAISE WARNING 'process_race_event_on_sale failed: %', SQLERRM;
  RETURN NEW;
END;
$function$
;

-- public.process_weekly_league_reset()

CREATE OR REPLACE FUNCTION public.process_weekly_league_reset()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    league_record RECORD;
    member_record RECORD;
    next_league_id UUID;
    prev_league_id UUID;
    total_members INT;
    top_slots INT;
    bottom_slots INT;
    current_rank INT;
BEGIN
    -- 1. Salvar histórico da semana anterior
    INSERT INTO public.league_history (salesperson_id, league_id, rank_achieved, xp_earned, season_date)
    SELECT salesperson_id, league_id, 0, weekly_xp, (CURRENT_DATE - INTERVAL '1 day')::DATE
    FROM public.league_members;

    -- 2. Processar Ligas Individualmente (Promoção/Rebaixamento)
    FOR league_record IN SELECT * FROM public.leagues ORDER BY tier DESC LOOP
        -- Pegar configurações da liga
        top_slots := league_record.promotion_slots;
        bottom_slots := league_record.demotion_slots;

        current_rank := 1;
        FOR member_record IN 
            SELECT * FROM public.league_members 
            WHERE league_id = league_record.id 
            ORDER BY weekly_xp DESC 
        LOOP
            -- Determinar Próxima Liga
            IF current_rank <= top_slots AND league_record.tier < 5 THEN
                SELECT id INTO next_league_id FROM public.leagues WHERE tier = league_record.tier + 1;
                IF next_league_id IS NOT NULL THEN
                    UPDATE public.league_members SET league_id = next_league_id, promoted_at = now() WHERE id = member_record.id;
                    UPDATE public.league_history SET promoted = true WHERE salesperson_id = member_record.salesperson_id AND season_date = (CURRENT_DATE - INTERVAL '1 day')::DATE;
                END IF;
            ELSIF current_rank > (SELECT count(*) FROM public.league_members WHERE league_id = league_record.id) - bottom_slots AND league_record.tier > 1 THEN
                SELECT id INTO prev_league_id FROM public.leagues WHERE tier = league_record.tier - 1;
                IF prev_league_id IS NOT NULL THEN
                    UPDATE public.league_members SET league_id = prev_league_id, demoted_at = now() WHERE id = member_record.id;
                    UPDATE public.league_history SET demoted = true WHERE salesperson_id = member_record.salesperson_id AND season_date = (CURRENT_DATE - INTERVAL '1 day')::DATE;
                END IF;
            END IF;

            UPDATE public.league_history SET rank_achieved = current_rank 
            WHERE salesperson_id = member_record.salesperson_id AND season_date = (CURRENT_DATE - INTERVAL '1 day')::DATE;
            
            current_rank := current_rank + 1;
        END LOOP;
    END LOOP;

    -- 3. Zerar XP Semanal
    UPDATE public.league_members SET weekly_xp = 0, last_reset_xp = weekly_xp, updated_at = now();
END;
$function$
;

-- public.protect_pa_nudge_content()

CREATE OR REPLACE FUNCTION public.protect_pa_nudge_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.content IS DISTINCT FROM OLD.content THEN
    RAISE EXCEPTION 'nudge.content is immutable';
  END IF;
  IF NEW.salesperson_id IS DISTINCT FROM OLD.salesperson_id THEN
    RAISE EXCEPTION 'nudge.salesperson_id is immutable';
  END IF;
  -- Auto-preenche feedback_at quando feedback muda de pending -> accepted/dismissed
  IF OLD.feedback = 'pending' AND NEW.feedback IN ('accepted','dismissed') AND NEW.feedback_at IS NULL THEN
    NEW.feedback_at = now();
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.purge_old_telemetry(_retention_days integer)

CREATE OR REPLACE FUNCTION public.purge_old_telemetry(_retention_days integer DEFAULT 90)
 RETURNS TABLE(table_name text, rows_deleted bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  targets jsonb := '[
    {"t":"web_vitals_samples",       "c":"created_at"},
    {"t":"access_denied_logs",       "c":"created_at"},
    {"t":"page_analytics",           "c":"created_at"},
    {"t":"geo_access_logs",          "c":"created_at"},
    {"t":"rate_limit_logs",          "c":"created_at"},
    {"t":"integration_logs",         "c":"timestamp"},
    {"t":"login_attempts",           "c":"created_at"},
    {"t":"mfa_verification_attempts","c":"created_at"},
    {"t":"bitrix24_sync_logs",       "c":"created_at"},
    {"t":"email_tracking_events",    "c":"created_at"},
    {"t":"duplicate_block_logs",     "c":"created_at"},
    {"t":"quote_sync_inbound_log",   "c":"created_at"},
    {"t":"webhook_inbound_dedupe",   "c":"created_at"},
    {"t":"query_telemetry",          "c":"created_at"},
    {"t":"error_logs",               "c":"created_at"}
  ]'::jsonb;
  rec jsonb;
  n bigint;
  total bigint := 0;
  per_table jsonb := '{}'::jsonb;
  cutoff timestamptz := now() - make_interval(days => _retention_days);
BEGIN
  IF _retention_days < 7 THEN
    RAISE EXCEPTION 'refusing to purge with retention < 7 days (got %)', _retention_days;
  END IF;

  FOR rec IN SELECT * FROM jsonb_array_elements(targets) LOOP
    EXECUTE format(
      'WITH d AS (DELETE FROM public.%I WHERE %I < $1 RETURNING 1) SELECT count(*) FROM d',
      rec->>'t', rec->>'c'
    ) INTO n USING cutoff;
    table_name := rec->>'t';
    rows_deleted := n;
    total := total + n;
    per_table := per_table || jsonb_build_object(rec->>'t', n);
    RETURN NEXT;
  END LOOP;

  INSERT INTO public.maintenance_log(job_name, status, completed_at, rows_affected, metadata)
  VALUES ('purge_old_telemetry', 'completed', now(), total,
          jsonb_build_object('retention_days', _retention_days,
                             'cutoff', cutoff,
                             'per_table', per_table));
END;
$function$
;

-- public.purge_telemetry_retention()

CREATE OR REPLACE FUNCTION public.purge_telemetry_retention()
 RETURNS TABLE(table_name text, deleted_rows bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_wv bigint := 0;
  v_qt bigint := 0;
  v_pa bigint := 0;
BEGIN
  DELETE FROM public.web_vitals_samples
   WHERE created_at < now() - interval '30 days';
  GET DIAGNOSTICS v_wv = ROW_COUNT;

  IF EXISTS (
    SELECT 1
    FROM information_schema.tables AS ist
    WHERE ist.table_schema = 'public'
      AND ist.table_name = 'query_telemetry'
  ) THEN
    DELETE FROM public.query_telemetry
     WHERE created_at < now() - interval '60 days';
    GET DIAGNOSTICS v_qt = ROW_COUNT;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM information_schema.tables AS ist
    WHERE ist.table_schema = 'public'
      AND ist.table_name = 'page_analytics'
  ) THEN
    DELETE FROM public.page_analytics
     WHERE created_at < now() - interval '90 days';
    GET DIAGNOSTICS v_pa = ROW_COUNT;
  END IF;

  RETURN QUERY VALUES
    ('web_vitals_samples'::text, v_wv),
    ('query_telemetry'::text, v_qt),
    ('page_analytics'::text, v_pa);
END;
$function$
;

-- public.race_cars_guard_counters()

CREATE OR REPLACE FUNCTION public.race_cars_guard_counters()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
    IF TG_OP = 'INSERT' THEN
      IF COALESCE(NEW.total_wins, 0) <> 0
         OR COALESCE(NEW.total_overtakes, 0) <> 0
         OR COALESCE(NEW.total_races, 0) <> 0 THEN
        RAISE EXCEPTION 'Contadores de corrida são gerenciados pelo servidor'
          USING ERRCODE = '42501';
      END IF;
    ELSIF NEW.total_wins IS DISTINCT FROM OLD.total_wins
       OR NEW.total_overtakes IS DISTINCT FROM OLD.total_overtakes
       OR NEW.total_races IS DISTINCT FROM OLD.total_races THEN
      RAISE EXCEPTION 'Contadores de corrida são gerenciados pelo servidor'
        USING ERRCODE = '42501';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.reassign_inactive_client_portfolio(p_portfolio_id uuid, p_expected_salesperson_id uuid, p_expected_updated_at timestamp with time zone, p_to_salesperson_id uuid, p_inactivity_threshold_days integer, p_strategy text)

CREATE OR REPLACE FUNCTION public.reassign_inactive_client_portfolio(p_portfolio_id uuid, p_expected_salesperson_id uuid, p_expected_updated_at timestamp with time zone, p_to_salesperson_id uuid, p_inactivity_threshold_days integer, p_strategy text)
 RETURNS TABLE(portfolio_id uuid, client_id uuid, previous_salesperson_id uuid, assigned_to uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_portfolio public.client_portfolio%ROWTYPE;
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Esta operação é exclusiva do serviço interno'
      USING ERRCODE = '42501';
  END IF;

  IF p_inactivity_threshold_days IS NULL
    OR p_inactivity_threshold_days < 1
    OR p_inactivity_threshold_days > 3650 THEN
    RAISE EXCEPTION 'Limite de inatividade inválido'
      USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_portfolio
  FROM public.client_portfolio
  WHERE id = p_portfolio_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Carteira não encontrada' USING ERRCODE = 'P0002';
  END IF;

  IF v_portfolio.status <> 'inactive'
    OR v_portfolio.salesperson_id IS DISTINCT FROM p_expected_salesperson_id
    OR v_portfolio.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Carteira foi alterada desde a seleção do job'
      USING ERRCODE = 'P0001';
  END IF;

  -- A seleção do job é apenas uma fotografia. Revalida a inatividade sob o
  -- mesmo lock para que uma compra recente não seja reatribuída por uma
  -- chamada service_role atrasada ou incorreta.
  IF v_portfolio.last_purchase_date IS NOT NULL
    AND v_portfolio.last_purchase_date >= current_date - p_inactivity_threshold_days THEN
    RAISE EXCEPTION 'Carteira não atingiu o limite de inatividade observado'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_to_salesperson_id IS NULL
    OR p_to_salesperson_id = v_portfolio.salesperson_id THEN
    RAISE EXCEPTION 'Vendedor de destino inválido'
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.salespeople
  WHERE id = p_to_salesperson_id
    AND is_active IS TRUE
    AND role IN ('closer', 'hybrid');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vendedor de destino inválido ou inativo'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.client_portfolio
  SET salesperson_id = p_to_salesperson_id,
      assigned_at = now(),
      updated_at = now()
  WHERE id = v_portfolio.id;

  INSERT INTO public.lead_routing_log (
    client_id,
    from_salesperson_id,
    to_salesperson_id,
    routing_reason,
    notes
  ) VALUES (
    v_portfolio.client_id,
    v_portfolio.salesperson_id,
    p_to_salesperson_id,
    'auto_reassign_inactive',
    format(
      'Reatribuição automática por inatividade (%s dias). Estratégia: %s',
      p_inactivity_threshold_days,
      left(trim(COALESCE(p_strategy, 'desconhecida')), 100)
    )
  );

  RETURN QUERY
    SELECT v_portfolio.id,
           v_portfolio.client_id,
           v_portfolio.salesperson_id,
           p_to_salesperson_id;
END;
$function$
;

-- public.recompute_engagement_score(_contact_id uuid, _contact_type text)

CREATE OR REPLACE FUNCTION public.recompute_engagement_score(_contact_id uuid, _contact_type text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_opens INTEGER := 0;
  v_total_clicks INTEGER := 0;
  v_total_replies INTEGER := 0;
  v_raw_score NUMERIC := 0;
  v_score NUMERIC := 0;
  v_tier TEXT := 'cold';
  v_last_signal TIMESTAMPTZ;
  v_half_life_days NUMERIC := 7;
BEGIN
  IF _contact_id IS NULL OR _contact_type NOT IN ('lead','client') THEN
    RETURN 0;
  END IF;

  SELECT
    COALESCE(SUM(opens), 0),
    COALESCE(SUM(clicks), 0),
    COALESCE(SUM(replies), 0),
    MAX(updated_at)
  INTO v_total_opens, v_total_clicks, v_total_replies, v_last_signal
  FROM public.contact_send_time_profile
  WHERE contact_id = _contact_id
    AND contact_type = _contact_type
    AND updated_at >= now() - interval '30 days';

  SELECT COALESCE(SUM(
    (opens * 1 + clicks * 3 + replies * 8) *
    POWER(0.5, EXTRACT(EPOCH FROM (now() - updated_at)) / (v_half_life_days * 86400))
  ), 0)
  INTO v_raw_score
  FROM public.contact_send_time_profile
  WHERE contact_id = _contact_id
    AND contact_type = _contact_type
    AND updated_at >= now() - interval '30 days';

  v_score := LEAST(100, GREATEST(0, v_raw_score * 2));

  v_tier := CASE
    WHEN v_score >= 81 THEN 'on_fire'
    WHEN v_score >= 51 THEN 'hot'
    WHEN v_score >= 21 THEN 'warm'
    ELSE 'cold'
  END;

  INSERT INTO public.contact_engagement_score
    (contact_id, contact_type, score, tier, total_opens, total_clicks, total_replies, last_signal_at, decay_applied_at, updated_at)
  VALUES
    (_contact_id, _contact_type, v_score, v_tier, v_total_opens, v_total_clicks, v_total_replies, v_last_signal, now(), now())
  ON CONFLICT (contact_id, contact_type) DO UPDATE SET
    score = EXCLUDED.score,
    tier = EXCLUDED.tier,
    total_opens = EXCLUDED.total_opens,
    total_clicks = EXCLUDED.total_clicks,
    total_replies = EXCLUDED.total_replies,
    last_signal_at = EXCLUDED.last_signal_at,
    decay_applied_at = now(),
    updated_at = now();

  INSERT INTO public.engagement_score_history (contact_id, contact_type, score, tier, captured_at)
  VALUES (_contact_id, _contact_type, v_score, v_tier, CURRENT_DATE)
  ON CONFLICT (contact_id, contact_type, captured_at) DO UPDATE SET
    score = EXCLUDED.score,
    tier = EXCLUDED.tier;

  RETURN v_score;
END;
$function$
;

-- public.reconcile_forecast_accuracy(_days integer)

CREATE OR REPLACE FUNCTION public.reconcile_forecast_accuracy(_days integer DEFAULT 30)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_target_date DATE := CURRENT_DATE - (_days || ' days')::interval;
BEGIN
    -- Atualiza os snapshots antigos com o valor real realizado no período
    UPDATE public.forecast_snapshots fs
    SET actual_realized_value = (
        SELECT COALESCE(SUM(amount), 0)
        FROM public.sales
        WHERE status = 'completed'
        AND created_at BETWEEN fs.snapshot_date AND (fs.snapshot_date + (fs.horizon_days || ' days')::interval)
    )
    WHERE fs.snapshot_date = v_target_date;

    -- Insere na tabela de precisão
    INSERT INTO public.forecast_accuracy (period_start, period_end, forecasted_value, actual_value, deviation_pct)
    SELECT 
        snapshot_date, 
        (snapshot_date + (horizon_days || ' days')::interval),
        realistic_value,
        actual_realized_value,
        CASE WHEN realistic_value > 0 THEN ABS(actual_realized_value - realistic_value) / realistic_value * 100 ELSE 0 END
    FROM public.forecast_snapshots
    WHERE snapshot_date = v_target_date;
END;
$function$
;

-- public.record_email_opt_out(_email text, _reason text, _source text, _owner_id uuid, _metadata jsonb)

CREATE OR REPLACE FUNCTION public.record_email_opt_out(_email text, _reason text DEFAULT NULL::text, _source text DEFAULT 'unsubscribe_link'::text, _owner_id uuid DEFAULT NULL::uuid, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text := lower(btrim(coalesce(_email, '')));
  v_id uuid;
BEGIN
  IF v_email = '' OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'invalid_email';
  END IF;

  INSERT INTO public.email_opt_outs (email, reason, source, owner_id, metadata)
  VALUES (v_email, _reason, coalesce(_source, 'unsubscribe_link'), _owner_id, coalesce(_metadata, '{}'::jsonb))
  ON CONFLICT (lower(email)) DO UPDATE
    SET reason = coalesce(EXCLUDED.reason, public.email_opt_outs.reason),
        source = EXCLUDED.source
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$
;

-- public.record_engagement_signal(_contact_id uuid, _contact_type text, _signal text, _occurred_at timestamp with time zone)

CREATE OR REPLACE FUNCTION public.record_engagement_signal(_contact_id uuid, _contact_type text, _signal text, _occurred_at timestamp with time zone DEFAULT now())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  h smallint;
  d smallint;
BEGIN
  IF _contact_id IS NULL OR _contact_type NOT IN ('lead', 'client') THEN
    RETURN;
  END IF;

  h := EXTRACT(HOUR FROM _occurred_at)::smallint;
  d := EXTRACT(DOW FROM _occurred_at)::smallint;

  INSERT INTO public.contact_send_time_profile
    (contact_id, contact_type, hour_of_day, day_of_week, opens, clicks, replies, updated_at)
  VALUES (
    _contact_id, _contact_type, h, d,
    CASE WHEN _signal = 'open' THEN 1 ELSE 0 END,
    CASE WHEN _signal = 'click' THEN 1 ELSE 0 END,
    CASE WHEN _signal = 'reply' THEN 1 ELSE 0 END,
    now()
  )
  ON CONFLICT (contact_id, contact_type, hour_of_day, day_of_week)
  DO UPDATE SET
    opens = public.contact_send_time_profile.opens + CASE WHEN _signal = 'open' THEN 1 ELSE 0 END,
    clicks = public.contact_send_time_profile.clicks + CASE WHEN _signal = 'click' THEN 1 ELSE 0 END,
    replies = public.contact_send_time_profile.replies + CASE WHEN _signal = 'reply' THEN 1 ELSE 0 END,
    updated_at = now();
END;
$function$
;

-- public.record_failed_login_attempt(p_email text, p_failure_reason text, p_user_agent text)

CREATE OR REPLACE FUNCTION public.record_failed_login_attempt(p_email text, p_failure_reason text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text := lower(trim(COALESCE(p_email, '')));
  v_headers jsonb := COALESCE(
    NULLIF(current_setting('request.headers', true), '')::jsonb,
    '{}'::jsonb
  );
  v_ip text;
  v_recent integer;
BEGIN
  IF length(v_email) < 3
     OR length(v_email) > 320
     OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN
    RAISE EXCEPTION 'email_invalid' USING ERRCODE = '22023';
  END IF;

  v_ip := left(trim(split_part(COALESCE(
    v_headers ->> 'cf-connecting-ip',
    v_headers ->> 'x-forwarded-for',
    v_headers ->> 'x-real-ip',
    ''
  ), ',', 1)), 64);
  IF v_ip = '' THEN
    v_ip := NULL;
  ELSE
    BEGIN
      v_ip := host(v_ip::inet);
    EXCEPTION WHEN invalid_text_representation THEN
      v_ip := NULL;
    END;
  END IF;

  SELECT count(*)::integer
    INTO v_recent
    FROM public.login_attempts AS la
   WHERE la.created_at >= now() - interval '1 minute'
     AND (
       lower(la.email) = v_email
       OR (v_ip IS NOT NULL AND la.ip_address = v_ip)
     );

  IF v_recent >= 10 THEN
    RAISE EXCEPTION 'rate_limit_exceeded' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.login_attempts (
    email, ip_address, user_agent, success, failure_reason, created_at
  ) VALUES (
    v_email,
    v_ip,
    left(NULLIF(p_user_agent, ''), 500),
    false,
    left(NULLIF(p_failure_reason, ''), 200),
    now()
  );
END;
$function$
;

