-- public.record_price_history()

CREATE OR REPLACE FUNCTION public.record_price_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.unit_price IS DISTINCT FROM NEW.unit_price THEN
    INSERT INTO price_history (supplier_product_id, product_id, supplier_id, old_price, new_price)
    VALUES (NEW.id, NEW.product_id, NEW.supplier_id, OLD.unit_price, NEW.unit_price);
    
    -- Create alert if price change is significant (> 5%)
    IF OLD.unit_price > 0 AND ABS((NEW.unit_price - OLD.unit_price) / OLD.unit_price) > 0.05 THEN
      INSERT INTO price_alerts (product_id, supplier_id, alert_type, old_price, new_price, price_change_percent)
      VALUES (
        NEW.product_id, 
        NEW.supplier_id, 
        CASE WHEN NEW.unit_price < OLD.unit_price THEN 'price_drop' ELSE 'price_increase' END,
        OLD.unit_price,
        NEW.unit_price,
        ((NEW.unit_price - OLD.unit_price) / OLD.unit_price) * 100
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.record_sale_stage_transition()

CREATE OR REPLACE FUNCTION public.record_sale_stage_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS NOT NULL THEN
      INSERT INTO public.deal_stage_transitions (sale_id, from_stage, to_stage, entered_at)
      VALUES (NEW.id, NULL, NEW.status::text, COALESCE(NEW.created_at, now()));
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    UPDATE public.deal_stage_transitions
       SET exited_at = now()
     WHERE sale_id = NEW.id AND exited_at IS NULL;

    INSERT INTO public.deal_stage_transitions (sale_id, from_stage, to_stage, entered_at)
    VALUES (NEW.id, OLD.status::text, NEW.status::text, now());
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.record_successful_login_attempt(p_user_agent text)

CREATE OR REPLACE FUNCTION public.record_successful_login_attempt(p_user_agent text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text := lower(trim(COALESCE(auth.jwt() ->> 'email', '')));
  v_headers jsonb := COALESCE(
    NULLIF(current_setting('request.headers', true), '')::jsonb,
    '{}'::jsonb
  );
  v_ip text;
BEGIN
  IF auth.uid() IS NULL OR v_email = '' THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  v_ip := left(trim(split_part(COALESCE(
    v_headers ->> 'cf-connecting-ip',
    v_headers ->> 'x-forwarded-for',
    v_headers ->> 'x-real-ip',
    ''
  ), ',', 1)), 64);
  IF v_ip = '' THEN
    v_ip := NULL;
  ELSE
    BEGIN
      v_ip := host(v_ip::inet);
    EXCEPTION WHEN invalid_text_representation THEN
      v_ip := NULL;
    END;
  END IF;

  INSERT INTO public.login_attempts (
    email, ip_address, user_agent, success, failure_reason, created_at
  ) VALUES (
    v_email,
    v_ip,
    left(NULLIF(p_user_agent, ''), 500),
    true,
    NULL,
    now()
  );
END;
$function$
;

