 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE active_sessions
  SET 
    expires_at = NOW() + INTERVAL '24 hours',
