-- public.resolve_weekly_matchups()

CREATE OR REPLACE FUNCTION public.resolve_weekly_matchups()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_matchup record;
  v_score_a numeric;
  v_score_b numeric;
  v_finished integer := 0;
  v_week_end date;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('resolve_weekly_matchups', 0));

  FOR v_matchup IN
    SELECT id, salesperson_a_id, salesperson_b_id, week_start, xp_reward
    FROM public.weekly_matchups
    WHERE status = 'active'
  LOOP
    v_week_end := v_matchup.week_start + 7;

    SELECT COALESCE(sum(xp_amount), 0) INTO v_score_a
      FROM public.xp_history
     WHERE salesperson_id = v_matchup.salesperson_a_id
       AND created_at >= v_matchup.week_start
       AND created_at < v_week_end;

    SELECT COALESCE(sum(xp_amount), 0) INTO v_score_b
      FROM public.xp_history
     WHERE salesperson_id = v_matchup.salesperson_b_id
       AND created_at >= v_matchup.week_start
       AND created_at < v_week_end;

    IF v_week_end <= current_date THEN
      UPDATE public.weekly_matchups
         SET score_a = v_score_a,
             score_b = v_score_b,
             winner_id = CASE
               WHEN v_score_a > v_score_b THEN v_matchup.salesperson_a_id
               WHEN v_score_b > v_score_a THEN v_matchup.salesperson_b_id
               ELSE NULL
             END,
             status = 'finished'
       WHERE id = v_matchup.id;

      -- Empate não paga prêmio e winner_id fica NULL.
      IF v_score_a <> v_score_b THEN
        INSERT INTO public.xp_history (salesperson_id, xp_amount, source_type, source_id, description)
        VALUES (
          CASE WHEN v_score_a > v_score_b THEN v_matchup.salesperson_a_id
               ELSE v_matchup.salesperson_b_id END,
          v_matchup.xp_reward,
          'weekly_matchup',
          v_matchup.id::text,
          'Vitória no confronto semanal'
        );
      END IF;
      v_finished := v_finished + 1;
    ELSE
      -- Semana corrente: só atualiza o placar ao vivo do card.
      UPDATE public.weekly_matchups
         SET score_a = v_score_a, score_b = v_score_b
       WHERE id = v_matchup.id;
    END IF;
  END LOOP;

  RETURN v_finished;
END;
$function$
;

-- public.restore_deleted_record(p_table_name text, p_record_id uuid, p_user_id uuid)

CREATE OR REPLACE FUNCTION public.restore_deleted_record(p_table_name text, p_record_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sql text;
  v_affected integer;
BEGIN
  IF auth.role() <> 'service_role'
     AND (auth.uid() IS NULL OR NOT public.is_admin_or_manager(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF auth.role() <> 'service_role' AND p_user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'actor_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_table_name NOT IN ('clients', 'activities', 'products', 'suppliers', 'teams') THEN
    RAISE EXCEPTION 'unsupported_soft_delete_table' USING ERRCODE = '22023';
  END IF;

  v_sql := format(
    'UPDATE public.%I SET deleted_at = NULL, deleted_by = NULL, delete_reason = NULL WHERE id = $1 AND deleted_at IS NOT NULL',
    p_table_name
  );
  EXECUTE v_sql USING p_record_id;
  GET DIAGNOSTICS v_affected = ROW_COUNT;
  RETURN v_affected = 1;
END;
$function$
;

-- public.restore_record(table_name text, record_id uuid)

CREATE OR REPLACE FUNCTION public.restore_record(table_name text, record_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.role() <> 'service_role'
     AND (auth.uid() IS NULL OR NOT public.is_admin_or_manager(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF table_name NOT IN ('clients', 'activities', 'products', 'suppliers', 'teams') THEN
    RAISE EXCEPTION 'unsupported_soft_delete_table' USING ERRCODE = '22023';
  END IF;

  EXECUTE format(
    'UPDATE public.%I SET deleted_at = NULL, deleted_by = NULL, delete_reason = NULL WHERE id = $1 AND deleted_at IS NOT NULL',
    table_name
  ) USING record_id;
END;
$function$
;

-- public.route_unassigned_client_portfolio(p_client_id uuid, p_strategy text, p_salesperson_id uuid, p_reason text)

CREATE OR REPLACE FUNCTION public.route_unassigned_client_portfolio(p_client_id uuid, p_strategy text, p_salesperson_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS TABLE(portfolio_id uuid, assigned_to uuid, strategy_used text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing public.client_portfolio%ROWTYPE;
  v_target uuid;
  v_portfolio_id uuid;
  v_actor_salesperson_id uuid;
  v_strategy text := lower(trim(p_strategy));
  v_reason text;
BEGIN
  IF auth.role() <> 'service_role'
    AND (auth.uid() IS NULL OR NOT public.is_admin_or_manager(auth.uid())) THEN
    RAISE EXCEPTION 'Apenas administradores e gestores podem rotear clientes'
      USING ERRCODE = '42501';
  END IF;

  IF p_client_id IS NULL THEN
    RAISE EXCEPTION 'client_id é obrigatório' USING ERRCODE = '22023';
  END IF;

  IF v_strategy NOT IN ('manual', 'round_robin', 'least_loaded', 'top_performer') THEN
    RAISE EXCEPTION 'Estratégia de roteamento inválida: %', p_strategy
      USING ERRCODE = '22023';
  END IF;

  IF v_strategy = 'manual' AND p_salesperson_id IS NULL THEN
    RAISE EXCEPTION 'salesperson_id é obrigatório para atribuição manual'
      USING ERRCODE = '22023';
  END IF;

  -- Serializa tentativas concorrentes para o mesmo cliente, inclusive quando
  -- ainda não existe uma linha de carteira para bloquear com FOR UPDATE.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'route_unassigned_client_portfolio:' || p_client_id::text,
    0
  ));

  PERFORM 1 FROM public.clients WHERE id = p_client_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente não encontrado' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO v_existing
  FROM public.client_portfolio
  WHERE client_id = p_client_id
  ORDER BY assigned_at DESC, created_at DESC, id DESC
  LIMIT 1;

  -- Repetições do mesmo pedido são idempotentes. Uma tentativa manual para
  -- outro vendedor falha de forma explícita em vez de criar dupla carteira.
  IF FOUND THEN
    IF v_strategy = 'manual'
      AND p_salesperson_id IS DISTINCT FROM v_existing.salesperson_id THEN
      RAISE EXCEPTION 'Cliente já possui uma carteira; use o fluxo explícito de transferência'
        USING ERRCODE = 'P0001';
    END IF;

    RETURN QUERY
      SELECT v_existing.id,
             v_existing.salesperson_id,
             COALESCE(v_existing.source, 'already_assigned');
    RETURN;
  END IF;

  -- As estratégias que dependem da carga global precisam ser serializadas
  -- entre clientes distintos; sem isto duas requisições podem escolher o mesmo
  -- vendedor a partir da mesma fotografia de carga.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'route_unassigned_client_portfolio:strategy:' || v_strategy,
    0
  ));

  IF v_strategy = 'manual' THEN
    v_target := p_salesperson_id;
  ELSIF v_strategy = 'round_robin' THEN
    SELECT s.id
    INTO v_target
    FROM public.salespeople AS s
    LEFT JOIN public.client_portfolio AS cp ON cp.salesperson_id = s.id
    WHERE s.is_active IS TRUE
      AND s.role IN ('closer', 'hybrid')
    GROUP BY s.id
    ORDER BY MAX(cp.assigned_at) NULLS FIRST, s.id
    LIMIT 1;
  ELSIF v_strategy = 'least_loaded' THEN
    SELECT s.id
    INTO v_target
    FROM public.salespeople AS s
    LEFT JOIN public.client_portfolio AS cp ON cp.salesperson_id = s.id
    WHERE s.is_active IS TRUE
      AND s.role IN ('closer', 'hybrid')
    GROUP BY s.id
    ORDER BY COUNT(cp.id) FILTER (WHERE cp.status = 'active') ASC, s.id
    LIMIT 1;
  ELSIF v_strategy = 'top_performer' THEN
    SELECT s.id
    INTO v_target
    FROM public.salespeople AS s
    LEFT JOIN public.sales AS sa
      ON sa.salesperson_id = s.id
      AND sa.status IN ('completed', 'won', 'closed')
      AND sa.created_at >= date_trunc('month', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo'
    WHERE s.is_active IS TRUE
      AND s.role IN ('closer', 'hybrid')
    GROUP BY s.id
    ORDER BY COALESCE(SUM(sa.amount), 0) DESC, s.id
    LIMIT 1;
  END IF;

  IF v_target IS NULL THEN
    RAISE EXCEPTION 'Nenhum closer ou híbrido ativo está disponível para roteamento'
      USING ERRCODE = 'P0001';
  END IF;

  PERFORM 1
  FROM public.salespeople
  WHERE id = v_target
    AND is_active IS TRUE
    AND role IN ('closer', 'hybrid');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vendedor de destino inválido ou inativo'
      USING ERRCODE = '22023';
  END IF;

  v_actor_salesperson_id := public.get_current_salesperson_id();
  v_reason := COALESCE(
    NULLIF(left(trim(COALESCE(p_reason, '')), 500), ''),
    'Atribuição de carteira: ' || v_strategy
  );

  INSERT INTO public.client_portfolio (
    client_id,
    salesperson_id,
    assigned_by,
    source,
    status
  ) VALUES (
    p_client_id,
    v_target,
    v_actor_salesperson_id,
    v_strategy,
    'active'
  )
  RETURNING id INTO v_portfolio_id;

  INSERT INTO public.lead_routing_log (
    client_id,
    to_salesperson_id,
    routing_reason
  ) VALUES (
    p_client_id,
    v_target,
    v_reason
  );

  RETURN QUERY SELECT v_portfolio_id, v_target, v_strategy;
END;
$function$
;

-- public.schedule_next_qbrs()

CREATE OR REPLACE FUNCTION public.schedule_next_qbrs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _r RECORD;
  _interval interval;
  _count int := 0;
BEGIN
  FOR _r IN SELECT id, frequency, last_qbr_at FROM public.qbr_schedule WHERE is_active = true
  LOOP
    _interval := CASE _r.frequency
      WHEN 'monthly' THEN INTERVAL '30 days'
      WHEN 'quarterly' THEN INTERVAL '90 days'
      WHEN 'biannual' THEN INTERVAL '180 days'
      ELSE INTERVAL '365 days'
    END;
    UPDATE public.qbr_schedule
    SET next_qbr_at = COALESCE(_r.last_qbr_at, CURRENT_DATE) + _interval,
        updated_at = now()
    WHERE id = _r.id;
    _count := _count + 1;
  END LOOP;
  RETURN _count;
END;
$function$
;

-- public.search_call_library(_query text, _limit integer)

CREATE OR REPLACE FUNCTION public.search_call_library(_query text, _limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, title text, recorded_at timestamp with time zone, duration_seconds integer, salesperson_id uuid, status text, rank real, snippet text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  ts_query tsquery;
  uid UUID := auth.uid();
  is_priv BOOLEAN := public.has_role(uid, 'admin') OR public.has_role(uid, 'manager');
BEGIN
  IF _query IS NULL OR length(trim(_query)) = 0 THEN
    RETURN;
  END IF;

  ts_query := websearch_to_tsquery('portuguese', _query);

  RETURN QUERY
  SELECT
    cr.id,
    cr.title,
    cr.recorded_at,
    cr.duration_seconds,
    cr.salesperson_id,
    cr.status,
    ts_rank(cr.transcript_tsv, ts_query) AS rank,
    ts_headline(
      'portuguese',
      coalesce(cr.transcript, cr.summary, cr.title),
      ts_query,
      'MaxWords=30, MinWords=10, ShortWord=3, HighlightAll=FALSE, MaxFragments=2, FragmentDelimiter=" … "'
    ) AS snippet
  FROM public.call_recordings cr
  LEFT JOIN public.salespeople sp ON sp.id = cr.salesperson_id
  WHERE cr.transcript_tsv @@ ts_query
    AND (is_priv OR sp.auth_user_id = uid)
  ORDER BY rank DESC, cr.recorded_at DESC
  LIMIT greatest(1, least(_limit, 100));
END;
$function$
;

-- public.search_products_semantic(_keywords text[], _query text, _limit integer)

CREATE OR REPLACE FUNCTION public.search_products_semantic(_keywords text[], _query text DEFAULT NULL::text, _limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, name text, category text, price numeric, rating numeric, sales_count integer, status text, similarity_score real)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _combined text;
BEGIN
  _combined := trim(COALESCE(_query, '') || ' ' || array_to_string(COALESCE(_keywords, ARRAY[]::text[]), ' '));

  IF _combined = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.name,
    p.category,
    p.price,
    p.rating,
    p.sales_count,
    p.status,
    GREATEST(
      similarity(COALESCE(p.name, ''), _combined),
      similarity(COALESCE(p.category, ''), _combined) * 0.6
    )::real AS similarity_score
  FROM public.products p
  WHERE
    p.name % _combined
    OR p.category % _combined
    OR EXISTS (
      SELECT 1 FROM unnest(_keywords) AS kw
      WHERE p.name ILIKE '%' || kw || '%'
         OR p.category ILIKE '%' || kw || '%'
    )
  ORDER BY similarity_score DESC, p.sales_count DESC
  LIMIT _limit;
END;
$function$
;

-- public.search_products_vector(_query_embedding vector, _limit integer)

CREATE OR REPLACE FUNCTION public.search_products_vector(_query_embedding vector, _limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, name text, category text, price numeric, rating numeric, sales_count integer, status text, similarity_score real)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    p.id,
    p.name,
    p.category,
    p.price,
    p.rating,
    p.sales_count,
    p.status,
    (1 - (s.embedding <=> _query_embedding))::real AS similarity_score
  FROM public.semantic_index s
  JOIN public.products p ON s.entity_id = p.id
  WHERE s.entity_type = 'product'
  ORDER BY s.embedding <=> _query_embedding
  LIMIT _limit;
END;
$function$
;

-- public.send_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_category text, p_priority text, p_action_url text, p_action_label text, p_metadata jsonb)

CREATE OR REPLACE FUNCTION public.send_notification(p_user_id uuid, p_type text, p_title text, p_message text DEFAULT NULL::text, p_category text DEFAULT 'general'::text, p_priority text DEFAULT 'medium'::text, p_action_url text DEFAULT NULL::text, p_action_label text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  -- Allow if:
  -- 1. It is the user themselves (auth.uid() = p_user_id)
  -- 2. It is an admin or manager
  -- 3. It is the system / service role (auth.uid() is NULL when using service key)
  
  IF auth.uid() IS NOT NULL THEN
    IF auth.uid() != p_user_id AND NOT is_admin_or_manager(auth.uid()) THEN
      RAISE EXCEPTION 'Not authorized to send notification to other users';
    END IF;
  END IF;

  INSERT INTO public.notifications (
    user_id, type, title, message, category, 
    priority, action_url, action_label, metadata
  ) VALUES (
    p_user_id, p_type, p_title, p_message, p_category, 
    p_priority, p_action_url, p_action_label, p_metadata
  )
  RETURNING id INTO v_id;
  
  RETURN v_id;
END;
$function$
;

