-- public.soft_delete_record(p_table_name text, p_record_id uuid, p_user_id uuid, p_reason text)

CREATE OR REPLACE FUNCTION public.soft_delete_record(p_table_name text, p_record_id uuid, p_user_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sql text;
  v_actor uuid := auth.uid();
  v_affected integer;
BEGIN
  IF auth.role() <> 'service_role'
     AND (v_actor IS NULL OR NOT public.is_admin_or_manager(v_actor)) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF auth.role() <> 'service_role' AND p_user_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'actor_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_table_name NOT IN ('clients', 'activities', 'products', 'suppliers', 'teams') THEN
    RAISE EXCEPTION 'unsupported_soft_delete_table' USING ERRCODE = '22023';
  END IF;

  v_sql := format(
    'UPDATE public.%I SET deleted_at = now(), deleted_by = $1, delete_reason = $2 WHERE id = $3 AND deleted_at IS NULL',
    p_table_name
  );
  EXECUTE v_sql USING COALESCE(v_actor, p_user_id), left(p_reason, 500), p_record_id;
  GET DIAGNOSTICS v_affected = ROW_COUNT;
  RETURN v_affected = 1;
END;
$function$
;

-- public.spin_prize_wheel(p_request_id uuid)

CREATE OR REPLACE FUNCTION public.spin_prize_wheel(p_request_id uuid)
 RETURNS TABLE(id uuid, prize_type text, prize_value integer, prize_label text, trigger_type text, spun_at timestamp with time zone, prize_index integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_salesperson_id uuid;
  v_spins_count integer;
  v_roll integer;
  v_prize_type text;
  v_prize_value integer;
  v_prize_label text;
  v_prize_index integer;
  v_existing public.prize_wheel_spins%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória para girar a roda'
      USING ERRCODE = '28000';
  END IF;

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'Identificador idempotente obrigatório'
      USING ERRCODE = '22004';
  END IF;

  v_salesperson_id := public.get_current_salesperson_id();
  IF v_salesperson_id IS NULL THEN
    RAISE EXCEPTION 'Perfil comercial não encontrado para o usuário autenticado'
      USING ERRCODE = 'P0001';
  END IF;

  -- Retorna a tentativa já concluída sem consumir outro giro.
  SELECT *
    INTO v_existing
    FROM public.prize_wheel_spins
   WHERE salesperson_id = v_salesperson_id
     AND request_id = p_request_id;

  IF FOUND THEN
    RETURN QUERY
    SELECT
      v_existing.id,
      v_existing.prize_type,
      v_existing.prize_value,
      v_existing.prize_label,
      v_existing.trigger_type,
      v_existing.spun_at,
      CASE v_existing.prize_label
        WHEN '+50 XP' THEN 0
        WHEN '+100 XP' THEN 1
        WHEN '+200 XP' THEN 2
        WHEN '2x XP 1h' THEN 3
        WHEN 'Badge 🔥' THEN 4
        WHEN '+500 XP' THEN 5
        WHEN '+25 XP' THEN 6
        ELSE NULL
      END;
    RETURN;
  END IF;

  -- Serializa somente os giros do vendedor atual. Uma chamada concorrente
  -- aguarda o lock, relê a requisição idempotente e não pode gerar prêmio
  -- adicional para o mesmo request_id.
  SELECT spins_count
    INTO v_spins_count
    FROM public.available_spins
   WHERE salesperson_id = v_salesperson_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Nenhum giro disponível'
      USING ERRCODE = 'P0001';
  END IF;

  -- A segunda leitura ocorre depois do lock. Em READ COMMITTED, isso permite
  -- que uma chamada concorrente enxergue a gravação concluída pela primeira
  -- transação antes de decidir se ainda há saldo a consumir.
  SELECT *
    INTO v_existing
    FROM public.prize_wheel_spins
   WHERE salesperson_id = v_salesperson_id
     AND request_id = p_request_id;

  IF FOUND THEN
    RETURN QUERY
    SELECT
      v_existing.id,
      v_existing.prize_type,
      v_existing.prize_value,
      v_existing.prize_label,
      v_existing.trigger_type,
      v_existing.spun_at,
      CASE v_existing.prize_label
        WHEN '+50 XP' THEN 0
        WHEN '+100 XP' THEN 1
        WHEN '+200 XP' THEN 2
        WHEN '2x XP 1h' THEN 3
        WHEN 'Badge 🔥' THEN 4
        WHEN '+500 XP' THEN 5
        WHEN '+25 XP' THEN 6
        ELSE NULL
      END;
    RETURN;
  END IF;

  IF v_spins_count <= 0 THEN
    RAISE EXCEPTION 'Nenhum giro disponível'
      USING ERRCODE = 'P0001';
  END IF;

  v_roll := floor(random() * 100)::integer;
  CASE
    WHEN v_roll < 25 THEN
      v_prize_type := 'xp'; v_prize_value := 50; v_prize_label := '+50 XP'; v_prize_index := 0;
    WHEN v_roll < 45 THEN
      v_prize_type := 'xp'; v_prize_value := 100; v_prize_label := '+100 XP'; v_prize_index := 1;
    WHEN v_roll < 55 THEN
      v_prize_type := 'xp'; v_prize_value := 200; v_prize_label := '+200 XP'; v_prize_index := 2;
    WHEN v_roll < 70 THEN
      v_prize_type := 'power_up'; v_prize_value := 2; v_prize_label := '2x XP 1h'; v_prize_index := 3;
    WHEN v_roll < 80 THEN
      v_prize_type := 'badge'; v_prize_value := 1; v_prize_label := 'Badge 🔥'; v_prize_index := 4;
    WHEN v_roll < 85 THEN
      v_prize_type := 'xp'; v_prize_value := 500; v_prize_label := '+500 XP'; v_prize_index := 5;
    ELSE
      v_prize_type := 'xp'; v_prize_value := 25; v_prize_label := '+25 XP'; v_prize_index := 6;
  END CASE;

  UPDATE public.available_spins
     SET spins_count = spins_count - 1,
         updated_at = now()
   WHERE salesperson_id = v_salesperson_id;

  INSERT INTO public.prize_wheel_spins (
    salesperson_id,
    request_id,
    prize_type,
    prize_value,
    prize_label,
    trigger_type
  )
  VALUES (
    v_salesperson_id,
    p_request_id,
    v_prize_type,
    v_prize_value,
    v_prize_label,
    'mission'
  )
  RETURNING * INTO v_existing;

  -- Concede o prêmio anunciado. O giro só alcança este ponto uma vez por
  -- request_id (o caminho idempotente retorna antes), então a concessão é
  -- exatamente-uma-vez por spin registrado.
  IF v_prize_type = 'xp' THEN
    INSERT INTO public.xp_history (
      salesperson_id, xp_amount, source_type, source_id, description
    ) VALUES (
      v_salesperson_id, v_prize_value, 'prize_wheel', v_existing.id::text,
      'Roleta da Sorte: ' || v_prize_label
    );
  ELSIF v_prize_type = 'power_up' THEN
    INSERT INTO public.active_power_ups (
      salesperson_id, power_up_type, multiplier, expires_at, source
    ) VALUES (
      v_salesperson_id, 'xp_boost', v_prize_value,
      now() + interval '1 hour', 'prize_wheel'
    );
  ELSIF v_prize_type = 'badge' THEN
    PERFORM private.award_achievement_if_not_exists(
      v_salesperson_id, 'prize_wheel_fire'
    );
  END IF;

  RETURN QUERY
  SELECT
    v_existing.id,
    v_existing.prize_type,
    v_existing.prize_value,
    v_existing.prize_label,
    v_existing.trigger_type,
    v_existing.spun_at,
    v_prize_index;
END;
$function$
;

-- public.start_of_week(date_val date, start_day integer)

CREATE OR REPLACE FUNCTION public.start_of_week(date_val date, start_day integer DEFAULT 1)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
    RETURN date_val - (EXTRACT(DOW FROM date_val)::INT - start_day + 7) % 7;
END;
$function$
;

-- public.sync_battle_score()

CREATE OR REPLACE FUNCTION public.sync_battle_score()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE v_battle_id UUID; v_metric TEXT; v_score NUMERIC; BEGIN FOR v_battle_id, v_metric IN SELECT b.id, b.metric FROM public.sales_battles b JOIN public.battle_participants p ON p.battle_id = b.id WHERE b.status = 'active' AND p.salesperson_id = COALESCE(NEW.salesperson_id, OLD.salesperson_id) AND (b.starts_at <= NOW() AND b.ends_at >= NOW()) LOOP v_score := 0; IF v_metric = 'revenue' THEN SELECT COALESCE(SUM(amount), 0) INTO v_score FROM public.sales WHERE salesperson_id = COALESCE(NEW.salesperson_id, OLD.salesperson_id) AND (status = 'won' OR status = 'completed') AND created_at >= (SELECT starts_at FROM public.sales_battles WHERE id = v_battle_id); ELSIF v_metric = 'deals' THEN SELECT COUNT(*) INTO v_score FROM public.sales WHERE salesperson_id = COALESCE(NEW.salesperson_id, OLD.salesperson_id) AND (status = 'won' OR status = 'completed') AND created_at >= (SELECT starts_at FROM public.sales_battles WHERE id = v_battle_id); ELSIF v_metric = 'calls' THEN SELECT COUNT(*) INTO v_score FROM public.activities WHERE salesperson_id = COALESCE(NEW.salesperson_id, OLD.salesperson_id) AND activity_type = 'call' AND deleted_at IS NULL AND created_at >= (SELECT starts_at FROM public.sales_battles WHERE id = v_battle_id); ELSIF v_metric = 'meetings' THEN SELECT COUNT(*) INTO v_score FROM public.activities WHERE salesperson_id = COALESCE(NEW.salesperson_id, OLD.salesperson_id) AND activity_type = 'meeting' AND deleted_at IS NULL AND created_at >= (SELECT starts_at FROM public.sales_battles WHERE id = v_battle_id); END IF; UPDATE public.battle_participants SET current_score = v_score WHERE battle_id = v_battle_id AND salesperson_id = COALESCE(NEW.salesperson_id, OLD.salesperson_id); END LOOP; RETURN NEW; END; $function$
;

-- public.sync_challenge_progress(p_salesperson_id uuid)

CREATE OR REPLACE FUNCTION public.sync_challenge_progress(p_salesperson_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scope uuid[];
  v_sp uuid;
  v_challenge record;
  v_val integer;
  v_done boolean;
  v_upserts integer := 0;
BEGIN
  IF auth.uid() IS NOT NULL AND auth.role() <> 'service_role' THEN
    -- Cliente: só o próprio vendedor (admin/manager pode apontar outro).
    v_sp := public.get_current_salesperson_id();
    IF v_sp IS NULL THEN
      RAISE EXCEPTION 'Perfil comercial não encontrado' USING ERRCODE = 'P0001';
    END IF;
    IF p_salesperson_id IS NOT NULL
       AND p_salesperson_id <> v_sp
       AND NOT public.is_admin_or_manager(auth.uid()) THEN
      RAISE EXCEPTION 'forbidden: só o próprio progresso pode ser sincronizado';
    END IF;
    v_scope := ARRAY[COALESCE(p_salesperson_id, v_sp)];
  END IF;
  -- service_role / cron (auth.uid() NULL): p_salesperson_id NULL → todos.

  FOR v_sp IN
    SELECT id FROM public.salespeople
     WHERE v_scope IS NULL OR id = ANY (v_scope)
  LOOP
    -- Semanais: desafios ativos cuja janela cobre hoje.
    FOR v_challenge IN
      SELECT id, challenge_type, target_value, start_date, end_date
        FROM public.weekly_challenges
       WHERE is_active
         AND CURRENT_DATE BETWEEN start_date AND end_date
    LOOP
      v_val := public.compute_challenge_progress_value(
        v_sp, v_challenge.challenge_type, v_challenge.start_date, v_challenge.end_date);
      v_done := v_val >= v_challenge.target_value;

      INSERT INTO public.challenge_progress
        (challenge_id, salesperson_id, current_value, completed_at)
      VALUES (v_challenge.id, v_sp, v_val, CASE WHEN v_done THEN now() ELSE NULL END)
      ON CONFLICT (challenge_id, salesperson_id) DO UPDATE
        SET current_value = EXCLUDED.current_value,
            completed_at = COALESCE(
              challenge_progress.completed_at, EXCLUDED.completed_at),
            updated_at = now();

      v_upserts := v_upserts + 1;
    END LOOP;

    -- Diários: desafios ativos do dia.
    FOR v_challenge IN
      SELECT id, challenge_type, target_value, challenge_date
        FROM public.daily_challenges
       WHERE is_active
         AND challenge_date = CURRENT_DATE
    LOOP
      v_val := public.compute_challenge_progress_value(
        v_sp, v_challenge.challenge_type, v_challenge.challenge_date, v_challenge.challenge_date);
      v_done := v_val >= v_challenge.target_value;

      INSERT INTO public.daily_challenge_progress
        (challenge_id, salesperson_id, current_value, completed_at)
      VALUES (v_challenge.id, v_sp, v_val, CASE WHEN v_done THEN now() ELSE NULL END)
      ON CONFLICT (challenge_id, salesperson_id) DO UPDATE
        SET current_value = EXCLUDED.current_value,
            completed_at = COALESCE(
              daily_challenge_progress.completed_at, EXCLUDED.completed_at),
            updated_at = now();

      v_upserts := v_upserts + 1;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('synced', v_upserts);
END;
$function$
;

-- public.sync_combo_on_activity()

CREATE OR REPLACE FUNCTION public.sync_combo_on_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_date date;
BEGIN
  -- Atividade sem vendedor (importacao, automacao) nao gera combo.
  IF NEW.salesperson_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_date := (COALESCE(NEW.created_at, now()) AT TIME ZONE 'America/Sao_Paulo')::date;

  -- Uma escrita so: o incremento e a escada de tier saem juntos, sem janela
  -- de corrida entre duas atividades do mesmo vendedor no mesmo instante.
  -- Dentro do ON CONFLICT a linha existente e referenciada por
  -- `combo_tracking.<col>` (sem o schema, que o Postgres nao aceita aqui).
  INSERT INTO public.combo_tracking (
    salesperson_id, combo_date, actions_count, current_multiplier, current_tier, max_tier_today
  )
  VALUES (NEW.salesperson_id, v_date, 1, 1.0, 0, 0)
  ON CONFLICT (salesperson_id, combo_date) DO UPDATE
    SET actions_count = combo_tracking.actions_count + 1,
        current_tier = CASE
                         WHEN combo_tracking.actions_count + 1 >= 12 THEN 4
                         WHEN combo_tracking.actions_count + 1 >= 8  THEN 3
                         WHEN combo_tracking.actions_count + 1 >= 5  THEN 2
                         WHEN combo_tracking.actions_count + 1 >= 3  THEN 1
                         ELSE 0
                       END,
        current_multiplier = CASE
                               WHEN combo_tracking.actions_count + 1 >= 12 THEN 3.0
                               WHEN combo_tracking.actions_count + 1 >= 8  THEN 2.5
                               WHEN combo_tracking.actions_count + 1 >= 5  THEN 2.0
                               WHEN combo_tracking.actions_count + 1 >= 3  THEN 1.5
                               ELSE 1.0
                             END,
        max_tier_today = GREATEST(
                           combo_tracking.max_tier_today,
                           CASE
                             WHEN combo_tracking.actions_count + 1 >= 12 THEN 4
                             WHEN combo_tracking.actions_count + 1 >= 8  THEN 3
                             WHEN combo_tracking.actions_count + 1 >= 5  THEN 2
                             WHEN combo_tracking.actions_count + 1 >= 3  THEN 1
                             ELSE 0
                           END
                         ),
        updated_at = now();

  RETURN NEW;
END;
$function$
;

-- public.sync_performance_bets()

CREATE OR REPLACE FUNCTION public.sync_performance_bets()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_salesperson_id UUID;
BEGIN
    v_salesperson_id := COALESCE(NEW.salesperson_id, OLD.salesperson_id);

    -- Update active bets for this salesperson
    UPDATE public.performance_bets b
    SET current_value = (
        CASE 
            WHEN b.bet_type = 'deals' THEN (
                SELECT COUNT(*) FROM public.sales 
                WHERE salesperson_id = v_salesperson_id AND deal_status = 'completed' AND created_at >= b.starts_at AND created_at <= b.ends_at
            )
            WHEN b.bet_type = 'revenue' THEN (
                SELECT COALESCE(SUM(amount), 0) FROM public.sales 
                WHERE salesperson_id = v_salesperson_id AND deal_status = 'completed' AND created_at >= b.starts_at AND created_at <= b.ends_at
            )
            WHEN b.bet_type = 'calls' THEN (
                SELECT COUNT(*) FROM public.activities 
                WHERE salesperson_id = v_salesperson_id AND activity_type = 'call' AND created_at >= b.starts_at AND created_at <= b.ends_at AND deleted_at IS NULL
            )
            WHEN b.bet_type = 'meetings' THEN (
                SELECT COUNT(*) FROM public.activities 
                WHERE salesperson_id = v_salesperson_id AND activity_type = 'meeting' AND created_at >= b.starts_at AND created_at <= b.ends_at AND deleted_at IS NULL
            )
            WHEN b.bet_type = 'activities' THEN (
                SELECT COUNT(*) FROM public.activities 
                WHERE salesperson_id = v_salesperson_id AND created_at >= b.starts_at AND created_at <= b.ends_at AND deleted_at IS NULL
            )
            ELSE b.current_value
        END
    )
    WHERE b.status = 'active' AND b.salesperson_id = v_salesperson_id;

    RETURN NEW;
END;
$function$
;

-- public.sync_quote_from_webhook(p_external_quote_id text, p_quote_number text, p_title text, p_description text, p_client_name text, p_client_email text, p_client_phone text, p_seller_name text, p_external_seller_id text, p_status text, p_pipeline_status text, p_total_value numeric, p_subtotal numeric, p_discount_percent numeric, p_discount_amount numeric, p_items jsonb, p_valid_until timestamp with time zone, p_notes text, p_sent_at timestamp with time zone, p_approved_at timestamp with time zone, p_rejected_at timestamp with time zone, p_quote_created_at timestamp with time zone, p_sale_product_name text)

CREATE OR REPLACE FUNCTION public.sync_quote_from_webhook(p_external_quote_id text, p_quote_number text, p_title text, p_description text, p_client_name text, p_client_email text, p_client_phone text, p_seller_name text, p_external_seller_id text, p_status text, p_pipeline_status text, p_total_value numeric, p_subtotal numeric, p_discount_percent numeric, p_discount_amount numeric, p_items jsonb, p_valid_until timestamp with time zone, p_notes text, p_sent_at timestamp with time zone, p_approved_at timestamp with time zone, p_rejected_at timestamp with time zone, p_quote_created_at timestamp with time zone, p_sale_product_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_client_id         uuid;
  v_salesperson_id    uuid;
  v_quote_id          uuid;
  v_sale_id           uuid;
  v_quote_inserted    boolean := false;
  v_now               timestamptz := now();
  v_items_sem_produto int := 0;
BEGIN
  -- 1) Upsert de cliente — mesmo helper que a edge function chamava via RPC
  IF p_client_email IS NOT NULL OR p_client_phone IS NOT NULL THEN
    v_client_id := public.upsert_client_from_quote(
      p_client_name, p_client_email, p_client_phone, NULL
    );
  END IF;

  -- 2) Vendedor externo → salesperson interno (external_seller_map)
  IF p_external_seller_id IS NOT NULL THEN
    SELECT salesperson_id INTO v_salesperson_id
    FROM public.external_seller_map
    WHERE external_source = 'gift_store'
      AND external_id = p_external_seller_id;
  END IF;

  -- 3) Quote existente — FOR UPDATE serializa retries concorrentes do mesmo
  --    external_quote_id dentro da transação
  SELECT id, sale_id INTO v_quote_id, v_sale_id
  FROM public.quotes
  WHERE external_quote_id = p_external_quote_id
  LIMIT 1
  FOR UPDATE;

  IF v_quote_id IS NULL THEN
    BEGIN
      INSERT INTO public.quotes (
        client_name, client_email, client_phone, seller_name,
        external_seller_id, client_id, created_by, title, description,
        total_value, status, external_reference, external_quote_id,
        quote_number, subtotal, discount_percent, discount_amount,
        items, valid_until, notes, source, synced_from_external,
        sync_status, last_synced_at, sent_at, approved_at, rejected_at,
        created_at, updated_at
      ) VALUES (
        p_client_name, p_client_email, p_client_phone, p_seller_name,
        p_external_seller_id, v_client_id, v_salesperson_id, p_title,
        p_description, p_total_value, p_status, p_quote_number,
        p_external_quote_id, p_quote_number, p_subtotal,
        p_discount_percent, p_discount_amount, p_items, p_valid_until,
        p_notes, 'gift_store', true, 'synced', v_now,
        p_sent_at, p_approved_at, p_rejected_at,
        COALESCE(p_quote_created_at, v_now), v_now
      )
      RETURNING id INTO v_quote_id;
      v_quote_inserted := true;
    EXCEPTION WHEN unique_violation THEN
      -- Dois webhooks concorrentes criando o mesmo external_quote_id:
      -- cai no caminho de update em vez de estourar 23505.
      SELECT id, sale_id INTO v_quote_id, v_sale_id
      FROM public.quotes
      WHERE external_quote_id = p_external_quote_id
      LIMIT 1
      FOR UPDATE;
    END;
  END IF;

  IF NOT v_quote_inserted THEN
    UPDATE public.quotes SET
      client_name          = p_client_name,
      client_email         = p_client_email,
      client_phone         = p_client_phone,
      seller_name          = p_seller_name,
      external_seller_id   = p_external_seller_id,
      client_id            = v_client_id,
      created_by           = v_salesperson_id,
      title                = p_title,
      description          = p_description,
      total_value          = p_total_value,
      status               = p_status,
      external_reference   = p_quote_number,
      quote_number         = p_quote_number,
      subtotal             = p_subtotal,
      discount_percent     = p_discount_percent,
      discount_amount      = p_discount_amount,
      items                = p_items,
      valid_until          = p_valid_until,
      notes                = p_notes,
      source               = 'gift_store',
      synced_from_external = true,
      sync_status          = 'synced',
      last_synced_at       = v_now,
      sent_at              = COALESCE(p_sent_at, sent_at),
      approved_at          = COALESCE(p_approved_at, approved_at),
      rejected_at          = COALESCE(p_rejected_at, rejected_at),
      updated_at           = v_now
    WHERE id = v_quote_id;
  END IF;

  -- 4) Substituição atômica dos itens normalizados (delete + insert na mesma
  --    transação — antes eram duas chamadas PostgREST independentes)
  IF p_items IS NOT NULL
     AND jsonb_typeof(p_items) = 'array'
     AND jsonb_array_length(p_items) > 0 THEN
    DELETE FROM public.quote_items WHERE quote_id = v_quote_id;

    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, quantity, unit_price,
      discount_amount, total_price
    )
    SELECT
      v_quote_id,
      prod.id,
      it.item->>'product_name',
      ROUND((it.item->>'quantity')::numeric)::int,
      (it.item->>'unit_price')::numeric,
      0,
      COALESCE(
        (it.item->>'subtotal')::numeric,
        (it.item->>'quantity')::numeric * (it.item->>'unit_price')::numeric
      )
    FROM jsonb_array_elements(p_items) AS it(item)
    LEFT JOIN public.products AS prod
      ON prod.id::text = it.item->>'product_id';

    -- Observabilidade: itens cujo product_id externo não existe em products
    SELECT COUNT(*) INTO v_items_sem_produto
    FROM jsonb_array_elements(p_items) AS it(item)
    LEFT JOIN public.products AS prod
      ON prod.id::text = it.item->>'product_id'
    WHERE NULLIF(it.item->>'product_id', '') IS NOT NULL
      AND prod.id IS NULL;
  END IF;

  -- 5) Pipeline (sales) + vínculo sale_id no quote
  IF v_sale_id IS NOT NULL THEN
    UPDATE public.sales SET
      client_name    = p_client_name,
      product_name   = p_sale_product_name,
      amount         = p_total_value,
      status         = p_pipeline_status,
      client_id      = v_client_id,
      salesperson_id = v_salesperson_id,
      updated_at     = v_now
    WHERE id = v_sale_id;
  ELSE
    INSERT INTO public.sales (
      client_name, product_name, amount, status, category,
      client_id, salesperson_id, source, created_at
    ) VALUES (
      p_client_name, p_sale_product_name, p_total_value, p_pipeline_status,
      'brindes', v_client_id, v_salesperson_id, 'gift_store',
      COALESCE(p_quote_created_at, v_now)
    )
    RETURNING id INTO v_sale_id;

    UPDATE public.quotes SET sale_id = v_sale_id WHERE id = v_quote_id;
  END IF;

  RETURN jsonb_build_object(
    'quote_id',          v_quote_id,
    'sale_id',           v_sale_id,
    'client_id',         v_client_id,
    'salesperson_id',    v_salesperson_id,
    'itens_sem_produto', v_items_sem_produto
  );
END;
$function$
;

-- public.sync_quote_to_sale_status()

CREATE OR REPLACE FUNCTION public.sync_quote_to_sale_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pipeline_status TEXT;
  v_current_sale_status TEXT;
BEGIN
  IF NEW.sale_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Read the current sale status to decide whether to allow sync
  SELECT status INTO v_current_sale_status
  FROM public.sales
  WHERE id = NEW.sale_id;

  -- Terminal states must never be overwritten by a quote status change
  IF v_current_sale_status IN ('won', 'completed', 'cancelled') THEN
    RETURN NEW;
  END IF;

  v_pipeline_status := CASE
    WHEN NEW.status = 'draft'    THEN 'lead'
    WHEN NEW.status = 'sent'     THEN 'proposal'
    WHEN NEW.status = 'approved' THEN 'closed'
    WHEN NEW.status = 'rejected' THEN 'cancelled'
    WHEN NEW.status = 'expired'  THEN 'cancelled'
    ELSE v_current_sale_status  -- unknown quote status → leave sale status unchanged
  END;

  -- Only write when the status actually needs to change
  IF v_pipeline_status IS DISTINCT FROM v_current_sale_status THEN
    UPDATE public.sales
    SET
      status     = v_pipeline_status,
      amount     = NEW.total_value,
      updated_at = now()
    WHERE id = NEW.sale_id;
  ELSE
    -- Status unchanged — still sync the amount
    UPDATE public.sales
    SET
      amount     = NEW.total_value,
      updated_at = now()
    WHERE id = NEW.sale_id;
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.sync_territory_ownership()

CREATE OR REPLACE FUNCTION public.sync_territory_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_territory_name TEXT;
  v_territory_id UUID;
  v_current_owner UUID;
  v_new_owner UUID;
  v_total_rev NUMERIC;
  v_total_deals INTEGER;
BEGIN
  BEGIN
    v_territory_name := COALESCE(NEW.product_name, NEW.category, 'Outros');

    INSERT INTO public.territories (name) VALUES (v_territory_name)
    ON CONFLICT (name) DO NOTHING;

    SELECT salesperson_id, SUM(amount), COUNT(*)
      INTO v_new_owner, v_total_rev, v_total_deals
      FROM public.sales
     WHERE (product_name = v_territory_name OR (product_name IS NULL AND category = v_territory_name))
       AND deal_status = 'completed'
     GROUP BY salesperson_id
     ORDER BY SUM(amount) DESC LIMIT 1;

    SELECT current_owner_id INTO v_current_owner
      FROM public.territories WHERE name = v_territory_name;

    -- territory_history.territory_id referencia sales_territories(id) — resolver antes.
    SELECT id INTO v_territory_id
      FROM public.sales_territories WHERE name = v_territory_name LIMIT 1;

    IF v_new_owner IS DISTINCT FROM v_current_owner THEN
      IF v_current_owner IS NOT NULL AND v_territory_id IS NOT NULL THEN
        UPDATE public.territory_history
           SET lost_at = NOW()
         WHERE salesperson_id = v_current_owner AND lost_at IS NULL
           AND territory_id = v_territory_id;
      END IF;

      IF v_territory_id IS NOT NULL AND v_new_owner IS NOT NULL THEN
        INSERT INTO public.territory_history
          (territory_id, salesperson_id, revenue_contribution, deals_count, conquered_at)
        VALUES (v_territory_id, v_new_owner, v_total_rev, v_total_deals, NOW());
      END IF;

      UPDATE public.territories
         SET current_owner_id = v_new_owner,
             total_revenue = v_total_rev, total_deals = v_total_deals,
             conquered_at = NOW(), updated_at = NOW()
       WHERE name = v_territory_name;

      IF v_new_owner IS NOT NULL THEN
        INSERT INTO public.victory_feed (salesperson_id, title, description, type, metadata)
        VALUES (v_new_owner, 'Território Conquistado: '||v_territory_name,
                'Dominou o segmento com R$ '||v_total_rev::TEXT, 'territory',
                jsonb_build_object('territory',v_territory_name,'revenue',v_total_rev));
      END IF;
    ELSE
      UPDATE public.territories
         SET total_revenue = v_total_rev, total_deals = v_total_deals, updated_at = NOW()
       WHERE name = v_territory_name;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Nunca bloquear uma venda por causa do sync de território
    NULL;
  END;
  RETURN NEW;
END;
$function$
;

-- public.sync_total_xp()

CREATE OR REPLACE FUNCTION public.sync_total_xp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    INSERT INTO public.salesperson_xp (salesperson_id, total_xp, updated_at)
    VALUES (NEW.salesperson_id, NEW.xp_amount, now())
    ON CONFLICT (salesperson_id) 
    DO UPDATE SET 
        total_xp = salesperson_xp.total_xp + NEW.xp_amount,
        updated_at = now();
    RETURN NEW;
END;
$function$
;

