-- public.track_bulk_draft_recovery()

CREATE OR REPLACE FUNCTION public.track_bulk_draft_recovery()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Preserva a última mensagem real de falha (marcadores operacionais são ignorados)
  IF NEW.error IS NOT NULL
     AND btrim(NEW.error) <> ''
     AND NEW.error NOT IN ('manual_retry_requested') THEN
    NEW.last_error_message := NEW.error;
  END IF;

  -- Marca recuperação quando um rascunho que já falhou passa a ser enviado
  IF NEW.sent_at IS NOT NULL
     AND OLD.sent_at IS NULL
     AND NEW.recovered_at IS NULL
     AND (OLD.retry_count > 0 OR OLD.error IS NOT NULL OR OLD.last_error_message IS NOT NULL) THEN
    NEW.recovered_at := NEW.sent_at;
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.transition_commission_status(p_commission_id uuid, p_new_status text, p_actor uuid, p_payment_notes text)

CREATE OR REPLACE FUNCTION public.transition_commission_status(p_commission_id uuid, p_new_status text, p_actor uuid DEFAULT NULL::uuid, p_payment_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current text;
BEGIN
  SELECT status INTO v_current
    FROM public.commissions
    WHERE id = p_commission_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Comissão não encontrada: %', p_commission_id;
  END IF;

  -- SECURITY DEFINER ignora RLS: replica a regra das policies de commissions
  -- (somente admin/manager modifica; vendedor só lê as próprias). Chamadas
  -- via service_role ou pg_cron (auth.uid() IS NULL) seguem autorizadas.
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF v_current IS DISTINCT FROM p_new_status
     AND NOT public.is_valid_status_transition('commissions', v_current, p_new_status) THEN
    RAISE EXCEPTION 'Transição de status inválida em commissions: % → %',
      v_current, p_new_status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.commissions
    SET status        = p_new_status,
        approved_at   = CASE WHEN p_new_status = 'approved' THEN now() ELSE approved_at END,
        approved_by   = CASE WHEN p_new_status = 'approved' THEN COALESCE(p_actor, approved_by) ELSE approved_by END,
        paid_at       = CASE WHEN p_new_status = 'paid' THEN now() ELSE paid_at END,
        paid_by       = CASE WHEN p_new_status = 'paid' THEN COALESCE(p_actor, paid_by) ELSE paid_by END,
        payment_notes = CASE WHEN p_new_status = 'paid' THEN COALESCE(p_payment_notes, payment_notes) ELSE payment_notes END,
        updated_at    = now()
    WHERE id = p_commission_id;
END;
$function$
;

-- public.transition_sale_status(p_sale_id uuid, p_new_status text, p_pipeline_id uuid, p_expected_version integer)

CREATE OR REPLACE FUNCTION public.transition_sale_status(p_sale_id uuid, p_new_status text, p_pipeline_id uuid DEFAULT NULL::uuid, p_expected_version integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_current text;
  v_version integer;
  v_owner   uuid;
  v_closer  uuid;
  v_caller  uuid;
BEGIN
  SELECT status, version, salesperson_id, closer_id INTO v_current, v_version, v_owner, v_closer
    FROM public.sales
    WHERE id = p_sale_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venda não encontrada: %', p_sale_id;
  END IF;

  -- SECURITY DEFINER ignora RLS: replica a regra das policies de UPDATE em
  -- sales (dono da venda, closer atribuído ou admin/manager). Chamadas via
  -- service_role ou pg_cron (auth.uid() IS NULL) seguem autorizadas.
  -- O chamador precisa ter salespeople.id próprio: sem ele, IS DISTINCT FROM
  -- com NULLs dos dois lados passaria sem checar nada (NULL não é distinto de
  -- NULL), autorizando qualquer usuário logado sem vínculo com a venda.
  v_caller := public.get_current_salesperson_id();
  IF auth.uid() IS NOT NULL
     AND NOT public.is_admin_or_manager(auth.uid())
     AND (v_caller IS NULL
          OR (v_owner IS DISTINCT FROM v_caller
              AND v_closer IS DISTINCT FROM v_caller)) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'insufficient_privilege';
  END IF;

  IF p_expected_version IS NOT NULL
     AND v_version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'optimistic_lock_conflict: versão esperada %, versão atual %',
      p_expected_version, v_version;
  END IF;

  IF v_current IS DISTINCT FROM p_new_status
     AND NOT public.is_valid_status_transition('sales', v_current, p_new_status) THEN
    RAISE EXCEPTION 'Transição de status inválida em sales: % → %',
      v_current, p_new_status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.sales
    SET status      = p_new_status,
        pipeline_id = COALESCE(p_pipeline_id, pipeline_id),
        updated_at  = now()
    WHERE id = p_sale_id;
END;
$function$
;

-- public.trg_deal_stage_history()

CREATE OR REPLACE FUNCTION public.trg_deal_stage_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS NOT NULL THEN
      INSERT INTO public.deal_stage_history (sale_id, stage, entered_at)
      SELECT NEW.id, NEW.status::text, COALESCE(NEW.created_at, now())
      WHERE NOT EXISTS (
        SELECT 1 FROM public.deal_stage_history h
        WHERE h.sale_id = NEW.id
          AND h.stage = NEW.status::text
          AND h.entered_at = COALESCE(NEW.created_at, now())
      );
    END IF;
    RETURN NEW;
  END IF;

  -- Guarda NULL: sem ela, UPDATE status→NULL inseria stage NULL e a
  -- violação de NOT NULL revertia o UPDATE inteiro da venda.
  IF TG_OP = 'UPDATE'
     AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.status IS NOT NULL THEN
    UPDATE public.deal_stage_history
       SET exited_at = now()
     WHERE sale_id = NEW.id AND exited_at IS NULL;

    INSERT INTO public.deal_stage_history (sale_id, stage, entered_at)
    VALUES (NEW.id, NEW.status::text, now());
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.trg_invalidate_forecast_narrative_cache()

CREATE OR REPLACE FUNCTION public.trg_invalidate_forecast_narrative_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND (
       NEW.commit_amount    IS DISTINCT FROM OLD.commit_amount
    OR NEW.best_case_amount IS DISTINCT FROM OLD.best_case_amount
    OR NEW.upside_amount    IS DISTINCT FROM OLD.upside_amount
    OR NEW.weighted_pipeline IS DISTINCT FROM OLD.weighted_pipeline
    OR NEW.goal_amount      IS DISTINCT FROM OLD.goal_amount
    OR NEW.deals_count      IS DISTINCT FROM OLD.deals_count
    OR NEW.confidence_score IS DISTINCT FROM OLD.confidence_score
    OR NEW.factors::text    IS DISTINCT FROM OLD.factors::text
  ) THEN
    DELETE FROM public.ai_narrative_cache
     WHERE narrative_type = 'forecast-narrative'
       AND cache_key LIKE 'forecast-narrative:' || NEW.id::text || ':%';
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.trg_process_email_tracking_event()

CREATE OR REPLACE FUNCTION public.trg_process_email_tracking_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_prospect_id UUID;
    v_intent_type TEXT;
BEGIN
    -- Map event types
    IF NEW.event_type = 'open' THEN
        v_intent_type := 'email_open';
    ELSIF NEW.event_type = 'click' THEN
        -- Check if it's a price click
        IF NEW.metadata->>'url' LIKE '%price%' OR NEW.metadata->>'url' LIKE '%preco%' THEN
            v_intent_type := 'price_click';
        ELSE
            v_intent_type := 'email_open';
        END IF;
    ELSE
        RETURN NEW;
    END IF;

    -- Find the active prospect cadence for this sale
    SELECT id INTO v_prospect_id
    FROM public.prospect_cadences
    WHERE sale_id = NEW.sale_id
      AND status = 'active'
    LIMIT 1;

    -- If found, process the intent
    IF v_prospect_id IS NOT NULL THEN
        PERFORM public.process_lead_intent_event(
            v_prospect_id,
            v_intent_type,
            jsonb_build_object(
                'source', 'email_tracking',
                'event_id', NEW.id,
                'metadata', NEW.metadata
            )
        );
    END IF;

    RETURN NEW;
END;
$function$
;

-- public.trg_recording_generate_coaching()

CREATE OR REPLACE FUNCTION public.trg_recording_generate_coaching()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _secret text;
  _base_url text;
  _has_transcript boolean;
BEGIN
  _has_transcript := (
    (TG_OP = 'INSERT' AND NEW.transcript IS NOT NULL AND length(NEW.transcript) > 40)
    OR
    (TG_OP = 'UPDATE' AND NEW.transcript IS NOT NULL AND length(NEW.transcript) > 40
      AND (OLD.transcript IS NULL OR OLD.transcript IS DISTINCT FROM NEW.transcript))
  );
  IF NOT _has_transcript THEN
    RETURN NEW;
  END IF;

  SELECT value INTO _secret   FROM public._internal_secrets WHERE key = 'coaching_cron_secret';
  SELECT value INTO _base_url FROM public._internal_secrets WHERE key = 'functions_base_url';

  IF _secret IS NULL THEN
    RAISE WARNING 'coaching_cron_secret not set — skipping AI coaching dispatch for recording %', NEW.id;
    RETURN NEW;
  END IF;

  PERFORM net.http_post(
    url := _base_url || '/generate-coaching-actions',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Cron-Secret', _secret
    ),
    body := jsonb_build_object('recording_id', NEW.id)
  );
  RETURN NEW;
END;
$function$
;

