-- public.trg_sales_stamp_closed_at()

CREATE OR REPLACE FUNCTION public.trg_sales_stamp_closed_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.status IN ('completed', 'won', 'closed', 'lost', 'cancelled')
     AND NEW.status NOT IN ('completed', 'won', 'closed', 'lost', 'cancelled') THEN
    NEW.closed_at := NULL;
  END IF;

  IF NEW.status IN ('completed', 'won', 'closed')
     AND NEW.closed_at IS NULL
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    NEW.closed_at := now();
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.trigger_auto_coaching_on_recording()

CREATE OR REPLACE FUNCTION public.trigger_auto_coaching_on_recording()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_secret text;
  v_anon_key text;
  v_base_url text;
  v_request_id bigint;
BEGIN
  IF NEW.summarized_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.summarized_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF (NEW.transcript IS NULL OR length(trim(NEW.transcript)) < 40)
     AND (NEW.summary IS NULL OR length(trim(NEW.summary)) < 40) THEN
    RETURN NEW;
  END IF;

  IF NEW.salesperson_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT value INTO v_secret   FROM public._internal_secrets WHERE key = 'coaching_cron_secret';
  SELECT value INTO v_anon_key FROM public._internal_secrets WHERE key = 'anon_key';
  SELECT value INTO v_base_url FROM public._internal_secrets WHERE key = 'functions_base_url';

  IF v_secret IS NULL THEN
    RAISE WARNING 'auto_coaching: coaching_cron_secret ausente';
    RETURN NEW;
  END IF;

  SELECT net.http_post(
    url := v_base_url || '/generate-coaching-actions',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_anon_key,
      'X-Cron-Secret', v_secret
    ),
    body := jsonb_build_object('recording_id', NEW.id::text),
    timeout_milliseconds := 30000
  ) INTO v_request_id;

  BEGIN
    INSERT INTO public.activity_audit_logs (event_type, entity_type, entity_id, metadata)
    VALUES (
      'auto_coaching_triggered',
      'call_recording',
      NEW.id,
      jsonb_build_object('request_id', v_request_id, 'salesperson_id', NEW.salesperson_id)
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN NEW;
END;
$function$
;

-- public.trigger_campaign_health_alert()

CREATE OR REPLACE FUNCTION public.trigger_campaign_health_alert()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
DECLARE
  v_base_url text;
  v_anon_key text;
  v_cron_secret text;
BEGIN
  SELECT
    max(s.value) FILTER (WHERE s.key = 'functions_base_url'),
    max(s.value) FILTER (WHERE s.key = 'anon_key'),
    max(s.value) FILTER (WHERE s.key = 'coaching_cron_secret')
  INTO v_base_url, v_anon_key, v_cron_secret
  FROM public._internal_secrets AS s;

  IF v_base_url IS NULL OR v_anon_key IS NULL OR v_cron_secret IS NULL THEN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('trigger_campaign_health_alert', 'campaign-health-alert',
            '{}'::jsonb, 'internal_edge_secrets_missing');
    RETURN;
  END IF;
  IF v_base_url !~ '^https://[^[:space:]]+$' THEN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('trigger_campaign_health_alert', 'campaign-health-alert',
            '{}'::jsonb, 'internal_edge_base_url_must_be_https');
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := rtrim(v_base_url, '/') || '/campaign-health-alert',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_anon_key,
      'Authorization', 'Bearer ' || v_anon_key,
      'X-Cron-Secret', v_cron_secret
    ),
    body := jsonb_build_object('scheduled_at', now())
  );
EXCEPTION WHEN OTHERS THEN
  BEGIN
    INSERT INTO public.edge_call_failures (function_name, target_function, context, error_message)
    VALUES ('trigger_campaign_health_alert', 'campaign-health-alert',
            '{}'::jsonb, SQLERRM);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RAISE WARNING 'trigger_campaign_health_alert failed: %', SQLERRM;
END;
$function$
;

