-- public.trigger_internal_edge_job(p_function_name text)

CREATE OR REPLACE FUNCTION public.trigger_internal_edge_job(p_function_name text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net'
AS $function$
DECLARE
  v_base_url text;
  v_anon_key text;
  v_cron_secret text;
  v_request_id bigint;
BEGIN
  IF p_function_name IS NULL OR NOT (
    p_function_name = ANY (ARRAY[
      -- operacionais pré-existentes
      'notify-v4-quote-status',
      'check-v4-callback-alerts',
      'cron-failure-alerter',
      'process-call-recording-ingest',
      'edge-retry-threshold-alert',
      'deal-risk-digest',
      'email-bulk-retry',
      'wal-health-alert',
      'winloss-webhook-health-monitor',
      'webvitals-regression-alert',
      -- máquina de vendas (Onda 1)
      'sequence-runner',
      'process-cadence-tasks',
      'process-scheduled-sends',
      'check-quote-expiration',
      'check-lead-sla',
      'sdr-consecutive-alerts',
      'activity-goal-alerts',
      'challenge-expiration-alerts',
      'send-alert-notifications',
      'auto-reassign-inactive',
      'access-denied-alerts',
      'scheduled-reports-runner',
      -- gamificação (Onda B)
      'rotate-daily-challenges',
      -- integração Bitrix24
      'bitrix24-sync'
    ]::text[])
  ) THEN
    RAISE EXCEPTION 'internal_edge_job_not_allowed';
  END IF;

  SELECT
    max(s.value) FILTER (WHERE s.key = 'functions_base_url'),
    max(s.value) FILTER (WHERE s.key = 'anon_key'),
    max(s.value) FILTER (WHERE s.key = 'coaching_cron_secret')
  INTO v_base_url, v_anon_key, v_cron_secret
  FROM public._internal_secrets AS s;

  IF v_base_url IS NULL OR v_anon_key IS NULL OR v_cron_secret IS NULL THEN
    RAISE EXCEPTION 'internal_edge_job_secrets_missing';
  END IF;
  IF v_base_url !~ '^https://[^[:space:]]+$' THEN
    RAISE EXCEPTION 'internal_edge_job_base_url_must_be_https';
  END IF;

  SELECT net.http_post(
    url := rtrim(v_base_url, '/') || '/' || p_function_name,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_anon_key,
      'Authorization', 'Bearer ' || v_anon_key,
      'X-Cron-Secret', v_cron_secret
    ),
    body := jsonb_build_object('scheduled_at', now())
  )
  INTO v_request_id;

  RETURN v_request_id;
END;
$function$
;

-- public.try_edge_job_lock(_job_name text, _ttl_seconds integer, _request_id text)

CREATE OR REPLACE FUNCTION public.try_edge_job_lock(_job_name text, _ttl_seconds integer, _request_id text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_acquired integer;
BEGIN
  INSERT INTO public.edge_job_locks (job_name, locked_at, request_id)
  VALUES (_job_name, now(), _request_id)
  ON CONFLICT (job_name) DO UPDATE
    SET locked_at = now(),
        request_id = EXCLUDED.request_id
    WHERE edge_job_locks.locked_at < now() - make_interval(secs => _ttl_seconds);
  GET DIAGNOSTICS v_acquired = ROW_COUNT;
  RETURN v_acquired > 0;
END;
$function$
;

-- public.unlock_race_item(_unlock_key text, _required_league text)

CREATE OR REPLACE FUNCTION public.unlock_race_item(_unlock_key text, _required_league text DEFAULT 'bronze'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE _user_id uuid := auth.uid(); _user_league text; _league_order int; _required_order int; BEGIN IF _user_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'unauthenticated'); END IF; _user_league := 'bronze'; _league_order := CASE _user_league WHEN 'bronze' THEN 1 WHEN 'prata' THEN 2 WHEN 'ouro' THEN 3 WHEN 'platina' THEN 4 WHEN 'diamante' THEN 5 ELSE 1 END; _required_order := CASE _required_league WHEN 'bronze' THEN 1 WHEN 'prata' THEN 2 WHEN 'ouro' THEN 3 WHEN 'platina' THEN 4 WHEN 'diamante' THEN 5 ELSE 1 END; IF _league_order < _required_order THEN RETURN jsonb_build_object('success', false, 'error', 'league_required', 'current_league', _user_league, 'required_league', _required_league); END IF; INSERT INTO public.race_unlocks (user_id, unlock_key) VALUES (_user_id, _unlock_key) ON CONFLICT (user_id, unlock_key) DO NOTHING; RETURN jsonb_build_object('success', true, 'unlock_key', _unlock_key); END; $function$
;

