-- public.update_call_recording_diarization(_id uuid, _diarization jsonb, _talk_ratio_seller numeric, _talk_ratio_client numeric, _longest_monologue_sec integer, _interruptions_count integer, _turns_count integer)

CREATE OR REPLACE FUNCTION public.update_call_recording_diarization(_id uuid, _diarization jsonb, _talk_ratio_seller numeric, _talk_ratio_client numeric, _longest_monologue_sec integer, _interruptions_count integer, _turns_count integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _sp uuid;
  _owner uuid;
BEGIN
  SELECT salesperson_id INTO _owner FROM public.call_recordings WHERE id = _id;
  IF _owner IS NULL THEN
    RAISE EXCEPTION 'Recording not found';
  END IF;

  SELECT public.get_current_salesperson_id() INTO _sp;
  IF _sp IS NULL OR _sp <> _owner THEN
    -- allow admins
    IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
      RAISE EXCEPTION 'Not authorized';
    END IF;
  END IF;

  UPDATE public.call_recordings
  SET diarization = _diarization,
      talk_ratio_seller = _talk_ratio_seller,
      talk_ratio_client = _talk_ratio_client,
      longest_monologue_sec = _longest_monologue_sec,
      interruptions_count = _interruptions_count,
      turns_count = _turns_count,
      diarized_at = now(),
      updated_at = now()
  WHERE id = _id;
END;
$function$
;

-- public.update_call_recording_summary(_recording_id uuid, _summary text, _action_items jsonb, _decisions jsonb, _objections jsonb, _next_steps jsonb, _key_topics text[], _sentiment text)

CREATE OR REPLACE FUNCTION public.update_call_recording_summary(_recording_id uuid, _summary text, _action_items jsonb, _decisions jsonb, _objections jsonb, _next_steps jsonb, _key_topics text[], _sentiment text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner uuid;
  v_caller_sp uuid;
BEGIN
  SELECT salesperson_id INTO v_owner FROM public.call_recordings WHERE id = _recording_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Recording not found';
  END IF;

  v_caller_sp := public.get_current_salesperson_id();
  IF v_owner <> v_caller_sp AND NOT public.is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF _sentiment IS NOT NULL AND _sentiment NOT IN ('positive','neutral','negative','mixed') THEN
    RAISE EXCEPTION 'Invalid sentiment value';
  END IF;

  UPDATE public.call_recordings SET
    summary = _summary,
    action_items = COALESCE(_action_items, '[]'::jsonb),
    decisions = COALESCE(_decisions, '[]'::jsonb),
    objections_summary = COALESCE(_objections, '[]'::jsonb),
    next_steps = COALESCE(_next_steps, '[]'::jsonb),
    key_topics = COALESCE(_key_topics, ARRAY[]::text[]),
    sentiment = _sentiment,
    summarized_at = now(),
    status = CASE WHEN status IN ('transcribed','analyzing') THEN 'ready' ELSE status END,
    updated_at = now()
  WHERE id = _recording_id;

  RETURN true;
END;
$function$
;

-- public.update_call_recording_transcript(_id uuid, _transcript text, _language text, _error text)

CREATE OR REPLACE FUNCTION public.update_call_recording_transcript(_id uuid, _transcript text, _language text DEFAULT 'pt'::text, _error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _owner uuid;
  _caller_sp uuid;
  _is_admin boolean;
BEGIN
  SELECT salesperson_id INTO _owner FROM public.call_recordings WHERE id = _id;
  IF _owner IS NULL THEN
    RAISE EXCEPTION 'Recording not found';
  END IF;

  SELECT public.get_current_salesperson_id() INTO _caller_sp;
  SELECT public.has_role(auth.uid(), 'admin') INTO _is_admin;

  IF _caller_sp IS DISTINCT FROM _owner AND NOT COALESCE(_is_admin, false) THEN
    RAISE EXCEPTION 'Not authorized to update this recording';
  END IF;

  IF _error IS NOT NULL THEN
    UPDATE public.call_recordings
       SET status = 'failed',
           transcription_error = _error,
           updated_at = now()
     WHERE id = _id;
  ELSE
    UPDATE public.call_recordings
       SET transcript = _transcript,
           transcript_language = COALESCE(_language, 'pt'),
           transcribed_at = now(),
           transcription_error = NULL,
           status = 'transcribed',
           updated_at = now()
     WHERE id = _id;
  END IF;
END;
$function$
;

-- public.update_call_recording_tsv()

CREATE OR REPLACE FUNCTION public.update_call_recording_tsv()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.transcript_tsv := to_tsvector(
    'portuguese',
    coalesce(NEW.transcript, '') || ' ' ||
    coalesce(NEW.summary, '') || ' ' ||
    coalesce(array_to_string(NEW.key_topics, ' '), '') || ' ' ||
    coalesce(NEW.title, '')
  );
  RETURN NEW;
END;
$function$
;

-- public.update_client_ltv_on_sale()

CREATE OR REPLACE FUNCTION public.update_client_ltv_on_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'INSERT' AND NEW.status = 'completed') OR 
       (TG_OP = 'UPDATE' AND NEW.status = 'completed' AND (OLD.status IS NULL OR OLD.status != 'completed')) THEN
        UPDATE public.clients
        SET total_value = COALESCE(total_value, 0) + NEW.amount,
            updated_at = now()
        WHERE id = NEW.client_id;
    ELSIF (TG_OP = 'UPDATE' AND OLD.status = 'completed' AND NEW.status != 'completed') THEN
        UPDATE public.clients
        SET total_value = GREATEST(0, COALESCE(total_value, 0) - OLD.amount),
            updated_at = now()
        WHERE id = NEW.client_id;
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.update_client_portfolio_status(p_portfolio_id uuid, p_status text, p_last_purchase_date date)

CREATE OR REPLACE FUNCTION public.update_client_portfolio_status(p_portfolio_id uuid, p_status text, p_last_purchase_date date DEFAULT NULL::date)
 RETURNS client_portfolio
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.client_portfolio%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_row
  FROM public.client_portfolio
  WHERE id = p_portfolio_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'portfolio_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_row.salesperson_id IS DISTINCT FROM public.get_current_salesperson_id()
     AND NOT public.is_admin_or_manager(auth.uid()) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.client_portfolio
  SET status = p_status,
      last_purchase_date = COALESCE(p_last_purchase_date, last_purchase_date)
  WHERE id = p_portfolio_id
  RETURNING * INTO v_row;
  RETURN v_row;
END;
$function$
;

-- public.update_client_score(client_id uuid)

CREATE OR REPLACE FUNCTION public.update_client_score(client_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  total_value NUMERIC;
  deal_count INTEGER;
  last_activity DATE;
  score NUMERIC;
BEGIN
  SELECT
    COALESCE(SUM(value), 0),
    COUNT(*),
    MAX(created_at)::DATE
  INTO total_value, deal_count, last_activity
  FROM deals
  WHERE deals.client_id = update_client_score.client_id
    AND status IN ('won', 'open');
  
  score := (total_value / 1000) + (deal_count * 10) + 
           (CASE WHEN last_activity > now() - INTERVAL '30 days' THEN 20 ELSE 0 END);
  
  UPDATE clients
  SET health_score = LEAST(100, score)
  WHERE id = client_id;
END;
$function$
;

-- public.update_client_total_value()

CREATE OR REPLACE FUNCTION public.update_client_total_value()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'INSERT' AND NEW.status = 'completed') OR (TG_OP = 'UPDATE' AND NEW.status = 'completed' AND OLD.status != 'completed') THEN
        UPDATE public.clients 
        SET total_value = COALESCE(total_value, 0) + NEW.amount
        WHERE id = NEW.client_id;
    ELSIF (TG_OP = 'UPDATE' AND OLD.status = 'completed' AND NEW.status != 'completed') THEN
        UPDATE public.clients 
        SET total_value = GREATEST(0, COALESCE(total_value, 0) - OLD.amount)
        WHERE id = NEW.client_id;
    END IF;
    RETURN NEW;
END;
$function$
;

-- public.update_lead_score(client_id uuid)

CREATE OR REPLACE FUNCTION public.update_lead_score(client_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  score INT;
BEGIN
  SELECT 
    (COALESCE(deal_count, 0) * 10) +
    (COALESCE(activity_count, 0) * 5) +
    (CASE WHEN last_contact > NOW() - INTERVAL '7 days' THEN 20 ELSE 0 END)
  INTO score
  FROM (
    SELECT 
      c.id,
      COUNT(DISTINCT d.id) as deal_count,
      COUNT(DISTINCT a.id) as activity_count,
      MAX(a.created_at) as last_contact
    FROM clients c
    LEFT JOIN deals d ON c.id = d.client_id
    LEFT JOIN activities a ON c.id = a.client_id
    WHERE c.id = client_id
    GROUP BY c.id
  ) stats;
  
  UPDATE clients SET lead_score = score WHERE id = client_id;
END;
$function$
;

