-- public.update_user_mfa_settings(p_totp_enabled boolean, p_sms_enabled boolean, p_preferred_method text, p_totp_secret text, p_backup_codes text[])

CREATE OR REPLACE FUNCTION public.update_user_mfa_settings(p_totp_enabled boolean DEFAULT NULL::boolean, p_sms_enabled boolean DEFAULT NULL::boolean, p_preferred_method text DEFAULT NULL::text, p_totp_secret text DEFAULT NULL::text, p_backup_codes text[] DEFAULT NULL::text[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Validate preferred_method
  IF p_preferred_method IS NOT NULL AND p_preferred_method NOT IN ('totp', 'sms', 'none') THEN
    RAISE EXCEPTION 'Invalid preferred_method. Must be totp, sms, or none.';
  END IF;

  -- Upsert the MFA settings
  INSERT INTO public.user_mfa_settings (user_id, totp_enabled, sms_enabled, preferred_method, totp_secret, backup_codes)
  VALUES (
    v_user_id,
    COALESCE(p_totp_enabled, false),
    COALESCE(p_sms_enabled, false),
    COALESCE(p_preferred_method, 'none'),
    p_totp_secret,
    p_backup_codes
  )
  ON CONFLICT (user_id) DO UPDATE SET
    totp_enabled = COALESCE(p_totp_enabled, user_mfa_settings.totp_enabled),
    sms_enabled = COALESCE(p_sms_enabled, user_mfa_settings.sms_enabled),
    preferred_method = COALESCE(p_preferred_method, user_mfa_settings.preferred_method),
    totp_secret = CASE WHEN p_totp_secret IS NOT NULL THEN p_totp_secret ELSE user_mfa_settings.totp_secret END,
    backup_codes = CASE WHEN p_backup_codes IS NOT NULL THEN p_backup_codes ELSE user_mfa_settings.backup_codes END,
    updated_at = now();

  RETURN TRUE;
END;
$function$
;

-- public.upsert_client_from_quote(p_name text, p_email text, p_phone text, p_company text)

CREATE OR REPLACE FUNCTION public.upsert_client_from_quote(p_name text, p_email text, p_phone text, p_company text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_client_id UUID;
BEGIN
  IF p_email IS NOT NULL AND length(trim(p_email)) > 0 THEN
    SELECT id INTO v_client_id
    FROM public.clients
    WHERE lower(email) = lower(trim(p_email))
      AND deleted_at IS NULL
    LIMIT 1;
  END IF;

  IF v_client_id IS NULL AND p_phone IS NOT NULL AND length(trim(p_phone)) > 0 THEN
    SELECT id INTO v_client_id
    FROM public.clients
    WHERE regexp_replace(phone, '\D', '', 'g') = regexp_replace(p_phone, '\D', '', 'g')
      AND deleted_at IS NULL
    LIMIT 1;
  END IF;

  IF v_client_id IS NULL THEN
    BEGIN
      INSERT INTO public.clients (name, email, phone, company, lead_source)
      VALUES (
        COALESCE(NULLIF(trim(p_name), ''), 'Cliente sem nome'),
        NULLIF(trim(p_email), ''),
        NULLIF(trim(p_phone), ''),
        NULLIF(trim(p_company), ''),
        'gift_store_quote'
      )
      RETURNING id INTO v_client_id;
    EXCEPTION WHEN unique_violation THEN
      -- Corrida: outra transação inseriu o mesmo e-mail primeiro.
      SELECT id INTO v_client_id
      FROM public.clients
      WHERE lower(email) = lower(trim(p_email))
        AND deleted_at IS NULL
      LIMIT 1;
      IF v_client_id IS NULL THEN
        RAISE; -- violação em outra constraint: propaga o erro original
      END IF;
    END;
  ELSE
    UPDATE public.clients
    SET
      name = COALESCE(NULLIF(trim(p_name), ''), name),
      phone = COALESCE(NULLIF(trim(p_phone), ''), phone),
      company = COALESCE(NULLIF(trim(p_company), ''), company),
      last_interaction_at = now()
    WHERE id = v_client_id;
  END IF;

  RETURN v_client_id;
END;
$function$
;

-- public.upsert_semantic_entry(_entity_type text, _entity_id uuid, _salesperson_id uuid, _content text, _embedding vector, _metadata jsonb)

CREATE OR REPLACE FUNCTION public.upsert_semantic_entry(_entity_type text, _entity_id uuid, _salesperson_id uuid, _content text, _embedding vector, _metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  INSERT INTO public.semantic_index (entity_type, entity_id, salesperson_id, content, embedding, metadata, updated_at)
  VALUES (_entity_type, _entity_id, _salesperson_id, _content, _embedding, COALESCE(_metadata, '{}'::jsonb), now())
  ON CONFLICT (entity_type, entity_id) DO UPDATE
    SET content = EXCLUDED.content,
        embedding = EXCLUDED.embedding,
        salesperson_id = EXCLUDED.salesperson_id,
        metadata = EXCLUDED.metadata,
        updated_at = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$
;

-- public.user_owns_engagement_contact(_contact_id uuid, _contact_type text)

CREATE OR REPLACE FUNCTION public.user_owns_engagement_contact(_contact_id uuid, _contact_type text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.is_admin_or_manager(auth.uid())
    OR (
      _contact_type = 'lead' AND EXISTS (
        SELECT 1 FROM public.sales s
        WHERE s.id = _contact_id
          AND s.salesperson_id = public.get_current_salesperson_id()
      )
    )
    OR (
      _contact_type = 'client' AND EXISTS (
        SELECT 1 FROM public.client_portfolio cp
        WHERE cp.client_id = _contact_id
          AND cp.salesperson_id = public.get_current_salesperson_id()
      )
    )
$function$
;

-- public.user_owns_sequence_step(_step_id uuid)

CREATE OR REPLACE FUNCTION public.user_owns_sequence_step(_step_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.sequence_steps st
    JOIN public.sequences s ON s.id = st.sequence_id
    WHERE st.id = _step_id
      AND (s.owner_id = auth.uid() OR public.is_admin_or_manager(auth.uid()))
  )
$function$
;

-- public.validate_api_token(p_token text)

CREATE OR REPLACE FUNCTION public.validate_api_token(p_token text)
 RETURNS TABLE(token_id uuid, team_id uuid, company_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT t.id, t.team_id, t.company_name
  FROM api_tokens t
  WHERE t.token = p_token
    AND t.is_active = true
    AND (t.expires_at IS NULL OR t.expires_at > now());
  
  -- Update usage stats
  UPDATE api_tokens SET last_used_at = now(), usage_count = usage_count + 1
  WHERE token = p_token;
END;
$function$
;

-- public.validate_mood_value()

CREATE OR REPLACE FUNCTION public.validate_mood_value()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.mood_score IS NOT NULL AND (NEW.mood_score < 1 OR NEW.mood_score > 5) THEN
    RAISE EXCEPTION 'mood_score must be between 1 and 5';
  END IF;
  RETURN NEW;
END;
$function$
;

-- public.validate_race_event()

CREATE OR REPLACE FUNCTION public.validate_race_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_status text;
BEGIN
  -- Bloqueia eventos em temporadas não-ativas
  SELECT status INTO v_status FROM public.race_seasons WHERE id = NEW.season_id;
  IF v_status IS NULL THEN
    RAISE EXCEPTION 'race_event rejected: season % does not exist', NEW.season_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF v_status <> 'active' THEN
    RAISE EXCEPTION 'race_event rejected: season % is not active (status=%)', NEW.season_id, v_status
      USING ERRCODE = 'check_violation';
  END IF;

  -- Bloqueia eventos sem race_car correspondente para o salesperson
  IF NOT EXISTS (
    SELECT 1 FROM public.race_cars WHERE salesperson_id = NEW.salesperson_id
  ) THEN
    RAISE EXCEPTION 'race_event rejected: no race_car found for salesperson %', NEW.salesperson_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;

  RETURN NEW;
END;
$function$
;

-- public.validate_session(session_id uuid)

CREATE OR REPLACE FUNCTION public.validate_session(session_id uuid)
 RETURNS TABLE(valid boolean, needs_refresh boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  session_record RECORD;
BEGIN
  SELECT * INTO session_record FROM active_sessions WHERE id = session_id;
  
  IF NOT FOUND THEN
    RETURN QUERY SELECT false, false, 'Session not found'::TEXT;
    RETURN;
  END IF;
  
  -- Verificar se expirou
  IF session_record.expires_at < NOW() THEN
    RETURN QUERY SELECT false, false, 'Session expired'::TEXT;
    RETURN;
  END IF;
  
  -- Verificar se precisa refresh (últimas 2 horas antes de expirar)
  IF session_record.expires_at - INTERVAL '2 hours' < NOW() THEN
    RETURN QUERY SELECT true, true, 'Needs refresh'::TEXT;
    RETURN;
  END IF;
  
  RETURN QUERY SELECT true, false, 'Valid'::TEXT;
END;
$function$
;

-- public.verify_and_enable_sms(p_code text)

CREATE OR REPLACE FUNCTION public.verify_and_enable_sms(p_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sms RECORD;
  v_backup_codes text[];
  v_existing_codes text[];
BEGIN
  SELECT * INTO v_sms FROM sms_verification_codes
  WHERE user_id = auth.uid() AND code = p_code AND used_at IS NULL AND expires_at > now()
  ORDER BY created_at DESC LIMIT 1;

  IF NOT FOUND THEN
    INSERT INTO mfa_verification_attempts (user_id, method, success) VALUES (auth.uid(), 'sms', false);
    RETURN false;
  END IF;

  UPDATE sms_verification_codes SET used_at = now() WHERE id = v_sms.id;

  SELECT backup_codes INTO v_existing_codes FROM user_mfa_settings WHERE user_id = auth.uid();
  IF v_existing_codes IS NULL THEN
    v_backup_codes := public.generate_mfa_backup_codes();
  ELSE
    v_backup_codes := v_existing_codes;
  END IF;

  UPDATE user_mfa_settings SET
    sms_enabled = true,
    phone_verified_at = now(),
    backup_codes = v_backup_codes,
    backup_codes_generated_at = COALESCE(backup_codes_generated_at, now()),
    updated_at = now()
  WHERE user_id = auth.uid();

  INSERT INTO mfa_verification_attempts (user_id, method, success) VALUES (auth.uid(), 'sms', true);
  RETURN true;
END;
$function$
;

-- public.verify_and_enable_totp(p_token text)

CREATE OR REPLACE FUNCTION public.verify_and_enable_totp(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_secret text;
  v_is_valid boolean := false;
  v_backup_codes text[];
  v_secret_bytes bytea;
  v_time_step bigint;
  v_counter bytea;
  v_hmac bytea;
  v_offset int;
  v_code int;
  v_expected text;
  v_i int;
  -- Base32 decode vars
  v_base32_chars text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  v_bits text := '';
  v_char_idx int;
  v_byte_arr bytea := E'\\x';
  v_bit_pos int;
  v_byte_val int;
  v_decoded bytea;
BEGIN
  SELECT totp_secret INTO v_secret FROM user_mfa_settings WHERE user_id = auth.uid();
  
  IF v_secret IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'TOTP not initialized');
  END IF;

  -- Basic format check first
  IF length(p_token) != 6 OR p_token !~ '^\d+$' THEN
    INSERT INTO mfa_verification_attempts (user_id, method, success, user_agent)
    VALUES (auth.uid(), 'totp', false, null);
    RETURN jsonb_build_object('success', false, 'error', 'Invalid code');
  END IF;

  -- Base32 decode the secret
  v_bits := '';
  FOR v_i IN 1..length(v_secret) LOOP
    v_char_idx := position(substr(v_secret, v_i, 1) in v_base32_chars) - 1;
    IF v_char_idx >= 0 THEN
      v_bits := v_bits || lpad(v_char_idx::bit(5)::text, 5, '0');
    END IF;
  END LOOP;
  
  -- Convert bits to bytes
  v_decoded := E'\\x'::bytea;
  FOR v_i IN 0..((length(v_bits) / 8) - 1) LOOP
    v_byte_val := 0;
    FOR v_bit_pos IN 0..7 LOOP
      IF substr(v_bits, v_i * 8 + v_bit_pos + 1, 1) = '1' THEN
        v_byte_val := v_byte_val + (1 << (7 - v_bit_pos));
      END IF;
    END LOOP;
    v_decoded := v_decoded || set_byte(E'\\x00'::bytea, 0, v_byte_val);
  END LOOP;

  v_secret_bytes := v_decoded;

  -- Try current time step and ±1 for clock skew tolerance
  FOR v_i IN -1..1 LOOP
    v_time_step := (extract(epoch from now())::bigint / 30) + v_i;
    
    -- Encode time step as 8-byte big-endian
    v_counter := E'\\x0000000000000000'::bytea;
    v_counter := set_byte(v_counter, 7, (v_time_step & 255)::int);
    v_counter := set_byte(v_counter, 6, ((v_time_step >> 8) & 255)::int);
    v_counter := set_byte(v_counter, 5, ((v_time_step >> 16) & 255)::int);
    v_counter := set_byte(v_counter, 4, ((v_time_step >> 24) & 255)::int);
    
    -- HMAC-SHA1
    v_hmac := hmac(v_counter, v_secret_bytes, 'sha1');
    
    -- Dynamic truncation (RFC 4226)
    v_offset := get_byte(v_hmac, 19) & 15;
    v_code := ((get_byte(v_hmac, v_offset) & 127) << 24)
            | (get_byte(v_hmac, v_offset + 1) << 16)
            | (get_byte(v_hmac, v_offset + 2) << 8)
            | get_byte(v_hmac, v_offset + 3);
    v_code := v_code % 1000000;
    
    v_expected := lpad(v_code::text, 6, '0');
    
    IF p_token = v_expected THEN
      v_is_valid := true;
      EXIT;
    END IF;
  END LOOP;

  -- Log attempt
  INSERT INTO mfa_verification_attempts (user_id, method, success, user_agent)
  VALUES (auth.uid(), 'totp', v_is_valid, null);

  IF v_is_valid THEN
    v_backup_codes := public.generate_mfa_backup_codes();
    
    UPDATE user_mfa_settings SET
      totp_enabled = true,
      totp_verified_at = now(),
      backup_codes = v_backup_codes,
      backup_codes_generated_at = now(),
      updated_at = now()
    WHERE user_id = auth.uid();

    RETURN jsonb_build_object('success', true, 'backup_codes', to_jsonb(v_backup_codes));
  ELSE
    RETURN jsonb_build_object('success', false, 'error', 'Invalid code');
  END IF;
END;
$function$
;

-- public.verify_mfa_code(p_code text, p_method text)

CREATE OR REPLACE FUNCTION public.verify_mfa_code(p_code text, p_method text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_settings RECORD;
  v_use_method text;
  v_is_valid boolean := false;
  v_new_codes text[];
  v_sms RECORD;
  -- TOTP vars
  v_secret_bytes bytea;
  v_time_step bigint;
  v_counter bytea;
  v_hmac bytea;
  v_offset int;
  v_totp_code int;
  v_expected text;
  v_i int;
  v_bits text;
  v_char_idx int;
  v_decoded bytea;
  v_byte_val int;
  v_bit_pos int;
  v_base32_chars text := 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
BEGIN
  SELECT * INTO v_settings FROM user_mfa_settings WHERE user_id = auth.uid();
  IF NOT FOUND THEN RETURN false; END IF;

  v_use_method := COALESCE(p_method, v_settings.preferred_method);

  IF v_use_method = 'backup_code' THEN
    IF p_code = ANY(v_settings.backup_codes) THEN
      v_new_codes := array_remove(v_settings.backup_codes, p_code);
      UPDATE user_mfa_settings SET backup_codes = v_new_codes, updated_at = now() WHERE user_id = auth.uid();
      v_is_valid := true;
    END IF;
  ELSIF v_use_method = 'totp' AND v_settings.totp_enabled THEN
    -- Real TOTP validation using HMAC-SHA1
    IF length(p_code) = 6 AND p_code ~ '^\d+$' AND v_settings.totp_secret IS NOT NULL THEN
      -- Base32 decode
      v_bits := '';
      FOR v_i IN 1..length(v_settings.totp_secret) LOOP
        v_char_idx := position(substr(v_settings.totp_secret, v_i, 1) in v_base32_chars) - 1;
        IF v_char_idx >= 0 THEN
          v_bits := v_bits || lpad(v_char_idx::bit(5)::text, 5, '0');
        END IF;
      END LOOP;
      
      v_decoded := E'\\x'::bytea;
      FOR v_i IN 0..((length(v_bits) / 8) - 1) LOOP
        v_byte_val := 0;
        FOR v_bit_pos IN 0..7 LOOP
          IF substr(v_bits, v_i * 8 + v_bit_pos + 1, 1) = '1' THEN
            v_byte_val := v_byte_val + (1 << (7 - v_bit_pos));
          END IF;
        END LOOP;
        v_decoded := v_decoded || set_byte(E'\\x00'::bytea, 0, v_byte_val);
      END LOOP;

      v_secret_bytes := v_decoded;

      FOR v_i IN -1..1 LOOP
        v_time_step := (extract(epoch from now())::bigint / 30) + v_i;
        v_counter := E'\\x0000000000000000'::bytea;
        v_counter := set_byte(v_counter, 7, (v_time_step & 255)::int);
        v_counter := set_byte(v_counter, 6, ((v_time_step >> 8) & 255)::int);
        v_counter := set_byte(v_counter, 5, ((v_time_step >> 16) & 255)::int);
        v_counter := set_byte(v_counter, 4, ((v_time_step >> 24) & 255)::int);
        
        v_hmac := hmac(v_counter, v_secret_bytes, 'sha1');
        v_offset := get_byte(v_hmac, 19) & 15;
        v_totp_code := ((get_byte(v_hmac, v_offset) & 127) << 24)
                | (get_byte(v_hmac, v_offset + 1) << 16)
                | (get_byte(v_hmac, v_offset + 2) << 8)
                | get_byte(v_hmac, v_offset + 3);
        v_totp_code := v_totp_code % 1000000;
        v_expected := lpad(v_totp_code::text, 6, '0');
        
        IF p_code = v_expected THEN
          v_is_valid := true;
          EXIT;
        END IF;
      END LOOP;
    END IF;
  ELSIF v_use_method = 'sms' AND v_settings.sms_enabled THEN
    SELECT * INTO v_sms FROM sms_verification_codes
    WHERE user_id = auth.uid() AND code = p_code AND used_at IS NULL AND expires_at > now()
    ORDER BY created_at DESC LIMIT 1;
    
    IF FOUND THEN
      UPDATE sms_verification_codes SET used_at = now() WHERE id = v_sms.id;
      v_is_valid := true;
    END IF;
  END IF;

  INSERT INTO mfa_verification_attempts (user_id, method, success, user_agent)
  VALUES (auth.uid(), COALESCE(v_use_method, 'unknown'), v_is_valid, null);

  RETURN v_is_valid;
END;
$function$
;

-- public.verify_reauth_request(p_request_id uuid, p_password text)

CREATE OR REPLACE FUNCTION public.verify_reauth_request(p_request_id uuid, p_password text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.reauthentication_requests%ROWTYPE;
  v_iat numeric;
BEGIN
  -- p_password faz parte do contrato, mas NÃO é lido nem persistido: a senha
  -- é validada no GoTrue pelo signInWithPassword do cliente, e o reflexo
  -- server-side disso é o iat fresco do JWT verificado abaixo.
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT * INTO v_request
  FROM public.reauthentication_requests
  WHERE id = p_request_id
    AND user_id = auth.uid();

  IF NOT FOUND OR v_request.verified OR v_request.expires_at <= now() THEN
    RETURN false;
  END IF;

  v_iat := nullif(auth.jwt() ->> 'iat', '')::numeric;
  IF v_iat IS NULL OR v_iat < extract(epoch from now() - interval '5 minutes') THEN
    RETURN false;
  END IF;

  UPDATE public.reauthentication_requests
  SET verified = true,
      verified_at = now()
  WHERE id = p_request_id;

  RETURN true;
END;
$function$
;

-- public.win_rate_breakdown(_dimension text, _days integer)

CREATE OR REPLACE FUNCTION public.win_rate_breakdown(_dimension text DEFAULT 'category'::text, _days integer DEFAULT 180)
 RETURNS TABLE(segment text, total_deals integer, won_deals integer, lost_deals integer, win_rate numeric, avg_deal_size numeric, total_revenue numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _col text;
BEGIN
  _col := CASE _dimension
    WHEN 'source' THEN 'source'
    WHEN 'product' THEN 'product_name'
    ELSE 'category'
  END;

  RETURN QUERY EXECUTE format($f$
    SELECT
      COALESCE(%I::text, 'unknown'),
      COUNT(*)::integer,
      COUNT(*) FILTER (WHERE status IN ('completed','won','closed'))::integer,
      COUNT(*) FILTER (WHERE status IN ('lost','cancelled'))::integer,
      CASE WHEN COUNT(*) FILTER (WHERE status IN ('completed','won','closed','lost','cancelled')) > 0
        THEN ROUND(100.0 * COUNT(*) FILTER (WHERE status IN ('completed','won','closed'))::numeric
          / NULLIF(COUNT(*) FILTER (WHERE status IN ('completed','won','closed','lost','cancelled')),0), 1)
        ELSE 0 END,
      COALESCE(AVG(amount) FILTER (WHERE status IN ('completed','won','closed')), 0)::numeric,
      COALESCE(SUM(amount) FILTER (WHERE status IN ('completed','won','closed')), 0)::numeric
    FROM public.sales
    WHERE created_at >= now() - ($1 || ' days')::interval
      AND (public.is_admin_or_manager(auth.uid()) OR salesperson_id = public.get_current_salesperson_id())
    GROUP BY %I
    ORDER BY 7 DESC
    LIMIT 50
  $f$, _col, _col) USING _days;
END;
$function$
;


