-- Parte 2 - POLICIES (1017)
-- =========================================================

-- ---- public._internal_secrets ----

DROP POLICY IF EXISTS "Deny all access to _internal_secrets" ON public._internal_secrets;
CREATE POLICY "Deny all access to _internal_secrets" ON public._internal_secrets AS PERMISSIVE FOR ALL TO authenticated, anon
  USING (false)
  WITH CHECK (false);

-- ---- public.ab_tests ----

DROP POLICY IF EXISTS "Admins and managers can manage ab_tests" ON public.ab_tests;
CREATE POLICY "Admins and managers can manage ab_tests" ON public.ab_tests AS PERMISSIVE FOR ALL TO PUBLIC
  USING (is_admin_or_manager(auth.uid()));

-- ---- public.access_denied_logs ----

DROP POLICY IF EXISTS "Admins can view access logs" ON public.access_denied_logs;
CREATE POLICY "Admins can view access logs" ON public.access_denied_logs AS PERMISSIVE FOR SELECT TO PUBLIC
  USING ((EXISTS ( SELECT 1
   FROM user_roles
  WHERE ((user_roles.user_id = auth.uid()) AND (user_roles.role = 'admin'::app_role)))));

DROP POLICY IF EXISTS "Authenticated users can log access denied" ON public.access_denied_logs;
CREATE POLICY "Authenticated users can log access denied" ON public.access_denied_logs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((user_id = auth.uid()));

DROP POLICY IF EXISTS "Authenticated users can log access denied events" ON public.access_denied_logs;
CREATE POLICY "Authenticated users can log access denied events" ON public.access_denied_logs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((auth.uid() = user_id));

DROP POLICY IF EXISTS "Users can insert their own access logs" ON public.access_denied_logs;
CREATE POLICY "Users can insert their own access logs" ON public.access_denied_logs AS PERMISSIVE FOR INSERT TO PUBLIC
  WITH CHECK ((auth.uid() = user_id));

-- ---- public.account_activities ----

DROP POLICY IF EXISTS "Insert activities for accessible accounts" ON public.account_activities;
CREATE POLICY "Insert activities for accessible accounts" ON public.account_activities AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((is_admin_or_manager(auth.uid()) OR (EXISTS ( SELECT 1
   FROM accounts a
  WHERE ((a.id = account_activities.account_id) AND (a.owner_id = get_current_salesperson_id()))))));

DROP POLICY IF EXISTS "View activities of accessible accounts" ON public.account_activities;
CREATE POLICY "View activities of accessible accounts" ON public.account_activities AS PERMISSIVE FOR SELECT TO authenticated
  USING ((is_admin_or_manager(auth.uid()) OR (EXISTS ( SELECT 1
   FROM accounts a
  WHERE ((a.id = account_activities.account_id) AND (a.owner_id = get_current_salesperson_id()))))));

-- ---- public.account_contacts ----

DROP POLICY IF EXISTS "Manage contacts of accessible accounts" ON public.account_contacts;
CREATE POLICY "Manage contacts of accessible accounts" ON public.account_contacts AS PERMISSIVE FOR ALL TO authenticated
  USING ((is_admin_or_manager(auth.uid()) OR (EXISTS ( SELECT 1
   FROM accounts a
  WHERE ((a.id = account_contacts.account_id) AND (a.owner_id = get_current_salesperson_id()))))))
  WITH CHECK ((is_admin_or_manager(auth.uid()) OR (EXISTS ( SELECT 1
   FROM accounts a
  WHERE ((a.id = account_contacts.account_id) AND (a.owner_id = get_current_salesperson_id()))))));

DROP POLICY IF EXISTS "View contacts of accessible accounts" ON public.account_contacts;
CREATE POLICY "View contacts of accessible accounts" ON public.account_contacts AS PERMISSIVE FOR SELECT TO authenticated
  USING ((is_admin_or_manager(auth.uid()) OR (EXISTS ( SELECT 1
   FROM accounts a
  WHERE ((a.id = account_contacts.account_id) AND (a.owner_id = get_current_salesperson_id()))))));

-- ---- public.account_plans ----

DROP POLICY IF EXISTS "Account plans owner or admin can read" ON public.account_plans;
CREATE POLICY "Account plans owner or admin can read" ON public.account_plans AS PERMISSIVE FOR SELECT TO authenticated
  USING ((is_admin_or_manager(auth.uid()) OR (created_by = auth.uid()) OR (EXISTS ( SELECT 1
   FROM accounts a
  WHERE ((a.id = account_plans.account_id) AND (a.owner_id = get_current_salesperson_id()))))));

DROP POLICY IF EXISTS "Account plans owner or admin can update" ON public.account_plans;
CREATE POLICY "Account plans owner or admin can update" ON public.account_plans AS PERMISSIVE FOR UPDATE TO authenticated
  USING ((is_admin_or_manager(auth.uid()) OR (created_by = auth.uid()) OR (EXISTS ( SELECT 1
   FROM accounts a
  WHERE ((a.id = account_plans.account_id) AND (a.owner_id = get_current_salesperson_id()))))));

DROP POLICY IF EXISTS "Owners or admins can insert account plans" ON public.account_plans;
CREATE POLICY "Owners or admins can insert account plans" ON public.account_plans AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((created_by = auth.uid()) AND (is_admin_or_manager(auth.uid()) OR (created_by = auth.uid()))));

-- ---- public.accounts ----

DROP POLICY IF EXISTS "Managers can delete accounts" ON public.accounts;
CREATE POLICY "Managers can delete accounts" ON public.accounts AS PERMISSIVE FOR DELETE TO authenticated
  USING (( SELECT is_admin_or_manager(( SELECT auth.uid() AS uid)) AS is_admin_or_manager));

DROP POLICY IF EXISTS "Owners and managers can insert accounts" ON public.accounts;
CREATE POLICY "Owners and managers can insert accounts" ON public.accounts AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((( SELECT is_admin_or_manager(( SELECT auth.uid() AS uid)) AS is_admin_or_manager) OR (owner_id = ( SELECT get_current_salesperson_id() AS get_current_salesperson_id))));

DROP POLICY IF EXISTS "Owners and managers can update accounts" ON public.accounts;
CREATE POLICY "Owners and managers can update accounts" ON public.accounts AS PERMISSIVE FOR UPDATE TO authenticated
  USING ((( SELECT is_admin_or_manager(( SELECT auth.uid() AS uid)) AS is_admin_or_manager) OR (owner_id = ( SELECT get_current_salesperson_id() AS get_current_salesperson_id))))
  WITH CHECK ((( SELECT is_admin_or_manager(( SELECT auth.uid() AS uid)) AS is_admin_or_manager) OR (owner_id = ( SELECT get_current_salesperson_id() AS get_current_salesperson_id))));

DROP POLICY IF EXISTS "Owners and managers can view accounts" ON public.accounts;
CREATE POLICY "Owners and managers can view accounts" ON public.accounts AS PERMISSIVE FOR SELECT TO authenticated
  USING ((( SELECT is_admin_or_manager(( SELECT auth.uid() AS uid)) AS is_admin_or_manager) OR (owner_id = ( SELECT get_current_salesperson_id() AS get_current_salesperson_id))));

-- ---- public.achievements ----

DROP POLICY IF EXISTS "Authenticated users can read achievements" ON public.achievements;
CREATE POLICY "Authenticated users can read achievements" ON public.achievements AS PERMISSIVE FOR SELECT TO authenticated
  USING (true);

DROP POLICY IF EXISTS "Users can insert own achievements" ON public.achievements;
CREATE POLICY "Users can insert own achievements" ON public.achievements AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((salesperson_id = get_current_salesperson_id()));

-- ---- public.active_power_ups ----

DROP POLICY IF EXISTS "Users can insert own power_ups" ON public.active_power_ups;
CREATE POLICY "Users can insert own power_ups" ON public.active_power_ups AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((salesperson_id = get_current_salesperson_id()));

DROP POLICY IF EXISTS "Users can view own or admin can view all power-ups" ON public.active_power_ups;
CREATE POLICY "Users can view own or admin can view all power-ups" ON public.active_power_ups AS PERMISSIVE FOR SELECT TO authenticated
  USING (((salesperson_id IN ( SELECT salespeople.id
   FROM salespeople
  WHERE (salespeople.auth_user_id = auth.uid()))) OR has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'manager'::app_role)));

