DROP POLICY IF EXISTS "Admins can view all sessions" ON public.active_sessions;
CREATE POLICY "Admins can view all sessions" ON public.active_sessions AS PERMISSIVE FOR SELECT TO PUBLIC
  USING (has_role(auth.uid(), 'admin'::app_role));

DROP POLICY IF EXISTS "Users can delete own sessions" ON public.active_sessions;
CREATE POLICY "Users can delete own sessions" ON public.active_sessions AS PERMISSIVE FOR DELETE TO authenticated
  USING ((user_id = auth.uid()));

DROP POLICY IF EXISTS "Users can insert own sessions" ON public.active_sessions;
CREATE POLICY "Users can insert own sessions" ON public.active_sessions AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((user_id = auth.uid()));

DROP POLICY IF EXISTS "Users can read own sessions" ON public.active_sessions;
CREATE POLICY "Users can read own sessions" ON public.active_sessions AS PERMISSIVE FOR SELECT TO authenticated
  USING ((user_id = auth.uid()));

DROP POLICY IF EXISTS "Users can update own sessions" ON public.active_sessions;
CREATE POLICY "Users can update own sessions" ON public.active_sessions AS PERMISSIVE FOR UPDATE TO authenticated
  USING ((user_id = auth.uid()));

DROP POLICY IF EXISTS "Users can view own sessions" ON public.active_sessions;
CREATE POLICY "Users can view own sessions" ON public.active_sessions AS PERMISSIVE FOR SELECT TO PUBLIC
  USING ((auth.uid() = user_id));

