CREATE POLICY "Salespeople manage own agenda events" ON public.agenda_events AS PERMISSIVE FOR ALL TO PUBLIC
  USING ((salesperson_id = get_current_salesperson_id()))
  WITH CHECK ((salesperson_id = get_current_salesperson_id()));

-- ---- public.ai_agent_actions ----

DROP POLICY IF EXISTS "View actions of accessible runs" ON public.ai_agent_actions;
CREATE POLICY "View actions of accessible runs" ON public.ai_agent_actions AS PERMISSIVE FOR SELECT TO authenticated
  USING ((EXISTS ( SELECT 1
   FROM ai_agent_runs r
  WHERE ((r.id = ai_agent_actions.run_id) AND ((r.salesperson_id = get_current_salesperson_id()) OR has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'manager'::app_role))))));

-- ---- public.ai_agent_runs ----

DROP POLICY IF EXISTS "Cancel own agent runs" ON public.ai_agent_runs;
CREATE POLICY "Cancel own agent runs" ON public.ai_agent_runs AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((salesperson_id = get_current_salesperson_id()) OR has_role(auth.uid(), 'admin'::app_role)))
  WITH CHECK ((((salesperson_id = get_current_salesperson_id()) OR has_role(auth.uid(), 'admin'::app_role)) AND (status = 'cancelled'::text) AND (result IS NULL) AND (completed_at IS NULL) AND ((approved_by IS NULL) OR (approved_by = auth.uid()))));

DROP POLICY IF EXISTS "Insert own pending agent runs" ON public.ai_agent_runs;
CREATE POLICY "Insert own pending agent runs" ON public.ai_agent_runs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((((salesperson_id = get_current_salesperson_id()) OR has_role(auth.uid(), 'admin'::app_role)) AND (status = 'pending'::text) AND (approved_by IS NULL) AND (result IS NULL) AND (completed_at IS NULL) AND (steps = '[]'::jsonb)));

