CREATE POLICY "Users can insert logs for their clients" ON public.lead_detailed_logs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((auth.uid() = created_by) AND (is_admin_or_manager(auth.uid()) OR (EXISTS ( SELECT 1
   FROM clients c
  WHERE ((c.id = lead_detailed_logs.client_id) AND (c.user_id = auth.uid())))))));

DROP POLICY IF EXISTS "Users can insert own logs" ON public.lead_detailed_logs;
CREATE POLICY "Users can insert own logs" ON public.lead_detailed_logs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((auth.uid() = created_by));

DROP POLICY IF EXISTS "Users can view logs of their clients" ON public.lead_detailed_logs;
CREATE POLICY "Users can view logs of their clients" ON public.lead_detailed_logs AS PERMISSIVE FOR SELECT TO PUBLIC
  USING ((EXISTS ( SELECT 1
   FROM clients c
  WHERE ((c.id = lead_detailed_logs.client_id) AND ((c.user_id = auth.uid()) OR (auth.uid() IN ( SELECT users.id
           FROM auth.users
          WHERE ((users.raw_user_meta_data ->> 'role'::text) = 'admin'::text))))))));

DROP POLICY IF EXISTS "Users can view own logs" ON public.lead_detailed_logs;
CREATE POLICY "Users can view own logs" ON public.lead_detailed_logs AS PERMISSIVE FOR SELECT TO authenticated
  USING (((auth.uid() = created_by) OR is_admin_or_manager(auth.uid())));

