  USING (((quote_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (quotes q
     JOIN salespeople sp ON ((sp.id = COALESCE(prospect_cadences.salesperson_id, sp.id))))
  WHERE ((q.id = prospect_cadences.quote_id) AND ((q.created_by = auth.uid()) OR has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'manager'::app_role)))))));

